    onOpenToolSettings: (ToolbarTool) -> Unit = {},
    onOpenRoute: (String) -> Unit = {},
    onPluginOpen: (String) -> Unit = {},
    onPluginBack: () -> Unit = {},
    onPluginEvent: (PluginEvent) -> Unit = {},
    onPluginInputFocus: (String?) -> Unit = {},
    onPluginPaste: (String) -> Unit = {},
    onPluginCopy: (String) -> Unit = {},
    launcher: LauncherPanelCallbacks = LauncherPanelCallbacks(),
    onDismissInlineSuggestions: () -> Unit = {},
    /**
     * Close button of whichever hardware overlay is up: the shortcut legend or
     * the language list. One callback, not two — they never show together, and
     * [KeyboardScreen]'s caller sits against the JVM's 64K method-size ceiling,
     * where every added parameter costs generated bytecode.
     */
    onPickerDismiss: () -> Unit = {},
    /** Smart chip tapped: type the answer over the text that triggered it. */
    onSmartAccept: () -> Unit = {},
    /** Smart chip's tool button: clear the trigger and stage the prefill. */
    onSmartOpen: () -> Unit = {},
    /**
     * An ask-first chip on the strip was answered: true accepted it, false
     * turned it down. One callback for the snippet offer and the add-word
     * offer both — they never share the strip, and the service picks by state,
     * because [KeyboardScreen]'s caller sits against the JVM's 64K method-size
     * ceiling where every added parameter costs generated bytecode.
     */
    onStripOfferAction: (StripOfferAction) -> Unit = {},
    /** A tool panel has read [KeyboardUiState.toolPrefill]. */
    onToolPrefillConsumed: () -> Unit = {},
    /** Dismiss the keyboard — the hide-keyboard tool and the toolbar swipe-down. */
    onHideKeyboard: () -> Unit = {},
) {
    // Collected here and read only in [KeyboardScreenFrame]. The service
    // publishes a new state on every keystroke, and whatever reads it
    // recomposes with it. This function's parameter list and the body lambda
    // below compile to one method of ~15,700 dex instructions and 562
    // registers: past ART's huge-method limit, so it is never compiled, and
    // too big a frame for its fast interpreter, so it ran in the slow one.
    // Reading the state here put all of that on every keystroke (14% of the
    // main thread in a typing burst on a CPH2481). Now this runs when the
    // service recomposes it, which is rarely, and the per-keystroke work is in
    // a function small enough to be compiled.
    val stateHolder = stateFlow.collectAsState()
    // The bubbles, owned here so the frame can draw them over everything it
    // holds while the keys deep inside the body publish to them.
    val keyPreview = remember { KeyPreviewState() }
    val languageSwitchEcho = remember { LanguageSwitchEcho() }

    val body:@Composable ColumnScope.(KeyboardUiState) -> Unit = { bodyState ->
        // Resolved off the main thread, so the first frame or two after a cold
        // start draw the built-in icons and a pack swaps in behind them.
        val iconSet by rememberIconSet(bodyState.settings.icons)
        // Only what changes with the state is provided here: this runs on
        // every keystroke, and each call builds the provider map afresh. The
        // rest is provided once, around [KeyboardScreenFrame] below.
        CompositionLocalProvider(
            LocalIconSet provides iconSet,
            LocalPhoneticIndic provides phoneticIsIndic(bodyState.composer.phoneticLanguage),
            // Where the caret sits in the keyboard's own focused field, for the
            // nine panels that draw one (#161).
            LocalCaptureCaret provides CaptureCaretHandle(
                bodyState.captureCaretIndex(),
                capture.onCaretTap,
                anchor = bodyState.captureAnchorIndex(),
                onSelect = capture.onSelect,
                onSelectionAction = capture.onSelectionAction,
                // The focus switch (#665), on every field that can let go of the keys.
                toApp = bodyState.captureHandedToApp,
                onFocusSwitch = capture.onFocusSwitch.takeIf {
                    bodyState.panelFieldTarget()?.handsKeysToApp == true
                },
            ),
            LocalSelectionTools provides selectionTools(bodyState, capture.onAiChat),
            LocalOctopusWords provides rememberUpdatedState(bodyState.octopus),
            LocalLiveWpmPrivate provides rememberLiveWpmPrivate(bodyState),
            // Only while something is composing, so a list the service has not
            // cleared yet never outlives the reading it was for.
            LocalConversionReadings provides rememberConversionReadings(bodyState),
            LocalTransliterationPreview provides rememberTransliterationPreview(bodyState),
            LocalMirrorBrackets provides (bodyState.script.direction == TextDirection.RTL),
            // Whether a D-pad ring can land on the toolbar and the strip. The
            // keys read the same setting through the grid itself; these two
            // surfaces are too far from it to be handed a parameter.
            LocalDpadRing provides bodyState.settings.hardwareKeyboard.dpadKeyNavigation,
        ) {
            KeyboardBody(
                state = bodyState,
                onEmojiRowShown = onEmojiRowShown,
                onDismissInlineSuggestions = onDismissInlineSuggestions,
                onPickerDismiss = onPickerDismiss,
                onSmartAccept = onSmartAccept,
                onSmartOpen = onSmartOpen,
                onStripOfferAction = onStripOfferAction,
                onToolPrefillConsumed = onToolPrefillConsumed,
                onHideKeyboard = onHideKeyboard,
                onKey = onKey,
                onText = onText,
                onGesture = onGesture,
                onGesturePreview = onGesturePreview,
                onGestureWords = onGestureWords,
                onKeyTouch = onKeyTouch,
                onTouchKeys = onTouchKeys,
                onCursorMove = onCursorMove,
                onLayoutSelect = onLayoutSelect,
                onSuggestion = onSuggestion,
                suggestionHold = suggestionHold,
                onJoinSuggestion = onJoinSuggestion,
                onRevisionSuggestion = onRevisionSuggestion,
                onCandidate = onCandidate,
                onCandidatesExpand = onCandidatesExpand,
                onEmoji = onEmoji,
                onEmojiVariant = onEmojiVariant,
                onEmojiFavourite = onEmojiFavourite,
                onEmojiSuggestion = onEmojiSuggestion,
                onPunctuation = onPunctuation,
                onEmojiQueryTap = onEmojiQueryTap,
                onEmojiRecentsClear = onEmojiRecentsClear,
                onEmojiRecentRemove = onEmojiRecentRemove,
                onEmojiFavouritesReorder = onEmojiFavouritesReorder,
                onEmojiLongPress = onEmojiLongPress,
                onEmojiLongPressEnd = onEmojiLongPressEnd,
                onAnimatedEmojiSend = onAnimatedEmojiSend,
                onEmojiStickerSend = onEmojiStickerSend,
                onEmojiSearchFieldDelete = onEmojiSearchFieldDelete,
                onTextArt = onTextArt,
                onPanelChange = onPanelChange,
                onClipboardItem = onClipboardItem,
                onClipboardSticker = onClipboardSticker,
                onClipboardPin = onClipboardPin,
                onClipboardDelete = onClipboardDelete,
                onClipboardSearchToggle = onClipboardSearchToggle,
                onClipboardSuggestionDismiss = onClipboardSuggestionDismiss,
                onRecentClipsToggle = onRecentClipsToggle,
                onClipboardEntity = onClipboardEntity,
                onOtpAccept = onOtpAccept,
                onOtpDismiss = onOtpDismiss,
                snippetPanel = snippetPanel,
                reply = reply,
                onToolTap = onToolTap,
                onToolbarToolsChange = onToolbarToolsChange,
                onToolboxOrderChange = onToolboxOrderChange,
                toolHold = toolHold,
                onToolboxHintDismiss = onToolboxHintDismiss,
                onWeatherRefresh = onWeatherRefresh,
                onCameraSend = onCameraSend,
                onCameraPermissionRequest = onCameraPermissionRequest,
                onScannedInsert = onScannedInsert,
                onScannedShare = onScannedShare,
                onScannedUrlOpen = onScannedUrlOpen,
                onVoiceToggle = onVoiceToggle,
                onVoicePermissionRequest = onVoicePermissionRequest,
                onVoiceUndo = onVoiceUndo,
                onVoiceModelDownload = onVoiceModelDownload,
                onWhisperTranslateToggle = onWhisperTranslateToggle,
                onOpenVoiceSettings = onOpenVoiceSettings,
                onVoiceUseSystemEngine = onVoiceUseSystemEngine,
                onVoiceRailKey = onVoiceRailKey,
                onMediaPlayPause = onMediaPlayPause,
                onMediaNext = onMediaNext,
                onMediaPrevious = onMediaPrevious,
                onMediaSeek = onMediaSeek,
                onMediaAccessRequest = onMediaAccessRequest,
                onMediaResume = onMediaResume,
                onDictionaryLookup = onDictionaryLookup,
                onDictionarySearchToggle = onDictionarySearchToggle,
                onDictionaryInsert = onDictionaryInsert,
                onThemeSelect = onThemeSelect,
                onAppColorPick = onAppColorPick,
                onAppColorStyle = onAppColorStyle,
                onIconPackSelect = onIconPackSelect,
                onEmojiFontSelect = onEmojiFontSelect,
                onFontSelect = onFontSelect,
                onSoundHaptic = onSoundHaptic,
                onHandwritingStroke = onHandwritingStroke,
                onKeyboardHandwritingStroke = onKeyboardHandwritingStroke,
                onHandwritingUndo = onHandwritingUndo,
                onHandwritingDownload = onHandwritingDownload,
                onMediaQueryTap = onMediaQueryTap,
                onMediaQueryClear = onMediaQueryClear,
                onMediaRetry = onMediaRetry,
                onGifSelect = onGifSelect,
                onGifSourceSelect = onGifSourceSelect,
                onGifCategorySelect = onGifCategorySelect,
                onMediaLongPress = onMediaLongPress,
                onStickerPackFilter = onStickerPackFilter,
                onStickerSaveToPack = onStickerSaveToPack,
                onGifFavouriteToggle = onGifFavouriteToggle,
                onMediaCopy = onMediaCopy,
                onMediaReport = onMediaReport,
                onMediaActionDismiss = onMediaActionDismiss,
                onWebResult = onWebResult,
                onWebResultOpen = onWebResultOpen,
                onImageResult = onImageResult,
                onImageResultLink = onImageResultLink,
                translateCallbacks = translateCallbacks,
                grammarCallbacks = grammarCallbacks,
                onWikiOpen = onWikiOpen,
                onWikiBack = onWikiBack,
                onWikiLoadLinks = onWikiLoadLinks,
                onWikiLoadFull = onWikiLoadFull,
                onSymbolInsert = onSymbolInsert,
                symbolRow = symbolRow,
                onFancyStyleSelect = onFancyStyleSelect,
                onModeSelect = onModeSelect,
                onToolInsert = onToolInsert,
                converter = converter,
                capture = capture,
                onPwSetting = onPwSetting,
                onTextRepeat = onTextRepeat,
                onTypingTestAction = onTypingTestAction,
                onSpeedTestAction = onSpeedTestAction,
                onQrSend = onQrSend,
                onAiAction = onAiAction,
                onAiReplace = onAiReplace,
                onAiInsert = onAiInsert,
                onAiRetry = onAiRetry,
                onAiRunCustom = onAiRunCustom,
                onAiPickModel = onAiPickModel,
                onAiToggleStripMarkdown = onAiToggleStripMarkdown,
                onAiSetShowDiff = onAiSetShowDiff,
                onAiReport = onAiReport,
                onOpenToolSettings = onOpenToolSettings,
                onOpenRoute = onOpenRoute,
                onPluginOpen = onPluginOpen,
                onPluginBack = onPluginBack,
                onPluginEvent = onPluginEvent,
                onPluginInputFocus = onPluginInputFocus,
                onPluginPaste = onPluginPaste,
                onPluginCopy = onPluginCopy,
                launcher = launcher,
            )
            CaretMagnifierHost(toolHold.caretMagnifier.state)
        }
    }

    // The body is emitted from several mutually exclusive places below — docked,
    // one-handed left, one-handed right, floating — and every one of them is a
    // different slot in the composition. Called plainly, moving between them is
    // a dispose plus a fresh compose, which throws away everything the open
    // panel remembered: toggling the floating keyboard from the toolbox sent
    // its grid back to the top, and the same went for every other panel's
    // scroll, search field and pager page.
    //
    // movableContent makes the move a move: the nodes and their remembered
    // state travel to the new parent intact. The lambda is remembered once (it
    // has to be, or it is a new content identity every frame), so it reads the
    // live `body` through a holder rather than capturing the one it was born
    // with. `body` is structurally identical every recomposition, so calling
    // the latest instance at the same slot keeps the remembers inside it.
    val currentBody by rememberUpdatedState(body)
    val movableBody = remember {
        movableContentWithReceiverOf<ColumnScope, KeyboardUiState> { bodyState ->
            currentBody(bodyState)
        }
    }

    // The locals that never change with the state, provided once for the
    // whole keyboard. [body] travels between the frame's slots as movable
    // content and resolves them from wherever it lands, all of which are
    // inside this.
    CompositionLocalProvider(
        LocalKeyPreviewState provides keyPreview,
        LocalKeyPressFeedback provides remember(onKeyPressed) {
            { onKeyPressed(KeySoundTarget.DEFAULT) }
        },
        LocalHapticFeedback provides onHaptic,
        LocalKeySound provides remember(onKeySound) {
            { onKeySound(KeySoundTarget.DEFAULT, KeySoundPhase.PRESS) }
        },
        LocalKeyRoleFeedback provides onKeyPressed,
        LocalKeyRoleSound provides onKeySound,
        LocalClipboardKeyAction provides onClipboardKey,
        LocalAlternatesGate provides remember { AlternatesGate() },
        LocalRestGate provides remember { RestGate() },
        // The ?123 chords (#754): where the held ?123 and the tapped key meet.
        LocalChordGate provides remember { ChordGate() },
        // Text selection over the tools' text and the keyboard's own
        // fields (#352): the one selection up, and what its bar calls.
        LocalSelectionOverlay provides remember { SelectionOverlayState() },
        LocalOctopusPick provides onOctopusPick,
        LocalPossessiveFlick provides onPossessiveFlick,
        LocalOctopusOccupancy provides remember { OctopusOccupancy() },
        // Where the last panel opener was pressed, for the panel it opens to
        // grow out of (see [PanelMotionSlot]).
        LocalPanelOrigins provides remember { PanelOrigins() },
        LocalSelectionHold provides toolHold.onSelectionHold,
        LocalSendAction provides toolHold.send.onAction,
        LocalAiSuggest provides toolHold.aiSuggest,
        LocalCanDelete provides canDelete,
        LocalCanDeleteField provides canDeleteField,
        LocalCanForwardDelete provides canForwardDelete,
        LocalDeleteSwipe provides deleteSwipe,
        LocalCursorMoveVertical provides onCursorMoveVertical,
        LocalSpaceTouchpad provides remember { SpaceTouchpad() },
        LocalCaretDrag provides toolHold.caretMagnifier.onDrag,
        LocalPanelOverKeysHeight provides toolHold.onPanelOverKeysHeight,
        LocalFullBleedHeight provides toolHold.onFullBleedHeight,
        LocalHideKeyboard provides onHideKeyboard,
        LocalLanguageSwitchEcho provides languageSwitchEcho,
        // Held behind a stable lambda: the service hands a fresh reference on
        // every pass, and a static local that changes recomposes every key.
        LocalOpenRoute provides rememberUpdatedState(onOpenRoute).let { latest ->
            remember { { route: String -> latest.value(route) } }
        },
        LocalTouchExploration provides rememberTouchExploration(),
        LocalPassthroughService provides
            KeyboardPassthrough.serviceConnected.collectAsState().value,
        LocalPanelFocus provides panelFocus,
        LocalLiveUiState provides stateHolder,
    ) {
        KeyboardScreenFrame(
            stateHolder = stateHolder,
            keyPreview = keyPreview,
            languageSwitchEcho = languageSwitchEcho,
            panelFocus = panelFocus,
            body = movableBody,
            onKey = onKey,
            onText = onText,
            onLayoutSelect = onLayoutSelect,
            onToolTap = onToolTap,
            onVoiceToggle = onVoiceToggle,
            onVoiceUndo = onVoiceUndo,
            onVoicePermissionRequest = onVoicePermissionRequest,
            onOpenVoiceSettings = onOpenVoiceSettings,
            onVoiceRailKey = onVoiceRailKey,
            onOneHanded = onOneHanded,
            onOneHandedSide = onOneHandedSide,
            onFloatingChange = onFloatingChange,
            onFloatingMoved = onFloatingMoved,
            onSizingAction = onSizingAction,
            onFloatingBounds = onFloatingBounds,
            onWindowHeadroom = onWindowHeadroom,
            onHandwritingStroke = onHandwritingStroke,
            onHandwritingUndo = onHandwritingUndo,
            onHandwritingDownload = onHandwritingDownload,
            onSuggestion = onSuggestion,
            onPanelChange = onPanelChange,
        )
    }
}

/**
 * The ui state as the service last published it, for the composables that
 * draw the per-keystroke fields ([withLiveTyping]). Null outside the
 * keyboard itself (a preview), where the state handed down is all there is.
 */
internal val LocalLiveUiState = staticCompositionLocalOf<State<KeyboardUiState>?> { null }

/**
 * This state with the fields that change on almost every keystroke cleared:
 * the strip's words and emoji, the composing preview, the next-letter bias and
 * the word a space would commit. Measured on device, these were the only
 * fields that differ between frames while typing a word, and every one of
 * those frames recomposed the whole keyboard. Readers of them go through
 * [withLiveTyping]. The same instance when there is nothing to clear.
 */
internal fun KeyboardUiState.withoutTypingFields(): KeyboardUiState =
    if (suggestions.isEmpty() && emojiSuggestions.isEmpty() && composingPreview.isEmpty() &&
        nextLetterBias.isEmpty() && autocorrectWord == null
    ) {
        this
    } else {
        copy(
            suggestions = emptyList(),
            emojiSuggestions = emptyList(),
            composingPreview = "",
            nextLetterBias = emptyMap(),
            autocorrectWord = null,
        )
    }

/** [this] with [live]'s per-keystroke fields put back; see [withoutTypingFields]. */
private fun KeyboardUiState.withTypingFrom(live: KeyboardUiState): KeyboardUiState =
    copy(
        suggestions = live.suggestions,
        emojiSuggestions = live.emojiSuggestions,
        composingPreview = live.composingPreview,
        nextLetterBias = live.nextLetterBias,
        autocorrectWord = live.autocorrectWord,
    )

/**
 * [state] with the per-keystroke fields read live. Calling this subscribes the
 * caller, and only the caller, to every publish of the state: use it at the
 * top of the composables that draw those fields, never above them.
 */
@Composable
internal fun withLiveTyping(state: KeyboardUiState): KeyboardUiState {
    val live = LocalLiveUiState.current ?: return state
    // A board drawn as a picture inside the keyboard (a theme or layout card)
    // shows its own sample words, not what is being typed.
    if (LocalKeyboardPreviewHost.current) return state
    val now = live.value
    return remember(
        state, now.suggestions, now.emojiSuggestions, now.composingPreview,
        now.nextLetterBias, now.autocorrectWord,
    ) {
        val same = state.suggestions === now.suggestions &&
            state.emojiSuggestions === now.emojiSuggestions &&
            state.composingPreview == now.composingPreview &&
            state.nextLetterBias === now.nextLetterBias &&
            state.autocorrectWord == now.autocorrectWord
        if (same) state else state.withTypingFrom(now)
    }
}

/** [LocalConversionReadings]'s value, read from the live state; see [withLiveTyping]. */
@Composable
private fun rememberConversionReadings(state: KeyboardUiState): State<List<String>> {
    val live = LocalLiveUiState.current
    if (live == null) {
        return rememberUpdatedState(
            if (state.composingPreview.isEmpty() && state.captureSuggestions.isEmpty()) {
                emptyList()
            } else {
                state.conversionReadings
            },
        )
    }
    // Derived, and read where the readings are drawn: the composing preview
    // moves with every key, and reading it here would recompose the body.
    return remember(live) {
        derivedStateOf {
            val now = live.value
            if (now.composingPreview.isEmpty() && now.captureSuggestions.isEmpty()) {
                emptyList()
            } else {
                now.conversionReadings
            }
        }
    }
}

/**
 * The per-keystroke half of [KeyboardScreen]: reads the state, resolves the
 * settings for the screen and the theme, and hands the body to the floating or
 * docked frame. Split off so the function every keystroke recomposes is small
 * enough for ART to compile; see the note at the top of [KeyboardScreen]'s body.
 */
@Composable
private fun KeyboardScreenFrame(
    stateHolder: State<KeyboardUiState>,
    keyPreview: KeyPreviewState,
    languageSwitchEcho: LanguageSwitchEcho,
    panelFocus: PanelFocusController,
    body: @Composable ColumnScope.(KeyboardUiState) -> Unit,
    onKey: (Key) -> Unit,
    onText: (String) -> Unit,
    onLayoutSelect: (String) -> Unit,
    onToolTap: (ToolbarTool) -> Unit,
    onVoiceToggle: () -> Unit,
    onVoiceUndo: () -> Unit,
    onVoicePermissionRequest: () -> Unit,
    onOpenVoiceSettings: () -> Unit,
    onVoiceRailKey: (VoiceBarAction) -> Unit,
    onOneHanded: (OneHandedMode) -> Unit,
    onOneHandedSide: (Boolean, OneHandedSide) -> Unit,
    onFloatingChange: (Boolean) -> Unit,
    onFloatingMoved: (Float, Float) -> Unit,
    onSizingAction: (SizingAction) -> Unit,
    onFloatingBounds: (IntRect) -> Unit,
    onWindowHeadroom: (Int) -> Unit,
    // Full-screen handwriting (#386) draws in the frame, outside the body.
    onHandwritingStroke: (HwStroke, IntSize) -> Unit,
    onHandwritingUndo: () -> Unit,
    onHandwritingDownload: () -> Unit,
    onSuggestion: (String) -> Unit,
    onPanelChange: (PanelMode) -> Unit,
) {
    val movableBody = body
    LaunchedEffect(languageSwitchEcho.shown) {
        val shown = languageSwitchEcho.shown ?: return@LaunchedEffect
        delay(shown.ms)
        if (languageSwitchEcho.shown == shown) languageSwitchEcho.clear()
    }
    // The frame, and everything under it that takes the state, reads the state
    // with its per-keystroke fields left out ([withoutTypingFields]): typing a
    // letter changes nothing else, so the whole keyboard is no longer composed
    // again for it. The few composables that draw those fields read them live
    // ([withLiveTyping]), and only they recompose as you type.
    val structural = remember(stateHolder) {
        derivedStateOf(structuralEqualityPolicy()) { stateHolder.value.withoutTypingFields() }
    }
    val rawState by structural

    // Sizing is resolved once, here, for the screen shape we are actually
    // drawing on: a folded phone in landscape can want a shorter key than
    // the same phone upright, and a tablet wants neither. Everything below
    // reads `state.settings.keyHeightDp` as before and never learns that
    // screen variants exist.
    val configuration = LocalConfiguration.current
    val variant = ScreenVariant.of(
        landscape = configuration.orientation == Configuration.ORIENTATION_LANDSCAPE,
        // Smallest dimension, not the current width: a phone turned sideways
        // is wide but still a phone, while an opened foldable is wide either
        // way round.
        unfolded = configuration.smallestScreenWidthDp >= ScreenVariant.UNFOLDED_MIN_DP,
    )
    // Resolved on its own, and remembered on the settings rather than on the
    // whole state: the keys downstream take `settings` as a parameter and Compose
    // reads it as unstable (it is full of lists and maps), so it is compared by
    // instance. Folding this into the state.copy below handed out a fresh
    // settings object on every keystroke whenever the variant had an override,
    // which is enough on its own to stop every key from skipping.
    //
    // Overlay order: the shape's own defaults first (a landscape phone starts
    // at a landscape-sized board, not a portrait one -- issue #251), then the
    // active theme's layout overrides, then the screen-variant sizing — a per-screen override the user set by hand is
    // more specific than the theme and wins. The spec here is resolved by the
    // same helpers KeyboardThemeProvider uses, so the theme that paints the
    // board and the one that reshapes it are always the same theme.
    // Before all of that: the grid on screen may name a theme of its own
    // (issue #61) — a layer's, else its layout's, resolved onto the compiled
    // grid. Laid over the settings first so the theme that then paints and
    // reshapes the board is that one; a grid naming nothing hands back the
    // same instance, so the remembers below keep their keys.
    // Through the remembered layout: `screenThemeId` builds the grid afresh —
    // every key copied — and this line runs on every keystroke, where the
    // grid it asks about has not changed.
    val screenLayout = rememberCurrentLayout(rawState)
    val layerThemeId = screenThemeId(rawState, screenLayout)
    val baseSettings = remember(rawState.settings, layerThemeId) {
        rawState.settings.applyLayoutTheme(layerThemeId)
    }
    val systemDark = isSystemInDarkTheme()
    val darkSlot = rememberAutoThemeDarkSlot(baseSettings, systemDark)
    val activeSpec = remember(baseSettings, darkSlot) {
        baseSettings.activeThemeSpec(darkSlot)
    }
    val layoutSizing = screenLayout.appearance?.takeIf { it.sizesBoard }
    val settings = remember(baseSettings, variant, activeSpec, layoutSizing) {
        baseSettings.applyScreenDefaults(variant).applyThemeOverrides(activeSpec)
            .applyLayoutSizing(layoutSizing).resolvedFor(variant)
    }
    // The layout's own font, which is deliberately NOT part of that chain. The
    // chain produces one KeyboardSettings for the whole board, and a layout's
    // type is per grid: its label size is per *layer* on top of that, and rides
    // the compiled KeyboardLayout down to the keys instead (see keyVisual). Only
    // the font is layout-wide, so only the font is read here.
    val layoutFontId = remember(rawState.settings.customLayouts, rawState.layoutId) {
        resolveLayout(rawState.settings.customLayouts, rawState.layoutId).appearance?.fontId
    }
    // The inline resize tool's live preview. Stored-space values, folded in
    // AFTER the resolve so a drag previews exactly what Done would persist;
    // null (resting, and every non-resize frame) short-circuits to the same
    // `settings` instance, so the block above keeps its skipping behaviour.
    val resizePreview = remember { mutableStateOf<ResizeValues?>(null) }
    LaunchedEffect(rawState.resize) { if (!rawState.resize) resizePreview.value = null }
    val preview = if (rawState.resize) resizePreview.value else null
    val previewScale = if (preview == null) 1f else {
        rawState.settings.sizingOverrides[variant]?.keyboardScale ?: 1f
    }
    val shown = remember(settings, preview, previewScale) {
        if (preview == null) settings else settings.withResizePreview(preview, previewScale)
    }
    val state = remember(rawState, shown) { rawState.withSettings(shown) }
    val autoBottomPadding = autoBottomPaddingDp(gestureBarAtBottom())
    val resizeSession = if (!rawState.resize) null else {
        remember(rawState.settings, variant, resizePreview, autoBottomPadding) {
            val values = rawState.settings.sizingValuesFor(variant)
            val scale = values.keyboardScale ?: 1f
            val entry = ResizeValues(
                keyHeightDp = values.keyHeightDp ?: rawState.settings.keyHeightDp,
                numberRowHeightDp = values.numberRowHeightDp
                    ?: rawState.settings.numberRowHeightDp,
                bottomPaddingDp = values.bottomPaddingDp ?: rawState.settings.bottomPaddingDp
                    ?: autoBottomPadding,
                sidePadLeft = values.sidePadLeftScale
                    ?: rawState.settings.layoutBehavior.sidePadLeftScale,
                sidePadRight = values.sidePadRightScale
                    ?: rawState.settings.layoutBehavior.sidePadRightScale,
            )
            // How much taller the keyboard could get from here: the frame
            // reserves this on entry so nothing under the finger moves during
            // a drag (see ResizeSession.headroomDp).
            val gridDp = { v: ResizeValues ->
                keyRowsHeight(
                    rawState.copy(
                        settings = settings.copy(
                            keyHeightDp = (v.keyHeightDp * scale).roundToInt(),
                            numberRowHeightDp = (v.numberRowHeightDp * scale).roundToInt(),
                        ),
                    ),
                ).value
            }
            val tallest = entry.copy(
                keyHeightDp = SettingsRepository.KEY_HEIGHT_MAX_DP,
                numberRowHeightDp = SettingsRepository.KEY_HEIGHT_MAX_DP,
            )
            val headroomDp = (
                (gridDp(tallest) - gridDp(entry)) +
                    (SettingsRepository.MAX_BOTTOM_PADDING_DP - entry.bottomPaddingDp)
                ).roundToInt().coerceAtLeast(0)
            ResizeSession(
                entry = entry,
                keyboardScale = scale,
                maxBottomPaddingDp = SettingsRepository.MAX_BOTTOM_PADDING_DP,
                headroomDp = headroomDp,
                preview = resizePreview,
                onCommit = { result ->
                    onSizingAction(resizeCommitAction(variant, entry, result))
                },
            )
        }
    }


    val rotationStates by PhotoBackgroundManager.rotationStates.collectAsState()
    val appColors by AppColors.current.collectAsState()
    KeyboardThemeProvider(
        settings = state.settings,
        rotationStates = rotationStates,
        appColors = appColors,
        layoutFontId = layoutFontId,
    ) {
        // The collapsed voice bar takes the whole window over: no keyboard, no
        // strips, just the pill. It outranks floating mode because it is the
        // temporary state — restoring the keyboard lands back in whichever
        // chrome the settings ask for.
        //
        // The two hand over with a slide, not a cut. Collapsing keeps the
        // keyboard composed while it slides down out of the window (the bar
        // enters beneath it with its own rise); restoring slides it back up
        // inside its own, already-resized window — the bar side is not kept
        // composed there, because its full-screen box would hold the window
        // tall and squeeze the app for the whole animation.
        val barTarget = voiceBarTakesWindow(state)
        val transitionTheme = LocalKbTheme.current
        val collapse = remember { Animatable(if (barTarget) 1f else 0f) }
        LaunchedEffect(barTarget, transitionTheme.reduceMotion) {
            val target = if (barTarget) 1f else 0f
            if (transitionTheme.reduceMotion) {
                collapse.snapTo(target)
            } else if (collapse.value != target) {
                collapse.animateTo(
                    target,
                    tween(VoiceBarTransitionMs, easing = FastOutSlowInEasing),
                )
            }
        }
        val chromeHeight = remember { mutableIntStateOf(0) }
        Box(contentAlignment = Alignment.BottomCenter) {
            if (barTarget) {
                VoiceBarLayer(
                    state = state,
                    onToggle = onVoiceToggle,
                    onUndo = onVoiceUndo,
                    onRequestPermission = onVoicePermissionRequest,
                    onOpenVoiceSettings = onOpenVoiceSettings,
                    onRestoreKeyboard = { onToolTap(ToolbarTool.VOICE) },
                    onAction = onVoiceRailKey,
                )
            }
            // The keyboard stays composed until the slide has fully carried it
            // out. Judged from the animation's value, not a flag an effect
            // sets: an effect runs after the composition that flipped the
            // target, so a flag unmounted the keyboard for one frame and
            // remounted it — a visible blink right as the slide began. The
            // short-circuit keeps the value unread (no per-frame recompose)
            // whenever the keyboard is staying anyway.
            if (!barTarget || collapse.value < 1f) {
                Box(
                    modifier = Modifier
                        .onSizeChanged { chromeHeight.intValue = it.height }
                        // Draw-phase read: the slide costs redraws, never a
                        // recomposition per frame.
                        .graphicsLayer {
                            translationY = collapse.value * chromeHeight.intValue
                        },
                ) {
                    if (handwritingFullScreen(state)) {
                        // Full-screen handwriting (issue #386) outranks both
                        // chromes: the canvas is the whole window and the
                        // keyboard is a small bar on top of it.
                        HandwritingFullScreen(
                            state = state,
                            onStroke = onHandwritingStroke,
                            onUndoStroke = onHandwritingUndo,
                            onDownloadModel = onHandwritingDownload,
                            onKey = onKey,
                            onSuggestion = onSuggestion,
                            onClose = { onPanelChange(PanelMode.HANDWRITING) },
                        )
                    } else if (state.settings.floatingKeyboard) {
                        // Floating mode: the compose root spans the whole IME
                        // window with no background; the service restricts the
                        // touchable region to the panel so everything else
                        // falls through to the app behind.
                        //
                        // No window blur here: the window spans the screen, so
                        // a blur would soften the whole app. Hiding the host
                        // tells the glass so, and the board falls back to the
                        // theme's fallback opacity (or the wallpaper backdrop)
                        // instead of sitting see-through on a sharp app.
                        CompositionLocalProvider(LocalWindowFrost provides NoWindowFrost) {
                            FloatingKeyboardFrame(
                                state = state,
                                onDock = { onFloatingChange(false) },
                                onMoved = onFloatingMoved,
                                onResized = { widthDp, heightScale ->
                                    onSizingAction(SizingAction.Floating(widthDp, heightScale))
                                },
                                onBounds = onFloatingBounds,
                                keyPreview = keyPreview,
                                keyGridFocus = panelFocus.keyGrid,
                                onRingKey = onKey,
                                onRingText = onText,
                                content = { heightScale ->
                                    // Key height carries the whole layout (panels
                                    // included), so scaling it scales the
                                    // keyboard's height.
                                    val scaled = if (heightScale == 1f) {
                                        state
                                    } else {
                                        state.withKeyHeights(
                                            (state.settings.keyHeightDp * heightScale).roundToInt(),
                                            (state.settings.numberRowHeightDp * heightScale).roundToInt(),
                                        )
                                    }
                                    movableBody(scaled)
                                },
                            )
                        }
                    } else {
                        DockedKeyboardFrame(
                            state = state,
                            landscape =
                                configuration.orientation == Configuration.ORIENTATION_LANDSCAPE,
                            onOneHanded = onOneHanded,
                            onOneHandedSide = onOneHandedSide,
                            resize = resizeSession,
                            keyPreview = keyPreview,
                            keyGridFocus = panelFocus.keyGrid,
                            onRingKey = onKey,
                            onRingText = onText,
                            onWindowHeadroom = onWindowHeadroom,
                            body = movableBody,
                        )
                    }
                }
            }
        }
    }
}

/** How long the keyboard takes to slide out for the voice bar, or back in. */
private const val VoiceBarTransitionMs = 260

/**
 * Paints [color] behind one bar row, or nothing when the theme leaves the bar
 * on the board. Null has to stay a no-op rather than a transparent fill: the
 * board underneath may be a gradient, a photo or an animation, and a drawn
 * fill would be a lid over all three.
 */
@Composable
private fun Modifier.barRowFill(color: Color?): Modifier =
    // Glass first, so the bar's own fill tints the backdrop slice under it.
    // A bar with no fill of its own still gets the glass: the theme asked
    // for the bars to be panes, and a pane with no tint is a clear one.
    frostGlass(LocalKbTheme.current, RectangleShape, FrostSurface.BARS)
        .then(if (color == null) Modifier else Modifier.background(color))

/**
 * Docked chrome: the board background plus the width, alignment and
 * one-handed arrangement around the keyboard body — the everyday counterpart
 * of [FloatingKeyboardFrame].
 */
@Composable
private fun DockedKeyboardFrame(
    state: KeyboardUiState,
    landscape: Boolean,
    onOneHanded: (OneHandedMode) -> Unit,
    onOneHandedSide: (Boolean, OneHandedSide) -> Unit,
    resize: ResizeSession? = null,
    keyPreview: KeyPreviewState,
    /** Where a television remote is pointing, drawn over the whole frame. */
    keyGridFocus: KeyGridFocus,
    /** What the ring's own long-press popup commits with; see [RingAlternatesPopup]. */
    onRingKey: (Key) -> Unit,
    onRingText: (String) -> Unit,
    onWindowHeadroom: (Int) -> Unit = {},
    body: @Composable ColumnScope.(KeyboardUiState) -> Unit,
) {
    // In resize mode the outer frame reserves the session's headroom and the
    // keyboard box sits at its bottom, so the window changes height once on
    // entry and the keyboard's own box is the only thing that changes size
    // frame to frame — the drag never moves its own origin. The band is kept
    // out of the app's insets (see [windowBandPx]), so the app does not move.
    val density = LocalDensity.current
    // The empty band above the board where a top-row bubble goes: the height
    // the bubbles ask for, and — once the measure pass has weighed it against
    // the window — the height they actually got.
    // Only a host with a window behind the band holds one; see [KeyPreviewBandMode].
    // A blurred window blurs all of itself, the empty band above the board
    // included, and that band sits over the app's field: with the window
    // blurred the bubble stays on the board instead, as in the editor preview.
    // So it does when the band is switched off, for the floating app windows
    // that dodge the whole IME window rather than its insets (#614).
    val bandMode = LocalKeyPreviewBand.current.let { mode ->
        if (mode == KeyPreviewBandMode.WINDOW &&
            (!state.settings.popup.windowBand || windowFrostLive(LocalKbTheme.current))
        ) {
            KeyPreviewBandMode.INSIDE
        } else {
            mode
        }
    }
    val wantedHeadroomPx = keyPreviewHeadroomPx(state.settings)
    val previewHeadroomPx =
        if (bandMode == KeyPreviewBandMode.WINDOW) wantedHeadroomPx else 0
    val previewBand = remember { KeyPreviewBand() }
    var frameOrigin by remember { mutableStateOf(Offset.Zero) }
    var frameSize by remember { mutableStateOf(IntSize.Zero) }
    val configuration = LocalConfiguration.current
    val headroomPx = resize?.let { with(density) { it.headroomDp.dp.roundToPx() } } ?: 0
    // The key-preview band sits above the reserved frame in the same window,
    // so the two together have to fit the tallest window there can be (#669).
    val windowMaxPx = rememberImeWindowMaxHeightPx()
    val maxReservedPx = with(density) {
        (configuration.screenHeightDp * RESIZE_MAX_SCREEN_SHARE).dp.roundToPx()
    }.coerceAtMost(windowMaxPx - previewHeadroomPx)
    // A bar row growing in or shrinking away is held the same way, for as long
    // as it is moving (see [RowRevealHeadroom]). The rows hear of it through a
    // local, since the body is the keyboard's movable content and its parameter
    // list is sealed. Resize mode keeps its own headroom instead: the frame is
    // already holding still there.
    val revealHeadroom = remember { RowRevealHeadroom() }
    // The same room `bottomRoom` below pads under the body, for the bottom key
    // row to take as touch area (#649).
    val boardBottomRoom = with(density) { navigationBarInsets().getBottom(this).toDp() } +
        bottomPaddingDp(state.settings).dp
    val revealingBody: @Composable ColumnScope.(KeyboardUiState) -> Unit = { bodyState ->
        CompositionLocalProvider(
            LocalRowRevealHeadroom provides revealHeadroom,
            LocalBoardBottomRoom provides boardBottomRoom,
        ) { body(bodyState) }
    }
    // The empty bands, reported to the service, which keeps them out of the
    // app's insets. Watched rather than read here: the reserved band changes as
    // a row opens and closes, and reading it in the composition would recompose
    // the whole frame on the very frame the row starts moving. A snapshot flow
    // sees the write from the layout pass that made it and delivers after the
    // frame, which is also where the service's requestLayout belongs. Resize
    // mode's frame holds its own band in place of the rows' (issue #643).
    LaunchedEffect(revealHeadroom, previewBand, onWindowHeadroom, resize) {
        snapshotFlow {
            previewBand.heldPx + (resize?.windowBandPx() ?: revealHeadroom.windowPx)
        }.collect { onWindowHeadroom(it) }
    }
    // Two boxes: the frame proper under its band, and the bubbles over the
    // lot. The band is on the inner one so the outer one's size, which the
    // overlay matches, takes it in; the position is read on the outer one,
    // which is always here, rather than on an overlay that is only in the
    // tree while a key is down.
    //
    // Both modifiers are remembered, and that is load-bearing. This frame
    // recomposes on every keystroke (it takes the state), and a `layout { }`
    // or `onGloballyPositioned { }` built in the composition is a new lambda
    // each time, which Compose reads as a changed modifier: the node is
    // measured again, and since the keyboard is sized by its content all the
    // way up, that reached the window as a full layout pass — two or three
    // of them per key on a phone, measured, with the keys, strip and toolbar
    // all measured again each time. Remembered, a keystroke measures only
    // what it actually changed.
    val outerFrameModifier = remember {
        Modifier
            .fillMaxWidth()
            .onGloballyPositioned {
                frameOrigin = it.positionInRoot()
                frameSize = it.size
            }
    }
    val innerFrameModifier = remember(previewHeadroomPx, previewBand, resize, revealHeadroom) {
        Modifier
            .fillMaxWidth()
            .keyPreviewHeadroom(previewHeadroomPx, previewBand)
            .then(
                if (resize == null) {
                    Modifier.rowRevealHeadroom(revealHeadroom)
                } else {
                    Modifier.resizeHeadroom(resize)
                },
            )
    }
    Box(modifier = outerFrameModifier) {
        Box(modifier = innerFrameModifier) {
            if (resize != null) {
                ResizeHeadroomScrim()
                ResizeWindowFit(resize)
            }
            // Rounded corners cut out of the whole board, the app showing
            // through them. Not on a television, whose card rounds itself, and
            // not while resizing, whose outline chrome runs to the corners.
            val behavior = state.settings.layoutBehavior
            val boardShape = remember(behavior.boardCornerTopDp, behavior.boardCornerBottomDp, behavior.boardCorners) {
                boardCornerShape(behavior)
            }.takeUnless {
                resize != null || (state.television && state.settings.oneHandedModeFor(landscape) == OneHandedMode.OFF)
            }
            // The board softens under an open glass popup (see PopupBackdrop).
            // Remembered: this frame recomposes per keystroke, and the layer's
            // own block reads the count, so a popup opening touches no measure.
            val popupBackdrop = LocalPopupBackdrop.current
            val popupBlur = remember(popupBackdrop) { Modifier.popupBackdropBlur(popupBackdrop) }
            val boardContext = LocalContext.current
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .align(Alignment.BottomCenter)
                    .then(if (boardShape == null) Modifier else Modifier.clip(boardShape))
                    .then(popupBlur)
                    // The box the background image is cropped to; the theme
                    // editor's cropper frames the picture in this shape.
                    .onSizeChanged { KeyboardBoardShape.record(boardContext, it, landscape) }
                    .then(
                        if (resize == null) Modifier else Modifier.onSizeChanged {
                            resize.latchReserved(it.height, headroomPx, maxReservedPx)
                        },
                    ),
            ) {
                // A television draws the board as a card over the app (see
                // [TelevisionCard]) and paints its own background, so the
                // sides beside it stay clear.
                val card = state.television && state.settings.oneHandedModeFor(landscape) == OneHandedMode.OFF
                if (!card) {
                    BoardBackground(LocalKbTheme.current)
                    // Under the keys and over the board, so a theme that gives the
                    // gesture bar a colour of its own paints only that band (#109).
                    NavigationBarBackground(LocalKbTheme.current)
                }
                // Below Android 15 the band above is never reached -- the IME
                // window stops short of the bar -- so the window itself is
                // asked for the colour instead (#255).
                SystemNavigationBarColor(LocalKbTheme.current)
                // The app behind the window, blurred for a glass theme. Only
                // the docked frame asks: the floating window spans the screen.
                WindowFrostEffect(
                    LocalKbTheme.current,
                    // The blur's outline takes one radius for all four corners;
                    // the board's top one is the one that shows.
                    boardCornerDp = behavior.boardCornerTopDp.takeIf {
                        BoardCorner.TOP_LEFT in behavior.boardCorners || BoardCorner.TOP_RIGHT in behavior.boardCorners
                    } ?: 0,
                )
                // Same trick for the inline-autofill chips: the service builds
                // their presentation spec long before this composition runs, so
                // the resolved colours are reported out to it (#250).
                InlineChipPaletteReport(LocalKbTheme.current)
                // Through the orientation: portrait-only one-handed (#503) is
                // off here when the phone is sideways, whatever is stored.
                val oneHanded = state.settings.oneHandedModeFor(landscape)
                val ohProfile = state.settings.oneHanded.forLandscape(landscape)
                // Entering, leaving or flipping one-handed mode slides the board
                // from where it was to where it now docks, instead of the keys
                // jumping sideways. The layout switches at once (the keys are
                // already the new width, and taps already land on them); only
                // the drawing starts displaced, in the same composition, and
                // settles. Measured as the body's centre, a share of the row.
                val alignment = state.fieldAlignment ?: state.settings.keyboardAlignment
                val bodyCenter =
                    dockedBodyCenter(state.settings, alignment, oneHanded, ohProfile.widthPercent)
                val lastBodyCenter = remember { floatArrayOf(Float.NaN) }
                // Not into resize mode, which leaves one-handed mode on its way in:
                // its outline is drawn at the settled arrangement and holds still.
                val slide = remember(oneHanded) {
                    val from = lastBodyCenter[0]
                    val still = from.isNaN() || state.settings.reduceMotion || resize != null
                    Animatable(if (still) 0f else from - bodyCenter)
                }
                // Kept current between mode changes too, so a width changed in
                // settings is where the next slide starts from.
                lastBodyCenter[0] = bodyCenter
                LaunchedEffect(slide) {
                    slide.animateTo(0f, tween(OneHandedSlideMs, easing = FastOutSlowInEasing))
                }
                // A start-to-end share, so a right-to-left row moves the other way.
                val slideSign = if (LocalLayoutDirection.current == LayoutDirection.Rtl) -1f else 1f
                // The navigation bar's inset keeps the bottom key row clear of
                // the gesture-navigation bar on edge-to-edge (SDK 35+) IME
                // windows, read from the window's own record of it rather than
                // Compose's, which could stay at zero after a keyboard switch
                // (#463, #468; see [ImeNavigationBars]);
                // the bottom padding is extra breathing room above it,
                // adjustable in Settings → Appearance. Both are the board's own
                // room, so the card takes them inside itself and runs down to
                // the screen's edge.
                // The window runs under a camera cutout (issue #370), so the
                // board is painted to the screen's edge; the keys stay clear of
                // the cutout's strip, sideways only — a phone held upright has
                // it above the window, not beside the keys.
                val bottomRoom = Modifier
                    .windowInsetsPadding(WindowInsets.displayCutout.only(WindowInsetsSides.Horizontal))
                    .windowInsetsPadding(navigationBarInsets())
                    .padding(bottom = bottomPaddingDp(state.settings).dp)
                Row(
                    modifier = Modifier
                        .fillMaxWidth()
                        .then(if (card) Modifier else bottomRoom)
                        // Read in the draw phase: the slide repaints, it never
                        // recomposes the keyboard. Key positions follow the
                        // layer as it moves, so they are exact once it settles.
                        .graphicsLayer { translationX = slide.value * size.width * slideSign },
                    verticalAlignment = Alignment.Bottom,
                ) {
                    // Flip to the other side: update the live mode and remember the
                    // new side as this orientation's default.
                    val flipSide: () -> Unit = {
                        val next =
                            if (oneHanded == OneHandedMode.LEFT) OneHandedSide.RIGHT
                            else OneHandedSide.LEFT
                        onOneHandedSide(landscape, next)
                        onOneHanded(next.toMode())
                    }
                    if (oneHanded == OneHandedMode.OFF) {
                        // Resizable width: below 100% the keyboard shrinks and sits
                        // at the chosen edge (or centered).
                        // Side-padding (A50) shaves an equal fraction off each side
                        // on top of the width setting, narrowing the keys toward the
                        // centre for thumb reach; it rides on the same slack/centering
                        // machinery below.
                        val arrangement = dockedWidthArrangement(state.settings, alignment)
                        if (arrangement.leftSlack > 0.001f) {
                            Spacer(modifier = Modifier.weight(arrangement.leftSlack))
                        }
                        if (card) {
                            TelevisionCard(modifier = Modifier.weight(arrangement.widthFraction)) {
                                Column(modifier = Modifier.fillMaxWidth().then(bottomRoom)) {
                                    revealingBody(state)
                                }
                            }
                        } else {
                            Column(modifier = Modifier.weight(arrangement.widthFraction)) { revealingBody(state) }
                        }
                        if (arrangement.rightSlack > 0.001f) {
                            Spacer(modifier = Modifier.weight(arrangement.rightSlack))
                        }
                    } else {
                        // One-handed: dock to the live side with this orientation's
                        // width and height scale. The weights sum to 1 so the body
                        // is exactly `widthFraction` of the screen and any leftover
                        // beyond the rail becomes centre-ward slack.
                        val widthFraction = oneHandedWidthFraction(ohProfile.widthPercent)
                        val leftover = 1f - widthFraction
                        val railWeight = ONE_HANDED_RAIL_WEIGHT.coerceAtMost(leftover)
                        val slack = (leftover - railWeight).coerceAtLeast(0f)
                        val ohState = if (ohProfile.heightScale >= 100) {
                            state
                        } else {
                            state.withKeyHeights(
                                (state.settings.keyHeightDp * ohProfile.heightScale / 100).coerceAtLeast(1),
                                (state.settings.numberRowHeightDp * ohProfile.heightScale / 100).coerceAtLeast(1),
                            )
                        }
                        val rail = @Composable {
                            OneHandedRail(
                                current = oneHanded,
                                onFlip = flipSide,
                                onExit = { onOneHanded(OneHandedMode.OFF) },
                                modifier = Modifier.weight(railWeight),
                            )
                        }
                        if (oneHanded == OneHandedMode.RIGHT) {
                            if (slack > 0.001f) Spacer(modifier = Modifier.weight(slack))
                            rail()
                            Column(modifier = Modifier.weight(widthFraction)) { revealingBody(ohState) }
                        } else {
                            Column(modifier = Modifier.weight(widthFraction)) { revealingBody(ohState) }
                            rail()
                            if (slack > 0.001f) Spacer(modifier = Modifier.weight(slack))
                        }
                    }
                }
                // Last in the keyboard box, so the chrome floats over the dimmed
                // keyboard. The service turns one-handed mode off before entering the
                // resize mode, so the overlay only ever mirrors the plain docked
                // arrangement.
                if (resize != null) ResizeOverlay(session = resize, state = state)
            }
        }
        KeyPreviewOverlay(
            keyPreview,
            state.settings,
            frameOrigin,
            frameSize,
            modifier = Modifier.matchParentSize(),
            // No band held, but the host lets the bubble out: anchor it as if
            // the band were there and draw it above the frame, which is where
            // the service's own band puts it.
            virtualHeadroom = bandMode == KeyPreviewBandMode.OUTSIDE,
        )
        // Where the remote is pointing (a television, normally). Drawn at the
        // frame rather than inside the key grid because the ring also lands on
        // the suggestion strip and the toolbar, which are above the keys and
        // outside the grid's own canvas — one clipped to the keys would simply
        // stop drawing the moment the ring left them.
        // Not while a panel is open: the panel owns the arrow keys then (its
        // own ring is what moves), and the keys this one was standing on are
        // behind it.
        if (state.settings.hardwareKeyboard.dpadKeyNavigation && state.panel == PanelMode.NONE) {
            KeyFocusRing(keyGridFocus, state.settings) { frameOrigin }
            RingAlternatesPopup(
                focus = keyGridFocus,
                popup = state.settings.popup,
                onKey = onRingKey,
                onText = onRingText,
                shifted = state.shiftState != ShiftState.OFF,
                origin = { frameOrigin },
            )
        }
    }
}

/**
 * The band the frame is actually holding above the board right now, decided in
 * the measure pass ([keyPreviewHeadroom]) rather than asked for in composition.
 *
 * A measure-written piece of snapshot state, like [RowReveal]'s two: the
 * service has to be told the band it really got, because that is the part of
 * the window it keeps out of the host app's insets. Telling it the band the
 * settings *wanted* would lay the app out as if the keyboard were the
 * difference shorter, and hide that much of the app behind the keys.
 */
internal class KeyPreviewBand {
    var heldPx by mutableIntStateOf(0)
}

/**
 * Where a top-row preview bubble goes, which is a question about the host
 * rather than about the theme.
 *
 * The service has a window: the band is empty window above the board, kept out
 * of the host app's insets, so the bubble drawn in it appears over the app and
 * the board loses nothing. A host that simply places the keyboard inside its
 * own layout — the theme editor's preview — has no such window. Room held
 * there is dead space in that host's UI, and on a scaled miniature it is space
 * the board itself could have been drawn in: the band is a fixed ~130dp, which
 * on the editor's pinned strip was a third of the whole budget and shrank the
 * board to half the width it had room for.
 */
internal enum class KeyPreviewBandMode {
    /** Hold the band inside the frame, and draw the bubble in it. */
    WINDOW,

    /**
     * No band; a bubble that wants one is drawn above the frame, over whatever
     * the host has put there. What the service's band looks like from outside,
     * for a host whose own content sits above the board and does not clip it.
     */
    OUTSIDE,

    /**
     * No band, and nothing may be drawn past the frame either: the bubble is
     * clamped to the board's top edge instead, over the row above its key. For
     * a host that clips the keyboard to its own bounds, where an escaping
     * bubble would be cut in half rather than seen.
     */
    INSIDE,
}

/**
 * True under a host that draws the board as a picture of the keyboard rather
 * than as the keyboard: the theme editor's preview and the layout cards on a
 * language's screen. Such a board still draws and animates exactly as the real
 * one, but publishes nothing process-wide that the real keyboard owns.
 */
internal val LocalKeyboardPreviewHost = staticCompositionLocalOf { false }

/** How the host wants the key-preview band handled; see [KeyPreviewBandMode]. */
internal val LocalKeyPreviewBand = staticCompositionLocalOf { KeyPreviewBandMode.WINDOW }

/**
 * Told where every key's visible face was laid out, for a host that needs the
 * board's geometry rather than its touches: the theme editor's image-size guide
 * (issue #397), which measures the real board so its templates match any
 * layout and sizing. Null everywhere else, which is every real keyboard, so the
 * keys pay one null check per layout pass and nothing per keystroke.
 */
internal val LocalKeyFaceProbe = staticCompositionLocalOf<((KeyVisual, LayoutCoordinates) -> Unit)?> { null }

/**
 * Holds up to [px] of empty space above the frame's content: the band a top-row
 * bubble is drawn in. Window height, not keyboard height — the service
 * subtracts it from the app's insets (see [keyPreviewHeadroomPx]).
 *
 * "Up to", because the band is held out of the window's *leftover* and never
 * out of the board's own room (issue #251). The child is measured against the
 * whole window and the band is whatever is still free afterwards, capped at the
 * height the bubbles asked for.
 *
 * Taking the band first was the bug. It is a fixed dp figure — a 34sp on-key
 * label plus its gaps, around 130dp — which is a comfortable slice of a phone
 * held upright and better than a third of the same phone turned sideways. The
 * board was handed the window minus that slice, had no way to say it did not
 * fit, and simply overflowed: on a landscape phone the bottom two key rows were
 * measured, drawn past the window's edge and clipped away.
 *
 * Still one measure pass, not two: a child given the whole window reports the
 * height it actually wants whenever it fits, and when it does not fit there is
 * no leftover to hold anyway, so the same number answers both.
 */
private fun Modifier.keyPreviewHeadroom(px: Int, band: KeyPreviewBand): Modifier =
    if (px <= 0) {
        band.heldPx = 0
        this
    } else {
        layout { measurable, constraints ->
            val inner = constraints.copy(
                minHeight = (constraints.minHeight - px).coerceAtLeast(0),
            )
            val placeable = measurable.measure(inner)
            val held = if (constraints.hasBoundedHeight) {
                (constraints.maxHeight - placeable.height).coerceIn(0, px)
            } else {
                px
            }
            band.heldPx = held
            layout(placeable.width, placeable.height + held) { placeable.place(0, held) }
        }
    }

/**
 * The most of the screen the resize mode's reserved frame may take: a tall
 * keyboard on a short screen still leaves the host app something to show.
 */
private const val RESIZE_MAX_SCREEN_SHARE = 0.8f

/**
 * How the docked keyboard's width settings become Row weights: the keyboard
 * takes [widthFraction] of the window with [leftSlack]/[rightSlack] of empty
 * space around it. Shared with [ResizeOverlay] so the resize outline hugs
 * exactly the rectangle the keys are laid out in.
 */
internal class DockedWidthArrangement(
    val widthFraction: Float,
    val leftSlack: Float,
    val rightSlack: Float,
)

internal fun dockedWidthArrangement(
    settings: KeyboardSettings,
    alignment: KeyboardAlignment = settings.keyboardAlignment,
): DockedWidthArrangement {
    // Issue #41: the two edges are padded independently, so each one is claimed
    // before the alignment gets a say. Whatever the width setting leaves over
    // after both pads is the free space alignment then distributes, which makes
    // the pads mean the same thing docked left, centred or right. Equal pads on
    // a centred board resolve to exactly what the old symmetric slider gave.
    val padLeft = settings.layoutBehavior.sidePadLeftScale.coerceIn(0f, 0.3f)
    val padRight = settings.layoutBehavior.sidePadRightScale.coerceIn(0f, 0.3f)
    val widthFraction =
        (settings.keyboardWidthPercent / 100f * (1f - padLeft - padRight)).coerceAtLeast(0.2f)
    val free = (1f - widthFraction - padLeft - padRight).coerceAtLeast(0f)
    val leftSlack = padLeft + when (alignment) {
        KeyboardAlignment.LEFT -> 0f
        KeyboardAlignment.CENTER -> free / 2f
        KeyboardAlignment.RIGHT -> free
    }
    return DockedWidthArrangement(widthFraction, leftSlack, 1f - widthFraction - leftSlack)
}

/**
 * The docked board on a television: a card with rounded top corners and a
 * soft shadow, standing on the bottom edge of the screen, with the app left
 * visible on either side of it. It is how Gboard draws itself on Android TV,
 * and it is what the width setting's slack is for there — on a phone the
 * slack beside a narrowed board is still board, painted, because a thumb
 * resting on it should not reach the app behind; a television has no thumb.
 *
 * The card paints the theme itself ([BoardBackground]), so an image, gradient
 * or animation is clipped to it rather than spread across the whole screen.
 * The theme's navigation-bar colour is left out: a TV draws no bar.
 */
@Composable
private fun TelevisionCard(modifier: Modifier, content: @Composable () -> Unit) {
    val shape = RoundedCornerShape(topStart = TelevisionCardCorner, topEnd = TelevisionCardCorner)
    Box(modifier = modifier.shadow(TelevisionCardElevation, shape, clip = true)) {
        BoardBackground(LocalKbTheme.current)
        content()
    }
}

/**
 * The docked board's outline from its corner settings, or null while every
 * corner is square, so the default board takes no clip at all. Left and right
 * are the screen's, whatever the language's direction, since the corners are
 * where the screen's are.
 */
internal fun boardCornerShape(behavior: LayoutBehaviorSettings): Shape? {
    val top = behavior.boardCornerTopDp.coerceIn(BoardCornerRadiusRange)
    val bottom = behavior.boardCornerBottomDp.coerceIn(BoardCornerRadiusRange)
    fun radius(corner: BoardCorner, dp: Int): Int = if (corner in behavior.boardCorners) dp else 0
    val topLeft = radius(BoardCorner.TOP_LEFT, top)
    val topRight = radius(BoardCorner.TOP_RIGHT, top)
    val bottomLeft = radius(BoardCorner.BOTTOM_LEFT, bottom)
    val bottomRight = radius(BoardCorner.BOTTOM_RIGHT, bottom)
    if (topLeft == 0 && topRight == 0 && bottomLeft == 0 && bottomRight == 0) return null
    return AbsoluteRoundedCornerShape(
        topLeft = topLeft.dp,
        topRight = topRight.dp,
        bottomRight = bottomRight.dp,
        bottomLeft = bottomLeft.dp,
    )
}

/** Corner radius of [TelevisionCard]'s two top corners. */
private val TelevisionCardCorner = 12.dp

/** How far [TelevisionCard]'s shadow reaches over the app beside it. */
private val TelevisionCardElevation = 12.dp

/** How long the floating panel takes to fade up once it has been placed. */
private const val FloatingAppearMs = 160

/** The share of the row a one-handed board takes, from its width setting. */
private fun oneHandedWidthFraction(widthPercent: Int): Float = (widthPercent / 100f).coerceIn(0.30f, 0.90f)

/**
 * Where the docked keyboard body's centre sits, as a share of the row from its
 * start edge, for [mode]: the arrangement [DockedKeyboardFrame] lays out, read
 * back as one number so a change of mode can slide from one to the other. The
 * one-handed weights sum to one, the body first on the left and last on the
 * right, which is all the one-handed half needs.
 */
private fun dockedBodyCenter(
    settings: KeyboardSettings,
    alignment: KeyboardAlignment,
    mode: OneHandedMode,
    widthPercent: Int,
): Float =
    when (mode) {
        OneHandedMode.OFF -> dockedWidthArrangement(settings, alignment).let { it.leftSlack + it.widthFraction / 2f }
        OneHandedMode.LEFT -> oneHandedWidthFraction(widthPercent) / 2f
        OneHandedMode.RIGHT -> 1f - oneHandedWidthFraction(widthPercent) / 2f
    }

/** How long the board takes to slide into, out of, or across one-handed mode. */
private const val OneHandedSlideMs = 240

/**
 * The collapsed voice bar owns the window right now. A panel forced open (a
 * hardware shortcut can do this) or a password field puts the keyboard back
 * without disarming the bar. The service's insets check mirrors this
 * predicate — keep the two in step.
 */
private fun voiceBarTakesWindow(state: KeyboardUiState): Boolean =
    state.voice.bar && state.panel == PanelMode.NONE && !state.secureField

/**
 * Floating mode chrome: a detached, elevated panel holding the regular
 * keyboard body, movable by its drag handle and resizable from the corner
 * handle. Position is kept as fractions of the free space so it survives
 * rotation; width in dp. Both persist via the callbacks on gesture end.
 *
 * The handle bar sits under the keys by default, where the thumb already is
 * (#584), or above them with [KeyboardSettings.floatingHandle] set to top.
 */
@Composable
private fun FloatingKeyboardFrame(
    state: KeyboardUiState,
    onDock: () -> Unit,
    onMoved: (Float, Float) -> Unit,
    onResized: (Int, Float) -> Unit,
    onBounds: (IntRect) -> Unit,
    keyPreview: KeyPreviewState,
    /** Where a television remote is pointing, drawn over the floating panel. */
    keyGridFocus: KeyGridFocus,
    /** What the ring's own long-press popup commits with; see [RingAlternatesPopup]. */
    onRingKey: (Key) -> Unit,
    onRingText: (String) -> Unit,
    content: @Composable ColumnScope.(Float) -> Unit,
) {
    // Where the bubbles' overlay sits in the root, read here since the
    // overlay itself is only in the tree while a key is down.
    var frameOrigin by remember { mutableStateOf(Offset.Zero) }
    var frameSize by remember { mutableStateOf(IntSize.Zero) }
    BoxWithConstraints(
        modifier = Modifier
            .fillMaxSize()
            // The window runs under the navigation bar. With the handle bar on
            // the panel's bottom edge (#584) a panel parked at the bottom put
            // the drag pill on the gesture strip, where a drag goes home
            // instead; held clear of it, the bar and the bottom keys both stay
            // the panel's.
            .windowInsetsPadding(navigationBarInsets())
            .onGloballyPositioned {
                frameOrigin = it.positionInRoot()
                frameSize = it.size
            },
    ) {
        val density = LocalDensity.current
        val boxWidthPx = constraints.maxWidth
        val boxHeightPx = constraints.maxHeight
        val maxWidthDp = (with(density) { boxWidthPx.toDp().value } - 16f)
            .coerceAtLeast(FLOATING_MIN_WIDTH_DP)

        // Panel size in px, written from layout. Never read during composition
        // — see the deferred reads below — so a resize settling over a couple
        // of layout passes does not drag the keyboard through a recomposition
        // for each one.
        val panelSize = remember { mutableStateOf(IntSize.Zero) }
        // Settled position in px, tagged with the window width it was pinned
        // in; null (or pinned in another width) = follow the persisted
        // fractions. A rotation changes the width, so the fractions re-anchor
        // the panel there.
        //
        // One state object for the frame's whole life, never re-keyed on the
        // box size (issue #342). The IME window measures its input view twice
        // per traversal against two different heights, so a height key minted
        // a fresh object on nearly every window layout — and the gesture
        // callbacks, which outlive a recomposition, went on writing the old
        // one. The placement then fell back to the fractions, still a DataStore
        // round trip behind: a release flashed the panel at its old spot for a
        // couple of frames, and a resize lost its pin and let the panel drift.
        val dragOffset = remember { mutableStateOf<FloatingPin?>(null) }
        // How far the finger has carried the panel away from [dragOffset] in
        // the gesture running right now, folded back into it when the gesture
        // ends. Read from the draw phase (the layer below), never from
        // placement, so following the finger costs a redraw per frame and no
        // window layout pass at all (issue #6).
        val dragShift = remember { mutableStateOf(Offset.Zero) }
        // Width is a layout input only, so it too is read from a measure
        // lambda rather than from composition: dragging the grip re-measures
        // the panel instead of recomposing the entire keyboard per frame.
        val liveWidthDp = remember(state.settings.floatingWidthDp) {
            mutableFloatStateOf(
                state.settings.floatingWidthDp.toFloat()
                    .coerceIn(FLOATING_MIN_WIDTH_DP, maxWidthDp),
            )
        }
        // Height is the one value a resize cannot keep out of composition: it
        // scales the key heights, which is a settings change. Quantised (see
        // the gesture below) so a drag costs a handful of recompositions
        // rather than one per frame.
        var liveHeightScale by remember(state.settings.floatingHeightScale) {
            mutableFloatStateOf(state.settings.floatingHeightScale)
        }
        // How much smaller everything in the panel is drawn (#967): labels,
        // hint letters, key icons, the toolbar and the toolbox, not only the
        // keys' height. Squeezed below its default width or its full height,
        // the panel used to shrink the keys around text and icons that stayed
        // their docked size. The smaller of the two shares, so a narrow but
        // tall panel shrinks as much as a short one; never more than full
        // size. Stepped, and read through a derived state, so a resize
        // recomposes the keyboard once per visible step and not per frame.
        val contentScale by remember(liveWidthDp, state.settings.floatingHeightScale) {
            derivedStateOf {
                val byWidth = liveWidthDp.floatValue / FLOATING_CONTENT_FULL_WIDTH_DP
                quantize(minOf(1f, byWidth, liveHeightScale), FLOATING_CONTENT_SCALE_STEP)
                    .coerceIn(FLOATING_MIN_HEIGHT_SCALE, 1f)
            }
        }
        // Everything a gesture needs but nothing else reads: kept off the
        // snapshot so touching it invalidates nothing.
        val gesture = remember { FloatingGesture() }

        fun slackX() = (boxWidthPx - panelSize.value.width).coerceAtLeast(0).toFloat()
        fun slackY() = (boxHeightPx - panelSize.value.height).coerceAtLeast(0).toFloat()
        fun pinned(): Offset? = dragOffset.value?.takeIf { it.boxWidthPx == boxWidthPx }?.offset
        fun pin(offset: Offset) {
            dragOffset.value = FloatingPin(offset, boxWidthPx)
        }
        fun currentOffset(): Offset {
            val raw = pinned() ?: Offset(
                state.settings.floatingXFraction * slackX(),
                state.settings.floatingYFraction * slackY(),
            )
            return Offset(raw.x.coerceIn(0f, slackX()), raw.y.coerceIn(0f, slackY()))
        }
        fun publishBounds() = gesture.bounds?.let(onBounds)
        // Persists [end] as fractions of the free space. The pin keeps the
        // panel where it is until the write comes back; see the effect below.
        fun persistPosition(end: Offset) {
            val moved = Offset(
                if (slackX() > 0f) end.x / slackX() else 0.5f,
                if (slackY() > 0f) end.y / slackY() else 0.5f,
            )
            val stored = Offset(state.settings.floatingXFraction, state.settings.floatingYFraction)
            // An unchanged value is never written back, so it must not be
            // waited for either.
            if (moved != stored) gesture.pendingPosition = moved
            onMoved(moved.x, moved.y)
        }

        // The pin outlives its own write, so a position stored from anywhere
        // else (the Layout screen's reset) has to drop it. Our own echoes are
        // skipped until the latest one arrives, including an older one landing
        // after a second drag has already written again.
        val storedPosition = Offset(state.settings.floatingXFraction, state.settings.floatingYFraction)
        LaunchedEffect(storedPosition) {
            val pending = gesture.pendingPosition
            when {
                pending == storedPosition -> gesture.pendingPosition = null
                pending == null && !gesture.active -> dragOffset.value = null
            }
        }

        // The panel fades up once it has been measured, rather than appearing
        // at full strength the frame after it was invisible. Opacity only: a
        // scale would move the bounds read below, which are the touchable region
        // the service hands the window.
        val appear = remember { Animatable(if (state.settings.reduceMotion) 1f else 0f) }
        LaunchedEffect(appear) {
            snapshotFlow { panelSize.value != IntSize.Zero }.first { it }
            appear.animateTo(1f, tween(FloatingAppearMs, easing = LinearOutSlowInEasing))
        }

        Surface(
            modifier = Modifier
                // Placement-scope read: moving the panel re-places one node.
                // Read at composition scope (the old `val offset = …`) it
                // recomposed the whole keyboard on every drag frame, which is
                // what made dragging feel like it was catching.
                .offset {
                    val o = currentOffset()
                    IntOffset(o.x.roundToInt(), o.y.roundToInt())
                }
                // Measure-scope read of the live width, for the same reason.
                .layout { measurable, constraints ->
                    val widthPx = with(density) {
                        liveWidthDp.floatValue.coerceIn(FLOATING_MIN_WIDTH_DP, maxWidthDp).dp.roundToPx()
                    }
                    val placeable = measurable.measure(
                        constraints.copy(minWidth = widthPx, maxWidth = widthPx),
                    )
                    layout(placeable.width, placeable.height) { placeable.place(0, 0) }
                }
                // Draw-scope reads, both of them. The live drag rides here
                // rather than on the offset above (see [dragShift]), and the
                // panel is invisible for the first frame, before it has been
                // measured and placed from real sizes — which avoids a flash
                // at a wrong position, and costs a redraw rather than a
                // recomposition.
                .graphicsLayer {
                    val shift = dragShift.value
                    translationX = shift.x
                    translationY = shift.y
                    alpha = if (panelSize.value == IntSize.Zero) 0f else appear.value
                    // Faded per draw rather than through a buffer the panel's
                    // size, so nothing at its edge is cut off while it rises.
                    compositingStrategy = CompositingStrategy.ModulateAlpha
                }
                .onGloballyPositioned { coords ->
                    panelSize.value = coords.size
                    val position = coords.positionInWindow()
                    gesture.bounds = IntRect(
                        offset = IntOffset(position.x.roundToInt(), position.y.roundToInt()),
                        size = coords.size,
                    )
                    // Publishing mid-gesture forces a decor-view layout pass
                    // per frame just to update the touchable region, and the
                    // region cannot matter while a finger is already captured.
                    // The end of the gesture publishes the settled bounds.
                    if (!gesture.active) publishBounds()
                },
            shape = RoundedCornerShape(18.dp),
            // The theme paints the panel (color + optional image); Surface
            // just supplies the shape, clip and shadow.
            color = Color.Transparent,
            shadowElevation = 10.dp,
        ) {
            Box {
                BoardBackground(LocalKbTheme.current)
                val handleAtBottom = state.settings.floatingHandle == FloatingHandlePosition.BOTTOM
                // One bar, placed above or below the keys; see the frame's KDoc.
                val handleBar: @Composable () -> Unit = {
                    FloatingHandleBar(
                        onDock = onDock,
                        onDragStart = {
                            gesture.active = true
                            // The panel's top-left is pinned in px for the whole
                            // drag, as it is for a resize: the shift below is
                            // measured from it, and the fractions it would
                            // otherwise fall back to are a DataStore round trip
                            // behind the finger.
                            pin(currentOffset())
                            dragShift.value = Offset.Zero
                        },
                        onDragBy = { delta ->
                            val base = pinned() ?: return@FloatingHandleBar
                            val shift = dragShift.value
                            // Clamped as a whole position, then stored back as a
                            // shift, so the panel stops at the window edge
                            // instead of the finger walking a shift off-screen.
                            dragShift.value = Offset(
                                (base.x + shift.x + delta.x).coerceIn(0f, slackX()) - base.x,
                                (base.y + shift.y + delta.y).coerceIn(0f, slackY()) - base.y,
                            )
                        },
                        onDragEnd = {
                            gesture.active = false
                            val base = pinned() ?: return@FloatingHandleBar
                            val shift = dragShift.value
                            val end = Offset(
                                (base.x + shift.x).coerceIn(0f, slackX()),
                                (base.y + shift.y).coerceIn(0f, slackY()),
                            )
                            // Hand the travel over to layout in one go: the
                            // offset takes the panel's new home and the shift
                            // returns to zero together, so both phases land in
                            // the same frame and the panel never blinks back.
                            pin(end)
                            dragShift.value = Offset.Zero
                            // The panel was never re-placed during the drag, so
                            // the measured rectangle is a whole gesture behind:
                            // move it by hand. Publishing it is also what forces
                            // the window layout pass that lands the offset above.
                            gesture.bounds = gesture.bounds?.translate(
                                (end.x - base.x).roundToInt(),
                                (end.y - base.y).roundToInt(),
                            )
                            publishBounds()
                            persistPosition(end)
                        },
                        onResizeStart = {
                            gesture.active = true
                            // The panel's own top-left is pinned for the whole
                            // resize. Left on the fractions it would slide as
                            // the slack shrank under it — the panel wandering
                            // away from the finger, which read as the resize
                            // being broken rather than as re-anchoring.
                            pin(currentOffset())
                            gesture.widthDp = liveWidthDp.floatValue
                            gesture.heightScale = liveHeightScale
                            // The unscaled height is measured once, here. Read
                            // per frame from the live panel it was a feedback
                            // loop: the size it divides by is a frame behind
                            // the scale it produced, so the grip accelerated
                            // away from the finger and oscillated.
                            gesture.baseHeightPx =
                                if (liveHeightScale > 0f) panelSize.value.height / liveHeightScale else 0f
                        },
                        onResizeBy = { delta ->
                            gesture.widthDp = (gesture.widthDp + with(density) { delta.x.toDp().value })
                                .coerceIn(FLOATING_MIN_WIDTH_DP, maxWidthDp)
                            // On the bottom bar the grip is the panel's bottom
                            // edge, which the pinned top-left lets follow the
                            // finger down. On the top bar dragging up (negative
                            // y) grows the panel instead, hence the sign.
                            if (gesture.baseHeightPx > 0f) {
                                val grow = if (handleAtBottom) delta.y else -delta.y
                                gesture.heightScale = (gesture.heightScale + grow / gesture.baseHeightPx)
                                    .coerceIn(FLOATING_MIN_HEIGHT_SCALE, FLOATING_MAX_HEIGHT_SCALE)
                            }
                            // Snapped before it reaches layout. The finger
                            // moves a pixel at a time; re-measuring a whole
                            // keyboard for a pixel is work nobody can see, and
                            // the height step keeps its recompositions down to
                            // one per visible change.
                            liveWidthDp.floatValue =
                                quantize(gesture.widthDp, FLOATING_WIDTH_STEP_DP)
                                    .coerceIn(FLOATING_MIN_WIDTH_DP, maxWidthDp)
                            liveHeightScale =
                                quantize(gesture.heightScale, FLOATING_HEIGHT_STEP)
                                    .coerceIn(FLOATING_MIN_HEIGHT_SCALE, FLOATING_MAX_HEIGHT_SCALE)
                        },
                        onResizeEnd = {
                            gesture.active = false
                            publishBounds()
                            onResized(liveWidthDp.floatValue.roundToInt(), liveHeightScale)
                            // The pin above is in px, so persist it too or the
                            // panel jumps back to the old fractions the next
                            // time they are applied.
                            val end = pinned() ?: return@FloatingHandleBar
                            persistPosition(end)
                        },
                    )
                }
                Column {
                    if (!handleAtBottom) handleBar()
                    // The keys keep the height the grip gave them: drawn at a
                    // smaller density, they are asked to be that much taller
                    // in its dp, and come out the same on screen.
                    val shrink = contentScale
                    val scaledDensity = remember(density, shrink) {
                        Density(density.density * shrink, density.fontScale)
                    }
                    CompositionLocalProvider(LocalDensity provides scaledDensity) {
                        content(liveHeightScale / shrink)
                    }
                    if (handleAtBottom) handleBar()
                }
            }
        }
        // The ring, over the panel wherever the panel has been dragged to. A
        // Canvas takes no pointers, so the touchable region the service carves
        // out for the floating board is unchanged — everything outside the
        // panel still falls through to the app.
        if (state.settings.hardwareKeyboard.dpadKeyNavigation && state.panel == PanelMode.NONE) {
            KeyFocusRing(keyGridFocus, state.settings) { frameOrigin }
            RingAlternatesPopup(
                focus = keyGridFocus,
                popup = state.settings.popup,
                onKey = onRingKey,
                onText = onRingText,
                shifted = state.shiftState != ShiftState.OFF,
                origin = { frameOrigin },
            )
        }
    }
}

/** Scratch state for one move/resize gesture. Deliberately not snapshot state. */
private class FloatingGesture {
    /** A finger is on the drag pill or the grip right now. */
    var active = false
    /** Latest measured panel bounds, published when the gesture ends. */
    var bounds: IntRect? = null
    /** Panel height at scale 1, measured once at the start of a resize. */
    var baseHeightPx = 0f
    /** Unsnapped width the finger has travelled to. */
    var widthDp = 0f
    /** Unsnapped height scale the finger has travelled to. */
    var heightScale = 1f
    /** Fractions last handed to the store and not yet read back from it. */
    var pendingPosition: Offset? = null
}

/** The floating panel's settled top-left in px, valid only in the window width it was set in. */
private data class FloatingPin(val offset: Offset, val boxWidthPx: Int)

private fun quantize(value: Float, step: Float): Float = (value / step).roundToInt() * step

// The one-handed rail's share of the screen width. Kept small so the body
// gets its full configured width; shrinks only if the width leaves less room.
private const val ONE_HANDED_RAIL_WEIGHT = 0.16f
private const val FLOATING_MIN_WIDTH_DP = 240f

/** The floating panel's width at which its contents are drawn at full size; the default width. */
private const val FLOATING_CONTENT_FULL_WIDTH_DP = 320f

/** The step the floating panel's content scale moves in; see `contentScale`. */
private const val FLOATING_CONTENT_SCALE_STEP = 0.05f
private const val FLOATING_MIN_HEIGHT_SCALE = 0.6f
private const val FLOATING_MAX_HEIGHT_SCALE = 1.6f

// Resize granularity. A pixel-exact resize re-measures (width) or recomposes
// (height) the whole keyboard for a change too small to see; these are the
// coarsest steps that still read as continuous under a moving finger.
private const val FLOATING_WIDTH_STEP_DP = 4f
private const val FLOATING_HEIGHT_STEP = 0.02f

/**
 * Handle row of the floating panel, under the keys or above them: dock button,
 * drag pill, resize grip.
 *
 * The two corner buttons are drawn as tool circles — same shape from the theme's
 * tool radius, same [KbTheme.toolCircle] fill, same [KbTheme.toolbarIcon] glyph
 * colour — because they sit directly above a keyboard full of them. Left on the
 * bare Material palette they were the only two things on the panel that ignored
 * the theme, and on anything but a plain grey board they read as leftovers from
 * another app.
 */
@Composable
private fun FloatingHandleBar(
    onDock: () -> Unit,
    onDragStart: () -> Unit,
    onDragBy: (Offset) -> Unit,
    onDragEnd: () -> Unit,
    onResizeStart: () -> Unit,
    onResizeBy: (Offset) -> Unit,
    onResizeEnd: () -> Unit,
) {
    // The drag detectors below are started once and outlive every
    // recomposition, so they call through to the latest callbacks. Holding the
    // first ones, they wrote to state the frame had since replaced (#342).
    val dragStart by rememberUpdatedState(onDragStart)
    val dragBy by rememberUpdatedState(onDragBy)
    val dragEnd by rememberUpdatedState(onDragEnd)
    val resizeStart by rememberUpdatedState(onResizeStart)
    val resizeBy by rememberUpdatedState(onResizeBy)
    val resizeEnd by rememberUpdatedState(onResizeEnd)
    val kb = LocalKbTheme.current
    val shape = kb.toolShape()
    val buttonFill = if (kb.toolRadiusDp > 0) kb.toolCircle else Color.Transparent
    // Same outline the tools on the bar wear, for the same reason the fill and
    // the shape are shared: these two buttons sit above a row of them.
    val buttonOutline = if (kb.toolBorder != null && kb.toolBorderWidthDp > 0f) {
        Modifier.border(kb.toolBorderWidthDp.dp, kb.toolBorder, shape)
    } else {
        Modifier
    }
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .height(FloatingHandleBarHeight)
            .padding(horizontal = 6.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        // Docking returns the full-width keyboard, so a fullscreen glyph reads
        // right; the old down-arrow looked like a download button.
        Box(
            modifier = Modifier
                .size(FloatingHandleButton)
                .background(buttonFill, shape)
                .then(buttonOutline)
                .clip(shape)
                .clickable(onClick = onDock),
            contentAlignment = Alignment.Center,
        ) {
            Icon(
                Icons.Outlined.Fullscreen,
                contentDescription = stringResource(R.string.ime_floating_dock_desc),
                modifier = Modifier.size(FloatingHandleGlyph),
                tint = kb.toolbarIcon,
            )
        }
        Box(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight()
                .pointerInput(Unit) {
                    detectDragGestures(
                        onDragStart = { dragStart() },
                        onDrag = { change, amount ->
                            change.consume()
                            dragBy(amount)
                        },
                        onDragEnd = { dragEnd() },
                        onDragCancel = { dragEnd() },
                    )
                },
            contentAlignment = Alignment.Center,
        ) {
            Box(
                modifier = Modifier
                    .width(48.dp)
                    .height(5.dp)
                    .background(kb.toolbarIcon.copy(alpha = 0.35f), RoundedCornerShape(2.5.dp)),
            )
        }
        Box(
            modifier = Modifier
                .size(FloatingHandleButton)
                .background(buttonFill, shape)
                .then(buttonOutline)
                .pointerInput(Unit) {
                    detectDragGestures(
                        onDragStart = { resizeStart() },
                        onDrag = { change, amount ->
                            change.consume()
                            resizeBy(amount)
                        },
                        onDragEnd = { resizeEnd() },
                        onDragCancel = { resizeEnd() },
                    )
                },
            contentAlignment = Alignment.Center,
        ) {
            // Classic grip lines instead of OpenInFull, whose diagonal
            // arrows read as a "go fullscreen" button rather than a
            // drag-to-resize handle.
            val gripColor = kb.toolbarIcon
            val resizeDesc = stringResource(R.string.ime_floating_resize_desc)
            Canvas(
                modifier = Modifier
                    .size(FloatingHandleGlyph)
                    .semantics { contentDescription = resizeDesc },
            ) {
                val stroke = 1.75.dp.toPx()
                drawLine(
                    gripColor,
                    Offset(size.width * 0.15f, size.height),
                    Offset(size.width, size.height * 0.15f),
                    stroke, cap = StrokeCap.Round,
                )
                drawLine(
                    gripColor,
                    Offset(size.width * 0.6f, size.height),
                    Offset(size.width, size.height * 0.6f),
                    stroke, cap = StrokeCap.Round,
                )
            }
        }
    }
}

private val FloatingHandleBarHeight = 38.dp
private val FloatingHandleButton = 32.dp
private val FloatingHandleGlyph = 19.dp

/** Side rail shown in one-handed mode: swap sides or return to full width. */
@Composable
private fun OneHandedRail(
    current: OneHandedMode,
    onFlip: () -> Unit,
    onExit: () -> Unit,
    modifier: Modifier = Modifier,
) {
    // The rail already followed the theme, through the Material scheme the
    // keyboard builds from it (see schemeFor), so this is not a fix for an
    // unthemed surface. What it could not do was differ from the board, which
    // is what a stylesheet states for it as its own element. The defaults are
    // the colours it already drew.
    val kb = LocalKbTheme.current
    Column(
        modifier = modifier.background(kb.oneHandedPanel),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center,
    ) {
        IconHint(stringResource(R.string.ime_one_handed_flip_desc)) {
            IconButton(onClick = onFlip) {
                Icon(
                    if (current == OneHandedMode.LEFT) {
                        Icons.AutoMirrored.Outlined.ArrowForward
                    } else {
                        Icons.AutoMirrored.Outlined.ArrowBack
                    },
                    contentDescription = stringResource(R.string.ime_one_handed_flip_desc),
                    tint = kb.oneHandedPanelIcon,
                )
            }
        }
        IconHint(stringResource(R.string.ime_one_handed_exit_desc)) {
            IconButton(onClick = onExit) {
                Icon(
                    Icons.Outlined.Fullscreen,
                    contentDescription = stringResource(R.string.ime_one_handed_exit_desc),
                    tint = kb.oneHandedPanelIcon,
                )
            }
        }
    }
}

// ---- top bar: suggestions or toolbar ----

/**
 * One duration for every toolbar transition: the strip/toolbar chevron
 * rotation, the back chevron's enter and exit, and the icon slides.
 *
 * They all fire off the same two taps — flip the bar, open a panel — so any
 * two that disagree read as one animation lagging the other rather than as
 * two separate animations. The icon slides used to run on a much softer
 * spring and were still travelling long after the chevron had settled.
 */
private const val ToolbarMotionMs = 140

/**
 * How long the surface leaving the bar — the tools, or the candidates — takes
 * to dissolve before the other one takes the row.
 *
 * Shorter than [ToolbarMotionMs] because it is spent before the flip rather
 * than during it: the whole exchange costs this plus the arrival, and a longer
 * exit would make a bar flip feel like it was waiting on something. Long enough
 * to read as a fade at 120Hz, which is all it has to be — the eye is following
 * the emoji, which does not fade and carries straight through the swap.
 */
private const val ToolbarExitMs = 90

/**
 * The matching spring for anything that slides within the toolbar. Tuned to
 * settle in about [ToolbarMotionMs] so it lands with the fades.
 */
private val ToolbarSlideSpring = spring(
    dampingRatio = Spring.DampingRatioNoBouncy,
    stiffness = Spring.StiffnessMedium,
    visibilityThreshold = IntOffset(1, 1),
)

/**
 * How far a re-placed icon may have travelled and still be animated, when
 * there is nothing better to size the limit against. Past this a move is
 * taken for a layout jump — a scroll, a page flip — and sliding to catch up
 * with one reads as lag, so it snaps instead.
 */
private const val PlacementSlideCap = 160f

/**
 * The same limit for an icon that lives in the toolbar, as a fraction of the
 * bar's width.
 *
 * A fixed cap is wrong there. The bar spreads its buttons over equal weighted
 * cells, so inserting one — the back chevron, when a panel opens — moves every
 * icon, and the leftmost moves the furthest: from the middle of the first cell
 * of n to the middle of the second of n+1. That is a quarter of the bar at its
 * worst (a bar holding only the toolbox button), well past [PlacementSlideCap]
 * on any phone. So the toolbox teleported into place on every panel open while
 * the icons beside it — which travel less the further right they sit — slid.
 * One icon snapping in a row of four sliding ones is the "jumpy" toolbar.
 *
 * Sized to clear that worst case with room to spare, while still refusing to
 * animate a move on the order of the whole bar.
 */
private const val ToolbarSlideCapFraction = 0.35f

/**
 * A vertical move larger than this means the row itself shifted rather than an
 * icon moving along it — a panel opened, the emoji row appeared or folded away.
 * Sliding into a row that has moved reads as lag, so those snap. Small enough
 * to ignore the sub-pixel rounding that weighted cells produce between passes.
 */
private const val ToolbarRowShiftPx = 4

/**
 * The strip's candidates fade in when they arrive and out when they leave,
 * rather than snapping. The fade-in is held a beat behind the emoji's slide
 * (the icon leads the eye into the strip) and runs long enough to read as a
 * fade rather than a flash; the fade-out is quicker, since it has to finish
 * inside the settle beat before the toolbar takes the row (see emptySettled).
 */
private const val StripContentStaggerMs = 45
private const val StripContentFadeInMs = 200
private const val StripContentFadeOutMs = 110

/**
 * How long the strip waits, after the candidates go empty, before it starts
 * hiding them. Fast typing empties the strip for a frame or two between
 * keystrokes (the engine clears then refills across the async compute), and
 * hiding on the first empty made the candidates pulse out and back in on every
 * keystroke. The hide is deferred by this beat; a fresh candidate landing
 * inside it cancels the pending hide, so a continuous typing burst never
 * flickers. Sized under the space of one relaxed keystroke so a genuine stop
 * still clears promptly.
 */
private const val StripHideDebounceMs = 180

/**
 * Issue-A tools fade: the toolbox and pinned tools materialise as the toolbar
 * takes over from the strip. Held back a beat so the emoji — which slides
 * across rather than fading — clears the toolbox slot first, instead of the
 * two overlapping mid-animation.
 */
private const val ToolbarToolsStaggerMs = 55

/**
 * Full-bleed return fade: the whole toolbar (emoji included) fades in when a
 * full-bleed panel closes and rebuilds the bar. Slower than the in-place
 * [ToolbarMotionMs] slide — nothing is moving to carry the eye, so a brisk
 * fade reads as an instant pop; a longer one lets the bar settle in.
 */
private const val FullBleedReturnFadeMs = 260

/**
 * The last candidates the strip actually drew, so a field that empties fades
 * them out instead of blanking.
 *
 * Deliberately not snapshot state: writing snapshot state from a composable
 * that reads it in the same pass is what forced the suggestion bar to compose
 * twice per keystroke. Nothing else observes these, and [TopBar] re-runs on
 * every publish of the ui state, so a plain object read in the pass that wrote
 * it is both correct and one composition cheaper.
 */
/**
 * These settings with the flick arms a layer asks for ([LayerSpec.flickHints],
 * #588) standing in for the keyboard-wide switch; the same object when the
 * layer has no say or agrees, so a grid that never sets it costs nothing.
 */
internal fun KeyboardSettings.withLayerFlickHints(layer: Boolean?): KeyboardSettings =
    if (layer == null || layer == layoutBehavior.flickHints) {
        this
    } else {
        copy(layoutBehavior = layoutBehavior.copy(flickHints = layer))
    }

private class HeldCandidates(state: KeyboardUiState) {
    var suggestions: List<String> = state.suggestions
        private set
    var emojiSuggestions: List<String> = state.emojiSuggestions
        private set
    var punctuation: List<String> = state.punctuationSuggestions
        private set
    var inlineEmoji: Boolean = state.inlineEmoji
        private set

    /**
     * Whether [suggestions] are a conversion IME's candidates, which draw as
     * the packed, scrolling candidate row. Taken with the list it describes:
     * switching from English to Japanese flips the composer while the English
     * words are still on the strip, and drawing those through the candidate
     * row for the length of their fade-out slid them left and resized them
     * (#587). It moves only when a new list arrives.
     */
    var conversion: Boolean = state.composer.isConversion
        private set

    fun advance(state: KeyboardUiState) {
        if (state.suggestions !== suggestions) conversion = state.composer.isConversion
        suggestions = state.suggestions
        emojiSuggestions = state.emojiSuggestions
        punctuation = state.punctuationSuggestions
        inlineEmoji = state.inlineEmoji
    }
}

@Composable
private fun TopBar(
    barState: KeyboardUiState,
    /**
     * Whether the tools' own row is open, when the placement gives them one. The
     * bar reads the placement off the settings itself; only the row's open state
     * has to come in, because the row is drawn by the caller.
     */
    toolsRowOpen: Boolean = false,
    onToolsRowToggle: () -> Unit = {},
    onSuggestion: (String) -> Unit,
    /**
     * A word on the strip was held rather than tapped (#28, #99). One bundle
     * and no menu state up here: the menu is the strip's own business, and
     * this call chain is already against the 64K method ceiling — which is
     * why the hold's five actions arrive as [SuggestionHoldCallbacks] rather
     * than as parameters.
     */
    suggestionHold: SuggestionHoldCallbacks = SuggestionHoldCallbacks(),
    onJoinSuggestion: () -> Unit = {},
    onRevisionSuggestion: () -> Unit = {},
    /** A conversion candidate tapped, with its position — see Composer.consumedForIndex. */
    onCandidate: (String, Int) -> Unit = { text, _ -> onSuggestion(text) },
    /** Open the expanded candidate grid. */
    onCandidatesExpand: () -> Unit = {},
    onEmoji: (String) -> Unit,
    onEmojiSuggestion: (String, Boolean) -> Unit,
    onPunctuation: (String) -> Unit = {},
    onPanelChange: (PanelMode) -> Unit,
    onToolTap: (ToolbarTool) -> Unit,
    drag: ToolDragController,
    onVoiceToggle: () -> Unit = {},
    onVoiceUndo: () -> Unit = {},
    onVoicePermissionRequest: () -> Unit = {},
    onOpenVoiceSettings: () -> Unit = {},
    /** The strip's collapse and close buttons; the one slot [VoiceBarAction] rides. */
    onVoiceAction: (VoiceBarAction) -> Unit = {},
    onDismissInlineSuggestions: () -> Unit = {},
    onSmartAccept: () -> Unit = {},
    onSmartOpen: () -> Unit = {},
    /** The vocabulary chips' callbacks; rides [ToolHoldCallbacks] on the way here. */
    vocab: VocabCallbacks = VocabCallbacks(),
    /** The stickers offered while typing, for the two styles that draw on the strip (#329). */
    stickerOffer: StickerOfferCallbacks = StickerOfferCallbacks(),
    onStripOfferAction: (StripOfferAction) -> Unit = {},
    onClipboardSuggestion: (ClipItem) -> Unit = {},
    onClipboardSuggestionDismiss: () -> Unit = {},
    onRecentClipsToggle: () -> Unit = {},
    onClipboardEntity: (ClipEntity) -> Unit = {},
    onOtpAccept: (NotificationOtp) -> Unit = {},
    onOtpDismiss: () -> Unit = {},
    onEmojiRowShown: () -> Unit = {},
    /** Downward flick on the strip: dismiss the keyboard (opt-in). */
    onSwipeDownHide: () -> Unit = {},
) {
    // The strip is what typing changes: this is where the live fields come in.
    val state = withLiveTyping(barState)
    // "Show the toolbar instead" while suggestions are up; resets once the
    // suggestions go away so the bar returns to candidates next time.
    var toolbarOverride by remember { mutableStateOf(false) }
    // Button-mode emoji row: a toolbar toggle swaps the strip for emojis.
    var emojiBarOpen by remember { mutableStateOf(false) }
    // A smart chip counts as strip content: without it the bar would flip
    // to the toolbar the moment word candidates ran out, taking the answer
    // to what was just typed with it. The recently-copied paste chip counts
    // the same way, so an idle strip holds it instead of flipping to the tools.
    val recentClipChip = state.settings.clipboard.suggestRecent && state.clipboardSuggestion != null
    // The row of the last few copies (#414), which holds the strip the same
    // way the single chip does. Only up when asked for (#612), and down again
    // at the first key typed, its ✕, or the next field.
    val recentClipsBar = state.recentClipsOpen &&
        state.clipboardItems.any { it.kind.isTextual && !it.sensitive && it.text.isNotBlank() }
    // Suggestions-first mode keeps the strip as the resting state (an empty
    // strip plus the chevron into the toolbar); the override then survives
    // idle gaps and instead resets when fresh candidates arrive.
    val suggestionsFirst = state.settings.suggestionStrip.suggestionsFirst && state.settings.suggestions
    // An empty field predicts its first word (#119), so the strip always had
    // words at rest and turning "Suggestion strip always visible" off did
    // nothing. With it off those openers do not exist (#629): the toolbar
    // rests, the chevron is not offered for them, and the first key moves the
    // caret off the start, at which point the candidates take the row as they
    // always did.
    // The same goes for the openers after a sentence end or at the start of a
    // new line (#889): a new line is not the line above going on, and the
    // toolbar is what someone starting one reaches for.
    // Not in an email field, where the strip only ever holds addresses: the
    // remembered ones are offered at the start of the field on purpose (#475).
    val atSentenceStart = state.caretAtFieldStart ||
        (state.suggestions.isNotEmpty() && state.suggestions == state.sentenceOpeners)
    val openersAtRest = !suggestionsFirst && atSentenceStart &&
        state.fieldKind != FieldKind.EMAIL &&
        state.composingPreview.isEmpty() &&
        (state.suggestions.isNotEmpty() || state.emojiSuggestions.isNotEmpty())
    val hasSuggestions =
        (!openersAtRest && (state.suggestions.isNotEmpty() || state.emojiSuggestions.isNotEmpty())) ||
        state.smart != null || recentClipChip || recentClipsBar ||
        // Stickers a typed word asked for, in the styles that draw them here.
        stickerStripShows(state) ||
        // The one-time-code chip counts as strip content for the same reason
        // the paste chip does: it lands exactly when nothing is being typed.
        state.otpSuggestion != null ||
        // A task that has fallen due waits for just that moment too.
        state.todoDueChip != null ||
        // So does a snippet waiting to be let in: a pattern's offer arrives on
        // the space that ends a sentence, which is precisely when the word
        // candidates are gone and the toolbar would otherwise take the row.
        state.snippetOffers != null ||
        // And so does a word asking to be learned: it arrives on the space
        // that ended the word, with the candidates for that word gone.
        state.learnOffer != null ||
        // As does the sandbox ladder's chip, which arrives at the same moment
        // and in the same place.
        state.sandboxOffer != null ||
        // And the chip pointing at a word list glide typing is missing, which
        // is up while nothing is being typed.
        state.glideWordListOffer != null ||
        // And its conversion twin, which now also goes up as the layout does,
        // before anything is typed.
        state.conversionPackOffer != null ||
        // And the Zawgyi chip, which lands on a paste or on entering a field,
        // both moments with nothing being typed.
        state.zawgyiOffer != null ||
        // And the one offering a swiped word's path to the whole dictionary,
        // which is up while the caret rests inside that word (#135).
        state.glideSearchChip != null ||
        // A morse sequence being tapped out counts as strip content: the
        // toolbar taking the row would hide the one live view of the chord.
        // Its SOS easter-egg note counts the same way, or the toolbar would
        // cover the joke in the exact pause it appears in.
        state.morsePending.isNotEmpty() || state.braillePending.isNotEmpty() || state.morseSosEgg ||
        // Inline chips count too, in both lanes. Neither arrives while the user
        // is typing — a login field has no word candidates and a smart reply
        // comes before you have written anything — so without this the toolbar
        // would be the resting view exactly when the chips land, and they would
        // only ever be seen by someone who had turned the suggestion bar on
        // permanently.
        state.autofillChips.isNotEmpty() || state.smartReplyChips.isNotEmpty() ||
        // The password manager chip (#1003), for the same reason: it is up
        // exactly when a login field has nothing else on the strip.
        state.showsPasswordManagerChip() ||
        // A Chinese reading kept out of the field (#973) is drawn here and
        // nowhere else, so it holds the row even before a candidate is found.
        (state.composingPreview.isNotEmpty() && state.readingInKeyboard())
    // The emoji panel is already all emojis — showing the row too would be
    // redundant, so opening the panel folds the row away.
    //
    // The fold is a derived flag read in the same pass, and the stored one is
    // cleared in an effect. Assigning to it inline instead wrote state that
    // this same composable reads further down, which forces a second
    // composition on the frame the panel opens — the row drew one frame at
    // its old size before folding, which is the flicker seen when the emoji
    // panel comes up.
    val emojiRowSuppressed =
        state.settings.emojiBarMode != EmojiBarMode.BUTTON || state.panel == PanelMode.EMOJI
    LaunchedEffect(emojiRowSuppressed) {
        if (emojiRowSuppressed) emojiBarOpen = false
    }
    // Committing a word can empty the strip for the moment it takes the
    // next-word predictions to land; flipping to the toolbar for that gap
    // makes the whole bar flicker on every space. The toolbar only takes
    // over once the strip has stayed empty for a beat.
    //
    // The beat is the hide debounce (which absorbs the typing-burst gaps, see
    // [StripHideDebounceMs]) plus the content fade-out, so the candidates
    // finish fading before the toolbar takes the row rather than being cut
    // mid-fade. During the debounce the strip still shows the last candidates
    // (held behind alpha 1), not an empty bar, so this no longer reads as the
    // keyboard stalling on a blank strip.
    var emptySettled by remember { mutableStateOf(true) }
    // One effect owns both the settle beat and the override reset, so the
    // override's live value can be read before it is cleared — two effects
    // racing on the same key left showToolbar reading a half-updated pair.
    LaunchedEffect(hasSuggestions) {
        if (hasSuggestions) {
            emptySettled = false
            // Suggestions-first rests on the strip, so a hand-opened toolbar
            // override only clears once fresh candidates actually arrive.
            if (suggestionsFirst) toolbarOverride = false
        } else {
            // Is the hand-opened toolbar the surface right now? Captured before
            // the reset just below clears it.
            val leavingOverrideToolbar = toolbarOverride && !suggestionsFirst
            // Candidates left: drop the override so the next ones show as
            // candidates again instead of staying hidden behind the toolbar.
            if (!suggestionsFirst) toolbarOverride = false
            if (leavingOverrideToolbar) {
                // Already on the toolbar the user opened by hand, and with no
                // suggestions the resting surface is the toolbar too — so hand
                // straight across, no settle gap. Delaying instead collapsed
                // the bar to an empty strip for that beat and bounced back: the
                // flip-flop that flung the emoji out to the row edge and popped
                // every other tool.
                emptySettled = true
            } else {
                delay((StripHideDebounceMs + StripContentFadeOutMs).toLong())
                emptySettled = true
            }
        }
    }
    // Where the tools live. With a row of their own this bar is the suggestion
    // strip and only that: the surface never flips, so the emoji handoff, the
    // dissolve and the settle beat below all sit at their resting values and cost
    // nothing. The chevron stays, as the opener for that row.
    val placement = state.settings.toolbarBehavior.placement
    // In a column beside the keys (#970) the tools are always on screen, the
    // way an always-open row keeps them: the bar never flips and has no
    // chevron to offer.
    val toolsColumn = toolsColumnSide(state) != null
    val toolsOwnRow = placement.isOwnRow || toolsColumn
    // With a row of their own the tools are on screen at the same time as this
    // strip, so anything the strip would duplicate from that row stays off.
    val toolsRowVisible = toolsColumn ||
        (toolsOwnRow && (placement == ToolbarPlacement.ALWAYS_ROW || toolsRowOpen))
    // Which way the chevron points for an own-row placement: towards the slot
    // the row takes in the bar order, since that is where it will appear.
    val barOrder = state.settings.barOrder
    val toolsRowAbove = barOrder.indexOf(BarRow.TOOLS) < barOrder.indexOf(BarRow.TOPBAR)
    // The number pad types into the field, and a snippet it triggers (#815)
    // is offered on the strip: the toolbar must not cover the chip (#876).
    val numpadOffer = state.panel == PanelMode.NUMPAD && state.snippetOffers != null
    val wantToolbar = !toolsOwnRow &&
        (
            (state.panel != PanelMode.NONE && !numpadOffer) || toolbarOverride ||
                (!hasSuggestions && emptySettled && !suggestionsFirst)
            )

    // The surface the bar is actually drawing, which lags [wantToolbar] by one
    // [ToolbarExitMs] fade.
    //
    // The two surfaces are branches of an `if`, so the one being replaced is
    // disposed on the frame the decision lands: seven tool icons, or a row of
    // candidates, gone between one frame and the next while the emoji — the one
    // thing that survives the swap — took another 140ms to slide into its new
    // spot. A single icon crawling across an otherwise empty bar is what reads
    // as the flip being broken. Holding the old surface for a short fade first
    // makes the exchange a dissolve, and the emoji's slide starts from a bar
    // that still had something in it.
    //
    // Not a Crossfade, and not both branches at once: the emoji exists in both
    // and hands its position from one node to the other (see [SharedPlacement]),
    // which needs the old node gone before the new one is placed.
    var showToolbar by remember { mutableStateOf(wantToolbar) }
    val barExit = remember { Animatable(1f) }
    LaunchedEffect(wantToolbar, state.settings.reduceMotion) {
        if (wantToolbar == showToolbar) {
            // Flipped back inside the fade — the surface that was leaving is
            // staying after all, so bring it back rather than leaving it dim.
            if (barExit.value != 1f) barExit.animateTo(1f, tween(ToolbarExitMs))
            return@LaunchedEffect
        }
        if (state.settings.reduceMotion) {
            barExit.snapTo(1f)
            showToolbar = wantToolbar
            return@LaunchedEffect
        }
        barExit.animateTo(0f, tween(ToolbarExitMs, easing = LinearEasing))
        showToolbar = wantToolbar
        // The arriving surface runs its own fade-in, so this goes back to
        // transparent-to-it on the same frame the swap happens.
        barExit.snapTo(1f)
    }

    // Previous toolbar state, advanced after each frame commits; drives the
    // synchronous reveal blank for the tools fade below.
    var prevShowToolbar by remember { mutableStateOf(showToolbar) }
    SideEffect { prevShowToolbar = showToolbar }

    // The strip renders [shownSuggestions]/[shownEmojiSuggestions] — the last
    // non-empty candidates — rather than the live state, so a cleared field
    // fades the old candidates out over [StripContentFadeOutMs] instead of
    // blanking them the instant state empties. They refresh whenever real
    // candidates arrive and are held (behind alpha 0) once they leave.
    val suggestionsShowing = state.suggestions.isNotEmpty() || state.emojiSuggestions.isNotEmpty()
    // Candidates are on screen only while the strip itself holds the row — not
    // when the toolbar or a panel does. The fade keys on this, not on the
    // candidates alone: candidates can already exist, hidden behind the
    // toolbar, so when the strip retakes the row (a toolbox close, the chevron
    // toggled back) they never "arrive" — a presence-keyed fade wouldn't fire
    // and they'd snap on at full strength over the still-sliding emoji.
    val stripContentVisible = !showToolbar && suggestionsShowing
    // Held in a plain object and advanced *here*, in the composition that sees
    // the new candidates, rather than in four snapshot states written from an
    // effect afterwards. That is the same hazard the emoji row above documents
    // (see [emojiRowSuppressed]) and it was costing more here: those writes
    // invalidated this composable, which had only just finished running, so
    // every keystroke composed the whole bar twice — the chevron's
    // AnimatedVisibility, the chip loops, and [LatinSuggestionChips], which is
    // a subcompose layout and the most expensive thing on the strip. This
    // composable takes the ui state and so re-runs on every publish, which is
    // what lets the values live outside the snapshot system without going
    // stale. The non-empty gate is unchanged: it is what holds the last
    // candidates on screen for the fade-out instead of blanking them.
    val held = remember { HeldCandidates(state) }
    if (state.suggestions.isNotEmpty() || state.emojiSuggestions.isNotEmpty()) {
        held.advance(state)
    }
    // Issue #84: while a stroke is still down, the strip can be held to the one
    // word the decode reads now instead of showing the whole candidate list
    // moving under the finger. Display only, and only while the stroke is live:
    // the lift puts the alternates back on the strip itself (see
    // `WMKeyboardService.onGesture`). Everything the row carries beside the
    // words — the rewrite chip, the emoji candidates, the punctuation marks —
    // stands down with them, since those are all left over from the word before
    // the stroke and "only the current word" is what the setting promises.
    val glideStripOnly = state.settings.gesture.stripPreviewOnly && state.glideWord != null
    val shownSuggestions = held.suggestions
    val shownEmojiSuggestions = if (glideStripOnly) emptyList() else held.emojiSuggestions
    // Held alongside the candidates: the fade-out must keep drawing the row it
    // faded in, or a cleared ":tada" buffer would flip the emoji back to text
    // chips for the length of the fade.
    val shownInlineEmoji = held.inlineEmoji
    // Punctuation chips are held alongside the words so they fade out with them
    // rather than blanking. The service only fills them when word candidates
    // are present, so they follow the same non-empty gate.
    val shownPunctuation = if (glideStripOnly) emptyList() else held.punctuation
    // Fade in when the strip shows its candidates, out when it stops. Keyed on
    // strip visibility (see [stripContentVisible]), so it fires both when
    // candidates land while the strip is up and when the strip retakes the row
    // from the toolbar with candidates already present — the latter used to
    // snap them on over the sliding emoji. It never re-fires mid-word, since
    // the engine updates candidates in place without emptying first. Initialised
    // to the current state so a strip that opens already showing doesn't fade in
    // from nothing.
    val stripContentAlpha = remember { Animatable(if (stripContentVisible) 1f else 0f) }
    LaunchedEffect(stripContentVisible, state.settings.reduceMotion) {
        if (state.settings.reduceMotion) {
            // No fade, but the hide still debounces so a typing-burst gap
            // doesn't blink the strip off and back on. Deferring a snap adds no
            // motion, so reduce-motion is honoured.
            if (stripContentVisible) {
                stripContentAlpha.snapTo(1f)
            } else {
                delay(StripHideDebounceMs.toLong())
                stripContentAlpha.snapTo(0f)
            }
        } else if (stripContentVisible) {
            // Let the emoji lead into the strip before the words follow. Linear
            // rather than the default eased curve, which front-loads the ramp
            // and made even a long fade read as an instant pop.
            delay(StripContentStaggerMs.toLong())
            stripContentAlpha.animateTo(1f, tween(StripContentFadeInMs, easing = LinearEasing))
        } else {
            // Defer the hide: the effect is keyed on visibility, so candidates
            // landing (or the strip retaking the row) inside the debounce cancel
            // this and restart the fade-in branch — the pulse fast typing caused.
            delay(StripHideDebounceMs.toLong())
            stripContentAlpha.animateTo(0f, tween(StripContentFadeOutMs, easing = LinearEasing))
        }
    }

    // The toolbar's tools are freshly composed when it takes over from the
    // strip, so [animatePlacement] settles them in place with no motion — they
    // would pop while the emoji (which hands its position across) slides. So
    // they fade in instead. Two shapes:
    //
    //  - In-place strip→toolbar flip: the emoji slides its position across (its
    //    throughline), and the other tools fade in held a beat behind so the
    //    icon clears the toolbox slot first (see [ToolbarToolsStaggerMs]). The
    //    surviving node keeps its old alpha of 1, so [toolbarJustRevealed]
    //    blanks its first frame rather than the initial value below.
    //
    //  - Fresh mount (returning from a full-bleed gif/emoji panel disposes and
    //    rebuilds the whole bar): nothing is sliding, everything simply
    //    appears, so the whole toolbar — emoji included — fades in together, no
    //    stagger. [toolsFade] starts at 0 so it fades from blank instead of
    //    painting one frame opaque, snapping to 0, and refading (the jitter).
    //
    // A board drawn as a picture (a layout card, the theme editor) has no
    // panel it is returning from: its mount is just the card scrolling into
    // view, so the tools are simply there, as they would be in a screenshot.
    val preview = LocalKeyboardPreviewHost.current
    val toolsFade = remember {
        Animatable(if (showToolbar && !state.settings.reduceMotion && !preview) 0f else 1f)
    }
    // Whether the emoji joins the tools' fade (fresh mount) or sits it out and
    // slides (in-place flip). Seeded for a mount that opens on the toolbar.
    var toolsFadeMounted by remember { mutableStateOf(false) }
    var emojiFadesWithTools by remember {
        mutableStateOf(showToolbar && !state.settings.reduceMotion && !preview)
    }
    val toolbarJustRevealed = !prevShowToolbar && showToolbar && !state.settings.reduceMotion
    LaunchedEffect(showToolbar, state.settings.reduceMotion) {
        val freshMount = !toolsFadeMounted
        toolsFadeMounted = true
        if (!showToolbar || state.settings.reduceMotion || (preview && freshMount)) {
            emojiFadesWithTools = false
            toolsFade.snapTo(1f)
        } else {
            // A mount fades the emoji in with the tools; a later in-place flip
            // lets it slide instead and trails the tools behind it. The mount
            // fade is slower ([FullBleedReturnFadeMs]) since nothing slides to
            // carry the eye; the in-place one matches the emoji's slide.
            emojiFadesWithTools = freshMount
            toolsFade.snapTo(0f)
            if (!freshMount) delay(ToolbarToolsStaggerMs.toLong())
            toolsFade.animateTo(1f, tween(if (freshMount) FullBleedReturnFadeMs else ToolbarMotionMs))
        }
    }
    // [barExit] is the dissolve the tools run when the strip is taking the row
    // back; [toolsFade] is the one they run arriving. Only ever one of the two
    // is away from 1, so the product is whichever is in play.
    val toolContentAlpha = {
        if (toolbarJustRevealed) 0f else toolsFade.value * barExit.value
    }
    /** The candidates' alpha: their own fade, dimmed by the bar's dissolve. */
    val stripContentFade = { stripContentAlpha.value * barExit.value }

    // The suggestion strip lays out right-to-left for RTL scripts — Arabic,
    // Hebrew, Persian, Urdu, Thaana — so the first/best candidate sits on the
    // right, where an RTL reader's eye starts. Only this bar is flipped; the
    // key grid is a sibling composable and stays left-to-right.
    //
    // The toolbar shares this bar, and it does NOT share that reasoning: it is
    // a row of buttons, not text, and whether it mirrors is the user's call
    // ([toolbarReadsRtl]). Flipping the bar itself while the tools sub-row
    // inside held LTR moved the whole cluster — chevron, toolbox launcher and
    // all — to the other edge of the screen, which is the flip the user sees
    // and the reason turning the setting off looked like it did nothing
    // (issue #80). So while the bar is drawing tools it takes the tools'
    // direction; only the candidate surface follows the script unconditionally.
    val stripDirection = if (
        state.script.direction == TextDirection.RTL && (!showToolbar || toolbarReadsRtl(state))
    ) {
        LayoutDirection.Rtl
    } else {
        LayoutDirection.Ltr
    }
    // One layout cache for every word and emoji the strip draws, kept for as
    // long as the bar is up: see [CachedTextLine].
    val stripMeasurer = rememberTextMeasurer(cacheSize = StripTextCacheSize)
    CompositionLocalProvider(
        LocalLayoutDirection provides stripDirection,
        LocalStripTextMeasurer provides stripMeasurer,
    ) {
    // The bar's size is fixed by this box rather than by the row itself. The
    // row's children change as you type — the strip and the toolbar trade
    // places, the chevron comes and goes — and Compose walks a change to a
    // node's children up to the first parent whose size cannot depend on it.
    // With the size on the row, that walk went past it to the window's root:
    // a full measure of the whole keyboard at every word boundary (traced on
    // a CPH2481). A box that is exactly this size stops it at the row.
    //
    // Its own layer for the draw the same way: the strip repaints on every
    // keystroke, and without a layer that repaint re-recorded the window's
    // root, and with it every key that has no layer of its own.
    // The toolbar's own fill while the tools hold the bar (#504); null paints
    // nothing, and the strip's fill from the slot outside shows through.
    val toolbarFill = LocalKbTheme.current.toolbar
    // The finger steering the swipe-up popup of more words, and where its cells are.
    val moreHold = remember { MoreSuggestionsHold() }
    Box(
        Modifier
            .fillMaxWidth()
            .height(topBarHeight(state.settings))
            .graphicsLayer()
            .barRowFill(if (showToolbar) toolbarFill else null),
    ) {
    if (state.moreSuggestions.isNotEmpty()) MoreSuggestionsPopup(state, moreHold)
    Row(
        modifier = Modifier
            .fillMaxSize()
            // A deliberate downward flick anywhere on the strip dismisses the
            // keyboard, or opens the pages of more words (#385); an upward one
            // opens the popup of more words over the strip. A tool's own reorder
            // is a hold-then-drag, so it fires its long-press first and never
            // reaches this detector; a quick flick never trips the long-press,
            // so the two don't collide. See [stripSwipes].
            .then(
                if (state.settings.toolbarBehavior.swipeDownHide || state.settings.suggestionStrip.swipeForMore ||
                    state.settings.suggestionStrip.swipeUpForMore
                ) {
                    // Read at the moment of the swipe, not when the detector
                    // was installed: whether there are words to page through
                    // changes with every keystroke (#385).
                    val wordsToPage = state.suggestions.isNotEmpty() && !state.composer.isConversion
                    val pages = rememberUpdatedState(state.settings.suggestionStrip.swipeForMore && wordsToPage)
                    val more = rememberUpdatedState(
                        state.settings.suggestionStrip.swipeUpForMore && wordsToPage && state.panel == PanelMode.NONE,
                    )
                    val pagesOpen = rememberUpdatedState(state.panel == PanelMode.CANDIDATES)
                    val hide = rememberUpdatedState(state.settings.toolbarBehavior.swipeDownHide)
                    Modifier.stripSwipes(pages, more, pagesOpen, hide, moreHold, suggestionHold, onSwipeDownHide)
                } else {
                    Modifier
                },
            )
            // Inside the flick detector, so the padding still hides the keyboard.
            .toolbarPadding(state.settings),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        val feedback = LocalKeyPressFeedback.current
        // Compact dictation bar takes over the whole strip while active;
        // the keys below stay usable for fixing recognition errors.
        //
        // Interactive voice typing gets a microphone button instead and the
        // strip carries on: there the keys are used all through the session,
        // so the candidates have to stay reachable. See [VoiceMicChip].
        if (state.voiceStripShown()) {
            if (state.voiceChipOnly()) {
                VoiceMicChip(state = state, onToggle = onVoiceToggle)
            } else {
                VoiceStripBar(
                    state = state,
                    onToggle = onVoiceToggle,
                    onUndo = onVoiceUndo,
                    onRequestPermission = onVoicePermissionRequest,
                    onOpenVoiceSettings = onOpenVoiceSettings,
                    onCollapse = {
                        onVoiceAction(VoiceBarAction.SwitchSurface(VoiceBarSettings.MODE_BAR))
                    },
                    // Not the tool tap: over a running dictation that finishes
                    // the phrase (#283), and this button is the way to drop it.
                    onClose = { onVoiceAction(VoiceBarAction.CloseStrip) },
                    modifier = Modifier.weight(1f),
                    onCycleMic = { onVoiceAction(VoiceBarAction.CycleMic) },
                    onPickLanguages = { onVoiceAction(VoiceBarAction.PickLanguages(it)) },
                )
                return@Row
            }
        }
        if (emojiBarOpen && !emojiRowSuppressed && !hasSuggestions) {
            EmojiBarStrip(
                state = state,
                onEmoji = onEmoji,
                onOpenPanel = { onPanelChange(PanelMode.EMOJI) },
                modifier = Modifier.weight(1f),
            )
            IconHint(stringResource(R.string.ime_emoji_row_close_desc)) {
                IconButton(
                    onClick = {
                        feedback()
                        emojiBarOpen = false
                    },
                    modifier = Modifier.size(36.dp),
                ) {
                    Icon(
                        Icons.Outlined.Close,
                        contentDescription = stringResource(R.string.ime_emoji_row_close_desc),
                        tint = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
            }
            return@Row
        }
        val motionMs = if (state.settings.reduceMotion) 0 else ToolbarMotionMs
        // One chevron that spins between the two directions, rather than
        // two icons swapped instantly: the rotation is what tells the
        // user the bar flipped, since the strip and the toolbar look
        // nothing alike and a hard cut reads as a redraw.
        //
        // Both the rotation state and the visibility gate live out here,
        // above the guard. Inside it they were useless: the bar auto-flips
        // to the toolbar at the moment the strip runs dry, which is the same
        // moment `hasSuggestions` goes false and the guard drops the button.
        // The node died on the very frame the rotation was meant to play, so
        // the chevron vanished mid-turn instead of turning.
        // Keyed on the decision, not on the drawn surface: the turn is the
        // acknowledgement of the tap, so it starts on the frame the tap lands
        // and runs through the outgoing dissolve rather than waiting it out.
        // With the tools on their own row the chevron opens and closes that row
        // instead of flipping this one, so the turn tracks the row's state.
        val chevronTurn by animateFloatAsState(
            targetValue = if (if (toolsOwnRow) toolsRowOpen else wantToolbar) 180f else 0f,
            animationSpec = if (state.settings.reduceMotion) snap() else tween(ToolbarMotionMs),
            label = "chevronTurn",
        )
        // While any panel is open the toolbar is forced on and shows its own
        // back chevron, so the suggestions-toggle chevron would sit next to
        // it doing nothing — tools don't need suggestions. Hide it.
        //
        // Fade only, never expandHorizontally/shrinkHorizontally. A width
        // animation here re-measures the whole toolbar on every frame of the
        // transition, and the pinned icons track their position through
        // [animatePlacement], which reads its target in onPlaced — so each of
        // those frames handed every icon a new target and restarted its
        // spring. That is what made opening the bar look like the icons were
        // shivering. Fading keeps the layout change atomic: one reflow, one
        // spring per icon.
        // The exit releases the slot at once instead of fading. AnimatedVisibility
        // holds a child's space for the whole exit, so a fade here meant the
        // strip swapped for the toolbar immediately, the chevron then sat
        // fading in a 36dp gap, and only 140ms later did that gap close and
        // shove everything sideways a second time. Two layout jumps around one
        // decision is the jitter. One jump, and the icons spring into it.
        //
        // Tied to the strip being up, not to there being suggestions. Those
        // are not the same instant: the strip stays for a beat after the last
        // suggestion goes (see emptySettled), and keying on suggestions alone
        // pulled the chevron out at the front of that beat. Its 36dp then
        // vanished from the middle of a strip that was still on screen, so
        // everything left of it — the emoji icon included — slid across
        // before the handoff to the toolbar had even begun, and the icon
        // started its slide from a position it had already been shoved out of.
        // Now the chevron leaves on the same frame the toolbar arrives.
        //
        // Both halves of that are why the test is written against the surface
        // being *drawn* and gated on [wantToolbar]. The bar decides its flip one
        // dissolve before it draws it, and the chevron reads inputs that change
        // with the decision — so on the plain "type into an empty bar" flip it
        // used to appear the instant a candidate arrived, claim its 36dp out of
        // a toolbar that was still on screen, and shove every tool right; the
        // emoji then slid right, was handed to the strip, and slid back left
        // past where it started. One decision, and the row moves once, when the
        // surface it belongs to arrives.
        AnimatedVisibility(
            visible = !toolsColumn && when (placement) {
                // The row is always there; there is nothing for a chevron to do.
                ToolbarPlacement.ALWAYS_ROW -> false
                // The chevron *is* the way to that row, so it is always offered.
                ToolbarPlacement.ON_DEMAND_ROW -> true
                ToolbarPlacement.STRIP -> !showToolbar ||
                    (
                        wantToolbar && state.panel == PanelMode.NONE &&
                            (hasSuggestions || suggestionsFirst)
                        )
            },
            enter = fadeIn(tween(motionMs)),
            exit = ExitTransition.None,
        ) {
            IconHint(
                stringResource(
                    when {
                        toolsOwnRow && toolsRowOpen -> R.string.ime_toolbar_hide_desc
                        toolsOwnRow -> R.string.ime_toolbar_show_desc
                        showToolbar -> R.string.ime_suggestions_show_desc
                        else -> R.string.ime_toolbar_show_desc
                    },
                ),
            ) {
                IconButton(
                    onClick = {
                        feedback()
                        when {
                            toolsOwnRow -> onToolsRowToggle()
                            else -> toolbarOverride = !toolbarOverride
                        }
                    },
                    modifier = Modifier.size(36.dp),
                ) {
                    // A sideways chevron says "flip this row", which is what it does
                    // on the shared strip. With a row of their own the tools open
                    // above or below this one, so the chevron points that way and
                    // turns to face back once the row is out.
                    Icon(
                        when {
                            !toolsOwnRow -> Icons.Outlined.ChevronRight
                            toolsRowAbove -> Icons.Outlined.KeyboardArrowUp
                            else -> Icons.Outlined.KeyboardArrowDown
                        },
                        contentDescription = stringResource(
                            when {
                                toolsOwnRow && toolsRowOpen -> R.string.ime_toolbar_hide_desc
                                toolsOwnRow -> R.string.ime_toolbar_show_desc
                                showToolbar -> R.string.ime_suggestions_show_desc
                                else -> R.string.ime_toolbar_show_desc
                            },
                        ),
                        tint = MaterialTheme.colorScheme.onSurfaceVariant,
                        modifier = Modifier.graphicsLayer { rotationZ = chevronTurn },
                    )
                }
            }
        }
        if (showToolbar) {
            // A tool the strip also keeps (the emoji, by default) never joins
            // the dissolve on the way out: it is the icon that survives the swap,
            // and it has to be solid at the moment it hands its position to the
            // strip's copy.
            //
            // Only while the strip has a copy to hand to. With the strip's
            // buttons turned off (or the tool disabled) there is no other node,
            // so nothing slides: the pinned tool is an ordinary one, and
            // exempting it left it popping in solid while every other tool faded,
            // which read as the handoff still playing for a button that was off.
            // Same condition the strip's copies are drawn under, below.
            ToolbarRow(
                state, onPanelChange, onToolTap, drag, toolContentAlpha,
                sharedTools = stripToolSet(state),
                fadeShared = emojiFadesWithTools && wantToolbar,
            )
            if (state.settings.emojiBarMode == EmojiBarMode.BUTTON) {
                IconHint(stringResource(R.string.ime_emoji_row_show_desc)) {
                    IconButton(
                        onClick = {
                            feedback()
                            emojiBarOpen = true
                            onEmojiRowShown()
                        },
                        modifier = Modifier
                            .size(36.dp)
                            // Fades in with the rest of the tools on strip→toolbar.
                            .graphicsLayer { alpha = toolContentAlpha() },
                    ) {
                        Icon(
                            Icons.Outlined.EmojiEmotions,
                            contentDescription = stringResource(R.string.ime_emoji_row_show_desc),
                            tint = MaterialTheme.colorScheme.onSurfaceVariant,
                        )
                    }
                }
            }
        } else {
            // The candidate surface, as a lambda of its own. It is most of the
            // bar, and written straight into the row it made the row's lambda
            // 9,360 dex instructions — within a few hundred of the 10,000 past
            // which ART never compiles a method, for a function that runs on
            // every keystroke. Here it compiles separately.
            StripSlot {
                // The tools kept beside the suggestions (#462), then the phonetic
                // layouts' English-words switch. See [StripTools].
                if (!stripToolsAtEnd(state)) {
                    StripTools(state, toolsRowVisible, drag, onToolTap) { onPanelChange(PanelMode.TOOLBOX) }
                }
                if (StripOfferChips(
                        state, suggestionsShowing, onStripOfferAction, onDismissInlineSuggestions,
                        onOtpAccept, onOtpDismiss, stickerOffer,
                    )
                ) {
                    return@StripSlot
                }
                // A recognised sum/conversion answers the text directly, so it
                // takes the whole strip the way autofill chips do. A keyword
                // chip ("wiki" → open Wikipedia) only claims the space it needs,
                // because the word being typed may simply be that word.
                val smart = state.smart
                val keywordChip = smart != null && smart.kind in SmartSuggest.narrowKinds
                // #513: every word in a place of its own. Chips that are not
                // words take a slot each instead of shoving the words aside.
                val fixedStrip = state.settings.suggestionStrip.fixedSlots &&
                    !state.settings.suggestionStrip.scrollable &&
                    !state.composer.isConversion && !shownInlineEmoji && !glideStripOnly
                val keywordInSlot = fixedStrip && keywordChip
                if (StripAnswerChips(
                        state, suggestionsShowing, recentClipChip, recentClipsBar, smart, keywordChip, keywordInSlot,
                        StripAnswerCallbacks(
                            onToolTap, onSmartOpen, onSmartAccept, vocab, onDismissInlineSuggestions,
                            onClipboardSuggestion, onClipboardSuggestionDismiss, onClipboardEntity,
                            onRecentClipsToggle,
                        ),
                    )
                ) {
                    return@StripSlot
                }
                // The AI continuation sits in front of the words, never in
                // place of them: it cost a request and may be wrong.
                val aiSuggest = state.aiSuggest
                if (aiSuggest != null && state.smart == null) {
                    val actions = LocalAiSuggest.current
                    AiSuggestionChip(
                        text = aiSuggest,
                        reduceMotion = state.settings.reduceMotion,
                        onAccept = actions.onTap,
                        onSuppress = actions.onHold,
                        modifier = Modifier.padding(start = 4.dp),
                    )
                }
                StripWords(
                    state = state,
                    held = held,
                    suggestionsShowing = suggestionsShowing,
                    shownSuggestions = shownSuggestions,
                    shownEmojiSuggestions = shownEmojiSuggestions,
                    shownInlineEmoji = shownInlineEmoji,
                    shownPunctuation = shownPunctuation,
                    glideStripOnly = glideStripOnly,
                    fixedStrip = fixedStrip,
                    keywordInSlot = keywordInSlot,
                    stripContentFade = stripContentFade,
                    onSuggestion = onSuggestion,
                    suggestionHold = suggestionHold,
                    onJoinSuggestion = onJoinSuggestion,
                    onRevisionSuggestion = onRevisionSuggestion,
                    onCandidate = onCandidate,
                    onCandidatesExpand = onCandidatesExpand,
                    onEmojiSuggestion = onEmojiSuggestion,
                    onPunctuation = onPunctuation,
                )
            }
            // The same buttons at the strip's far end instead, after the words,
            // when the user put them there.
            if (stripToolsAtEnd(state)) {
                StripTools(state, toolsRowVisible, drag, onToolTap) { onPanelChange(PanelMode.TOOLBOX) }
            }
        }
    }
    }
    }
}

/**
 * Runs [content] in the row it is called from, as its own lambda: a method of
 * its own in the dex, and its own recomposition scope. See the candidate
 * surface in [TopBar].
 */
@Composable
private fun RowScope.StripSlot(content: @Composable RowScope.() -> Unit) {
    content()
}

/** The strip's shared text layouts; see [CachedTextLine]. */
private val LocalStripTextMeasurer = staticCompositionLocalOf<TextMeasurer?> { null }

/**
 * How many laid-out words the strip keeps. Typing a word cycles through a few
 * dozen candidates, most of them seen again a keystroke later ("th", "the",
 * "then"), and an entry is one line of text.
 */
private const val StripTextCacheSize = 96

/** Label layouts the key bubbles keep: every key on a layer, with room for shift. */
private const val BubbleLabelCacheSize = 128

/**
 * One line of the strip's text: a word or an emoji candidate, laid out through
 * [LocalStripTextMeasurer]'s cache and drawn directly.
 *
 * A `Text` builds its layout afresh whenever it is composed with a new string,
 * and the strip composes new strings on every keystroke. Each layout is a
 * StaticLayout, and on some phones creating one is expensive by itself (the
 * OnePlus font hook parses font-variation settings in every Paint it makes):
 * about half a millisecond a word, several words a keystroke. The words come
 * round again constantly, so here a repeat is a cache hit. The text is still
 * exposed to accessibility the way a `Text` would expose it.
 */
@Composable
private fun CachedTextLine(
    text: AnnotatedString,
    style: TextStyle,
    color: Color,
    overflow: TextOverflow,
    modifier: Modifier = Modifier,
    // The cache to lay out through, for a caller outside the strip; the
    // strip's own by default.
    cache: TextMeasurer? = null,
) {
    val measurer = cache ?: LocalStripTextMeasurer.current ?: rememberTextMeasurer()
    // The composition's density, not the layout scope's: the cache compares
    // density by equality, and every node's scope is an object of its own, so
    // passing the scope made every lookup a miss.
    val density = LocalDensity.current
    val laidOut = remember { arrayOfNulls<TextLayoutResult>(1) }
    Spacer(
        modifier
            .semantics { this.text = text }
            .layout { measurable, constraints ->
                val result = measurer.measure(
                    text = text,
                    style = style,
                    overflow = overflow,
                    softWrap = false,
                    maxLines = 1,
                    constraints = Constraints(maxWidth = constraints.maxWidth),
                    layoutDirection = layoutDirection,
                    density = density,
                )
                // Read here so a font still loading invalidates this layout
                // when it lands; the cache never hands back a stale one.
                result.multiParagraph.intrinsics.hasStaleResolvedFonts
                laidOut[0] = result
                val width = constraints.constrainWidth(result.size.width)
                val height = constraints.constrainHeight(result.size.height)
                val placeable = measurable.measure(Constraints.fixed(width, height))
                layout(width, height) { placeable.place(0, 0) }
            }
            .drawBehind { laidOut[0]?.let { drawText(it, color = color) } },
    )
}

// The candidate surface's body, in three functions rather than written
// straight into [StripSlot]'s lambda. That lambda had grown back to 10,172
// dex instructions, past the 10,000 at which ART stops compiling a method
// at all, so the code the strip runs on every keystroke was interpreted
// forever. Each of these compiles on its own, well under the limit; the two
// that can claim the row say so by returning true.

/** The offers that come before the words: autofill, the morse readout, the code and download chips. */
@Composable
private fun RowScope.StripOfferChips(
    state: KeyboardUiState,
    suggestionsShowing: Boolean,
    onStripOfferAction: (StripOfferAction) -> Unit,
    onDismissInlineSuggestions: () -> Unit,
    onOtpAccept: (NotificationOtp) -> Unit,
    onOtpDismiss: () -> Unit,
    stickerOffer: StickerOfferCallbacks,
): Boolean {
    // Bengali's ANSI button: on every Bengali layout once Bengali's
    // screen allows ANSI output, lit while the layouts write it. Beside
    // the words for the reason the switch above is: the field that
    // wants ANSI is the one being typed in, and that is when it is
    // reached for.
    if (state.language.id == "bn" && state.settings.suggestionStrip.bengaliAnsiAllowed) {
        EncodingToggle(
            active = state.settings.suggestionStrip.bengaliAnsiOn,
            label = stringResource(R.string.ime_ansi_button),
            description = stringResource(R.string.ime_ansi_output),
        ) {
            onStripOfferAction(StripOfferAction.ToggleAnsi)
        }
    }
    // Burmese's Zawgyi button, the same switch for the same reason. Lit by
    // what the layout writes now, which the strip's offer can turn on for one
    // field without the setting.
    if (state.language.id == "my" && state.settings.suggestionStrip.burmeseZawgyiAllowed) {
        EncodingToggle(
            active = state.zawgyiOutput,
            label = stringResource(R.string.ime_zawgyi_button),
            description = stringResource(R.string.ime_zawgyi_output),
        ) {
            onStripOfferAction(StripOfferAction.ToggleZawgyi)
        }
    }
    // Chinese and Cantonese's 繁 button, the same switch over Traditional
    // characters (#962). Lit while candidates come out Traditional.
    if ((state.language.id == "zh" || state.language.id == "yue") && state.settings.cjk.traditionalButton) {
        EncodingToggle(
            active = state.settings.cjk.traditionalOutput,
            label = stringResource(R.string.ime_traditional_button),
            description = stringResource(R.string.ime_traditional_output),
        ) {
            onStripOfferAction(StripOfferAction.ToggleTraditional)
        }
    }
    // Autofill chips take the whole strip while they are up: they
    // answer the field directly ("use this saved login"), which beats
    // any word the dictionary could offer, and they are transient —
    // dismissed, or gone as soon as the field is left. Smart replies
    // off the same API do *not* get this treatment; they are handled
    // further down, beside the words.
    if (state.autofillChips.isNotEmpty()) {
        InlineChipRow(
            chips = state.autofillChips,
            modifier = Modifier.weight(1f).fillMaxHeight(),
        )
        Box(
            modifier = Modifier
                .fillMaxHeight()
                .clickable { onDismissInlineSuggestions() }
                .padding(horizontal = 8.dp),
            contentAlignment = Alignment.Center,
        ) {
            Icon(
                Icons.Outlined.Close,
                contentDescription = stringResource(R.string.ime_autofill_dismiss_desc),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.size(18.dp),
            )
        }
        return true
    }
    // No saved login came up by itself in a password field (#1003): the
    // keyboard cannot ask the autofill service for one, only the app can, so
    // the chip opens the manager to copy one from instead.
    val passwordManager = state.passwordManagerApp
    if (passwordManager != null && state.showsPasswordManagerChip()) {
        OfferChip(
            label = stringResource(R.string.ime_password_manager_chip, passwordManager),
            icon = Icons.Outlined.Password,
            declineDescription = stringResource(R.string.ime_password_manager_dismiss_desc),
            onAccept = { onStripOfferAction(StripOfferAction.OpenPasswordManager) },
            onDecline = { onStripOfferAction(StripOfferAction.DismissPasswordManager) },
            modifier = Modifier.padding(horizontal = 4.dp),
        )
        return true
    }
    // A dead key is armed: show which accent the next letter will
    // take, otherwise the keyboard looks like it swallowed a press.
    state.pendingDeadKey?.let { accent ->
        Box(
            modifier = Modifier
                .fillMaxHeight()
                .padding(horizontal = 6.dp),
            contentAlignment = Alignment.Center,
        ) {
            Text(
                text = accent,
                color = MaterialTheme.colorScheme.primary,
                fontWeight = FontWeight.SemiBold,
            )
        }
    }
    // The morse sequence being tapped out, plus the letter it spells so
    // far — the same "show the armed input" job as the dead-key hint
    // above, sized up because it is the primary feedback while typing
    // morse (the keys themselves all look alike).
    if (state.braillePending.isNotEmpty()) {
        Box(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight(),
            contentAlignment = Alignment.Center,
        ) {
            Text(
                text = state.braillePending,
                color = MaterialTheme.colorScheme.primary,
                fontWeight = FontWeight.SemiBold,
                fontSize = 18.sp,
                maxLines = 1,
            )
        }
        return true
    }
    if (state.morsePending.isNotEmpty()) {
        Box(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight(),
            contentAlignment = Alignment.Center,
        ) {
            val spelled = MorseCode.decode(
                state.morsePending.map { if (it == '·') '.' else '-' }.joinToString(""),
            )
            Text(
                text = if (spelled != null) {
                    "${state.morsePending}   $spelled"
                } else {
                    state.morsePending
                },
                color = MaterialTheme.colorScheme.primary,
                fontWeight = FontWeight.SemiBold,
                fontSize = 18.sp,
            )
        }
        return true
    }
    // Easter egg: S, O, S was just keyed. Below the live readout on
    // purpose — feedback for the letter being tapped outranks a joke —
    // so it shows in the pauses and retires by itself after a few
    // seconds.
    if (state.morseSosEgg) {
        Box(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight(),
            contentAlignment = Alignment.Center,
        ) {
            Text(
                text = stringResource(R.string.ime_morse_sos_egg_info),
                color = MaterialTheme.colorScheme.primary,
                fontSize = 13.sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }
        return true
    }
    // A one-time code lifted from a just-arrived notification. It
    // outranks every chip below: the code is the reason the user is on
    // this field, and it expires while everything else can wait. Only
    // the autofill lane above beats it — the platform may be offering
    // the same code with more context than the keyboard has.
    val otpSuggestion = state.otpSuggestion
    if (otpSuggestion != null) {
        val otpShares = suggestionsShowing || state.smartReplyChips.isNotEmpty()
        OtpSuggestionChip(
            otp = otpSuggestion,
            onAccept = { onOtpAccept(otpSuggestion) },
            onDismiss = onOtpDismiss,
            stretch = !otpShares,
            modifier = if (otpShares) {
                Modifier.widthIn(max = 180.dp).padding(horizontal = 4.dp)
            } else {
                Modifier.weight(1f).padding(horizontal = 4.dp)
            },
        )
        if (!otpShares) return true
    }
    // A task that has fallen due. Below a code, which expires, and above
    // everything else, which is still there after it is dealt with.
    val todoChip = state.todoDueChip
    if (todoChip != null) {
        TodoDueSuggestionChip(todoChip, Modifier.weight(1f).padding(horizontal = 4.dp))
        return true
    }
    // A snippet whose trigger matched but which was told to ask first.
    // It shares the row rather than taking it: what the user typed is
    // still perfectly good text, and the word candidates are how they
    // carry on typing it if the answer is no.
    val snippetOffer = state.snippetOffers
    if (snippetOffer != null) {
        val offerShares = suggestionsShowing || state.smart != null
        val single = snippetOffer.isSingle()
        SnippetOfferRow(
            offers = snippetOffer,
            onAction = onStripOfferAction,
            stretch = !offerShares && single,
            modifier = if (offerShares) {
                Modifier
                    .widthIn(max = if (single) 200.dp else 280.dp)
                    .padding(horizontal = 4.dp)
            } else {
                Modifier.weight(1f).padding(horizontal = 4.dp)
            },
        )
        if (!offerShares) return true
    }
    // A word nothing recognises, asking whether it belongs in the
    // dictionary. Shares the row like the snippet offer above and for
    // the same reason: the word is already typed and perfectly good
    // text either way, so the candidates keep working while it waits.
    val learnOffer = state.learnOffer
    if (snippetOffer == null && learnOffer != null) {
        val learnShares = suggestionsShowing || state.smart != null
        LearnWordChip(
            word = learnOffer,
            onAccept = { onStripOfferAction(StripOfferAction.Accept()) },
            onDecline = { onStripOfferAction(StripOfferAction.Decline) },
            stretch = !learnShares,
            modifier = if (learnShares) {
                Modifier.widthIn(max = 210.dp).padding(horizontal = 4.dp)
            } else {
                Modifier.weight(1f).padding(horizontal = 4.dp)
            },
        )
        if (!learnShares) return true
    }
    // The sandbox ladder asking whether to climb a rung. Behind the
    // other two: it is about a setting rather than about the text on
    // screen, so it waits until nothing more immediate is asking.
    val sandboxOffer = state.sandboxOffer
    if (snippetOffer == null && learnOffer == null && sandboxOffer != null) {
        val sandboxShares = suggestionsShowing || state.smart != null
        OfferChip(
            label = stringResource(
                when (sandboxOffer) {
                    GlideSandboxPolicy.LEARNED_ONLY -> R.string.ime_sandbox_offer_only
                    else -> R.string.ime_sandbox_offer_prefer
                }
            ),
            icon = Icons.Outlined.AutoAwesome,
            declineDescription = stringResource(R.string.ime_sandbox_offer_never_desc),
            onAccept = { onStripOfferAction(StripOfferAction.Accept()) },
            onDecline = { onStripOfferAction(StripOfferAction.Decline) },
            onExplain = { onStripOfferAction(StripOfferAction.Explain) },
            stretch = !sandboxShares,
            modifier = if (sandboxShares) {
                Modifier.widthIn(max = 210.dp).padding(horizontal = 4.dp)
            } else {
                Modifier.weight(1f).padding(horizontal = 4.dp)
            },
        )
        if (!sandboxShares) return true
    }
    // A language with no word list cannot glide, and a swipe going
    // nowhere looks like a broken keyboard (#219). Behind the other
    // chips for the sandbox chip's reason: it is about a download,
    // not about the text on screen. Tapping it opens the language's
    // page, where the list downloads.
    val wordListOffer = state.glideWordListOffer
    if (snippetOffer == null && learnOffer == null && sandboxOffer == null && wordListOffer != null) {
        val wordListShares = suggestionsShowing || state.smart != null
        OfferChip(
            label = stringResource(
                if (state.wordListOfferIsPhonetic) {
                    R.string.ime_phonetic_word_list_offer
                } else {
                    R.string.ime_glide_word_list_offer
                },
                wordListOffer.englishName,
            ),
            icon = Icons.Outlined.Download,
            declineDescription = stringResource(R.string.ime_glide_word_list_offer_dismiss_desc),
            onAccept = { onStripOfferAction(StripOfferAction.Accept()) },
            onDecline = { onStripOfferAction(StripOfferAction.Decline) },
            stretch = !wordListShares,
            modifier = if (wordListShares) {
                Modifier.widthIn(max = 260.dp).padding(horizontal = 4.dp)
            } else {
                Modifier.weight(1f).padding(horizontal = 4.dp)
            },
        )
        if (!wordListShares) return true
    }
    // The same chip for the other missing download: a conversion IME
    // whose pack was never fetched types the reading and offers no
    // character for it, which reads as a broken keyboard exactly the
    // way a swipe going nowhere does (#260). The two cannot both be up
    // — the one above is only raised for a composer that does not
    // convert — so they share the row's precedence slot.
    val packOffer = state.conversionPackOffer?.let { CjkDictCatalog.byId(it) }
    if (snippetOffer == null && learnOffer == null && sandboxOffer == null &&
        wordListOffer == null && packOffer != null
    ) {
        val packShares = suggestionsShowing || state.smart != null
        OfferChip(
            label = stringResource(
                // The word pairs improve conversion; it works without them.
                if (packOffer.alongside != null) {
                    R.string.ime_conversion_pack_improve_offer
                } else {
                    R.string.ime_conversion_pack_offer
                },
                stringResource(packOffer.displayNameRes),
            ),
            icon = Icons.Outlined.Download,
            declineDescription = stringResource(R.string.ime_conversion_pack_offer_dismiss_desc),
            onAccept = { onStripOfferAction(StripOfferAction.Accept()) },
            onDecline = { onStripOfferAction(StripOfferAction.Decline) },
            stretch = !packShares,
            modifier = if (packShares) {
                Modifier.widthIn(max = 260.dp).padding(horizontal = 4.dp)
            } else {
                Modifier.weight(1f).padding(horizontal = 4.dp)
            },
        )
        if (!packShares) return true
    }
    // A word a swipe wrote, being read back: the chip hands that
    // stroke to every word list at once, which is what the sandbox
    // and the vocabulary cap keep the ordinary decode away from
    // (#135). Last of the chips — it is about text already in the
    // field, where the others are about what is being typed now — and
    // the one chip with no sentence on it: the words it shares the
    // strip with are the ones it is offering to improve on, and
    // spelling the offer out took half the row from them (#264).
    val searchChip = state.glideSearchChip
    if (snippetOffer == null && learnOffer == null && sandboxOffer == null &&
        wordListOffer == null && searchChip != null
    ) {
        StripIconChip(
            icon = Icons.Outlined.Search,
            description = stringResource(R.string.ime_glide_search_all_offer),
            dismissDescription = stringResource(R.string.ime_glide_search_all_dismiss_desc),
            onAccept = { onStripOfferAction(StripOfferAction.Accept()) },
            onDismiss = { onStripOfferAction(StripOfferAction.Decline) },
        )
    }
    // Zawgyi found where Unicode was expected: text just pasted, or the field
    // the user is typing Burmese into. After every chip about the word being
    // typed, since it is about text already in the field.
    val zawgyiOffer = state.zawgyiOffer
    if (snippetOffer == null && learnOffer == null && sandboxOffer == null &&
        wordListOffer == null && packOffer == null && searchChip == null && zawgyiOffer != null
    ) {
        val zawgyiShares = suggestionsShowing || state.smart != null
        OfferChip(
            label = stringResource(
                if (zawgyiOffer is ZawgyiOffer.Pasted) R.string.ime_zawgyi_paste_offer else R.string.ime_zawgyi_field_offer,
            ),
            icon = Icons.Outlined.Translate,
            declineDescription = stringResource(R.string.ime_zawgyi_offer_dismiss_desc),
            onAccept = { onStripOfferAction(StripOfferAction.Accept()) },
            onDecline = { onStripOfferAction(StripOfferAction.Decline) },
            stretch = !zawgyiShares,
            modifier = if (zawgyiShares) {
                Modifier.widthIn(max = 260.dp).padding(horizontal = 4.dp)
            } else {
                Modifier.weight(1f).padding(horizontal = 4.dp)
            },
        )
        if (!zawgyiShares) return true
    }
    // Stickers of the user's own that the text before the cursor asked
    // for (#329), in the two styles that put them here rather than in
    // the tray above. Narrow, like a keyword chip: the word that asked
    // may simply be a word, so the candidates keep their place.
    val stickerOfferNow = state.stickerOffer
    if (stickerOfferNow != null && stickerStripShows(state)) {
        StickerStripOffer(
            offer = stickerOfferNow,
            style = offerStyle(state, stickerOfferNow),
            callbacks = stickerOffer,
            modifier = Modifier.padding(start = 4.dp),
        )
    }
    return false
}

/** What [StripAnswerChips] calls back into, bundled to keep its parameter list short. */
private class StripAnswerCallbacks(
    val onToolTap: (ToolbarTool) -> Unit,
    val onSmartOpen: () -> Unit,
    val onSmartAccept: () -> Unit,
    val vocab: VocabCallbacks,
    val onDismissInlineSuggestions: () -> Unit,
    val onClipboardSuggestion: (ClipItem) -> Unit,
    val onClipboardSuggestionDismiss: () -> Unit,
    val onClipboardEntity: (ClipEntity) -> Unit,
    val onRecentClipsToggle: () -> Unit,
)

/** The smart chip, the daily word, the clipboard chips and the smart replies. */
@Composable
private fun RowScope.StripAnswerChips(
    state: KeyboardUiState,
    suggestionsShowing: Boolean,
    recentClipChip: Boolean,
    recentClipsBar: Boolean,
    smart: SmartSuggest.SmartHit?,
    keywordChip: Boolean,
    keywordInSlot: Boolean,
    callbacks: StripAnswerCallbacks,
): Boolean {
    // A copy the keyboard just made privately holds the row over a smart
    // chip too, until the next key (#679).
    val shownSmart = smart.takeUnless { state.clipChipHeld && recentClipChip }
    val onToolTap = callbacks.onToolTap
    val onSmartOpen = callbacks.onSmartOpen
    val onSmartAccept = callbacks.onSmartAccept
    val vocab = callbacks.vocab
    val onDismissInlineSuggestions = callbacks.onDismissInlineSuggestions
    val onClipboardSuggestion = callbacks.onClipboardSuggestion
    val onClipboardSuggestionDismiss = callbacks.onClipboardSuggestionDismiss
    val onClipboardEntity = callbacks.onClipboardEntity
    val onRecentClipsToggle = callbacks.onRecentClipsToggle
    // A Send link just copied (#729): offered first, since it is why the
    // user came back to this field, and it goes stale on its own.
    val sendOffer = state.sendLinkOffer
    if (sendOffer != null) {
        val sendAct = LocalSendAction.current
        com.wasimaster.wmkeyboard.ime.ui.send.SendLinkOfferChip(
            offer = sendOffer,
            reduceMotion = state.settings.reduceMotion,
            onOpen = { sendAct(com.wasimaster.wmkeyboard.ime.send.SendAction.OpenOffer) },
            onDismiss = { sendAct(com.wasimaster.wmkeyboard.ime.send.SendAction.DismissOffer) },
            modifier = Modifier.panelOrigin().padding(horizontal = 4.dp),
        )
        if (!suggestionsShowing) return true
    }
    if (shownSmart != null) {
        // Opening runs in two halves: the service clears the trigger
        // text and stages the prefill, then the tool is tapped the
        // ordinary way so panel routing stays in one place.
        val contactChip = shownSmart.kind == SmartSuggest.Kind.CONTACT
        val open = {
            onSmartOpen()
            // A contact chip's button texts the contact; the
            // service does that alone, with no panel to open.
            if (!contactChip) onToolTap(shownSmart.tool)
        }
        // A vocabulary nudge has two doors: the card and the swap. The
        // setting says which one the tap is; the hold is the other.
        val vocabSwap = shownSmart.kind == SmartSuggest.Kind.VOCAB && shownSmart.insert != null
        val vocabTapSwaps = vocabSwap &&
            state.settings.vocabulary.chipTapAction == com.wasimaster.wmkeyboard.core.vocab.VocabChipTap.REPLACE
        SmartSuggestionChip(
            hit = shownSmart,
            reduceMotion = state.settings.reduceMotion,
            icon = if (contactChip) Icons.Outlined.Call else toolIcon(shownSmart.tool),
            // An answer chip still shows with its tool switched off,
            // and onToolTap would drop the gear's press without a word.
            canOpen = contactChip || shownSmart.tool in state.settings.enabledTools &&
                isSupportedTool(shownSmart.tool) && isUsableTool(shownSmart.tool, state.settings),
            // The tool it opens grows out of the chip.
            modifier = Modifier.panelOrigin().then(
                if (keywordInSlot) {
                    Modifier.weight(1f).padding(horizontal = 4.dp)
                } else if (keywordChip) {
                    Modifier.padding(start = 4.dp)
                } else {
                    Modifier
                        .weight(1f)
                        .padding(horizontal = 4.dp)
                },
            ),
            // A wide chip with nothing to type (the weather answer)
            // opens its tool instead: the whole face is one door.
            onAccept = {
                when {
                    // The face calls; the service starts the dialer.
                    contactChip -> onSmartAccept()
                    vocabTapSwaps -> onSmartAccept()
                    // Rates it may fetch only on a tap: this is that tap.
                    shownSmart.awaitingTap -> onSmartAccept()
                    keywordChip || shownSmart.insert == null -> open()
                    else -> onSmartAccept()
                }
            },
            onOpen = open,
            onLongPress = if (vocabSwap) {
                { if (vocabTapSwaps) open() else onSmartAccept() }
            } else {
                null
            },
        )
    }
    if (shownSmart != null && !keywordChip) return true
    // The once-a-day word chip sits where a smart chip would, when none is up.
    val daily = state.vocabDaily
    if (shownSmart == null && daily != null) {
        VocabDailyChip(
            word = daily.word,
            hourly = state.settings.vocabulary.wordInterval != com.wasimaster.wmkeyboard.core.vocab.VocabWordInterval.DAILY,
            modifier = Modifier.padding(start = 4.dp).panelOrigin(),
            onOpen = {
                vocab.onDailyOpen()
                onToolTap(ToolbarTool.VOCABULARY)
            },
            onDismiss = vocab.onDailyDismiss,
        )
    }
    // Platform smart replies. They share the row rather than claiming
    // it: a proposed reply is a suggestion like any other, and the user
    // may well be about to type something else entirely.
    val smartReplies = state.smartReplyChips
    // Recently-copied paste chip (Gboard style): takes the idle strip
    // when there are no candidates, one tap from pasting the last copy.
    // Word candidates always win the row, so it never hides a suggestion.
    val recentClip = state.clipboardSuggestion
    // A verification SMS is the one copy where the whole clip is not
    // what you want pasted, so the chip offers the code out of it
    // instead — dashed, to say it is a piece of the clip and not the
    // clip. Only codes get this: a copied link or number is already
    // exactly what the ordinary chip would paste.
    val chipOtp = if (recentClip != null && state.settings.clipboard.detectEntities) {
        remember(recentClip.id, recentClip.text) {
            ClipEntities.extract(recentClip.text, recentClip.id)
                .firstOrNull { it.kind == ClipEntityKind.OTP }
                ?.takeIf { it.value != recentClip.text.trim() }
        }
    } else {
        null
    }
    // Replies crowd the row the same way word candidates do, so the
    // paste chip gives way to its narrow form when both are present
    // rather than stretching across a strip it now shares.
    // Not a copy the keyboard just made privately, which holds the row
    // until the next key ([KeyboardUiState.clipChipHeld], #679).
    val clipChipSharesNow = !state.clipChipHeld && (suggestionsShowing || smartReplies.isNotEmpty())
    // Held in its narrow form for a moment after the words go (#612): they
    // come and go between keystrokes and as the caret moves, and a chip that
    // grew to fill the strip each time they went flickered while typing.
    var clipChipShareHold by remember { mutableStateOf(false) }
    LaunchedEffect(clipChipSharesNow) {
        if (clipChipSharesNow) {
            clipChipShareHold = true
        } else {
            delay(ClipChipShareHoldMs)
            clipChipShareHold = false
        }
    }
    val clipChipShares = clipChipSharesNow || clipChipShareHold || state.settings.clipboard.compactPasteChip
    // The last few copies as a row of chips (#414), newest first
    // whatever is pinned (#612). Asked for by hand, so it holds the
    // strip over any words until something is typed or its ✕.
    // Text clips only, never a secret, the same gates as the
    // single chip's.
    val clipBarChips = if (recentClipsBar && shownSmart == null) {
        state.clipboardItems
            .filter { it.kind.isTextual && !it.sensitive && it.text.isNotBlank() }
            .sortedByDescending { it.timestamp }
            .take(recentClipsRowCount(state.settings.clipboard.recentChips))
    } else {
        emptyList()
    }
    if (clipBarChips.isNotEmpty()) {
        Row(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight()
                .horizontalScroll(rememberScrollState())
                .padding(horizontal = 4.dp),
            horizontalArrangement = Arrangement.spacedBy(6.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            for (chip in clipBarChips) {
                ClipboardSuggestionChip(
                    clip = chip,
                    onPaste = { onClipboardSuggestion(chip) },
                    onDismiss = {},
                    dismissible = false,
                    modifier = Modifier.widthIn(max = 200.dp),
                )
            }
        }
        Box(
            modifier = Modifier
                .fillMaxHeight()
                .clickable { onClipboardSuggestionDismiss() }
                .padding(horizontal = 8.dp),
            contentAlignment = Alignment.Center,
        ) {
            Icon(
                Icons.Outlined.Close,
                contentDescription = stringResource(R.string.ime_clip_chip_dismiss_desc),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.size(18.dp),
            )
        }
        return true
    }
    // The parts of a fresh copy take the strip (#612, opt-in): the
    // copy itself, then a dashed chip per part, so a number in a
    // message pastes from here rather than from the panel. Over
    // the words, like the row of recent copies, until a key is
    // typed or the ✕; the plain chip below carries on after that.
    val fragmentClip = recentClip?.takeIf {
        recentClipChip && shownSmart == null &&
            state.settings.clipboard.fragmentsOnStrip &&
            state.settings.clipboard.detectEntities &&
            state.clipFragmentsDoneId != it.id
    }
    val phoneFormats = state.settings.clipboard.phoneFormats
    val stripFragments = if (fragmentClip != null) {
        remember(fragmentClip.id, fragmentClip.text, phoneFormats) {
            ClipEntities.byClip(listOf(fragmentClip), PhoneFormats.parseAll(phoneFormats))[fragmentClip.id]
                .orEmpty()
        }
    } else {
        emptyList()
    }
    if (fragmentClip != null && stripFragments.isNotEmpty()) {
        Row(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight()
                .horizontalScroll(rememberScrollState())
                .padding(horizontal = 4.dp),
            horizontalArrangement = Arrangement.spacedBy(6.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            ClipboardSuggestionChip(
                clip = fragmentClip,
                onPaste = { onClipboardSuggestion(fragmentClip) },
                onDismiss = {},
                dismissible = false,
                modifier = Modifier.widthIn(max = 160.dp),
            )
            for (part in stripFragments) {
                ClipboardSuggestionChip(
                    clip = fragmentClip,
                    otp = part,
                    onPaste = { onClipboardEntity(part) },
                    onDismiss = {},
                    dismissible = false,
                    modifier = Modifier.widthIn(max = 200.dp),
                )
            }
        }
        Box(
            modifier = Modifier
                .fillMaxHeight()
                .clickable { onClipboardSuggestionDismiss() }
                .padding(horizontal = 8.dp),
            contentAlignment = Alignment.Center,
        ) {
            Icon(
                Icons.Outlined.Close,
                contentDescription = stringResource(R.string.ime_clip_chip_dismiss_desc),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.size(18.dp),
            )
        }
        return true
    }
    // [recentClipChip] already says the clip is there; the null check is for
    // the compiler, which cannot see through a parameter.
    if (recentClip != null && recentClipChip && shownSmart == null) {
        val clipChip = @Composable { chipModifier: Modifier ->
            ClipboardSuggestionChip(
                clip = recentClip,
                otp = chipOtp,
                onPaste = {
                    if (chipOtp != null) onClipboardEntity(chipOtp)
                    else onClipboardSuggestion(recentClip)
                },
                onDismiss = onClipboardSuggestionDismiss,
                // More than the last copy, from a button on the
                // chip (#612), when the row is set to hold more.
                onMore = if (state.settings.clipboard.recentChips > 1) {
                    onRecentClipsToggle
                } else null,
                modifier = chipModifier,
            )
        }
        if (clipChipShares) {
            clipChip(Modifier.widthIn(max = 160.dp).padding(horizontal = 4.dp))
        } else {
            // Alone on the strip it still sizes to what it holds
            // (#519): a four-letter copy is a short pill, not a bar
            // with the ✕ a screen away. The Box keeps the rest of
            // the row where a full-width chip would have left it.
            Box(
                modifier = Modifier.weight(1f).fillMaxHeight(),
                contentAlignment = Alignment.CenterStart,
            ) {
                clipChip(Modifier.widthIn(max = ClipChipMaxWidth).padding(horizontal = 4.dp))
            }
            return true
        }
    }
    // Nothing typed yet: the replies are the strip, so they take the
    // rest of the row and carry the dismiss ✕ the way the autofill lane
    // does. This is the case they exist for — the message is on screen,
    // the field is empty, and the reply is the whole answer.
    if (smartReplies.isNotEmpty() && !suggestionsShowing) {
        InlineChipRow(
            chips = smartReplies,
            modifier = Modifier.weight(1f).fillMaxHeight(),
        )
        Box(
            modifier = Modifier
                .fillMaxHeight()
                .clickable { onDismissInlineSuggestions() }
                .padding(horizontal = 8.dp),
            contentAlignment = Alignment.Center,
        ) {
            Icon(
                Icons.Outlined.Close,
                contentDescription = stringResource(R.string.ime_smart_replies_dismiss_desc),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.size(18.dp),
            )
        }
        return true
    }
    return false
}

/** The words themselves (or a conversion's candidates), then the emoji, replies and marks after them. */
@Composable
private fun RowScope.StripWords(
    state: KeyboardUiState,
    held: HeldCandidates,
    suggestionsShowing: Boolean,
    shownSuggestions: List<String>,
    shownEmojiSuggestions: List<String>,
    shownInlineEmoji: Boolean,
    shownPunctuation: List<String>,
    glideStripOnly: Boolean,
    fixedStrip: Boolean,
    keywordInSlot: Boolean,
    stripContentFade: () -> Float,
    onSuggestion: (String) -> Unit,
    suggestionHold: SuggestionHoldCallbacks,
    onJoinSuggestion: () -> Unit,
    onRevisionSuggestion: () -> Unit,
    onCandidate: (String, Int) -> Unit,
    onCandidatesExpand: () -> Unit,
    onEmojiSuggestion: (String, Boolean) -> Unit,
    onPunctuation: (String) -> Unit,
) {
    val smartReplies = state.smartReplyChips
    // Latin gets three wide chips; a conversion IME gets a scrolling
    // row. Three is the right number when the engine is choosing for you
    // and you only overrule it now and then, but a pinyin reading is
    // genuinely ambiguous — the composer offers a dozen candidates and
    // picking among them *is* the typing. Splitting here rather than
    // widening the shared row keeps the Latin strip exactly as it was.
    // Issue #413: with the setting on, an emoji candidate is one of
    // the slots the count asks for rather than a chip after them,
    // so the strip never shows more than that number. The words
    // give up one slot and the emoji takes it at the same width.
    // Never beside a conversion's candidates: those scroll in a row
    // weighted to the whole strip, and a weighted emoji slot would
    // take half of it (#633).
    val emojiInSlot = (state.settings.suggestionStrip.emojiTakesSlot || fixedStrip) &&
        shownEmojiSuggestions.isNotEmpty() && !shownInlineEmoji && !glideStripOnly && !held.conversion
    // The marks and the emoji never show together (the service
    // leaves one list empty), so they share the one last slot.
    val punctuationInSlot = fixedStrip && !emojiInSlot && shownPunctuation.isNotEmpty()
    val rewriteInSlot = fixedStrip && suggestionsShowing && (
        state.joinSuggestion ?: state.revisionSuggestion
            ?: state.correctionOffer ?: state.correctionUndo
        ) != null
    // Slots ahead of the words, so the primary can still land in
    // the strip's own second slot.
    val leadSlots = (if (keywordInSlot) 1 else 0) + (if (rewriteInSlot) 1 else 0)
    val tailSlots = if (emojiInSlot || punctuationInSlot) 1 else 0
    val wordSlots = (state.settings.suggestionStrip.slotCount - leadSlots - tailSlots)
        .coerceAtLeast(1)
    // The Chinese reading, when it is kept out of the field (#973). It decides
    // the branch too: a reading with no candidates yet keeps the strip's
    // previous list, and with it a stale [HeldCandidates.conversion].
    val readingOnStrip = if (state.readingInKeyboard()) state.composingPreview else ""
    if (shownInlineEmoji) {
        // A ":tada" buffer: emoji, in the emoji font, as many as fit
        // the scroll rather than the three slots words get.
        InlineEmojiChips(
            emojis = shownSuggestions,
            enabled = suggestionsShowing,
            alpha = stripContentFade,
            onEmoji = onSuggestion,
        )
    } else if (held.conversion || readingOnStrip.isNotEmpty()) {
        CandidateStrip(
            candidates = shownSuggestions,
            enabled = suggestionsShowing,
            alpha = stripContentFade,
            textScale = state.settings.suggestionStrip.textScale,
            hints = if (suggestionsShowing) suggestionHintPlan(state) else null,
            highlighted = state.candidateCursor,
            adjustable = state.composer.adjustsChoices,
            reading = readingOnStrip,
            onCandidate = onCandidate,
            onExpand = onCandidatesExpand,
            onAdjust = suggestionHold.onCandidateAdjust,
        )
    } else {
        // The join chip leads the row, visually apart from the three
        // word slots: it rewrites text already in the field, which a
        // plain suggestion never does. The revision chip shares the
        // slot (they can't coexist: join needs a composing word,
        // revision needs an empty one) and the same look, for the
        // same reason — both rewrite committed text on tap. So does
        // the near-miss correction chip, behind both: a confusable the
        // follower has already proved wrong is better evidence than a
        // correction that only came close.
        // Behind all three sits the undo chip, which is the odd one
        // out: it puts back a word the keyboard already replaced,
        // rather than rewriting one the user typed. Last because
        // everything above it is about the word at the caret, and the
        // correction it takes back may be several words old.
        val join = state.joinSuggestion
        val revision = state.revisionSuggestion
        val undo = state.correctionUndo
        val rewriteChip = join ?: revision ?: state.correctionOffer ?: undo
        if (rewriteChip != null && suggestionsShowing && !glideStripOnly) {
            val undoing = join == null && revision == null &&
                state.correctionOffer == null && undo != null
            Box(
                modifier = Modifier
                    .then(if (rewriteInSlot) Modifier.weight(1f) else Modifier)
                    .fillMaxHeight()
                    .graphicsLayer { alpha = stripContentFade() }
                    .padding(vertical = 8.dp, horizontal = 2.dp)
                    .clip(RoundedCornerShape(14.dp))
                    .background(MaterialTheme.colorScheme.secondaryContainer)
                    .clickable {
                        if (join != null) onJoinSuggestion() else onRevisionSuggestion()
                    }
                    .padding(horizontal = 10.dp),
                contentAlignment = Alignment.Center,
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(4.dp),
                ) {
                    // The arrow is what separates "put this back" from
                    // the three chips that read as plain words. An icon
                    // rather than an arrow glyph because the strip is
                    // drawn in whatever font the theme picked, and half
                    // of those have no arrows in them.
                    if (undoing) {
                        Icon(
                            Icons.AutoMirrored.Outlined.Undo,
                            // Named, unlike the chip's own word: the
                            // three chips above this one read as
                            // "replace with X", and a screen reader
                            // has nothing else to tell it this one
                            // goes the other way.
                            contentDescription = stringResource(
                                R.string.ime_undo_correction_desc,
                            ),
                            modifier = Modifier.size(16.dp),
                            tint = MaterialTheme.colorScheme.onSecondaryContainer,
                        )
                    }
                    Text(
                        text = rewriteChip,
                        style = MaterialTheme.typography.bodyMedium,
                        fontWeight = FontWeight.SemiBold,
                        color = MaterialTheme.colorScheme.onSecondaryContainer,
                        maxLines = 1,
                    )
                }
            }
        }
        LatinSuggestionChips(
            // One slot, so the word sits centred across the whole strip
            // rather than in the first of three (see [glideStripOnly]).
            candidates = if (glideStripOnly) {
                listOfNotNull(state.glideWord)
            } else {
                shownSuggestions
            },
            enabled = suggestionsShowing,
            alpha = stripContentFade,
            slotCount = wordSlots,
            weight = wordSlots.toFloat(),
            textScale = state.settings.suggestionStrip.textScale,
            scrollable = state.settings.suggestionStrip.scrollable,
            textPadding = state.settings.suggestionStrip.chipPadding.dp,
            centerPrimaryEnabled = state.settings.suggestionStrip.suggestionPrimaryCenter &&
                !state.fixedPhoneticStrip(),
            primaryColor = state.settings.suggestionStrip.primaryColor?.let { Color(it.toInt()) },
            leadWord = state.stripTyped.takeIf { state.settings.suggestionStrip.typedWordFirst && !glideStripOnly },
            fitMore = state.settings.suggestionStrip.fitMoreWords && !glideStripOnly,
            autocorrectWord = state.autocorrectWord,
            // A fixed phonetic strip leads with the word as typed, not
            // with what a space writes; the bold follows the latter.
            primaryWord = if (state.fixedPhoneticStrip()) state.autocorrectWord.orEmpty() else null,
            // Mid-stroke, the shift the lift will commit under (#162):
            // a glide through the shift key previews its capital on
            // the strip as well as in the pill. Zero crossings between
            // strokes, so this is the board's own shift then.
            shiftState = shiftForGlide(state.shiftState, state.glideCase),
            // Per-letter capitals a stroke drew (#163), which no one
            // shift state can say; empty under the whole-word reading.
            casedWords = state.glideCased,
            // A glided trigger shows what the lift types for it (#205).
            expansions = state.glideExpansions,
            // Only while the live candidates are the ones on screen: the
            // strip holds the last set behind alpha 0, and a key promised
            // against a faded word would commit something else.
            hints = if (suggestionsShowing) suggestionHintPlan(state) else null,
            onSuggestion = onSuggestion,
            suggestionHold = suggestionHold,
            menuItems = state.settings.suggestionStrip.wordMenuItems,
            overflow = state.settings.suggestionStrip.overflow,
            fixedSlots = fixedStrip,
            primarySlot = (1 - leadSlots).coerceAtLeast(0),
            tinted = state.settings.suggestionStrip.tintedSlots,
        )
        // A strip that scrolls gets the arrow the conversion strip has (#890):
        // past the words it scrolls through, the rest of the ranked list opens
        // in the same grid a swipe down does. Outside the scroll, as there, so
        // it cannot scroll away itself.
        if (state.settings.suggestionStrip.scrollable && state.settings.suggestionStrip.moreArrow &&
            !glideStripOnly && shownSuggestions.size > wordSlots
        ) {
            IconHint(stringResource(R.string.ime_candidates_more_desc)) {
                IconButton(onClick = onCandidatesExpand, enabled = suggestionsShowing) {
                    Icon(
                        Icons.Outlined.ArrowDropDown,
                        contentDescription = stringResource(R.string.ime_candidates_more_desc),
                        tint = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
            }
        }
        // The word card (#99) is a window over the whole keyboard, so
        // where it is composed does not matter; it lives beside the
        // strip that opens it. It steps aside while its own spelling
        // editor is up (#138): that window covers the keys the
        // respelling is typed on.
        // Composed with a null value too, so the popup can play its
        // way out after the service has closed it.
        // A card the selection bar opened is the bar's to host.
        WordCardPopup(
            card = state.wordCard?.takeIf { state.wordSpell == null && !it.fromSelection },
            onAction = suggestionHold.onCard,
        )
        // The synonyms a held word asked for (#321), a window over the
        // keyboard like the card.
        SynonymsPopup(sheet = state.synonyms, onAction = suggestionHold.onSynonyms)
    }
    // Emoji candidates ride along after the words: typing "birthday"
    // puts 🎂 🎉 🥳 🎁 one tap away. Held set, so they fade out with
    // the words rather than vanishing; taps gated to the live ones.
    //
    // Holding one runs the *other* insert mode: the setting decides
    // which of "replace the word" and "keep the word" a tap does, and
    // the hold is the escape hatch for the one time you want the other,
    // without a trip to settings. The label says which, read from the
    // live setting, so TalkBack announces the action rather than "long
    // press".
    //
    // The label is resolved inside the guard, not above it: the strip
    // recomposes on every keystroke, and most of those have no emoji
    // candidates to label.
    if (shownEmojiSuggestions.isNotEmpty()) {
        val holdLabel = stringResource(
            if (state.settings.emojiInsertMode == EmojiInsertMode.APPEND) {
                R.string.ime_emoji_suggestion_hold_replace
            } else {
                R.string.ime_emoji_suggestion_hold_keep
            },
        )
        val emojiShown = if (emojiInSlot) 1 else state.settings.suggestionStrip.emojiCount
        for (emoji in shownEmojiSuggestions.take(emojiShown)) {
            Box(
                modifier = Modifier
                    // A slot of its own, the width of a word's (#413).
                    .then(if (emojiInSlot) Modifier.weight(1f) else Modifier)
                    .fillMaxHeight()
                    .graphicsLayer { alpha = stripContentFade() }
                    .combinedClickable(
                        enabled = suggestionsShowing,
                        onLongClickLabel = holdLabel,
                        onLongClick = { onEmojiSuggestion(emoji, true) },
                        onClick = { onEmojiSuggestion(emoji, false) },
                    )
                    .padding(horizontal = 5.dp),
                contentAlignment = Alignment.Center,
            ) {
                // A kaomoji chip ("shrug" → ¯\_(ツ)_/¯) is text, not a glyph:
                // the text face at a text size, or it would run off the strip.
                // It takes the words' colour too: the content colour here is
                // not the strip's, and read black on dark themes.
                val face = KaomojiLibrary.isTextArt(emoji)
                CachedTextLine(
                    text = AnnotatedString(if (face) emoji else LocalEmojiShaper.current.shape(emoji)),
                    style = LocalTextStyle.current.merge(
                        if (face) TextStyle(fontSize = 14.sp) else TextStyle(fontSize = 22.sp, fontFamily = emojiFamilyFor(emoji)),
                    ),
                    color = if (face) LocalKbTheme.current.secondarySuggestionText else LocalContentColor.current,
                    overflow = TextOverflow.Clip,
                )
            }
        }
    }
    // Replies ride the tail once there are words to share with, capped
    // in width so the candidates keep their three slots — the weighted
    // word row is measured after unweighted children, so an unbounded
    // scroll row here would quietly eat the whole strip.
    if (smartReplies.isNotEmpty()) {
        VerticalDivider(
            modifier = Modifier.height(20.dp),
            color = MaterialTheme.colorScheme.outlineVariant,
        )
        InlineChipRow(
            chips = smartReplies,
            modifier = Modifier.widthIn(max = 180.dp).fillMaxHeight(),
        )
    }
    // Quick-punctuation chips ride the tail (the service leaves the list
    // empty whenever an emoji prediction claimed it, so the two never
    // fight for the row). A leading divider sets them off from the words.
    if (shownPunctuation.isNotEmpty()) {
        VerticalDivider(
            modifier = Modifier
                .height(20.dp)
                .graphicsLayer { alpha = stripContentFade() },
            color = MaterialTheme.colorScheme.outlineVariant,
        )
        // In a slot of their own (#513) the marks share the last
        // slot's width between them instead of each taking its own.
        Row(
            modifier = if (punctuationInSlot) Modifier.weight(1f) else Modifier,
            horizontalArrangement = Arrangement.Center,
        ) {
            for (mark in shownPunctuation) {
                Box(
                    modifier = Modifier
                        .then(if (punctuationInSlot) Modifier.weight(1f) else Modifier)
                        .fillMaxHeight()
                        .graphicsLayer { alpha = stripContentFade() }
                        .clickable(enabled = suggestionsShowing) { onPunctuation(mark) }
                        .padding(horizontal = if (punctuationInSlot) 2.dp else 8.dp),
                    contentAlignment = Alignment.Center,
                ) {
                    Text(
                        text = mark,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        fontWeight = FontWeight.Medium,
                    )
                }
            }
        }
    }
}

/** How many slots past its count a strip of short words may grow to (#970). */
internal const val FitMoreExtraSlots = 3

/**
 * The most slots, from [slotCount] up to [FitMoreExtraSlots] more, in which
 * each of the first that many [candidates] fits its equal share of [width]
 * unshrunk. [widthDp] measures a word at the strip's size, in dp.
 */
private fun slotsThatFit(
    candidates: List<String>,
    slotCount: Int,
    width: Dp,
    textPadding: Dp,
    widthDp: (String) -> Float,
): Int {
    val most = minOf(candidates.size, slotCount + FitMoreExtraSlots)
    if (most <= slotCount) return slotCount
    val widths = candidates.take(most).map(widthDp)
    for (n in most downTo slotCount + 1) {
        val share = (width - SuggestionDividerWidth * (n - 1)) / n - textPadding * 2
        if (widths.take(n).all { it <= share.value }) return n
    }
    return slotCount
}

/**
 * A scrolling row of inline-suggestion chips — the views another process
 * inflated for us. Shared by both lanes: password-manager chips, which take
 * the whole strip, and platform smart replies, which take whatever the caller
 * gives them.
 *
 * The views arrive fully built, so this only positions them; anything that
 * looks like styling would be a guess at what the sending app drew.
 */
@Composable
private fun InlineChipRow(
    chips: List<android.view.View>,
    modifier: Modifier = Modifier,
) {
    val gapPx = with(LocalDensity.current) { 2.dp.roundToPx() }
    // An Android scroller rather than a Compose one, deliberately: these views
    // are remote surfaces that ignore a Compose clip and keep their full width
    // off screen, so a horizontalScroll let them paint over the strip's own
    // controls and steal their touches. See [InlineChipScroller].
    AndroidView(
        factory = { InlineChipScroller(it) },
        update = { it.setChips(chips, gapPx) },
        modifier = modifier,
    )
}

/**
 * The inline emoji-search row: what a ":tada" composing buffer puts in the
 * strip.
 *
 * Unlike [LatinSuggestionChips] this scrolls and sizes its cells to the emoji,
 * because a shortcode search is a search — ":sm" has a dozen answers worth
 * scanning, and three word-shaped slots would hide nine of them. Drawn through
 * [LocalEmojiFontFamily]/[LocalEmojiShaper] like every other emoji surface, so
 * a chosen emoji font applies here too.
 */
@Composable
private fun RowScope.InlineEmojiChips(
    emojis: List<String>,
    enabled: Boolean,
    alpha: () -> Float,
    onEmoji: (String) -> Unit,
) {
    LazyRow(
        modifier = Modifier
            .weight(1f)
            .fillMaxHeight()
            .graphicsLayer { this.alpha = alpha() },
        horizontalArrangement = Arrangement.Start,
        verticalAlignment = Alignment.CenterVertically,
    ) {
        // Keyed by position, not by the emoji: a duplicate key is a hard crash
        // in LazyRow, and the results come from a generated catalog no runtime
        // check guarantees is duplicate-free.
        itemsIndexed(emojis, key = { index, emoji -> "$index $emoji" }) { _, emoji ->
            Box(
                modifier = Modifier
                    .fillMaxHeight()
                    .clickable(enabled = enabled) { onEmoji(emoji) }
                    .padding(horizontal = 8.dp),
                contentAlignment = Alignment.Center,
            ) {
                Text(
                    // Drawn as this font spells it; the tap still commits the
                    // standard form (see [EmojiFontShaping]).
                    text = LocalEmojiShaper.current.shape(emoji),
                    fontSize = 22.sp,
                    fontFamily = emojiFamilyFor(emoji),
                    maxLines = 1,
                )
            }
        }
    }
}

/**
 * The Latin suggestion strip: the top [slotCount] candidates splitting the bar
 * evenly (Gboard style), so each gets the largest possible tap target.
 *
 * [candidates] is the *held* set, so a cleared field fades the last words out
 * rather than blanking them; [enabled] gates taps to the live ones. [alpha] is
 * read inside a graphics layer so the fade does not recompose the row.
 */
@Composable
internal fun RowScope.LatinSuggestionChips(
    candidates: List<String>,
    enabled: Boolean,
    alpha: () -> Float,
    slotCount: Int,
    /**
     * The chips' share of the row against the other weighted children: one
     * per word slot when an emoji candidate holds a slot of its own (#413),
     * so every slot, word or emoji, comes out the same width.
     */
    weight: Float = 1f,
    /** Multiplier on the suggestion text, from the settings slider. */
    textScale: Float,
    /**
     * Draw every word at its natural width and let the row scroll, instead of
     * shrinking words into equal fixed slots. A slot still gets at least its
     * equal share, so short words fill the strip the same either way.
     */
    scrollable: Boolean = false,
    /** Breathing room on each side of a word inside its slot. */
    textPadding: Dp = SuggestionTextPadding,
    centerPrimaryEnabled: Boolean,
    /**
     * The word the bold goes on, when that is not simply the first one: a
     * fixed phonetic strip's is whatever a space commits, wherever it sits.
     * Empty bolds nothing; null keeps the bold on the primary slot.
     */
    primaryWord: String? = null,
    /** The primary word's own colour (#90), or null for the strip's text colour. */
    primaryColor: Color? = null,
    /** A word to draw in the first slot, wherever it was ranked (#970): the word as typed. */
    leadWord: String? = null,
    /**
     * Up to [FitMoreExtraSlots] slots past [slotCount] while every word shown
     * still fits its share at full size (#970). Ignored when [scrollable] or
     * [fixedSlots] already decide the widths.
     */
    fitMore: Boolean = false,
    /** The word autocorrect has decided a space will put in, or null (#90). */
    autocorrectWord: String? = null,
    shiftState: ShiftState,
    /**
     * Words shown in a casing of their own, keyed by the raw word: a glide's
     * per-letter capitals (#163). Wins over [shiftState] for the words it
     * names; the raw word is still what a tap commits.
     */
    casedWords: Map<String, String> = emptyMap(),
    /**
     * Words that are text-expansion triggers a glide will expand, keyed by the
     * raw word (#205): drawn as "fk = FUTO Keyboard" with the trigger dimmed.
     */
    expansions: Map<String, GlideExpansion> = emptyMap(),
    /** The hotkey badges, or null when no physical keyboard is asking for them. */
    hints: HintPlan? = null,
    onSuggestion: (String) -> Unit,
    /** A word was held: the menu's actions and the facts that pick its items. */
    suggestionHold: SuggestionHoldCallbacks = SuggestionHoldCallbacks(),
    /** Which optional items the held-word menu may show (#99). */
    menuItems: Set<WordMenuItem> = emptySet(),
    /** Where a word still too long after shrinking is cut. */
    overflow: SuggestionOverflow = SuggestionOverflow.MIDDLE,
    /**
     * Lay out all [slotCount] slots whatever the number of words, so no word
     * moves because another one is missing (#513). See [fixedSlotOrder].
     */
    fixedSlots: Boolean = false,
    /** With [fixedSlots] and a centred primary: which of this row's slots it takes. */
    primarySlot: Int = 1,
    /**
     * Each word on a pill of the theme's accent, the best word's the deepest
     * (#510), so the slots read apart at a glance. Dividers step aside.
     */
    tinted: Boolean = false,
) {
    val kb = LocalKbTheme.current
    val tint = kb.accent to kb.dark
    // The word a long press is asking about, or null while no menu is up. Held
    // here rather than per slot so the menu survives the strip re-laying itself
    // out underneath it, which it does on every keystroke.
    var heldWord by remember { mutableStateOf<String?>(null) }
    // One static read for the whole strip: whether a D-pad ring can land on
    // these chips (a television remote, normally). See [dpadTarget].
    val dpadRing = LocalDpadRing.current
    // What the service knew about that word when it was held; read once, so
    // the menu cannot change shape under a finger.
    var heldFacts by remember { mutableStateOf(WordMenuFacts()) }
    val holdLabel = stringResource(R.string.ime_suggestion_hold_label)
    // A hold that goes on to slide (#790): which word, the rank it held, and
    // how many steps the finger has moved it. Null while nothing is sliding.
    var rankSlide by remember { mutableStateOf<RankSlide?>(null) }
    // Candidates change under the menu as the user keeps typing; a menu still
    // naming the old word would blacklist something they never held.
    LaunchedEffect(candidates) { heldWord = null }

    // BoxWithConstraints, not a bare Row, because the chips shrink long words to
    // fit and that needs the slot width up front. One subcomposition covers
    // every slot: they carry equal weight, so each is the same width.
    BoxWithConstraints(
        modifier = Modifier
            .weight(weight)
            .fillMaxHeight()
            // Fades in a beat behind the emoji's slide as candidates arrive,
            // and out as they leave (see [stripContentAlpha]).
            .graphicsLayer { this.alpha = alpha() },
    ) {
        val measurer = LocalStripTextMeasurer.current ?: rememberTextMeasurer()
        val density = LocalDensity.current
        val baseStyle = LocalTextStyle.current
        // The user's own text scale rides on whichever base is in force, so a
        // theme that sets its own suggestion size is scaled rather than replaced.
        val baseSize = (
            if (baseStyle.fontSize.isSpecified) baseStyle.fontSize else SuggestionFontSize
            ) * textScale
        // Short words make room for more of them (#970).
        val slots = if (fitMore && !scrollable && !fixedSlots && candidates.size > slotCount) {
            remember(candidates, slotCount, maxWidth, textPadding, baseSize, baseStyle, shiftState) {
                slotsThatFit(candidates, slotCount, maxWidth, textPadding) { word ->
                    measurer.measure(
                        text = displayCaseForShift(word, shiftState),
                        style = baseStyle.merge(TextStyle(fontSize = baseSize, fontWeight = FontWeight.SemiBold)),
                        maxLines = 1,
                        softWrap = false,
                    ).size.width / density.density
                }
            }
        } else {
            slotCount
        }
        // A scrolling strip runs on through every word it was given (#516);
        // a fixed one shows what fits its slots.
        val ranked = if (scrollable) candidates else candidates.take(slots)
        // Gboard convention: the primary candidate sits in the middle slot with
        // the runner-up on its left. The commit path still uses the engine's
        // order — this is display-only.
        val centerPrimary = centerPrimaryEnabled && ranked.size >= 2
        val fixed = fixedSlots && !scrollable && ranked.isNotEmpty()
        val arranged: List<String?> = when {
            fixed -> fixedSlotOrder(ranked, slotCount, if (centerPrimaryEnabled) primarySlot else 0)
            centerPrimary -> listOf(ranked[1], ranked[0]) + ranked.drop(2)
            else -> ranked
        }
        // The word as typed to the front when asked for (#970); the bold
        // still goes on what a space commits, wherever that now sits.
        val leadAt = leadWord?.let { lead -> arranged.indexOf(lead) } ?: -1
        val shown: List<String?> = if (leadAt > 0) {
            listOf(arranged[leadAt]) + arranged.filterIndexed { i, _ -> i != leadAt }
        } else {
            arranged
        }
        val primaryIndex = when {
            primaryWord != null -> shown.indexOf(primaryWord)
            fixed || leadAt > 0 -> shown.indexOf(ranked.first())
            centerPrimary -> 1
            else -> 0
        }
        // Scroll mode floors each word at the share it would have had among
        // the first [slotCount], however many more follow it.
        val shares = if (scrollable) minOf(shown.size, slotCount) else shown.size
        val slotWidth = if (shares == 0) {
            0.dp
        } else {
            (maxWidth - SuggestionDividerWidth * (shares - 1)) / shares
        }
        val textWidth = (slotWidth - textPadding * 2).coerceAtLeast(0.dp)
        val shaper = LocalEmojiShaper.current
        // One slot: its divider, then the word. A lambda so the two row shapes
        // below draw identical slots.
        val slot: @Composable RowScope.(Int, String?) -> Unit = slot@{ index, suggestion ->
            if (index > 0) {
                // Drawn clear beside an empty slot rather than left out, so
                // every slot keeps the same width.
                VerticalDivider(
                    modifier = Modifier.height(20.dp),
                    thickness = SuggestionDividerWidth,
                    color = if (!tinted && suggestion != null && shown[index - 1] != null) {
                        MaterialTheme.colorScheme.outlineVariant
                    } else {
                        Color.Transparent
                    },
                )
            }
            if (suggestion == null) {
                Box(modifier = Modifier.weight(1f).fillMaxHeight())
                return@slot
            }
            // Fixed mode splits the width by weight. Scroll mode cannot
            // (weights are meaningless under unbounded width), so each
            // slot floors at the equal share and grows with its word.
            val slotModifier = if (scrollable) {
                Modifier.widthIn(min = slotWidth)
            } else {
                Modifier.weight(1f)
            }
            Box(
                modifier = slotModifier
                    .fillMaxHeight()
                    .then(
                        if (tinted) {
                            val (accent, dark) = tint
                            val strong = index == primaryIndex
                            Modifier
                                .padding(horizontal = 2.dp, vertical = 5.dp)
                                .clip(RoundedCornerShape(10.dp))
                                .background(
                                    accent.copy(
                                        alpha = when {
                                            strong && dark -> 0.34f
                                            strong -> 0.24f
                                            dark -> 0.16f
                                            else -> 0.10f
                                        },
                                    ),
                                )
                        } else {
                            Modifier
                        },
                    )
                    // Reachable by remote: a suggestion taken with one
                    // button press is the difference between typing a word
                    // and walking a ring across ten keys to spell it.
                    // Registered by slot, not by word — the words change on
                    // every keystroke and the slots do not.
                    .then(
                        if (dpadRing) {
                            Modifier.dpadTarget(SuggestionRingId(index)) {
                                onSuggestion(suggestion)
                            }
                        } else {
                            Modifier
                        },
                    )
                    // Hold, then slide (#790): up lifts the word, down sinks
                    // it, and far enough down never suggests it again. Only
                    // watched once the hold has fired, so a tap, a swipe
                    // along the strip and a plain hold are untouched. The
                    // hold opens the menu first, and the first full step of
                    // a slide closes it: the two never answer together
                    // (#843). A word already on the never-suggest list does
                    // not slide; its menu's Allow again is the way back, and
                    // a rank saved for a word that stays hidden changes
                    // nothing anyone can see.
                    .pointerInput(suggestion, enabled) {
                        if (!enabled) return@pointerInput
                        val stepPx = RankSlideStep.toPx()
                        awaitEachGesture {
                            val down = awaitFirstDown(requireUnconsumed = false)
                            var anchorY = Float.NaN
                            var held = 0
                            var lifted = false
                            // The badge goes however the gesture ends (#843):
                            // a strip that changes the word in this slot
                            // restarts this block and cancels the loop, and
                            // nothing after it would run. Nothing is saved then.
                            try {
                                while (true) {
                                    // The Initial pass, where a lift is still
                                    // unconsumed: the long press consumes
                                    // everything up to the lift in the Main
                                    // pass, while Compose's synthetic cancel
                                    // arrives consumed in every pass (#824).
                                    val event = awaitPointerEvent(PointerEventPass.Initial)
                                    val change = event.changes.firstOrNull { it.id == down.id } ?: break
                                    if (anchorY.isNaN() && heldWord == suggestion && !heldFacts.blacklisted) {
                                        // Where the finger was when the hold
                                        // fired: this event may already be the
                                        // first step of the slide.
                                        anchorY = change.previousPosition.y
                                        held = heldFacts.rankSteps
                                    }
                                    if (!anchorY.isNaN() && change.pressed) {
                                        val steps = ((anchorY - change.position.y) / stepPx).toInt()
                                        val current = rankSlide
                                        if (steps != 0 || current != null) {
                                            if (current == null || current.steps != steps) {
                                                rankSlide = RankSlide(suggestion, held, steps)
                                            }
                                            // The menu was the hold's answer; a slide is a different one.
                                            heldWord = null
                                            change.consume()
                                        }
                                    }
                                    if (!change.pressed) {
                                        lifted = !change.isConsumed
                                        break
                                    }
                                }
                                val slide = rankSlide
                                rankSlide = null
                                // Only a real lift saves the preview (#824); a
                                // cancelled touch leaves the word as it was.
                                if (lifted && slide != null && slide.word == suggestion && slide.steps != 0) {
                                    suggestionHold.onRankSlide(slide.word, slide.target, slide.blocks)
                                }
                            } finally {
                                if (rankSlide?.word == suggestion) rankSlide = null
                            }
                        }
                    }
                    .combinedClickable(
                        enabled = enabled,
                        onLongClickLabel = holdLabel,
                        // Held rather than tapped: the strip is where a
                        // wrong suggestion is seen, so it is where the user
                        // should be able to say never again (#28). The word
                        // is remembered rather than acted on, because a
                        // silent unrecoverable edit off a long press is not
                        // something to do without asking.
                        onLongClick = {
                            heldFacts = suggestionHold.facts(suggestion)
                            heldWord = suggestion
                        },
                    ) { onSuggestion(suggestion) },
                contentAlignment = Alignment.Center,
            ) {
                // Counted by slot, so the strip always reads 1 2 3 from the
                // left even with the primary centred. The plan holds the
                // rank each slot is drawing (see [suggestionDisplayOrder]).
                // By word, not by slot, when empty slots sit among them.
                val hint = hints?.label(
                    HintSurface.SUGGESTION,
                    if (fixed) shown.subList(0, index).count { it != null } else index,
                )
                if (hint != null) {
                    HintBadge(hint, modifier = Modifier.align(Alignment.BottomCenter))
                }
                // A chip is sometimes an emoji rather than a word — a learned
                // bigram can predict one ("you" → ❤️). Those have to be drawn
                // in the chosen emoji font, and in the spelling that font
                // wants, or they fall back to the system emoji.
                val isEmoji = remember(suggestion) { EmojiGraphemes.isEmojiOnly(suggestion) }
                // Follows the live shift state, so pressing shift re-cases
                // the strip (matching the committed word).
                val display = if (isEmoji) {
                    shaper.shape(suggestion)
                } else {
                    casedWords[suggestion] ?: displayCaseForShift(suggestion, shiftState)
                }
                val primary = index == primaryIndex
                // See the colour note on the Text below. The other
                // suggestions take the theme's own colour and size for
                // them (#504), which are the strip's until a theme says.
                val textColor = when {
                    primaryColor != null &&
                        suggestion.equals(autocorrectWord, ignoreCase = true) -> primaryColor
                    !primary -> kb.secondarySuggestionText
                    else -> MaterialTheme.colorScheme.onSurface
                }
                val slotSize = if (primary) baseSize else baseSize * kb.secondarySuggestionScale
                val label = expansions[suggestion]
                    ?.takeIf { !isEmoji }
                    ?.let { glideExpansionLabel(display, it.previewFor(display), textColor) }
                    ?: AnnotatedString(display)
                val family = if (isEmoji) emojiFamilyFor(suggestion) else null
                val weight = if (primary) FontWeight.SemiBold else FontWeight.Normal
                // Re-measured only when the word, its styling or the slot
                // width actually change — not on every keystroke that leaves
                // this chip alone.
                val fit = if (scrollable) {
                    // Natural width: nothing to fit, the row scrolls instead.
                    SuggestionTextFit(1f, 1f)
                } else remember(label, family, weight, textWidth, slotSize, baseStyle) {
                    val measured = measurer.measure(
                        text = label,
                        style = baseStyle.merge(
                            TextStyle(
                                fontSize = slotSize,
                                fontFamily = family,
                                fontWeight = weight,
                            ),
                        ),
                        maxLines = 1,
                        softWrap = false,
                    ).size.width
                    fitSuggestionText(
                        measuredWidthPx = measured.toFloat(),
                        availableWidthPx = with(density) { textWidth.toPx() },
                    )
                }
                CachedTextLine(
                    text = label,
                    modifier = Modifier.padding(horizontal = textPadding),
                    // The user's own colour on the word the commit will
                    // really put in, and on no other: the primary is only
                    // the top guess until autocorrect has decided, and "Th"
                    // bold beside a coloured "The" would promise a fix that
                    // never comes (#90). A glide claims the same field for
                    // the word a lift would type (#121), so the promise
                    // reads the same whether it is a space or a fingertip
                    // about to keep it. The bold stays on the primary
                    // either way.
                    color = textColor,
                    style = (
                        if (fit.condensed) {
                            baseStyle.copy(
                                textGeometricTransform =
                                    TextGeometricTransform(scaleX = fit.scaleX),
                            )
                        } else {
                            baseStyle
                        }
                        ).merge(
                        TextStyle(
                            fontSize = slotSize * fit.fontScale,
                            // The default 0.5sp tracking is dead width once a
                            // word is already being squeezed.
                            letterSpacing = if (fit.condensed) 0.sp else TextUnit.Unspecified,
                            fontFamily = family,
                            fontWeight = weight,
                            textAlign = TextAlign.Center,
                        ),
                    ),
                    // Cutting the middle keeps the word's ending, which is
                    // what tells "international" from "internationally".
                    overflow = when (overflow) {
                        SuggestionOverflow.MIDDLE -> TextOverflow.MiddleEllipsis
                        SuggestionOverflow.END -> TextOverflow.Ellipsis
                    },
                )
            }
        }
        if (scrollable) {
            // Lazy, because a scrolling strip is handed the deep list (24 words)
            // and a plain scrolling Row composed, measured and laid out the text
            // of every one of them on every keystroke, to show three. That text
            // layout was most of the keyboard's frame time while typing.
            // A fresh set of candidates starts at the left edge again, otherwise
            // the strip could be sitting at the far end of the previous word's
            // overflow and show nothing of the new primary.
            val listState = rememberLazyListState()
            LaunchedEffect(shown) { listState.scrollToItem(0) }
            LazyRow(
                state = listState,
                modifier = Modifier.fillMaxSize(),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                itemsIndexed(shown) { index, suggestion ->
                    Row(
                        modifier = Modifier.fillMaxHeight(),
                        verticalAlignment = Alignment.CenterVertically,
                    ) {
                        slot(index, suggestion)
                    }
                }
            }
        } else {
            Row(
                modifier = Modifier.fillMaxSize(),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                shown.forEachIndexed { index, suggestion -> slot(index, suggestion) }
            }
        }
        rankSlide?.let { slide -> RankSlideBadge(slide, Modifier.align(Alignment.Center)) }
        val held = heldWord
        if (held != null) {
            StripMenuScrim(onDismiss = { heldWord = null })
            DropdownMenu(
                expanded = true,
                onDismissRequest = { heldWord = null },
                // Non-focusable, like every other popup the keyboard raises;
                // see [MenuPopupProperties] for what a focusable one does to
                // the editor underneath.
                properties = MenuPopupProperties,
            ) {
                val act: (WordMenuAction) -> Unit = { action ->
                    heldWord = null
                    suggestionHold.onMenu(action)
                }
                if (WordMenuItem.NEVER_SUGGEST in menuItems) {
                    if (heldFacts.blacklisted) {
                        WordMenuRow(
                            label = stringResource(R.string.ime_word_menu_allow_again, held),
                            icon = Icons.Outlined.Visibility,
                        ) { act(WordMenuAction.AllowAgain(held)) }
                    } else {
                        WordMenuRow(
                            label = stringResource(R.string.ime_suggestion_never_suggest, held),
                            icon = Icons.Outlined.VisibilityOff,
                        ) { act(WordMenuAction.NeverSuggest(held)) }
                    }
                }
                val typed = heldFacts.typedAddable
                if (typed != null && WordMenuItem.ADD in menuItems) {
                    WordMenuRow(
                        label = stringResource(R.string.ime_word_menu_add, typed),
                        icon = Icons.Outlined.LibraryAdd,
                    ) { act(WordMenuAction.Add(typed)) }
                }
                if (heldFacts.deletable && WordMenuItem.DELETE in menuItems) {
                    WordMenuRow(
                        label = stringResource(R.string.ime_word_menu_delete, held),
                        icon = Icons.Outlined.Delete,
                    ) { act(WordMenuAction.Delete(held)) }
                }
                // Beside Delete and under its switch: the same forgetting,
                // keeping the word (#679).
                if (heldFacts.resettable && WordMenuItem.DELETE in menuItems) {
                    WordMenuRow(
                        label = stringResource(R.string.ime_word_menu_forget, held),
                        icon = Icons.Outlined.RestartAlt,
                    ) { act(WordMenuAction.Forget(held)) }
                }
                // About the word the caret is in, not the chip being held —
                // like "Add" above, which is about the word being typed. The
                // swipe that wrote it is decoded again against every word
                // list, which is the only way back to a word the sandbox was
                // never allowed to offer (#135).
                val searchable = heldFacts.searchableStroke
                if (searchable != null) {
                    WordMenuRow(
                        label = stringResource(R.string.ime_word_menu_search_all, searchable),
                        icon = Icons.Outlined.Search,
                    ) { act(WordMenuAction.SearchAllWords(searchable)) }
                }
                // About the held word itself, unlike the two above: its
                // synonyms, any of which goes in place of the word the chip
                // stands for, as picking it off the strip would (#321).
                if (heldFacts.synonyms && WordMenuItem.SYNONYMS in menuItems) {
                    WordMenuRow(
                        label = stringResource(R.string.ime_word_menu_synonyms, held),
                        icon = Icons.Outlined.SwapHoriz,
                    ) { act(WordMenuAction.Synonyms(held)) }
                }
                // The slide's rank steps as two taps (#970), for whoever never
                // finds the slide. Not on a blacklisted word, which no rank
                // brings back.
                if (WordMenuItem.RANK in menuItems && !heldFacts.blacklisted) {
                    WordMenuRow(
                        label = stringResource(R.string.ime_word_menu_rank_up, held),
                        icon = Icons.Outlined.KeyboardArrowUp,
                    ) { act(WordMenuAction.RankStep(held, heldFacts.rankSteps + 1)) }
                    WordMenuRow(
                        label = stringResource(R.string.ime_word_menu_rank_down, held),
                        icon = Icons.Outlined.KeyboardArrowDown,
                    ) { act(WordMenuAction.RankStep(held, heldFacts.rankSteps - 1)) }
                }
                // About the caret's word too, like the search above: take it
                // back out and type it again (#844), with no binding needed.
                val retypable = heldFacts.retypable
                if (retypable != null) {
                    WordMenuRow(
                        label = stringResource(R.string.ime_word_menu_retype, retypable),
                        icon = Icons.AutoMirrored.Outlined.Undo,
                    ) { act(WordMenuAction.Retype(retypable)) }
                }
                // Always offered: the card carries every action above but
                // Synonyms too, so a menu trimmed to this one item still
                // reaches all of those —
                // and since #138 it edits the word itself as well, which is
                // why it is "Edit" rather than "Adjust rank".
                WordMenuRow(
                    label = stringResource(R.string.ime_word_menu_edit),
                    icon = Icons.Outlined.Edit,
                ) { act(WordMenuAction.Open(held)) }
            }
        }
    }
}

/** One item of the held-word menu: an icon and a label. */
@Composable
private fun WordMenuRow(label: String, icon: ImageVector, onClick: () -> Unit) {
    DropdownMenuItem(
        text = { Text(label) },
        leadingIcon = {
            Icon(icon, contentDescription = null, modifier = Modifier.size(18.dp))
        },
        onClick = onClick,
    )
}

/**
 * The voice typing modes, hung off the Voice tool's cell on a press and hold
 * (#173): the one in force is ticked, and picking any of them starts dictation
 * in it straight away, so changing how the mic shares the field is one hold
 * rather than a trip through settings. The same shape as the held-word menu —
 * non-focusable (see [MenuPopupProperties]) and drawn over a [StripMenuScrim],
 * which the caller raises first so the dismissing tap types nothing.
 */
@Composable
private fun VoiceModeMenu(
    current: String,
    /** The modes that work with the view and engine in use; see [supportedVoiceModes]. */
    modes: List<String>,
    onDismiss: () -> Unit,
    onPick: (String) -> Unit,
) {
    DropdownMenu(
        expanded = true,
        onDismissRequest = onDismiss,
        properties = MenuPopupProperties,
    ) {
        Text(
            text = stringResource(R.string.ime_voice_mode_menu_title),
            style = MaterialTheme.typography.labelMedium,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
            modifier = Modifier.padding(horizontal = 16.dp, vertical = 8.dp),
        )
        for ((mode, label) in VoiceModeMenuEntries) {
            if (mode !in modes) continue
            DropdownMenuItem(
                text = { Text(stringResource(label)) },
                leadingIcon = {
                    // A tick beside the mode in force, and the same width of
                    // nothing beside the others, so the labels line up.
                    if (mode == current) {
                        Icon(Icons.Outlined.Check, contentDescription = null, modifier = Modifier.size(18.dp))
                    } else {
                        Box(Modifier.size(18.dp))
                    }
                },
                onClick = { onPick(mode) },
            )
        }
    }
}

/** The three [VoiceBarSettings.typingMode]s in the order the settings screen lists them. */
private val VoiceModeMenuEntries = listOf(
    VoiceBarSettings.TYPING_BLOCK to R.string.ime_voice_mode_block,
    VoiceBarSettings.TYPING_INTERACTIVE to R.string.ime_voice_mode_interactive,
    VoiceBarSettings.TYPING_PLAIN to R.string.ime_voice_mode_plain,
)

/** Divider thickness between suggestion slots; subtracted from the usable slot width. */
private val SuggestionDividerWidth = 1.dp

/** Breathing room on each side of a suggestion word inside its slot; the shipped default. */
private val SuggestionTextPadding = 6.dp

/** Fallback base size when the ambient text style doesn't name one (Material's `bodyLarge`). */
private val SuggestionFontSize = 16.sp

/**
 * How small a suggestion's font may go, as a fraction of the base size — 16sp
 * down to about 11sp. Past this the word condenses horizontally instead, because
 * shrinking further costs legibility faster than it buys width.
 */
private const val MinSuggestionFontScale = 0.68f

/**
 * How far a suggestion may be squeezed horizontally. Below roughly 0.8 the
 * letterforms visibly distort, so anything still too long after this ellipsizes.
 */
private const val MinSuggestionScaleX = 0.8f

/**
 * How a suggestion word is scaled down to fit its slot.
 *
 * [fontScale] multiplies the base font size; [scaleX] condenses the glyphs
 * horizontally on top of that. `SuggestionTextFit(1f, 1f)` means the word fits
 * as-is and neither is applied.
 */
internal data class SuggestionTextFit(val fontScale: Float, val scaleX: Float) {
    /** True once the word is being squeezed horizontally, not merely shrunk. */
    val condensed: Boolean get() = scaleX < 1f
}

/**
 * Works out how to fit a suggestion of [measuredWidthPx] into [availableWidthPx].
 *
 * Two stages, in the order that costs the least legibility: shrink the point
 * size first (text width is near enough linear in font size, so the ratio of the
 * two widths *is* the scale), and only once that hits [MinSuggestionFontScale]
 * start condensing the glyphs. Together the two floors fit a word about 1.8× the
 * slot width; longer than that and the caller's ellipsis takes over.
 */
internal fun fitSuggestionText(
    measuredWidthPx: Float,
    availableWidthPx: Float,
    minFontScale: Float = MinSuggestionFontScale,
    minScaleX: Float = MinSuggestionScaleX,
): SuggestionTextFit {
    if (availableWidthPx <= 0f || measuredWidthPx <= 0f || measuredWidthPx <= availableWidthPx) {
        return SuggestionTextFit(1f, 1f)
    }
    val needed = availableWidthPx / measuredWidthPx
    val fontScale = needed.coerceAtLeast(minFontScale)
    val scaleX = (needed / fontScale).coerceIn(minScaleX, 1f)
    return SuggestionTextFit(fontScale, scaleX)
}

/**
 * The conversion-IME candidate row: pinyin, zhuyin, kana, jyutping, cangjie and
 * stroke candidates, scrolling horizontally.
 *
 * Deliberately unlike [LatinSuggestionChips] in three ways, all for the same
 * reason — here the candidate list *is* the input method, not a hint about it:
 *  - it scrolls, because the composers rank a dozen candidates and a reading
 *    like `xian` genuinely has that many distinct characters behind it;
 *  - chips are sized to their text and packed from the left, so the best
 *    candidate is always in the same place. Splitting the bar evenly would put
 *    a two-candidate list in two different spots than a three-candidate one;
 *  - the primary is never moved to the centre. That convention reads as
 *    "the middle one is the safe default", which is wrong when the space bar
 *    commits index 0 and the eye has to track which chip that is.
 *
 * No shift re-casing either: Han characters and kana have no case.
 */
@Composable
private fun RowScope.CandidateStrip(
    candidates: List<String>,
    enabled: Boolean,
    alpha: () -> Float,
    /** Same multiplier the Latin strip uses; the two are one row in two modes. */
    textScale: Float,
    /** The hotkey badges, or null when no physical keyboard is asking for them. */
    hints: HintPlan? = null,
    /** The candidate the arrow keys or a stepping space bar moved to, or -1 (#419). */
    highlighted: Int = -1,
    /** Whether holding a candidate opens its menu: earlier, later, never (#580). */
    adjustable: Boolean = false,
    /**
     * The reading being converted, drawn ahead of the candidates when the
     * field does not show it (#973); empty when it does.
     */
    reading: String = "",
    onCandidate: (String, Int) -> Unit,
    onExpand: () -> Unit,
    onAdjust: (String, Int, CandidateAdjustment) -> Unit = { _, _, _ -> },
) {
    val listState = rememberLazyListState()
    // The held candidate whose menu fills the strip, by position; -1 for none.
    var menuFor by remember { mutableIntStateOf(-1) }
    // A new reading starts at the left edge, where its best candidates are.
    // The list keeps its scroll by item key otherwise, so a strip scrolled
    // through for one word opened the next one part way along (#589).
    // requestScrollToItem lands before the next layout, with no frame drawn
    // at the old offset.
    LaunchedEffect(candidates) {
        // The menu belongs to the list it was opened on.
        menuFor = -1
        listState.requestScrollToItem(highlighted.takeIf { it in candidates.indices } ?: 0)
    }
    val held = candidates.getOrNull(menuFor)
    if (held != null) {
        CandidateMenu(
            candidate = held,
            textScale = textScale,
            onPick = { adjustment ->
                onAdjust(held, menuFor, adjustment)
                menuFor = -1
            },
            onDismiss = { menuFor = -1 },
        )
        return
    }
    // Stepping past the right edge has to bring the highlight with it, or the
    // candidate Enter is about to type is one nobody can see.
    ScrollFocusIntoView(highlighted.takeIf { it >= 0 && it < candidates.size }) {
        listState.animateScrollToItem(it)
    }
    // Outside the scrolling row, so the reading stays put while the
    // candidates scroll; a long one gives up its start, the end being where
    // the next key lands.
    if (reading.isNotEmpty()) {
        Text(
            text = reading,
            modifier = Modifier
                .widthIn(max = CandidateReadingMaxWidth)
                .padding(start = 10.dp, end = 6.dp),
            color = MaterialTheme.colorScheme.primary,
            fontSize = CandidateReadingFontSize * textScale,
            maxLines = 1,
            softWrap = false,
            overflow = TextOverflow.StartEllipsis,
        )
        VerticalDivider(
            modifier = Modifier.height(20.dp),
            color = MaterialTheme.colorScheme.outlineVariant,
        )
    }
    LazyRow(
        state = listState,
        modifier = Modifier
            .weight(1f)
            .fillMaxHeight()
            .graphicsLayer { this.alpha = alpha() },
        horizontalArrangement = Arrangement.Start,
        verticalAlignment = Alignment.CenterVertically,
    ) {
        itemsIndexed(candidates, key = { index, text -> "$index\u0000$text" }) { index, suggestion ->
            if (index > 0) {
                VerticalDivider(
                    modifier = Modifier.height(20.dp),
                    color = MaterialTheme.colorScheme.outlineVariant,
                )
            }
            Box(
                modifier = Modifier
                    .widthIn(min = CandidateChipMinWidth)
                    .fillMaxHeight()
                    .padding(vertical = if (index == highlighted) 6.dp else 0.dp)
                    .focusRing(index == highlighted, RoundedCornerShape(10.dp))
                    // By position, not text: the composer works out how much of
                    // the buffer to eat from where the chip sat.
                    .combinedClickable(
                        enabled = enabled,
                        onLongClick = if (adjustable) {
                            { menuFor = index }
                        } else {
                            null
                        },
                    ) { onCandidate(suggestion, index) },
                contentAlignment = Alignment.Center,
            ) {
                Text(
                    text = suggestion,
                    modifier = Modifier.padding(horizontal = 10.dp),
                    color = MaterialTheme.colorScheme.onSurface,
                    fontSize = CandidateFontSize * textScale,
                    // Bold is "what the space bar commits", which is the
                    // highlight once there is one.
                    fontWeight = if (index == highlighted.coerceAtLeast(0)) FontWeight.SemiBold else FontWeight.Normal,
                    textAlign = TextAlign.Center,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
                val hint = hints?.label(HintSurface.SUGGESTION, index)
                if (hint != null) {
                    HintBadge(hint, modifier = Modifier.align(Alignment.BottomCenter))
                }
            }
        }
    }
    // Outside the scrolling row on purpose, so the way to see the rest of the
    // candidates cannot itself scroll off the end of the candidates.
    IconHint(stringResource(R.string.ime_candidates_more_desc)) {
        IconButton(onClick = onExpand, enabled = enabled) {
            Icon(
                Icons.Outlined.ArrowDropDown,
                contentDescription = stringResource(R.string.ime_candidates_more_desc),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

/**
 * The candidate strip's overflow: every candidate the composer ranked, wrapped
 * over as many rows as it takes.
 *
 * Covers the keys while it is open, which is what Sogou, Baidu and QQ all do —
 * at this point you are choosing a character, not typing one. A [FlowRow] rather
 * than a grid because candidates run from one glyph to four and fixed columns
 * would leave ragged gaps; not lazy, because a hundred short chips is nothing.
 */
@Composable
private fun CandidateGridPanel(
    state: KeyboardUiState,
    onCandidate: (String, Int) -> Unit,
    onAdjust: (String, Int, CandidateAdjustment) -> Unit = { _, _, _ -> },
) {
    val textScale = state.settings.suggestionStrip.textScale
    var menuFor by remember(state.expandedCandidates) { mutableIntStateOf(-1) }
    val adjustable = state.composer.isConversion && state.composer.adjustsChoices
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .height(keyRowsHeight(state))
            .verticalScroll(rememberScrollState())
            .padding(horizontal = 8.dp, vertical = 4.dp),
    ) {
        // A held candidate's menu (#580), over the grid it was held in.
        state.expandedCandidates.getOrNull(menuFor)?.let { held ->
            Row(modifier = Modifier.fillMaxWidth().height(CandidateGridRowHeight)) {
                CandidateMenu(
                    candidate = held,
                    textScale = textScale,
                    onPick = { adjustment ->
                        onAdjust(held, menuFor, adjustment)
                        menuFor = -1
                    },
                    onDismiss = { menuFor = -1 },
                )
            }
        }
        // Pages of word suggestions (#385) have no chevron on the strip to
        // close them by, so they carry their own way back to the keys.
        if (!state.composer.isConversion) {
            Row(
                modifier = Modifier
                    .fillMaxWidth()
                    .clickable { onCandidate("", -1) }
                    .padding(vertical = 4.dp),
                horizontalArrangement = Arrangement.Center,
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Icon(
                    Icons.Outlined.KeyboardArrowUp,
                    contentDescription = null,
                    tint = MaterialTheme.colorScheme.onSurfaceVariant,
                    modifier = Modifier.size(18.dp),
                )
                Text(
                    stringResource(R.string.ime_suggestion_pages_close),
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    fontSize = 13.sp,
                )
            }
        }
        // One candidate's chip, wherever the layout below puts it.
        val chip: @Composable (Modifier, Int, String) -> Unit = { cell, index, candidate ->
            Box(
                modifier = cell
                    .padding(2.dp)
                    .widthIn(min = CandidateChipMinWidth)
                    .height(CandidateGridRowHeight)
                    .combinedClickable(
                        onLongClick = if (adjustable) {
                            { menuFor = index }
                        } else {
                            null
                        },
                    ) { onCandidate(candidate, index) },
                contentAlignment = Alignment.Center,
            ) {
                Text(
                    text = candidate,
                    modifier = Modifier.padding(horizontal = 10.dp),
                    color = MaterialTheme.colorScheme.onSurface,
                    fontSize = CandidateFontSize * textScale,
                    fontWeight = if (index == 0) FontWeight.SemiBold else FontWeight.Normal,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
        }
        // Word pages may be a grid of the strip's own columns instead (the
        // expanded-grid setting); conversion candidates run from one glyph to
        // four, which fixed columns would leave ragged, so they always wrap.
        val columns = state.settings.suggestionStrip.slotCount.coerceAtLeast(1)
        if (!state.composer.isConversion && state.settings.suggestionStrip.expandedGrid) {
            state.expandedCandidates.chunked(columns).forEachIndexed { row, words ->
                Row(modifier = Modifier.fillMaxWidth()) {
                    words.forEachIndexed { column, candidate ->
                        chip(Modifier.weight(1f), row * columns + column, candidate)
                    }
                    repeat(columns - words.size) { Spacer(modifier = Modifier.weight(1f)) }
                }
            }
        } else {
            FlowRow(modifier = Modifier.fillMaxWidth()) {
                state.expandedCandidates.forEachIndexed { index, candidate ->
                    chip(Modifier, index, candidate)
                }
            }
        }
    }
}

/**
 * What holding a conversion candidate offers (#580), in the strip's own row:
 * the candidate, then show it earlier, show it later, never show it. Every
 * shipping Chinese IME has this, and it is the only way to tell the keyboard
 * that 亡八 is not a word anyone types — the decoder will not learn that from
 * the user simply not picking it.
 */
@Composable
private fun RowScope.CandidateMenu(
    candidate: String,
    textScale: Float,
    onPick: (CandidateAdjustment) -> Unit,
    onDismiss: () -> Unit,
) {
    Row(
        modifier = Modifier.weight(1f).fillMaxHeight(),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Text(
            text = candidate,
            modifier = Modifier.padding(horizontal = 10.dp).weight(1f, fill = false),
            color = MaterialTheme.colorScheme.onSurface,
            fontSize = CandidateFontSize * textScale,
            fontWeight = FontWeight.SemiBold,
            maxLines = 1,
            overflow = TextOverflow.Ellipsis,
        )
        CandidateMenuItem(Icons.Outlined.KeyboardArrowUp, stringResource(R.string.ime_candidate_menu_earlier)) {
            onPick(CandidateAdjustment.PROMOTE)
        }
        CandidateMenuItem(Icons.Outlined.KeyboardArrowDown, stringResource(R.string.ime_candidate_menu_later)) {
            onPick(CandidateAdjustment.DEMOTE)
        }
        CandidateMenuItem(Icons.Outlined.RemoveCircleOutline, stringResource(R.string.ime_candidate_menu_never)) {
            onPick(CandidateAdjustment.BLOCK)
        }
        // 以词定字: type only the first or the last character of a word, for
        // a character that is hard to find under its own reading.
        if (candidate.codePointCount(0, candidate.length) >= 2) {
            val first = candidate.substring(0, candidate.offsetByCodePoints(0, 1))
            val last = candidate.substring(candidate.offsetByCodePoints(candidate.length, -1))
            CandidateCharItem(first, stringResource(R.string.ime_candidate_menu_first_desc, first), textScale) {
                onPick(CandidateAdjustment.FIRST_CHARACTER)
            }
            CandidateCharItem(last, stringResource(R.string.ime_candidate_menu_last_desc, last), textScale) {
                onPick(CandidateAdjustment.LAST_CHARACTER)
            }
        }
        Spacer(Modifier.weight(1f))
        IconButton(onClick = onDismiss) {
            Icon(
                Icons.Outlined.Close,
                contentDescription = stringResource(R.string.ime_candidate_menu_close_desc),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

/**
 * One character of the held candidate in [CandidateMenu], drawn as itself
 * in a tinted box: a tap types only that character.
 */
@Composable
private fun CandidateCharItem(char: String, description: String, textScale: Float, onClick: () -> Unit) {
    Box(
        modifier = Modifier
            .fillMaxHeight()
            .clickable(onClick = onClick)
            .semantics { contentDescription = description }
            .padding(horizontal = 4.dp),
        contentAlignment = Alignment.Center,
    ) {
        Text(
            text = char,
            modifier = Modifier
                .background(MaterialTheme.colorScheme.primary.copy(alpha = 0.12f), RoundedCornerShape(6.dp))
                .padding(horizontal = 8.dp, vertical = 2.dp),
            color = MaterialTheme.colorScheme.primary,
            fontSize = CandidateFontSize * textScale,
            maxLines = 1,
        )
    }
}

/** One action in [CandidateMenu]: an icon and a word, one tap target. */
@Composable
private fun CandidateMenuItem(icon: ImageVector, label: String, onClick: () -> Unit) {
    Row(
        modifier = Modifier
            .fillMaxHeight()
            .clickable(onClick = onClick)
            .padding(horizontal = 8.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Icon(icon, contentDescription = null, modifier = Modifier.size(18.dp), tint = MaterialTheme.colorScheme.primary)
        Spacer(Modifier.width(4.dp))
        Text(label, color = MaterialTheme.colorScheme.onSurface, fontSize = 14.sp, maxLines = 1)
    }
}

/** Widest the paste chip grows on an otherwise empty strip; longer copies ellipsize (#519). */
private val ClipChipMaxWidth = 280.dp

/**
 * The words of [ranked] laid into [slots] fixed places (#513): the primary at
 * [primarySlot], then the runner-up to its left, the next to its right, and on
 * outwards, the order the centred strip has always used. A slot with no word
 * left for it is null and stays empty, so a word's place depends only on its
 * rank, never on how many others there are.
 */
internal fun fixedSlotOrder(ranked: List<String>, slots: Int, primarySlot: Int): List<String?> {
    if (slots <= 0) return emptyList()
    val out = arrayOfNulls<String>(slots)
    val p = primarySlot.coerceIn(0, slots - 1)
    var next = 0
    fun put(at: Int) {
        if (next < ranked.size) out[at] = ranked[next++]
    }
    put(p)
    for (d in 1 until slots) {
        if (p - d >= 0) put(p - d)
        if (p + d < slots) put(p + d)
    }
    return out.toList()
}

/** Row height in the expanded grid — a comfortable tap target for one glyph. */
private val CandidateGridRowHeight = 44.dp

/** Tap-target floor for a candidate chip; single Hanzi would be narrower. */
private val CandidateChipMinWidth = 44.dp

/** Han and kana need more size than Latin to stay legible at strip height. */
private val CandidateFontSize = 20.sp

/** The reading ahead of the candidates (#973): letters, smaller than the Han after them. */
private val CandidateReadingFontSize = 15.sp

/** Past this the reading shows its end only, so the candidates keep most of the strip. */
private val CandidateReadingMaxWidth = 128.dp

/** How long the last-copy chip keeps its narrow form after the words leave the strip (#612). */
private const val ClipChipShareHoldMs = 1_500L

/**
 * How many copies the row of recent copies holds (#612): the setting's own
 * number once it is above one; at one, which is the chip alone and no button
 * on it, the Recent copies tool still opens a row of [ClipRecentChipsMax].
 */
internal fun recentClipsRowCount(setting: Int): Int = if (setting > 1) setting else ClipRecentChipsMax

/**
 * The recently-copied paste chip shown on the suggestion strip: an accent pill
 * that pastes the last copied text on tap, with a trailing dismiss button. Styled
 * to match [SmartSuggestionChip] so the two chips read as one family.
 */
@Composable
private fun ClipboardSuggestionChip(
    clip: ClipItem,
    onPaste: () -> Unit,
    onDismiss: () -> Unit,
    modifier: Modifier = Modifier,
    /**
     * Set when the chip offers a part of [clip] rather than all of it: the
     * code out of a verification message, or any part in the row of a fresh
     * copy's parts (#612).
     */
    otp: ClipEntity? = null,
    /** False for a chip in the row of recent copies (#414), which shares one ✕ for the row. */
    dismissible: Boolean = true,
    /** Opens the row of recent copies, from a button before the ✕ (#612); null for none. */
    onMore: (() -> Unit)? = null,
) {
    val kb = LocalKbTheme.current
    val feedback = LocalKeyPressFeedback.current
    // A press and hold deletes the copy (#612); not a part of one, whose
    // clip is more than what the chip shows.
    val onDelete = LocalClipChipDelete.current?.takeIf { otp == null }
    val tint = kb.accent
    // The fragment chip is an outline, not a solid — same language as the
    // clipboard panel's own fragment chips, and unmistakably not the ordinary
    // "paste what you copied" pill.
    val fill = if (otp != null) Color.Transparent else tint.copy(alpha = if (kb.dark) 0.20f else 0.11f)

    val bitmap by produceState<ImageBitmap?>(initialValue = null, clip.imagePath) {
        if (clip.kind == ClipKind.IMAGE && clip.imagePath != null) {
            value = withContext(Dispatchers.IO) {
                runCatching {
                    val bounds = BitmapFactory.Options().apply { inJustDecodeBounds = true }
                    BitmapFactory.decodeFile(clip.imagePath, bounds)
                    var sample = 1
                    while (bounds.outWidth / (sample * 2) >= 64 &&
                        bounds.outHeight / (sample * 2) >= 64
                    ) {
                        sample *= 2
                    }
                    BitmapFactory.decodeFile(clip.imagePath, BitmapFactory.Options().apply { inSampleSize = sample })
                        ?.asImageBitmap()
                }.getOrNull()
            }
        } else {
            value = null
        }
    }

    Row(
        modifier = modifier
            .fillMaxHeight()
            .padding(vertical = 5.dp)
            .clip(RoundedCornerShape(50))
            .background(fill)
            .then(
                if (otp != null) {
                    Modifier.dashedOutline(tint.copy(alpha = 0.6f), 50.dp)
                } else {
                    Modifier.border(1.dp, tint.copy(alpha = 0.32f), RoundedCornerShape(50))
                },
            ),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Row(
            modifier = Modifier
                .weight(1f, fill = false)
                .fillMaxHeight()
                .combinedClickable(
                    onLongClickLabel = onDelete?.let { stringResource(R.string.ime_clip_chip_delete_desc) },
                    onLongClick = onDelete?.let { delete -> { feedback(); delete(clip) } },
                ) {
                    feedback()
                    onPaste()
                }
                .padding(horizontal = 6.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(6.dp),
        ) {
            val clipBitmap = bitmap
            if (clip.kind == ClipKind.IMAGE && clipBitmap != null) {
                Image(
                    bitmap = clipBitmap,
                    contentDescription = null,
                    modifier = Modifier
                        .size(22.dp)
                        .clip(CircleShape)
                        .background(tint.copy(alpha = 0.22f)),
                    contentScale = ContentScale.Crop,
                )
            } else {
                Box(
                    modifier = Modifier
                        .size(22.dp)
                        .clip(CircleShape)
                        .background(tint.copy(alpha = 0.22f)),
                    contentAlignment = Alignment.Center,
                ) {
                    Icon(
                        when {
                            otp != null -> clipEntityIcon(otp.kind)
                            clip.kind == ClipKind.IMAGE -> Icons.Outlined.Image
                            else -> Icons.Outlined.ContentPaste
                        },
                        contentDescription = null,
                        tint = tint,
                        modifier = Modifier.size(13.dp),
                    )
                }
            }
            if (otp != null) {
                // "CODE" earns its space here: without it the chip is a bare
                // number, and the user has no way to tell it was lifted out of
                // the message rather than being the whole copy.
                Text(
                    text = stringResource(
                        if (otp.kind == ClipEntityKind.OTP) R.string.ime_clip_chip_code_badge else otp.kind.tagRes,
                    ),
                    color = tint.copy(alpha = 0.85f),
                    fontSize = 9.sp,
                    letterSpacing = 0.8.sp,
                    fontWeight = FontWeight.Medium,
                    maxLines = 1,
                )
            }
            val textToDisplay = when {
                otp != null -> otp.value
                clip.kind == ClipKind.IMAGE -> stringResource(
                    // "System UI" is the package label Android gives a
                    // screenshot, not wording anyone reads.
                    if (clip.sourceApp == "System UI") {
                        R.string.ime_clip_chip_screenshot
                    } else {
                        R.string.ime_clip_chip_image
                    },
                )
                // One line is all the chip shows; the rest is not laid out.
                clip.text.isNotBlank() -> clipPreviewText(clip.text, lines = 1)
                else -> stringResource(R.string.ime_clip_chip_item)
            }
            Text(
                text = textToDisplay,
                // suggestionText, not keyText: this chip sits on the strip,
                // over the board. A theme whose keys invert the board — dark
                // letters on cream caps over a near-black board — draws the
                // key colour invisible here.
                color = kb.suggestionText,
                fontSize = 13.sp,
                fontWeight = if (otp != null) FontWeight.Medium else FontWeight.Normal,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.weight(1f, fill = false),
            )
        }
        if (onMore != null) Box(
            modifier = Modifier
                .fillMaxHeight()
                .clip(CircleShape)
                .clickable {
                    feedback()
                    onMore()
                }
                .padding(start = 6.dp, end = if (dismissible) 0.dp else 8.dp),
            contentAlignment = Alignment.Center,
        ) {
            Icon(
                Icons.Outlined.History,
                contentDescription = stringResource(R.string.ime_clip_chip_more_desc),
                tint = tint.copy(alpha = 0.85f),
                modifier = Modifier.size(16.dp),
            )
        }
        if (dismissible) Box(
            modifier = Modifier
                .fillMaxHeight()
                .clip(CircleShape)
                .clickable {
                    feedback()
                    onDismiss()
                }
                .padding(horizontal = 8.dp),
            contentAlignment = Alignment.Center,
        ) {
            Icon(
                Icons.Outlined.Close,
                contentDescription = stringResource(R.string.ime_clip_chip_dismiss_desc),
                tint = tint.copy(alpha = 0.7f),
                modifier = Modifier.size(15.dp),
            )
        }
    }
}

/**
 * The one-time-code chip: a code found in a just-arrived notification, one tap
 * from typed. Dashed outline in the same language as the clipboard fragment
 * chips — this is a piece lifted out of something, not typed text — plus the
 * posting app's name, so the user can tell whose code they are about to trust
 * before they trust it.
 */
@Composable
private fun OtpSuggestionChip(
    otp: NotificationOtp,
    onAccept: () -> Unit,
    onDismiss: () -> Unit,
    modifier: Modifier = Modifier,
    stretch: Boolean = false,
) {
    val kb = LocalKbTheme.current
    val feedback = LocalKeyPressFeedback.current
    val tint = kb.accent
    Row(
        modifier = modifier
            .fillMaxHeight()
            .padding(vertical = 5.dp)
            .clip(RoundedCornerShape(50))
            .dashedOutline(tint.copy(alpha = 0.6f), 50.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Row(
            modifier = Modifier
                .weight(1f, fill = stretch)
                .fillMaxHeight()
                .clickable {
                    feedback()
                    onAccept()
                }
                .padding(horizontal = 6.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(6.dp),
        ) {
            Box(
                modifier = Modifier
                    .size(22.dp)
                    .clip(CircleShape)
                    .background(tint.copy(alpha = 0.22f)),
                contentAlignment = Alignment.Center,
            ) {
                Icon(
                    Icons.Outlined.Password,
                    contentDescription = null,
                    tint = tint,
                    modifier = Modifier.size(13.dp),
                )
            }
            Text(
                text = stringResource(R.string.ime_clip_chip_code_badge),
                color = tint.copy(alpha = 0.85f),
                fontSize = 9.sp,
                letterSpacing = 0.8.sp,
                fontWeight = FontWeight.Medium,
                maxLines = 1,
            )
            Text(
                text = otp.code,
                // On the board, so the board's text colour — see the same
                // note in [ClipboardSuggestionChip].
                color = kb.suggestionText,
                fontSize = 13.sp,
                fontWeight = FontWeight.Medium,
                maxLines = 1,
            )
            Text(
                text = otp.sourceApp,
                color = kb.suggestionText.copy(alpha = 0.6f),
                fontSize = 11.sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.weight(1f, fill = false),
            )
        }
        Box(
            modifier = Modifier
                .fillMaxHeight()
                .clip(CircleShape)
                .clickable {
                    feedback()
                    onDismiss()
                }
                .padding(horizontal = 8.dp),
            contentAlignment = Alignment.Center,
        ) {
            Icon(
                Icons.Outlined.Close,
                contentDescription = stringResource(R.string.ime_otp_chip_dismiss_desc),
                tint = tint.copy(alpha = 0.7f),
                modifier = Modifier.size(15.dp),
            )
        }
    }
}

/**
 * A task that has fallen due: its words, which open the list, then a tick, a
 * snooze and a close. Actions go through [TodoChipActions], so a chip few people
 * ever see adds no parameter to the strip's long chain of callers.
 */
@Composable
private fun TodoDueSuggestionChip(chip: TodoDueChip, modifier: Modifier = Modifier) {
    val kb = LocalKbTheme.current
    val feedback = LocalKeyPressFeedback.current
    val tint = kb.accent
    fun act(action: TodoChipAction) {
        feedback()
        TodoChipActions.handler(chip.id, action)
    }
    Row(
        modifier = modifier
            .fillMaxHeight()
            .padding(vertical = 5.dp)
            .clip(RoundedCornerShape(50))
            .dashedOutline(tint.copy(alpha = 0.6f), 50.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Row(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight()
                .clickable { act(TodoChipAction.OPEN) }
                .padding(start = 10.dp, end = 4.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(6.dp),
        ) {
            Icon(Icons.Outlined.Notifications, contentDescription = null, tint = tint, modifier = Modifier.size(14.dp))
            Text(
                text = chip.text,
                color = kb.suggestionText,
                fontSize = 13.sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }
        for ((icon, label, action) in listOf(
            Triple(Icons.Outlined.Check, R.string.ime_todo_chip_done_desc, TodoChipAction.DONE),
            Triple(Icons.Outlined.Schedule, R.string.ime_todo_chip_snooze_desc, TodoChipAction.SNOOZE),
            Triple(Icons.Outlined.Close, R.string.ime_todo_chip_close_desc, TodoChipAction.CLOSE),
        )) {
            Box(
                modifier = Modifier
                    .fillMaxHeight()
                    .clip(CircleShape)
                    .clickable { act(action) }
                    .padding(horizontal = 7.dp),
                contentAlignment = Alignment.Center,
            ) {
                Icon(icon, contentDescription = stringResource(label), tint = tint.copy(alpha = 0.8f), modifier = Modifier.size(16.dp))
            }
        }
    }
}

/**
 * The snippet chip: a snippet whose trigger matched and which was marked "ask
 * first", one tap from inserted.
 *
 * It shows the text it would put in rather than the snippet's name. The name is
 * how the panel lists it, and for a pack of replies it is a category ("Thank-you
 * letter"); what matters here is the sentence about to be typed for you. Solid
 * fill in the [SmartSuggestionChip] language — this is text the user set up,
 * not a piece lifted out of somewhere else.
 */
@Composable
private fun SnippetOfferChip(
    chip: SnippetChip,
    onAccept: () -> Unit,
    modifier: Modifier = Modifier,
    stretch: Boolean = false,
    swap: Boolean = false,
    onDrill: (() -> Unit)? = null,
) {
    val kb = LocalKbTheme.current
    val feedback = LocalKeyPressFeedback.current
    val tint = kb.accent
    // One line, so the newlines in a signature or a letter have to become
    // spaces; a snippet with any in it would otherwise show only its first.
    val preview = remember(chip.text) { chip.text.replace(WHITESPACE_RUN, " ").trim() }
    // Accent-tinted like the smart chip — it is an offer, not a word — but the
    // outline follows the theme's chip shape.
    val chipShape = kb.chipShape()
    Row(
        modifier = modifier
            .fillMaxHeight()
            .padding(vertical = 5.dp)
            .clip(chipShape)
            .background(tint.copy(alpha = if (kb.dark) 0.20f else 0.11f))
            .border(1.dp, tint.copy(alpha = 0.32f), chipShape)
            .clickable {
                feedback()
                onAccept()
            },
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Row(
            modifier = Modifier
                .weight(1f, fill = stretch)
                .fillMaxHeight()
                .padding(start = 6.dp, end = 10.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(6.dp),
        ) {
            Box(
                modifier = Modifier
                    .size(22.dp)
                    .clip(CircleShape)
                    .background(tint.copy(alpha = 0.22f)),
                contentAlignment = Alignment.Center,
            ) {
                Icon(
                    if (swap) Icons.Outlined.SwapHoriz else toolIcon(ToolbarTool.SNIPPETS),
                    contentDescription = stringResource(
                        if (swap) R.string.ime_snippet_swap_desc else R.string.ime_snippet_offer_desc,
                        chip.label,
                    ),
                    tint = tint,
                    modifier = Modifier.size(13.dp),
                )
            }
            Text(
                text = preview,
                // Strip text, not key text: the chip sits on the board, and a
                // theme may ink its keys against it.
                color = kb.suggestionText,
                fontSize = 13.sp,
                fontWeight = FontWeight.Medium,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.weight(1f, fill = false),
            )
        }
        // A chip that stands for a linked snippet with more behind it gets a
        // second target, split off the way the add-word chip splits off its
        // ✕: tapping the text takes what the chip says, tapping the chevron
        // asks what else that snippet has. Its own node, so a screen reader
        // reads the two as the two things they are.
        if (onDrill != null) {
            Box(
                modifier = Modifier
                    .width(1.dp)
                    .fillMaxHeight()
                    .padding(vertical = 7.dp)
                    .background(tint.copy(alpha = 0.28f)),
            )
            Box(
                modifier = Modifier
                    .fillMaxHeight()
                    .clickable {
                        feedback()
                        onDrill()
                    }
                    .padding(horizontal = 7.dp),
                contentAlignment = Alignment.Center,
            ) {
                Icon(
                    Icons.Outlined.ChevronRight,
                    contentDescription = stringResource(
                        R.string.ime_snippet_offer_more_desc,
                        chip.label,
                    ),
                    tint = tint.copy(alpha = 0.7f),
                    modifier = Modifier.size(15.dp),
                )
            }
        }
    }
}

/**
 * Every snippet chip the strip is showing at once.
 *
 * One chip is drawn exactly as it always was — the overwhelmingly common case
 * is still a single ask-first offer, and it should not start looking like a
 * list. Several are a scrolling row, for the same reason the word candidates
 * scroll: a snippet may link to a dozen others, and hiding the rest behind a
 * "more" button that opens a panel would trade one tap for a mode switch and
 * take the strip away while it did.
 */
@Composable
private fun SnippetOfferRow(
    offers: SnippetOfferSet,
    onAction: (StripOfferAction) -> Unit,
    modifier: Modifier = Modifier,
    stretch: Boolean = false,
) {
    val chips = offers.visibleChips()
    if (offers.isSingle()) {
        SnippetOfferChip(
            chip = chips.first(),
            onAccept = { onAction(StripOfferAction.Accept(0)) },
            modifier = modifier,
            stretch = stretch,
        )
        return
    }
    val scroll = rememberScrollState()
    // Back to the left whenever the offer itself changes or the user walks a
    // level: the first chip is the default answer and has to be the one in
    // front of them.
    LaunchedEffect(offers.rootId, offers.consumed, offers.path) { scroll.scrollTo(0) }
    Row(
        modifier = modifier.fillMaxHeight().horizontalScroll(scroll),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.spacedBy(4.dp),
    ) {
        if (offers.path.isNotEmpty()) {
            SnippetBackChip(
                label = offers.rootLabel,
                onClick = { onAction(StripOfferAction.Back) },
            )
        }
        chips.forEachIndexed { index, chip ->
            SnippetOfferChip(
                chip = chip,
                onAccept = { onAction(StripOfferAction.Accept(index)) },
                modifier = Modifier.widthIn(max = 180.dp),
                swap = offers.kind == SnippetOfferKind.SWAP,
                onDrill = if (chip.drillable && offers.canDrill(chip.snippetId)) {
                    { onAction(StripOfferAction.Drill(index)) }
                } else {
                    null
                },
            )
        }
    }
}

/** Leaves a walk into a linked snippet and goes back to what matched. */
@Composable
private fun SnippetBackChip(label: String, onClick: () -> Unit) {
    val kb = LocalKbTheme.current
    val feedback = LocalKeyPressFeedback.current
    val tint = kb.accent
    val chipShape = kb.chipShape()
    Box(
        modifier = Modifier
            .fillMaxHeight()
            .padding(vertical = 5.dp)
            .clip(chipShape)
            .background(tint.copy(alpha = if (kb.dark) 0.14f else 0.08f))
            .border(1.dp, tint.copy(alpha = 0.32f), chipShape)
            .clickable {
                feedback()
                onClick()
            }
            .padding(horizontal = 7.dp),
        contentAlignment = Alignment.Center,
    ) {
        Icon(
            Icons.AutoMirrored.Outlined.ArrowBack,
            contentDescription = stringResource(R.string.ime_snippet_offer_back_desc, label),
            tint = tint,
            modifier = Modifier.size(15.dp),
        )
    }
}

/**
 * The add-word chip: a word nothing recognises, asking to be let into the
 * personal dictionary.
 *
 * Same accent language as the snippet offer above, with the word shown as the
 * user typed it — the whole question is whether that spelling is right, so
 * nothing here tidies it up. Two targets: the word itself accepts, the ✕
 * declines and stops the keyboard asking about that word again.
 */
@Composable
private fun LearnWordChip(
    word: String,
    onAccept: () -> Unit,
    onDecline: () -> Unit,
    modifier: Modifier = Modifier,
    stretch: Boolean = false,
) = OfferChip(
    label = stringResource(R.string.ime_learn_word_offer, word),
    icon = Icons.Outlined.LibraryAdd,
    declineDescription = stringResource(R.string.ime_learn_word_never_desc, word),
    onAccept = onAccept,
    onDecline = onDecline,
    modifier = modifier,
    stretch = stretch,
)

/**
 * The strip's ask-first chip: a line of text, a tap to accept, a cross to
 * decline.
 *
 * One composable rather than one per question, so the add-word chip and the
 * sandbox chip cannot drift apart visually — they sit in the same place on the
 * same row and a user should read them as the same kind of thing.
 */
@Composable
private fun OfferChip(
    label: String,
    icon: androidx.compose.ui.graphics.vector.ImageVector,
    declineDescription: String,
    onAccept: () -> Unit,
    onDecline: () -> Unit,
    modifier: Modifier = Modifier,
    stretch: Boolean = false,
    onExplain: (() -> Unit)? = null,
) {
    val kb = LocalKbTheme.current
    val feedback = LocalKeyPressFeedback.current
    val tint = kb.accent
    val chipShape = kb.chipShape()
    Row(
        modifier = modifier
            .fillMaxHeight()
            .padding(vertical = 5.dp)
            .clip(chipShape)
            .background(tint.copy(alpha = if (kb.dark) 0.20f else 0.11f))
            .border(1.dp, tint.copy(alpha = 0.32f), chipShape),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Row(
            modifier = Modifier
                .weight(1f, fill = stretch)
                .fillMaxHeight()
                .combinedClickable(
                    // A chip that asks about a setting opens it on a hold, so
                    // "what is this?" has an answer short of saying yes (#312).
                    onLongClick = onExplain?.let { explain ->
                        {
                            feedback()
                            explain()
                        }
                    },
                    onClick = {
                        feedback()
                        onAccept()
                    },
                )
                .padding(start = 6.dp, end = 8.dp),
            verticalAlignment = Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(6.dp),
        ) {
            Box(
                modifier = Modifier
                    .size(22.dp)
                    .clip(CircleShape)
                    .background(tint.copy(alpha = 0.22f)),
                contentAlignment = Alignment.Center,
            ) {
                Icon(
                    icon,
                    contentDescription = null,
                    tint = tint,
                    modifier = Modifier.size(13.dp),
                )
            }
            // Two lines, shrinking before it cuts: a chip squeezed beside the
            // candidates is too narrow for a whole question on one line, and
            // a question read as "Swipe using only…" cannot be answered (#312).
            BasicText(
                text = label,
                // Strip text, not key text: the chip sits on the board, and a
                // theme may ink its keys against it. A line height relative to
                // the size, not the theme's 24 sp, so two lines fit the strip.
                style = TextStyle(
                    color = kb.suggestionText,
                    fontSize = 13.sp,
                    fontWeight = FontWeight.Medium,
                    lineHeight = 1.15.em,
                ),
                maxLines = 2,
                overflow = TextOverflow.Ellipsis,
                autoSize = TextAutoSize.StepBased(minFontSize = 10.sp, maxFontSize = 13.sp, stepSize = 0.5.sp),
                modifier = Modifier.weight(1f, fill = false),
            )
        }
        Box(
            modifier = Modifier
                .width(1.dp)
                .fillMaxHeight()
                .padding(vertical = 7.dp)
                .background(tint.copy(alpha = 0.28f)),
        )
        Box(
            modifier = Modifier
                .fillMaxHeight()
                .clickable {
                    feedback()
                    onDecline()
                }
                .padding(horizontal = 9.dp),
            contentAlignment = Alignment.Center,
        ) {
            Icon(
                Icons.Outlined.Close,
                contentDescription = declineDescription,
                tint = tint.copy(alpha = 0.7f),
                modifier = Modifier.size(15.dp),
            )
        }
    }
}

/**
 * The same offer, shrunk to its icon: one accent-tinted button, no words.
 *
 * The strip is four candidates wide on a phone, and a chip that says what it
 * does in a sentence takes half of that (#264). That is the worst trade
 * exactly where this one is used — the words it would cover are the words the
 * offer exists to improve on — so the sentence moves to the content
 * description, the tool it belongs to and the setting's own info text, and the
 * row keeps its candidates. Same accent language as [OfferChip] so the two
 * still read as the same kind of thing.
 *
 * The ✕ goes with the label: there is no room for a second target, and the
 * chip is transient anyway (the cursor leaving the word takes it down). The
 * hold is the way to send it away early, and TalkBack is told so.
 */
@Composable
private fun StripIconChip(
    icon: ImageVector,
    description: String,
    dismissDescription: String,
    onAccept: () -> Unit,
    onDismiss: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val kb = LocalKbTheme.current
    val feedback = LocalKeyPressFeedback.current
    val tint = kb.accent
    val chipShape = kb.chipShape()
    Box(
        modifier = modifier
            .fillMaxHeight()
            .padding(vertical = 5.dp, horizontal = 4.dp)
            .width(34.dp)
            .clip(chipShape)
            .background(tint.copy(alpha = if (kb.dark) 0.20f else 0.11f))
            .border(1.dp, tint.copy(alpha = 0.32f), chipShape)
            .combinedClickable(
                onLongClickLabel = dismissDescription,
                onLongClick = {
                    feedback()
                    onDismiss()
                },
                onClick = {
                    feedback()
                    onAccept()
                },
            ),
        contentAlignment = Alignment.Center,
    ) {
        Icon(
            icon,
            contentDescription = description,
            tint = tint,
            modifier = Modifier.size(17.dp),
        )
    }
}

/** Any run of spaces, tabs or newlines, folded to one space for a preview. */
private val WHITESPACE_RUN = Regex("""\s+""")

/**
 * Fallback content for the dedicated emoji row before any usage exists.
 *
 * Longer than the row fits on purpose: the row scrolls by default
 * ([EmojiSettings.barScrollable]), so a starter set the length of one screen
 * would leave nothing to swipe to and make a fresh install look like scrolling
 * was broken. Written as neutral bases — [visibleEmojiBarItems] applies the
 * default skin tone to this list, and only to this list, because history
 * entries are already exact sequences.
 */
private val DEFAULT_BAR_EMOJIS = listOf(
    "😂", "❤️", "🤣", "👍", "😭", "🙏", "😍", "🥰", "😊", "🎉", "😅", "🔥",
    "🥺", "😁", "💯", "✨", "🙌", "👏", "🤔", "😎", "😢", "🤗", "💪", "👌",
)

/**
 * Height of the dedicated emoji row. The emoji panel absorbs it while
 * open (the row hides there), so the keyboard's total height never
 * changes when switching between keys and the emoji panel.
 */
internal val EmojiBarHeight = 40.dp

/**
 * The dedicated emoji row (Gboard style): favourites and/or most-used
 * emojis one tap from any screen, with a launcher into the full panel.
 * Used as its own row (ALWAYS) or swapped into the strip (BUTTON).
 */
@Composable
private fun EmojiBarStrip(
    state: KeyboardUiState,
    onEmoji: (String) -> Unit,
    onOpenPanel: () -> Unit,
    modifier: Modifier = Modifier,
) {
    // Favourites already lead the recents/frequents lists (EmojiUsage pins
    // them), so each content mode is a straight pick. History entries are
    // exact sequences already; only the starter set is written as neutral
    // bases, so it is the one that needs the skin tone applied.
    val emojis = visibleEmojiBarItems(state)
    val scrollable = state.settings.emoji.barScrollable
    val count = state.settings.emoji.barCount.coerceIn(EmojiBarCountRange)
    Row(
        modifier = modifier
            .fillMaxWidth()
            .height(EmojiBarHeight),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        IconHint(stringResource(R.string.ime_emoji_panel_open_desc)) {
            IconButton(onClick = onOpenPanel, modifier = Modifier.size(36.dp)) {
                Icon(
                    Icons.Outlined.EmojiEmotions,
                    contentDescription = stringResource(R.string.ime_emoji_panel_open_desc),
                    modifier = Modifier.size(20.dp),
                    tint = MaterialTheme.colorScheme.onSurfaceVariant,
                )
            }
        }
        // One slot width drives both layouts: `count` emoji span the leftover
        // width either way, and the glyphs shrink into their slot, so a
        // tighter setting packs more in instead of clipping or overflowing.
        // Scrolling only decides whether the emoji past those slots are
        // reachable — off (the default), the row is a fixed set of taps and a
        // sideways swipe can't slide it out from under a finger.
        BoxWithConstraints(modifier = Modifier.weight(1f)) {
            val slot = maxWidth / count
            val fontScale = LocalDensity.current.fontScale
            // Cap at the historical 24sp; below that the glyph is sized in dp
            // (slot-relative) and converted back, so a large system font scale
            // can't push emoji wider than their slot.
            val fontSize = minOf(24f, slot.value * 0.74f / fontScale).sp
            val hints = armedHintPlan(if (state.toolPicker != null) withLiveTyping(state) else state)
            if (scrollable) {
                LazyRow(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceEvenly,
                ) {
                    itemsIndexed(emojis) { index, emoji ->
                        EmojiBarCell(
                            emoji, slot, fontSize, onEmoji,
                            hint = hints?.label(HintSurface.EMOJI_ROW, index),
                        )
                    }
                }
            } else {
                // SpaceEvenly spreads the cells when there are fewer emoji
                // than slots, so a short favourites list doesn't huddle left.
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.SpaceEvenly,
                ) {
                    emojis.take(count).forEachIndexed { index, emoji ->
                        EmojiBarCell(
                            emoji, slot, fontSize, onEmoji,
                            hint = hints?.label(HintSurface.EMOJI_ROW, index),
                        )
                    }
                }
            }
        }
    }
}

/** One tappable emoji slot of [EmojiBarStrip], sized by the row's packing. */
@Composable
private fun EmojiBarCell(
    emoji: String,
    width: Dp,
    fontSize: TextUnit,
    onEmoji: (String) -> Unit,
    hint: String? = null,
) {
    Box(contentAlignment = Alignment.Center) {
        Text(
            // Drawn as this font spells it; onEmoji still commits the standard form.
            text = LocalEmojiShaper.current.shape(emoji),
            modifier = Modifier
                .width(width)
                // Lifted so the badge sits under the emoji rather than over it;
                // the cell's own size is unchanged.
                .offset(y = if (hint != null) -(HintBadgeHeight / 2) else 0.dp)
                .clickable { onEmoji(emoji) }
                .padding(vertical = 4.dp),
            fontSize = fontSize,
            fontFamily = emojiFamilyFor(emoji),
            textAlign = TextAlign.Center,
            maxLines = 1,
            // The theme's bodyLarge line is 24sp, the same as the glyph, and an
            // emoji font draws taller than its em: in a line that size the
            // default clip cut the bottom off every emoji (#601). The font's
            // own line fits it, and nothing is clipped if one still overhangs.
            // (A `lineHeight` argument of Unspecified would fall back to the
            // style's, so the style itself is copied.)
            style = LocalTextStyle.current.copy(lineHeight = TextUnit.Unspecified),
            overflow = TextOverflow.Visible,
        )
        if (hint != null) {
            HintBadge(hint, modifier = Modifier.align(Alignment.BottomCenter))
        }
    }
}

/**
 * Height of the dedicated symbol row (chips are text, not emoji).
 *
 * The shipped value, and still the fallback for the Fancy Text strip, which
 * mirrors this row but is not the same row. The symbol row itself reads
 * [RowSettings.symbolRowHeightDp] so it can be matched to the number row.
 */
internal val SymbolRowHeight = 40.dp

/**
 * What to call one symbol set. A shipped set that still carries its shipped
 * name is drawn from resources; a set the user made or renamed keeps the name
 * the user typed.
 */
@Composable
private fun symbolSetName(set: SymbolSet): String =
    BuiltInSymbolSets.nameRes(set)?.let { stringResource(it) } ?: set.name

/**
 * Properties for the strip pickers' [DropdownMenu]s.
 *
 * A menu is its own window, and Material's default properties make that window
 * focusable. Raised from an app that is only a window, that is harmless; raised
 * from the IME it takes input focus away from the editor the keyboard is typing
 * into. The app sees its field lose focus and hides the keyboard, then shows it
 * again once focus comes back — and the restart tears the menu's composition
 * down mid-flight, so the picker either flickers shut or comes back with the
 * keyboard behind it gone. How visible that is depends on how the target window
 * reacts to losing focus, which is why the row pickers look fine in most apps
 * and misbehave in dialogs and in this app's own settings search.
 *
 * Every other popup the keyboard raises is non-focusable for this reason (see
 * [LanguagePickerPopup], `GrammarDialectPicker`); these two menus were the
 * outliers. Tapping outside still dismisses: Compose asks for outside touches
 * whether or not the window is focusable.
 */
internal val MenuPopupProperties = PopupProperties(focusable = false)

/** Pins a popup to the keyboard window's own corner, whatever its anchor. */
private object WindowOriginPositionProvider : PopupPositionProvider {
    override fun calculatePosition(
        anchorBounds: IntRect,
        windowSize: IntSize,
        layoutDirection: LayoutDirection,
        popupContentSize: IntSize,
    ): IntOffset = IntOffset.Zero
}

/**
 * Swallows the tap that closes an open strip picker.
 *
 * A window that takes no focus also takes no touch grab, so the tap that
 * dismisses the menu carries on to whatever is underneath — and under these
 * strips is the key grid, which would type a character on the way out. This
 * covers the keyboard with an invisible window that takes that tap instead.
 * The menu's own window is added after this one and so sits above it.
 */
@Composable
internal fun StripMenuScrim(onDismiss: () -> Unit) {
    Popup(
        popupPositionProvider = WindowOriginPositionProvider,
        properties = MenuPopupProperties,
    ) {
        Box(
            modifier = Modifier
                .fillMaxSize()
                // On press, not on tap: a dismissing finger that then drags
                // must not leave the menu open under it.
                .pointerInput(Unit) { detectTapGestures(onPress = { onDismiss() }) },
        )
    }
}

/**
 * The dedicated symbol row: one symbol set's characters and snippets a tap
 * away, with a picker chip on the left switching between the enabled sets
 * (or the sets the active keyboard mode prescribes).
 *
 * Since issue #83 the row can be a stack of [RowSettings.symbolRowLines] lines,
 * each [RowSettings.symbolRowHeightDp] tall, and an entry can carry a
 * press-and-hold popup of its own ([SymbolSet.popups]). One line is the
 * [LazyRow] it always was; more lines are a [LazyHorizontalGrid] when the stack
 * scrolls together and a column of independent [LazyRow]s when each line
 * scrolls on its own. All three draw the same [SymbolCell], and the entry
 * order is [symbolRowLineEntries]'s in both stacked forms, so the row looks the
 * same in either until a line is actually scrolled.
 *
 * Holding an entry that has no popup of its own opens a menu instead (#323):
 * remove that entry, hide the row in the active mode, delete the set, or open
 * the settings behind the row. See [SymbolEntryMenu].
 */
@Composable
private fun SymbolRowStrip(
    state: KeyboardUiState,
    onInsert: (String) -> Unit,
    callbacks: SymbolRowCallbacks,
    modifier: Modifier = Modifier,
) {
    val settings = state.settings
    // An edited built-in is stored as a custom set under the built-in's id;
    // resolveSymbolSets shadows the shipped one rather than listing both.
    val allSets = resolveSymbolSets(settings.customSymbolSets)
    val enabledSets = settings.symbolRowSetIds
        .mapNotNull { id -> allSets.firstOrNull { it.id == id } }
        .ifEmpty { BuiltInSymbolSets.sets }
    val active = activeSymbolSet(state)
    var pickerOpen by remember { mutableStateOf(false) }
    val feedback = LocalKeyPressFeedback.current
    // What a held entry's menu may offer, worked out once for the whole row.
    // The mode is the one the service applied; its own sets or an explicit
    // "on" are what make the row part of it, as opposed to a row it inherits.
    val mode = state.activeModeId?.let { id -> settings.keyboardModes.firstOrNull { it.id == id } }
    val activeName = symbolSetName(active)
    // Remembered so the cells, which take it, are skipped on an unrelated
    // recomposition of the row.
    val menu = remember(active, activeName, mode) {
        SymbolEntryMenuSpec(
            setName = activeName,
            removable = active.chars.size > 1,
            hideInMode = mode?.takeIf { it.symbolRowEnabled == true || it.symbolSetIds != null },
            // A shipped set cannot be deleted, only reset from its editor.
            deletable = BuiltInSymbolSets.byId(active.id) == null,
        )
    }
    // Asked here rather than in the cell: the question has to outlive the
    // menu that raised it, and the cell is a slot in a lazy list.
    var confirmDelete by remember { mutableStateOf<SymbolSet?>(null) }
    confirmDelete?.let { set ->
        SymbolSetDeleteConfirm(
            name = symbolSetName(set),
            onConfirm = {
                confirmDelete = null
                callbacks.onAction(SymbolRowAction.DeleteSet(set.id))
            },
            onDismiss = { confirmDelete = null },
        )
    }
    Row(
        modifier = modifier
            .fillMaxWidth()
            .height(symbolRowHeight(settings.rows)),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        // Only offer the picker when there is something to switch to.
        Box {
            Row(
                modifier = Modifier
                    .clip(RoundedCornerShape(14.dp))
                    .clickable(enabled = enabledSets.size > 1) {
                        feedback()
                        pickerOpen = true
                    }
                    .padding(start = 10.dp, end = 2.dp, top = 4.dp, bottom = 4.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                if (enabledSets.size > 1) {
                    Text(
                        symbolSetName(active),
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        maxLines = 1,
                    )
                    Icon(
                        Icons.Outlined.ArrowDropDown,
                        contentDescription = stringResource(R.string.ime_symbol_set_switch_desc),
                        modifier = Modifier.size(18.dp),
                        tint = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
            }
            if (pickerOpen) StripMenuScrim(onDismiss = { pickerOpen = false })
            DropdownMenu(
                expanded = pickerOpen,
                onDismissRequest = { pickerOpen = false },
                properties = MenuPopupProperties,
            ) {
                for (set in enabledSets) {
                    DropdownMenuItem(
                        text = { Text(symbolSetName(set)) },
                        trailingIcon = if (set.id == active.id) {
                            {
                                Icon(
                                    Icons.Outlined.Check,
                                    contentDescription = null,
                                    modifier = Modifier.size(16.dp),
                                )
                            }
                        } else {
                            null
                        },
                        onClick = {
                            pickerOpen = false
                            callbacks.onSetSelect(set.id)
                        },
                    )
                }
            }
        }
        val hints = armedHintPlan(if (state.toolPicker != null) withLiveTyping(state) else state)
        val lines = symbolRowLines(settings.rows)
        val lineHeight = settings.rows.symbolRowHeightDp.dp
        val cell: @Composable (Int) -> Unit = { index ->
            SymbolCell(
                index = index,
                symbol = active.chars[index],
                set = active,
                settings = settings,
                hint = hints?.label(HintSurface.SYMBOL_ROW, index),
                onInsert = onInsert,
                modifier = Modifier.height(lineHeight),
                menu = menu,
                onMenuAction = { action ->
                    if (action == null) confirmDelete = active else callbacks.onAction(action)
                },
            )
        }
        when {
            lines <= 1 -> LazyRow(
                modifier = Modifier.weight(1f),
                verticalAlignment = Alignment.CenterVertically,
                horizontalArrangement = Arrangement.SpaceEvenly,
            ) {
                // Positional, never keyed: a set may repeat an entry, and a
                // duplicate key is a hard crash in a lazy list.
                itemsIndexed(active.chars) { index, _ -> cell(index) }
            }
            settings.rows.symbolRowScroll == SymbolRowScroll.TOGETHER -> LazyHorizontalGrid(
                rows = GridCells.Fixed(lines),
                modifier = Modifier
                    .weight(1f)
                    .fillMaxHeight(),
                horizontalArrangement = Arrangement.SpaceEvenly,
            ) {
                // The grid fills each column top to bottom, which is the order
                // symbolRowLineEntries deals the separate lines in.
                itemsIndexed(active.chars) { index, _ -> cell(index) }
            }
            else -> Column(modifier = Modifier.weight(1f)) {
                for (line in symbolRowLineEntries(active.chars.size, lines)) {
                    LazyRow(
                        modifier = Modifier
                            .fillMaxWidth()
                            .height(lineHeight),
                        verticalAlignment = Alignment.CenterVertically,
                        horizontalArrangement = Arrangement.SpaceEvenly,
                    ) {
                        lazyRowItems(line) { index -> cell(index) }
                    }
                }
            }
        }
    }
}

/**
 * One entry of the symbol row: a tap types it, and where the set gives it a
 * popup ([SymbolSet.popupFor]), a hold opens that popup exactly as a hold on a
 * key opens the key's alternates. The popup is the key grid's own
 * [AlternatesPopup] over a stand-in [Key], so it takes the same columns, font
 * scale, padding and hold-to-select behaviour the user set for the keys.
 *
 * The tap stays a [clickable] for its ripple and its slop rules; the hold is a
 * pointer handler *inside* it, added only to a cell that has a popup. The
 * handler consumes nothing until the hold fires, so a tap reaches the clickable
 * and a drag reaches the list's scroll as before. Once it fires it owns the
 * finger: every later move steers the popup and is consumed, which is what
 * tells the clickable to give up its press and the scroll never to start.
 *
 * A cell with no popup holds to [SymbolEntryMenu] instead, through the same
 * handler with no hold-to-select: the popup was there first, and an entry the
 * user gave one keeps it.
 */
@Composable
private fun SymbolCell(
    /** Where the entry sits in [set], so a repeated entry is removed where it was held. */
    index: Int,
    symbol: String,
    set: SymbolSet,
    settings: KeyboardSettings,
    hint: String?,
    onInsert: (String) -> Unit,
    modifier: Modifier = Modifier,
    menu: SymbolEntryMenuSpec? = null,
    /** A menu item; null asks to delete the set, which the row confirms first. */
    onMenuAction: (SymbolRowAction?) -> Unit = {},
) {
    val alternates = set.popupFor(symbol)
    val feedback = LocalKeyPressFeedback.current
    val scope = rememberCoroutineScope()
    // Keyed on the entry: the cells are positional in their lazy list, so a
    // set switched under an open popup would otherwise hand that popup to
    // whatever entry now sits in the slot.
    var showPopup by remember(symbol) { mutableStateOf(false) }
    val hold = remember { AlternatesHold() }
    val holdToSelect = settings.popup.alternatesHoldToSelect
    // The popup draws labels ([symbolChipLabel]) and the commit types the raw
    // entry; the index is what joins the two, on both the hold and the tap path.
    val labels = alternates.map(::symbolChipLabel)
    hold.onCommit = { index ->
        showPopup = false
        alternates.getOrNull(index)?.let(onInsert)
    }
    val popupPosition = rememberAboveAnchorPopup()
    // Read through state by the hold handler, never captured: the handler is a
    // pointerInput that restarts when its keys change, and a lambda made fresh
    // each composition as a key would restart it on the very recomposition
    // that opening the popup causes, mid-hold, so the lift would commit nothing.
    val openPopup = rememberUpdatedState {
        hold.open()
        showPopup = true
    }
    var showMenu by remember(symbol) { mutableStateOf(false) }
    val openMenu = rememberUpdatedState { showMenu = true }
    val press = rememberUpdatedState(feedback)
    Box(modifier = modifier, contentAlignment = Alignment.Center) {
        Box(
            // Lifted so the badge sits under the character instead of across
            // it; the cell keeps its size.
            modifier = Modifier.offset(y = if (hint != null) -(HintBadgeHeight / 2) else 0.dp),
        ) {
            Text(
                text = symbolChipLabel(symbol),
                modifier = Modifier
                    .clip(RoundedCornerShape(8.dp))
                    .clickable { onInsert(symbol) }
                    .then(
                        if (alternates.isEmpty()) {
                            if (menu == null) {
                                Modifier
                            } else {
                                Modifier.symbolHoldInput(
                                    delayMs = settings.longPressDelayMs,
                                    hapticOnLongPress = settings.haptics.onLongPress,
                                    // Nothing is typed on the lift: the menu
                                    // stays up for a tap.
                                    hapticOnLongPressRelease = false,
                                    hold = null,
                                    feedback = press,
                                    scope = scope,
                                    open = openMenu,
                                )
                            }
                        } else {
                            Modifier
                                // Beside the pointer handler and before the
                                // padding, like the key's own: the hold measures
                                // the finger against this node.
                                .onGloballyPositioned {
                                    hold.cell = Rect(it.positionInWindow(), it.size.toSize())
                                }
                                .symbolHoldInput(
                                    delayMs = settings.longPressDelayMs,
                                    hapticOnLongPress = settings.haptics.onLongPress,
                                    hapticOnLongPressRelease = settings.haptics.onLongPressRelease,
                                    hold = hold.takeIf { holdToSelect },
                                    feedback = press,
                                    scope = scope,
                                    open = openPopup,
                                )
                        },
                    )
                    .padding(horizontal = 8.dp, vertical = 8.dp),
                fontSize = 15.sp,
                color = MaterialTheme.colorScheme.onSurface,
                maxLines = 1,
            )
            // The same corner hint a key with alternates wears, under the same
            // switch, so a cell that holds to more says so the way a key does.
            if (alternates.isNotEmpty() && settings.longPressHints) {
                Text(
                    text = labels.first(),
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .hintPlacement(settings, end = 3.dp),
                    fontSize = (HintLabelSp * settings.layoutBehavior.hintFontScale).sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    maxLines = 1,
                    softWrap = false,
                    style = keyHintTextStyle(),
                )
            }
            if (showPopup) {
                // The popup can go with the finger still down (the row
                // recomposed away under it); nothing then delivers the lift,
                // so the hold is cleared here for it.
                DisposableEffect(hold) {
                    onDispose { hold.cancel() }
                }
                AlternatesPopup(
                    key = Key(label = symbol, longPress = labels),
                    popupPosition = popupPosition,
                    popup = settings.popup,
                    hold = hold.takeIf { holdToSelect },
                    onDismiss = { showPopup = false },
                    onText = { label ->
                        showPopup = false
                        val index = labels.indexOf(label)
                        onInsert(alternates.getOrElse(index) { label })
                    },
                    // A symbol set's popup is characters only.
                    onAction = {},
                )
            }
            if (showMenu && menu != null) {
                SymbolEntryMenu(
                    entry = SymbolRowAction.RemoveEntry(set.id, index, symbol),
                    spec = menu,
                    onDismiss = { showMenu = false },
                    onAction = { action ->
                        showMenu = false
                        onMenuAction(action)
                    },
                )
            }
        }
        if (hint != null) {
            HintBadge(hint, modifier = Modifier.align(Alignment.BottomCenter))
        }
    }
}

/**
 * What the menu on a held symbol row entry may offer, the same for every entry
 * of the set on show. [hideInMode] is the active mode when the row is part of
 * it (the mode turns the row on or names its own sets), else null.
 */
@Immutable
private class SymbolEntryMenuSpec(
    val setName: String,
    val removable: Boolean,
    val hideInMode: KeyboardMode?,
    val deletable: Boolean,
)

/**
 * The menu a held symbol row entry opens (#323), shaped like the held-word
 * menu on the suggestion strip: non-focusable, over a [StripMenuScrim] so the
 * dismissing tap types nothing. Removing the entry and hiding the row are
 * single presses; deleting the set is handed back as a null action so the row
 * can ask first. [entry] is the held entry, already in the form its Remove
 * item sends.
 */
@Composable
private fun SymbolEntryMenu(
    entry: SymbolRowAction.RemoveEntry,
    spec: SymbolEntryMenuSpec,
    onDismiss: () -> Unit,
    onAction: (SymbolRowAction?) -> Unit,
) {
    StripMenuScrim(onDismiss = onDismiss)
    DropdownMenu(
        expanded = true,
        onDismissRequest = onDismiss,
        properties = MenuPopupProperties,
    ) {
        if (spec.removable) {
            WordMenuRow(
                label = stringResource(R.string.ime_symbol_row_remove, symbolChipLabel(entry.entry)),
                icon = Icons.Outlined.RemoveCircleOutline,
            ) { onAction(entry) }
        }
        spec.hideInMode?.let { mode ->
            WordMenuRow(
                label = stringResource(R.string.ime_symbol_row_hide_in_mode, mode.name),
                icon = Icons.Outlined.VisibilityOff,
            ) { onAction(SymbolRowAction.HideInMode(mode.id)) }
        }
        if (spec.deletable) {
            WordMenuRow(
                label = stringResource(R.string.ime_symbol_row_delete_set, spec.setName),
                icon = Icons.Outlined.Delete,
            ) { onAction(null) }
        }
        WordMenuRow(
            label = stringResource(R.string.ime_symbol_row_settings),
            icon = Icons.Outlined.Settings,
        ) { onAction(SymbolRowAction.OpenSettings) }
    }
}

/**
 * The press-and-hold half of a [SymbolCell]'s gesture: a hold past [delayMs]
 * opens the popup, and with [hold] set the finger then steers it and the lift
 * commits, exactly as the key grid's hold-to-select does. With [hold] null the
 * popup stays up after the lift for a tap, the older behaviour.
 *
 * Lives inside a scrolling list, which the key grid's handler never had to
 * think about. Until the hold fires this consumes nothing and watches for its
 * finger being taken: the list claims a drag in the same pass this cell sees
 * it in, but after it, so each move is looked at again once the pass is over
 * (the trick `awaitLongPressOrCancellation` uses). A finger the list took
 * cancels the timer, and a tap is left entirely to the clickable underneath.
 */
private fun Modifier.symbolHoldInput(
    delayMs: Int,
    hapticOnLongPress: Boolean,
    hapticOnLongPressRelease: Boolean,
    hold: AlternatesHold?,
    /** Both as state, so the handler survives the recomposition it causes. */
    feedback: State<() -> Unit>,
    scope: kotlinx.coroutines.CoroutineScope,
    open: State<() -> Unit>,
): Modifier = pointerInput(delayMs, hapticOnLongPress, hapticOnLongPressRelease, hold) {
    val reachPx = AlternatesReachDp.toPx()
    val steerPx = AlternatesSteerDp.toPx()
    awaitEachGesture {
        val down = awaitFirstDown(requireUnconsumed = false)
        var fired = false
        var taken = false
        val timer = scope.launch {
            delay(delayMs.toLong())
            fired = true
            if (hapticOnLongPress) feedback.value()
            open.value()
        }
        try {
            while (true) {
                val event = awaitPointerEvent(PointerEventPass.Main)
                val change = event.changes.firstOrNull { it.id == down.id } ?: break
                if (fired) {
                    // The popup's finger: nothing under it may read this.
                    change.consume()
                    if (!change.pressed) break
                    hold?.moveTo(change.position, reachPx, steerPx)
                    continue
                }
                if (!change.pressed) break
                if (change.isConsumed) {
                    taken = true
                    break
                }
                val settled = awaitPointerEvent(PointerEventPass.Final)
                if (settled.changes.any { it.id == down.id && it.isConsumed }) {
                    taken = true
                    break
                }
            }
        } finally {
            timer.cancel()
        }
        // The lift chooses what the popup has highlighted, which is the first
        // entry when the finger never moved; a finger the list took, or one
        // that came up before the hold fired, chooses nothing here.
        if (fired && !taken) {
            hold?.commit()
            if (hapticOnLongPressRelease) feedback.value()
        }
    }
}

/** Height of the Fancy Text style strip (mirrors [SymbolRowHeight]). */
internal val FancyRowHeight = 40.dp

/** Height of the dictionary bar (issue #51), the same strip shape as the fancy one. */
internal val DictionaryRowHeight = 40.dp

/** Height of the row holding desktop Avro's candidate list, the same strip shape again. */
internal val PhoneticCandidateRowHeight = 40.dp

/**
 * Whether the row holding desktop Avro's candidate list is on screen: the
 * layout being typed on is phonetic, and its language is set to show the list
 * in a row of its own. It stays up, empty, between words, so the keyboard
 * does not grow and shrink by a row with every word typed.
 */
internal fun phoneticCandidateBarShown(state: KeyboardUiState): Boolean =
    state.settings.suggestions &&
        state.settings.suggestionStrip.phoneticCandidateListFor(state.composer.phoneticLanguage) ==
        PhoneticCandidateList.BAR

/**
 * Desktop Avro's candidate list for the word being typed, as a row above the
 * strip that scrolls through every word of it. A tap writes the word the way
 * a tap on the strip does. The word a space would write is in bold, the way
 * Avro highlights the candidate it has selected.
 */
@Composable
private fun PhoneticCandidateBar(barState: KeyboardUiState, onPick: (String) -> Unit) {
    val state = withLiveTyping(barState)
    val words = if (state.composingPreview.isEmpty()) emptyList() else state.phoneticCandidates
    val committing = state.autocorrectWord ?: state.suggestions.firstOrNull()
    val kb = LocalKbTheme.current
    val listState = rememberLazyListState()
    // A new word starts at the left edge, where its best candidates are.
    LaunchedEffect(words) { listState.scrollToItem(0) }
    LazyRow(
        state = listState,
        modifier = Modifier
            .fillMaxWidth()
            .height(PhoneticCandidateRowHeight),
        verticalAlignment = Alignment.CenterVertically,
        contentPadding = PaddingValues(horizontal = 4.dp),
    ) {
        lazyRowItems(words) { word ->
            Text(
                text = word,
                modifier = Modifier
                    .padding(horizontal = 2.dp)
                    .clip(kb.chipShape())
                    .clickable { onPick(word) }
                    .padding(horizontal = 10.dp, vertical = 8.dp),
                fontSize = 15.sp,
                fontWeight = if (word == committing) FontWeight.Bold else null,
                color = kb.suggestionText,
                maxLines = 1,
            )
        }
    }
}

/**
 * The Fancy Text style in force at draw time, or null outside the fancy
 * layout — the render-side twin of the service's own resolver, and the gate
 * every fancy branch in this file checks.
 */
internal fun fancyStyleFor(state: KeyboardUiState): FancyStyle? =
    if (state.language.id == FancyStyles.LANG_ID) {
        // A font the user has since deleted falls back to the default style
        // rather than to null, which would read as "not the fancy keyboard".
        FancyStyles.byId(
            state.activeFancyStyleId ?: state.settings.layoutBehavior.fancyStyleId,
        ) ?: FancyStyles.byId(FancyStyles.DEFAULT_ID)
    } else {
        null
    }

/**
 * The style picker for Fancy Text: a strip over the keys, shown only while
 * the fancy layout is active, with each style's chip written in the style
 * itself (𝐁𝐨𝐥𝐝, 𝘐𝘵𝘢𝘭𝘪𝘤, 𝔉𝔯𝔞𝔨𝔱𝔲𝔯 …). Modeled on [SymbolRowStrip]: a
 * left-hand dropdown naming the current style in plain text, then the
 * scrollable WYSIWYG chips. It takes the [BarRow.FANCY] slot of the row
 * order, so it can sit above or below the other rows, but it has no on/off
 * setting of its own: it appears with the fancy layout and leaves with it.
 */
@Composable
@Suppress("UnusedParameter")
private fun FancyStyleStrip(
    state: KeyboardUiState,
    active: FancyStyle,
    onStyleSelect: (String) -> Unit,
    modifier: Modifier = Modifier,
) {
    var pickerOpen by remember { mutableStateOf(false) }
    val feedback = LocalKeyPressFeedback.current
    // Land on the active chip when the strip appears — with thirty-odd styles
    // the selected one is otherwise likely off-screen to the right.
    //
    // Seeded into the list's initial index rather than scrolled to from a
    // LaunchedEffect. An effect runs after the first layout, so the strip drew
    // one frame from the top of the list and then jumped to the active style —
    // and it appears on the same frame the fancy layout does, which is exactly
    // when the eye is already on it.
    val listState = rememberLazyListState(
        initialFirstVisibleItemIndex = FancyStyles.all
            .indexOfFirst { it.id == active.id }
            .coerceAtLeast(0),
    )
    // The chips are Latin glyphs whatever the system locale; mirroring the
    // strip under RTL would put the list order at odds with the layout.
    CompositionLocalProvider(LocalLayoutDirection provides LayoutDirection.Ltr) {
        Row(
            modifier = modifier
                .fillMaxWidth()
                .height(FancyRowHeight),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Box {
                Row(
                    modifier = Modifier
                        .clip(RoundedCornerShape(14.dp))
                        .clickable {
                            feedback()
                            pickerOpen = true
                        }
                        .padding(start = 10.dp, end = 2.dp, top = 4.dp, bottom = 4.dp),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    Text(
                        active.name,
                        fontSize = 12.sp,
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        maxLines = 1,
                    )
                    Icon(
                        Icons.Outlined.ArrowDropDown,
                        contentDescription = stringResource(R.string.ime_fancy_style_switch_desc),
                        modifier = Modifier.size(18.dp),
                        tint = MaterialTheme.colorScheme.onSurfaceVariant,
                    )
                }
                if (pickerOpen) StripMenuScrim(onDismiss = { pickerOpen = false })
                DropdownMenu(
                    expanded = pickerOpen,
                    onDismissRequest = { pickerOpen = false },
                    properties = MenuPopupProperties,
                ) {
                    for (style in FancyStyles.all) {
                        DropdownMenuItem(
                            // WYSIWYG like the chips: the name written in its
                            // own style, with the plain name left for TalkBack.
                            text = {
                                Text(
                                    style.sample,
                                    modifier = Modifier.semantics {
                                        contentDescription = style.name
                                    },
                                    // The long ones ("𝙎𝙖𝙣𝙨 𝘽𝙤𝙡𝙙 𝙄𝙩𝙖𝙡𝙞𝙘") would
                                    // otherwise wrap and clip the fixed-height item.
                                    maxLines = 1,
                                )
                            },
                            trailingIcon = if (style.id == active.id) {
                                {
                                    Icon(
                                        Icons.Outlined.Check,
                                        contentDescription = null,
                                        modifier = Modifier.size(16.dp),
                                    )
                                }
                            } else {
                                null
                            },
                            onClick = {
                                pickerOpen = false
                                onStyleSelect(style.id)
                            },
                        )
                    }
                }
            }
            LazyRow(
                state = listState,
                modifier = Modifier.weight(1f),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                lazyRowItems(FancyStyles.all) { style ->
                    val selected = style.id == active.id
                    val kb = LocalKbTheme.current
                    val chipShape = kb.chipShape()
                    Text(
                        text = style.sample,
                        modifier = Modifier
                            .padding(horizontal = 2.dp)
                            .clip(chipShape)
                            .background(if (selected) kb.chipActive else Color.Transparent)
                            .then(
                                if (selected) Modifier.chipBorder(kb, chipShape) else Modifier,
                            )
                            .clickable { onStyleSelect(style.id) }
                            .padding(horizontal = 8.dp, vertical = 8.dp)
                            // The samples are astral soup to TalkBack; speak
                            // the plain name instead.
                            .semantics { contentDescription = style.name },
                        fontSize = 14.sp,
                        color = if (selected) kb.chipActiveText else kb.suggestionText,
                        maxLines = 1,
                    )
                }
            }
        }
    }
}

/**
 * The dictionary bar's callbacks (issue #51), a field of [ToolHoldCallbacks]
 * rather than a [KeyboardScreen] parameter of its own: that caller sits
 * against the JVM's 64K method-size ceiling, and there is no strip-chrome
 * bundle to join, so the two ride the nearest bundle already on the call.
 */
data class DictionaryBarCallbacks(
    /** A chip was tapped: switch that dictionary the other way. */
    val onToggle: (DictionaryChip) -> Unit = {},
    /** The language filter was picked: a language id, or null for every language. */
    val onFilter: (String?) -> Unit = {},
)

/** The chips the bar draws under its filter: every language, or one. */
internal fun dictionaryChipsFor(state: KeyboardUiState): List<DictionaryChip> {
    val filter = state.settings.rows.dictionaryBarFilter
    // A remembered filter for a language since switched off shows nothing;
    // fall back to every language rather than an empty bar.
    val filtering = filter.isNotEmpty() && state.settings.enabledLanguages.any { it.id == filter }
    return if (filtering) state.dictionaryBar.filter { it.langId == filter } else state.dictionaryBar
}

/**
 * The dictionary bar (issue #51): every dictionary on the device as a chip,
 * coloured while it is on, plain while it is off, a tap flipping it in place.
 * Modeled on [FancyStyleStrip]: a left-hand dropdown holding the language
 * filter — "All" plus each enabled language, scrolling when the list is long
 * — then the chips. Under "All" a chip is prefixed with its language so two
 * word lists can be told apart; under one language the prefix goes.
 */
@Composable
private fun DictionaryBarStrip(
    state: KeyboardUiState,
    callbacks: DictionaryBarCallbacks,
    modifier: Modifier = Modifier,
) {
    var pickerOpen by remember { mutableStateOf(false) }
    val feedback = LocalKeyPressFeedback.current
    val kb = LocalKbTheme.current
    val filter = state.settings.rows.dictionaryBarFilter
    val languages = state.settings.enabledLanguages
    val filterLang = languages.firstOrNull { it.id == filter }
    val chips = dictionaryChipsFor(state)
    val allLabel = stringResource(R.string.ime_dictionary_bar_all)
    val wordsLabel = stringResource(R.string.ime_dictionary_bar_words)
    val emojiLabel = stringResource(R.string.ime_dictionary_bar_emoji)
    fun chipLabel(chip: DictionaryChip): String {
        val kind = when (chip.kind) {
            DictionaryKind.WORDS -> wordsLabel
            DictionaryKind.EMOJI -> emojiLabel
            DictionaryKind.IMPORTED -> chip.label ?: chip.fileName
        }
        return if (filterLang == null) {
            "${LanguageRegistry.byId(chip.langId).displayName} · $kind"
        } else {
            kind
        }
    }
    Row(
        modifier = modifier
            .fillMaxWidth()
            .height(DictionaryRowHeight),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Box {
            Row(
                modifier = Modifier
                    .clip(RoundedCornerShape(14.dp))
                    .clickable {
                        feedback()
                        pickerOpen = true
                    }
                    .padding(start = 10.dp, end = 2.dp, top = 4.dp, bottom = 4.dp),
                verticalAlignment = Alignment.CenterVertically,
            ) {
                Text(
                    filterLang?.displayName ?: allLabel,
                    fontSize = 12.sp,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                    maxLines = 1,
                )
                Icon(
                    Icons.Outlined.ArrowDropDown,
                    contentDescription = stringResource(R.string.ime_dictionary_bar_filter_desc),
                    modifier = Modifier.size(18.dp),
                    tint = MaterialTheme.colorScheme.onSurfaceVariant,
                )
            }
            if (pickerOpen) StripMenuScrim(onDismiss = { pickerOpen = false })
            // DropdownMenu scrolls on its own once the list outgrows the
            // screen, which is the "many active languages" case the request
            // named.
            DropdownMenu(
                expanded = pickerOpen,
                onDismissRequest = { pickerOpen = false },
                properties = MenuPopupProperties,
            ) {
                val options = listOf<Pair<String?, String>>(null to allLabel) +
                    languages.map { it.id to it.displayName }
                for ((id, name) in options) {
                    val selected = id == filterLang?.id
                    DropdownMenuItem(
                        text = { Text(name, maxLines = 1) },
                        trailingIcon = if (selected) {
                            {
                                Icon(
                                    Icons.Outlined.Check,
                                    contentDescription = null,
                                    modifier = Modifier.size(16.dp),
                                )
                            }
                        } else {
                            null
                        },
                        onClick = {
                            pickerOpen = false
                            callbacks.onFilter(id)
                        },
                    )
                }
            }
        }
        if (chips.isEmpty()) {
            Text(
                stringResource(R.string.ime_dictionary_bar_empty),
                fontSize = 12.sp,
                color = kb.suggestionText,
                maxLines = 1,
                modifier = Modifier.padding(horizontal = 8.dp),
            )
            return@Row
        }
        LazyRow(
            modifier = Modifier.weight(1f),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            lazyRowItems(chips) { chip ->
                val chipShape = kb.chipShape()
                val label = chipLabel(chip)
                val stateLabel = stringResource(
                    if (chip.enabled) R.string.ime_dictionary_bar_chip_on else R.string.ime_dictionary_bar_chip_off,
                    label,
                )
                Text(
                    text = label,
                    modifier = Modifier
                        .padding(horizontal = 2.dp)
                        .clip(chipShape)
                        .background(if (chip.enabled) kb.chipActive else Color.Transparent)
                        .then(
                            if (chip.enabled) Modifier.chipBorder(kb, chipShape) else Modifier,
                        )
                        .clickable { callbacks.onToggle(chip) }
                        .padding(horizontal = 8.dp, vertical = 8.dp)
                        .semantics { contentDescription = stateLabel },
                    fontSize = 14.sp,
                    color = if (chip.enabled) kb.chipActiveText else kb.suggestionText,
                    maxLines = 1,
                )
            }
        }
    }
}

/**
 * The Modes panel: pick which keyboard mode is active. "None" turns every
 * mode off, bindings included; "Automatic" follows
 * the per-app and per-field bindings; picking a mode by hand overrides them
 * until the user switches to another app. Modes are created and edited in
 * the settings app (long-press the tool).
 */
@Composable
private fun ModesPanel(
    state: KeyboardUiState,
    onModeSelect: (String?) -> Unit,
    onOpenSettings: () -> Unit,
) {
    val height = keyRowsHeight(state)
    val modes = state.settings.keyboardModes
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .height(height),
    ) {
        if (modes.isEmpty()) {
            Column(
                modifier = Modifier.fillMaxSize(),
                horizontalAlignment = Alignment.CenterHorizontally,
                verticalArrangement = Arrangement.Center,
            ) {
                Text(
                    stringResource(R.string.ime_modes_empty),
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
                Spacer(Modifier.height(10.dp))
                ToolPanelChip(
                    stringResource(R.string.ime_modes_settings_desc),
                    selected = true,
                    onClick = onOpenSettings,
                )
            }
            return@Column
        }
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .padding(start = 20.dp, end = 8.dp, top = 4.dp, bottom = 4.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Text(
                stringResource(R.string.ime_modes_manual_note),
                fontSize = 12.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                modifier = Modifier.weight(1f),
            )
            ToolCircle(
                slot = IconSlots.forTool(ToolbarTool.SETTINGS),
                description = stringResource(R.string.ime_modes_settings_desc),
                active = false,
                onClick = onOpenSettings,
            )
        }
        // Index 0 is the leading "None" row and 1 is "Automatic", so a mode
        // sits at its own position plus two — the offset the lambda undoes.
        PanelFocusTarget(
            panel = PanelMode.MODES,
            count = modes.size + 2,
            columns = 1,
            onActivate = { index ->
                when (index) {
                    0 -> onModeSelect(NoKeyboardModeId)
                    1 -> onModeSelect(null)
                    else -> modes.getOrNull(index - 2)?.let { onModeSelect(it.id) }
                }
            },
        )
        val focused = state.focusedIndex()
        val listState = rememberLazyListState()
        ScrollFocusIntoView(focused) { listState.animateScrollToItem(it) }
        // Hoisted out of the list: the summaries are worded per mode, and a
        // LazyColumn's content block is not a composable scope.
        val resources = LocalContext.current.resources
        val noneTitle = stringResource(CommonR.string.common_none)
        val noneSubtitle = stringResource(R.string.ime_modes_none_subtitle)
        val autoTitle = stringResource(CommonR.string.common_auto)
        val autoSubtitle = stringResource(R.string.ime_modes_auto_subtitle)
        LazyColumn(state = listState, modifier = Modifier.weight(1f)) {
            item {
                ModeRow(
                    title = noneTitle,
                    subtitle = noneSubtitle,
                    icon = Icons.Outlined.Block,
                    selected = state.noModePicked,
                    focused = focused == 0,
                ) { onModeSelect(NoKeyboardModeId) }
            }
            item {
                ModeRow(
                    title = autoTitle,
                    subtitle = autoSubtitle,
                    icon = Icons.Outlined.AutoAwesome,
                    selected = state.activeModeId == null && !state.noModePicked,
                    focused = focused == 1,
                ) { onModeSelect(null) }
            }
            itemsIndexed(modes) { index, mode ->
                ModeRow(
                    title = mode.name,
                    subtitle = modeSummary(resources, mode),
                    icon = ModeIcons.icon(mode.icon),
                    selected = state.activeModeId == mode.id,
                    focused = focused == index + 2,
                ) { onModeSelect(mode.id) }
            }
        }
    }
}

/**
 * One-line recap of what a mode changes and when it kicks in.
 *
 * Each part is its own resource, written the way it reads at the start of the
 * line: the parts are joined, so no part may be re-cased afterwards — the
 * first letter of a translated word is not the compiler's to change.
 */
private fun modeSummary(resources: Resources, mode: KeyboardMode): String {
    val parts = mutableListOf<String>()
    mode.emojiBarMode?.let {
        parts += resources.getString(
            when (it) {
                EmojiBarMode.OFF -> R.string.ime_mode_summary_emoji_row_off
                EmojiBarMode.BUTTON -> R.string.ime_mode_summary_emoji_button
                EmojiBarMode.ALWAYS -> R.string.ime_mode_summary_emoji_row
            },
        )
    }
    mode.toolbarTools?.let {
        val plural = if (mode.toolbarToolsAppend) {
            R.plurals.ime_mode_summary_pinned_tools_added
        } else {
            R.plurals.ime_mode_summary_pinned_tools
        }
        parts += resources.getQuantityString(plural, it.size, it.size)
    }
    mode.symbolRowEnabled?.let {
        parts += resources.getString(
            if (it) R.string.ime_mode_summary_symbol_row else R.string.ime_mode_summary_symbol_row_off,
        )
    }
    if (mode.apps.isNotEmpty()) {
        parts += resources.getQuantityString(
            R.plurals.ime_mode_summary_apps, mode.apps.size, mode.apps.size,
        )
    }
    if (mode.fieldKinds.isNotEmpty()) {
        // FieldKind has no name of its own yet, so the enum names stand in.
        parts += resources.getString(
            R.string.ime_mode_summary_fields,
            mode.fieldKinds.joinToString(", ") { it.name.lowercase() },
        )
    }
    return if (parts.isEmpty()) {
        resources.getString(R.string.ime_mode_summary_none)
    } else {
        parts.joinToString(" · ")
    }
}

@Composable
private fun ModeRow(
    title: String,
    subtitle: String,
    icon: ImageVector,
    selected: Boolean,
    focused: Boolean = false,
    onClick: () -> Unit,
) {
    val kb = LocalKbTheme.current
    Row(
        modifier = Modifier
            .fillMaxWidth()
            .clickable(onClick = onClick)
            // Fill and outline both, since the accent alone already means
            // "this is the active mode" on the icon and the title weight.
            .focusRing(focused, RoundedCornerShape(10.dp))
            .padding(horizontal = 20.dp, vertical = 10.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Icon(
            icon,
            contentDescription = null,
            modifier = Modifier
                .padding(end = 14.dp)
                .size(22.dp),
            // The active mode's icon carries the accent; the rest stay quiet
            // so the list reads as names first, icons second.
            tint = if (selected) kb.accent else MaterialTheme.colorScheme.onSurfaceVariant,
        )
        Column(modifier = Modifier.weight(1f)) {
            Text(
                title,
                fontSize = 15.sp,
                fontWeight = if (selected) FontWeight.SemiBold else FontWeight.Normal,
                color = MaterialTheme.colorScheme.onSurface,
            )
            Text(
                subtitle,
                fontSize = 12.sp,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }
        if (selected) {
            Icon(
                Icons.Outlined.Check,
                contentDescription = stringResource(R.string.ime_modes_active_desc),
                modifier = Modifier.size(20.dp),
                tint = kb.accent,
            )
        }
    }
}

