/** [toolLabelRes], worded for a caller that is already drawing. */
@Composable
internal fun toolLabel(tool: ToolbarTool): String = stringResource(toolLabelRes(tool))

@Composable
private fun toolActive(tool: ToolbarTool, state: KeyboardUiState): Boolean = when (tool) {
    // With "open the last used" on, the emoji tool opens and closes all three
    // of emoji, GIFs and stickers (#366), so it is lit for any of them.
    ToolbarTool.EMOJI -> if (state.settings.emoji.rememberMediaTab) {
        state.panel in MediaTabPanels
    } else {
        state.panel == PanelMode.EMOJI
    }
    ToolbarTool.CLIPBOARD -> state.panel == PanelMode.CLIPBOARD
    ToolbarTool.CLIPBOARD_SEARCH -> state.panel == PanelMode.CLIPBOARD && state.clipboardSearchActive
    ToolbarTool.RECENT_COPIES -> state.recentClipsOpen
    ToolbarTool.SNIPPETS -> state.panel == PanelMode.SNIPPETS
    ToolbarTool.TEXT_EDIT -> state.panel == PanelMode.TEXT_EDIT
    ToolbarTool.TRACKPAD -> state.panel == PanelMode.TRACKPAD
    // Lit for the mode in force, not the stored one: portrait-only one-handed
    // (#503) is off while the phone is sideways, and the tool says so.
    ToolbarTool.ONE_HANDED -> state.settings.oneHandedModeFor(
        LocalConfiguration.current.orientation == Configuration.ORIENTATION_LANDSCAPE,
    ) != OneHandedMode.OFF
    ToolbarTool.SPLIT -> state.settings.splitKeyboard
    // Per orientation (#584), like one-handed above.
    ToolbarTool.FLOATING -> state.settings.floatingFor(
        LocalConfiguration.current.orientation == Configuration.ORIENTATION_LANDSCAPE,
    )
    ToolbarTool.PERSISTENT -> state.settings.persistentKeyboard
    ToolbarTool.RESIZE -> state.resize
    ToolbarTool.SETTINGS -> false
    ToolbarTool.FLASHLIGHT -> state.torchOn
    ToolbarTool.COMPASS -> state.panel == PanelMode.COMPASS
    ToolbarTool.LEVEL -> state.panel == PanelMode.LEVEL
    ToolbarTool.UNDO -> false
    ToolbarTool.REDO -> false
    ToolbarTool.MOON_PHASE -> state.panel == PanelMode.MOON_PHASE
    ToolbarTool.WEATHER -> state.panel == PanelMode.WEATHER
    ToolbarTool.CALENDAR -> state.panel == PanelMode.CALENDAR
    ToolbarTool.INCOGNITO -> state.incognitoOn
    ToolbarTool.SELECTION_ACTIONS -> state.settings.selectionMacros.enabled
    ToolbarTool.PHONETIC_ENGLISH ->
        state.settings.suggestionStrip.phoneticEnglishFor(state.composer.phoneticLanguage)
    ToolbarTool.POWER_SAVING -> state.powerSavingOn
    ToolbarTool.THEMES -> state.panel == PanelMode.THEMES
    ToolbarTool.AUTOCORRECT -> state.settings.correction.enabledFor(state.language.id)
    ToolbarTool.SOUND_HAPTICS -> state.panel == PanelMode.SOUND_HAPTICS
    ToolbarTool.NUMPAD -> state.panel == PanelMode.NUMPAD
    ToolbarTool.HANDWRITING -> state.panel == PanelMode.HANDWRITING
    ToolbarTool.CAMERA -> state.panel == PanelMode.CAMERA
    ToolbarTool.DICTIONARY -> state.panel == PanelMode.DICTIONARY
    ToolbarTool.VOCABULARY -> state.panel == PanelMode.VOCABULARY
    ToolbarTool.LEARN_FROM_TEXT -> state.panel == PanelMode.LEARN_FROM_TEXT
    ToolbarTool.TRANSLATE -> state.panel == PanelMode.TRANSLATE
    ToolbarTool.GIF -> state.panel == PanelMode.GIF
    ToolbarTool.STICKER -> state.panel == PanelMode.STICKER
    ToolbarTool.EMOJI_MIX -> state.panel == PanelMode.EMOJI_MIX
    ToolbarTool.WEB_SEARCH -> state.panel == PanelMode.WEB_SEARCH
    ToolbarTool.IMAGE_SEARCH -> state.panel == PanelMode.WEB_SEARCH && state.searchTab == SearchTab.IMAGES
    ToolbarTool.OCR -> state.panel == PanelMode.OCR
    ToolbarTool.QR_SCAN -> state.panel == PanelMode.QR_SCAN
    ToolbarTool.DOC_SCAN -> false
    // Opens the settings app, like Settings: nothing on the keyboard to stay lit for.
    ToolbarTool.STATISTICS -> false
    ToolbarTool.FIND_REPLACE -> state.panel == PanelMode.FIND_REPLACE
    ToolbarTool.NOTES -> state.panel == PanelMode.NOTES
    ToolbarTool.TODO -> state.panel == PanelMode.TODO
    ToolbarTool.QUICK_NOTE -> state.panel == PanelMode.NOTES && state.notes.quick
    ToolbarTool.LOCATION -> state.panel == PanelMode.LOCATION
    ToolbarTool.CLOCK -> state.panel == PanelMode.CLOCK
    ToolbarTool.MUSIC_ID -> state.panel == PanelMode.MUSIC_ID
    ToolbarTool.HOME_ASSISTANT -> state.panel == PanelMode.HOME_ASSISTANT
    ToolbarTool.SEND_FILES -> state.panel == PanelMode.SEND_FILES
    ToolbarTool.GALLERY -> state.panel == PanelMode.GALLERY
    ToolbarTool.VOICE -> state.panel == PanelMode.VOICE || state.voice.strip || state.voice.bar
    ToolbarTool.GRAMMAR -> state.panel == PanelMode.GRAMMAR
    ToolbarTool.WIKIPEDIA -> state.panel == PanelMode.WIKIPEDIA
    ToolbarTool.SYMBOLS -> state.panel == PanelMode.SYMBOLS
    ToolbarTool.CALCULATOR -> state.panel == PanelMode.CALCULATOR
    ToolbarTool.UNIT_CONVERT -> state.panel == PanelMode.UNIT_CONVERT
    ToolbarTool.CURRENCY -> state.panel == PanelMode.CURRENCY
    ToolbarTool.QR_GEN -> state.panel == PanelMode.QR_GEN
    ToolbarTool.PASSWORD_GEN -> state.panel == PanelMode.PASSWORD_GEN
    ToolbarTool.TEXT_REPEAT -> state.panel == PanelMode.TEXT_REPEAT
    ToolbarTool.TYPING_TEST -> state.panel == PanelMode.TYPING_TEST
    ToolbarTool.SPEED_TEST -> state.panel == PanelMode.SPEED_TEST
    ToolbarTool.MEDIA_CONTROL -> state.panel == PanelMode.MEDIA_CONTROL
    ToolbarTool.KDE_CONNECT -> state.panel == PanelMode.KDE_CONNECT
    ToolbarTool.PLUGINS -> state.panel == PanelMode.PLUGINS
    ToolbarTool.APP_LAUNCHER -> state.panel == PanelMode.APP_LAUNCHER
    ToolbarTool.AI -> state.panel == PanelMode.AI
    ToolbarTool.AI_REPLY -> state.panel == PanelMode.AI_REPLY
    ToolbarTool.MODES -> state.panel == PanelMode.MODES || state.activeModeId != null
    // Lit while the fancy layout is the one typing, however it got there:
    // the tool and the 🌐 key reach the same place.
    ToolbarTool.FANCY -> state.language.id == FancyStyles.LANG_ID
    // Lit while any secondary layout is up, whether this tool or a key put it
    // there: the tool takes it down either way.
    ToolbarTool.CUSTOM_LAYOUT ->
        state.layoutMode == LayoutMode.SECONDARY || state.panel == PanelMode.CUSTOM_LAYOUTS
    // Lit while a caret move would extend the selection, however that was
    // asked for: this tool, a hold on it, or the panel's own Select key. The
    // tool is the only indicator the mode has outside that panel, so it reads
    // the whole answer rather than its own flag.
    ToolbarTool.SELECT_MODE -> state.selectingText
    // Stateless one-shot moves, like undo/redo: nothing to stay lit for.
    ToolbarTool.CURSOR_LEFT, ToolbarTool.CURSOR_RIGHT,
    ToolbarTool.CURSOR_WORD_LEFT, ToolbarTool.CURSOR_WORD_RIGHT,
    ToolbarTool.CURSOR_UP, ToolbarTool.CURSOR_DOWN,
    ToolbarTool.CURSOR_HOME, ToolbarTool.CURSOR_END,
    ToolbarTool.PAGE_UP, ToolbarTool.PAGE_DOWN,
    ToolbarTool.SELECT_WORD, ToolbarTool.SELECT_LINE, ToolbarTool.SELECT_ALL,
    // The clipboard trio the same: they act and are done.
    ToolbarTool.COPY, ToolbarTool.CUT, ToolbarTool.PASTE,
    // A one-shot action too — it hides the keyboard, nothing to keep lit.
    ToolbarTool.HIDE_KEYBOARD, ToolbarTool.LEAVE_FIELD -> false
    // Switches and is done, like the 🌐 key it stands in for.
    ToolbarTool.LANGUAGE -> false
    // Lit while it reads, so the second tap reads as Stop.
    ToolbarTool.READ_BACK -> state.readingBack
}

/**
 * Live state of a toolbar-customization drag. Bounds and positions are all
 * in window-root coordinates; the ghost is drawn relative to the keyboard
 * body's origin. Drops on the toolbar insert at the slot under the finger,
 * drops on the toolbox grid reorder the toolbox (unpinning first when the
 * tool came off the bar), drops anywhere else send a toolbar tool back to
 * the toolbox at its remembered rank.
 *
 * [barSlot] and [boxSlot] are the live drop preview: whichever is non-null
 * is where the tool would land right now, and the owning row/grid renders
 * a ghost stand-in there so the surrounding icons make room ahead of the
 * drop.
 */
private class ToolDragController {
    var dragging by mutableStateOf<ToolbarTool?>(null)
        private set
    /**
     * The toolbox folder being dragged (#709), or null. Exclusive with
     * [dragging]: a folder moves around the grid, or onto the toolbar to pin
     * it, and is never filed into anything.
     */
    var draggingFolder by mutableStateOf<ToolboxFolder?>(null)
        private set
    /** Whether a tool or a folder is in flight. */
    val active: Boolean get() = dragging != null || draggingFolder != null
    /**
     * The cell a dragged tool is held over the middle of (#709). Letting go
     * there files the tool with that cell's tool in a new folder, or into that
     * folder. While it is set there is no [boxSlot]: nothing makes room, so the
     * cell stays put under the finger and lights up instead.
     */
    var boxMerge by mutableStateOf<ToolboxCell?>(null)
        private set
    /** Over the open folder's header (#709), where a drop takes the tool out of it. */
    var overFolderExit by mutableStateOf(false)
        private set
    var position by mutableStateOf(Offset.Zero)
        private set
    /** Toolbar insertion slot under the finger, or null when off the bar. */
    var barSlot by mutableStateOf<Int?>(null)
        private set
    /** Toolbox grid slot under the finger, or null when off the grid. */
    var boxSlot by mutableStateOf<Int?>(null)
        private set
    private var fromToolbar = false
    var toolbarBounds: Rect? = null
    /**
     * Width, in px, that the toolbar last gave one of its buttons.
     *
     * Not the same as the theme's tool width. The bar spreads its buttons over
     * equal weighted cells, so a tool width wider than a cell is silently capped
     * at the cell — and the emoji shortcut the *strip* draws sits in no cell at
     * all, so it took the full width and the two copies of one icon came out
     * different sizes. At the top of the width slider that is a 60px jump on
     * every strip↔toolbar flip, right as the icon is meant to be sliding
     * smoothly between the two spots. Recorded from the toolbox launcher, which
     * is drawn whenever the bar is and shares the tools' cell.
     */
    var pinnedToolWidthPx: Int = 0
    /** Keyboard-body coordinates; the anchor for tool placement animations. */
    var bodyCoords: LayoutCoordinates? = null
    /**
     * Shared home of each tool the strip keeps a copy of (the emoji, by
     * default). It rides here rather than in [TopBar] because the strip's copy
     * and the toolbar's pinned copy are different nodes: the handoff needs a
     * holder that outlives both.
     */
    private val sharedPlacements = HashMap<ToolbarTool, SharedPlacement>()

    fun placementOf(tool: ToolbarTool): SharedPlacement = sharedPlacements.getOrPut(tool) { SharedPlacement() }
    /**
     * The stored pinned-tool list, in the order it is saved back. Every commit
     * is a rewrite of this.
     *
     * Always storage order, never mirrored: an RTL bar is a layout direction on
     * the row that draws the tools, not a different list. Mirroring the list as
     * well was the reorder bug — the row was flipped twice and the slot maths
     * once, so a tool dragged left landed to the right (issue #79).
     */
    var currentTools: List<ToolbarTool> = emptyList()
    /**
     * The subset of [currentTools] the bar actually draws — a pinned tool the
     * user has disabled, or one this build does not ship, is stored but never
     * shown. Slots are counted against this list, because it is the one the
     * finger is pointing at; [end] then translates the slot back into a
     * position in the stored list, so hiding a tool never unpins it.
     */
    var visibleTools: List<ToolbarTool> = emptyList()
    /**
     * Whether the row drawing [visibleTools] lays them out right-to-left.
     *
     * Registered by the bar itself, from the layout direction it actually draws
     * under, so the hit-testing follows the display instead of re-deriving it:
     * under RTL the tool at index 0 is the one hard against the *right* edge,
     * and a slot measured from the left names its mirror image.
     */
    var barRtl: Boolean = false
    /**
     * Whether the tools are drawn down a column beside the keys (#970) rather
     * than along a row: registered by whichever of the two is drawing them, as
     * [barRtl] is. A column counts its slots by [columnCentres] instead of by
     * a share of its length, since how far apart its tools sit depends on
     * Tool layout and on how many there are.
     */
    var barVertical: Boolean = false
    /** Each tool's centre down the screen in the column, in root coordinates, as last laid out. */
    val columnCentres = HashMap<ToolbarTool, Float>()
    var onCommit: (List<ToolbarTool>) -> Unit = {}
    /** Haptic tick when the drop target changes: slot to slot, or on/off the bar. */
    var onSnap: () -> Unit = {}
    /** Hold without dragging past the slop: open the tool's settings page. */
    var onOpenSettings: (ToolbarTool) -> Unit = {}

    /**
     * Runs the tool a hold was remapped to (see `holdActionFor`). Routed through
     * the controller alongside [onOpenSettings] rather than captured per tool:
     * both are the same gesture's outcome, and the tool cells are recomposed on
     * every frame of a drag, so a captured lambda would restart their pointer
     * handlers.
     */
    var onHoldAction: (ToolbarTool) -> Unit = {}

    /**
     * The Selection mode tool held down (true) and let go (false). On the
     * controller for the same reason [onHoldAction] is, and because the release
     * has to reach the service even when the finger travels far enough to turn
     * the gesture into a reorder.
     */
    var onSelectionHold: (Boolean) -> Unit = {}

    /**
     * The Trackpad tool held down (true) and let go (false): the panel is open
     * for exactly that long. Paired the same way [onSelectionHold] is.
     */
    var onTrackpadHold: (Boolean) -> Unit = {}

    /**
     * A voice typing mode picked off the Voice tool's hold menu (#173): the
     * mode's token. On the controller for the reason [onHoldAction] is.
     */
    var onVoiceModePick: (String) -> Unit = {}

    /** The show-keys button (#642). On the controller because the bar already takes it. */
    var onHardwareKeysToggle: () -> Unit = {}

    /** The incognito badge tapped: says who switched incognito on (#665). */
    var onIncognitoBadge: () -> Unit = {}

    // Toolbox geometry and data, registered by ToolboxPanel while it is
    // open (a drag can only happen with the toolbox open). The viewport is
    // the visible panel box; content coords are the scrolling grid column,
    // so slot math follows the scroll position for free.
    var toolboxViewport: Rect? = null
    var toolboxContentCoords: LayoutCoordinates? = null
    var toolboxCellSize: Size = Size.Zero
    var toolboxColumns: Int = 1
    /** [barRtl] for the grid: column 0 is the rightmost one under RTL. */
    var boxRtl: Boolean = false
    /**
     * Index the visible page starts at, when the toolbox is paginated. The
     * registered content coords belong to that one page, so its first cell is
     * slot [toolboxPageStart], not slot 0. Zero for the scrolling toolbox,
     * where the content is the whole grid.
     */
    var toolboxPageStart: Int = 0
    /**
     * How many slots that page holds — the drop is clamped to it so a drag
     * that wanders past the last pill on page 2 lands at the end of page 2
     * rather than at the end of the toolbox.
     */
    var toolboxPageLength: Int = Int.MAX_VALUE
    /** The cells the toolbox grid is showing, in toolbox order: tools, and folders of them (#709). */
    var toolboxCells: List<ToolboxCell> = emptyList()
    /**
     * Complete ordering over every tool; reorders rewrite this. Inside an open
     * folder it is that folder's own tools, and a reorder rewrites the folder.
     */
    var toolboxOrder: List<ToolbarTool> = emptyList()
    /** The folder open in the toolbox (#709), or null at the top level. */
    var folderView: ToolboxFolder? = null
    /** The open folder's header, in root coordinates: the take-out target. */
    var folderExitBounds: Rect? = null
    /**
     * Root position of the folder cell last tapped open (#709): the point the
     * folder's grid grows out of, and shrinks back into on the way out. Null
     * for a folder opened from its toolbar button, which grows from the top.
     */
    var folderOrigin: Offset? = null
    /** True while the toolbox lists search results (#687): no drop lands in a filtered grid. */
    var toolboxSearching: Boolean = false
    /** The folder side of the toolbox (#709, #687), handed down from the service. */
    var toolbox: ToolboxCallbacks = ToolboxCallbacks()
    /**
     * Tools the user hid from the grid. The grid is no drop target for them:
     * it would show a slot and then never draw the tool in it. Dragged off the
     * bar, one simply unpins, the way any off-bar drop does.
     */
    var toolboxHidden: Set<ToolbarTool> = emptySet()
    var onOrderCommit: (List<ToolbarTool>) -> Unit = {}

    /**
     * The order a drop just committed, handed to the grid so it can draw it
     * before the settings come back with it. Separate from [onOrderCommit]
     * because they go different ways: the commit goes out to storage and takes
     * a coroutine hop to return, and this one stays here.
     */
    var onOrderPreview: (List<ToolbarTool>) -> Unit = {}

    fun start(tool: ToolbarTool, fromBar: Boolean, at: Offset) {
        dragging = tool
        fromToolbar = fromBar
        position = at
        retarget(at)
    }

    /** Picks up a toolbox folder (#709); see [draggingFolder]. */
    fun startFolder(folder: ToolboxFolder, at: Offset) {
        draggingFolder = folder
        fromToolbar = false
        position = at
        retarget(at)
    }

    fun move(to: Offset) {
        position = to
        if (retarget(to)) onSnap()
    }

    /**
     * Works out every drop target under [at] at once, in the order they win:
     * the open folder's header, the toolbar, the middle of a toolbox cell, a
     * slot between cells. True when any of them changed.
     */
    private fun retarget(at: Offset): Boolean {
        val exit = folderExitAt(at)
        val bar = if (exit) null else slotAt(at)
        val merge = if (exit || bar != null) null else mergeAt(at)
        val box = if (exit || bar != null || merge != null) null else toolboxSlotAt(at)
        val changed = bar != barSlot || box != boxSlot || merge?.key != boxMerge?.key || exit != overFolderExit
        barSlot = bar
        boxSlot = box
        boxMerge = merge
        overFolderExit = exit
        return changed
    }

    fun cancel() {
        dragging = null
        draggingFolder = null
        barSlot = null
        boxSlot = null
        boxMerge = null
        overFolderExit = false
    }

    fun end() {
        val folder = draggingFolder
        val tool = dragging
        if (folder == null && tool == null) return
        retarget(position)
        val bar = barSlot
        val box = boxSlot
        val merge = boxMerge
        val exit = overFolderExit
        cancel()
        if (folder != null) {
            // A folder goes on the toolbar as a whole, after the pinned tools,
            // or to another place in the grid as a whole.
            if (bar != null) {
                if (!folder.pinned) toolbox.onPinToggle(folder.id)
            } else if (box != null) {
                val next = folderOrderWith(folder, box)
                onOrderPreview(next)
                onOrderCommit(next)
            }
            return
        }
        tool ?: return
        val view = folderView
        if (exit) {
            toolbox.onTakeOut(tool)
        } else if (bar != null) {
            onCommit(barWith(tool, bar))
        } else if (merge != null) {
            if (fromToolbar) onCommit(currentTools - tool)
            when (merge) {
                is ToolboxCell.Tool -> toolbox.onMerge(tool, merge.tool)
                is ToolboxCell.Folder -> toolbox.onAddToFolder(tool, merge.folder.id)
            }
        } else if (box != null) {
            // Dropped on the grid: place it at that spot in the toolbox
            // order — and off the bar first, when that's where it came from.
            if (fromToolbar) onCommit(currentTools - tool)
            if (view != null && tool !in view.tools) {
                // Off the bar into an open folder: filed in it.
                toolbox.onAddToFolder(tool, view.id)
                return
            }
            val next = orderWith(tool, box)
            // Shown first, saved second. Both from the same list, so the grid
            // never draws an arrangement the storage will not agree with.
            onOrderPreview(next)
            if (view != null) toolbox.onFolderOrder(view.id, next) else onOrderCommit(next)
        } else if (fromToolbar && toolboxViewport != null) {
            // Off-bar drops unpin only while the toolbox is open (its
            // viewport is registered) — a reorder drag that wanders off the
            // bar with no toolbox in sight just snaps back.
            onCommit(currentTools - tool)
        }
    }

    /**
     * Insertion slot under [at], or null when off the toolbar. The bar's hit
     * box is inflated so a drop just above/below it still counts.
     */
    private fun slotAt(at: Offset): Int? {
        val bar = toolbarBounds?.inflate(30f) ?: return null
        if (!bar.contains(at)) return null
        // A folder lands after the pinned tools, wherever it is let go (#709).
        if (draggingFolder != null) return visibleTools.size
        val tool = dragging ?: return null
        val without = visibleTools - tool
        if (without.isEmpty()) return 0
        // Down a column: in front of the first tool whose centre is still
        // below the finger. The centres are where the cells were laid out with
        // the preview already in place, so the slot holds still while the
        // finger stays between two of them.
        if (barVertical) return without.count { (columnCentres[it] ?: Float.MAX_VALUE) < at.y }
        // Measured from the edge the row starts its tools at — the right one
        // when the bar draws RTL ([barRtl]), so the slot always counts in the
        // same direction the icons are laid out in.
        val travel = if (barRtl) bar.right - at.x else at.x - bar.left
        return ((travel / bar.width) * (without.size + 1))
            .toInt()
            .coerceIn(0, without.size)
    }

    /**
     * The stored pinned list with [tool] moved to display slot [slot] of the
     * bar. The same trick [orderWith] uses for the toolbox: the slot indexes
     * the drawn tools, so the drawn tool it lands in front of is what pins the
     * position down in a stored list that may hold tools the bar never drew.
     */
    private fun barWith(tool: ToolbarTool, slot: Int): List<ToolbarTool> {
        val shown = visibleTools - tool
        val successor = shown.getOrNull(slot.coerceIn(0, shown.size))
        val bar = currentTools.toMutableList().apply { remove(tool) }
        val at = successor?.let { bar.indexOf(it) }?.takeIf { it >= 0 } ?: bar.size
        bar.add(at, tool)
        return bar
    }

    /** The cell being dragged, as the grid lists it; null for a tool coming off the bar. */
    private fun draggedCell(): ToolboxCell? {
        val folder = draggingFolder
        if (folder != null) return toolboxCells.firstOrNull { it is ToolboxCell.Folder && it.folder.id == folder.id }
        val tool = dragging ?: return null
        return toolboxCells.firstOrNull { it is ToolboxCell.Tool && it.tool == tool }
    }

    /** The grid as the drop preview draws it: without the cell in flight. */
    private fun cellsWithout(): List<ToolboxCell> {
        val key = draggedCell()?.key ?: return toolboxCells
        return toolboxCells.filterNot { it.key == key }
    }

    /**
     * The page-local cell under [at], with how far across it the finger is
     * from the side the grid starts at (0 to 1), or null when off the grid.
     * The grid scrolls, so the position converts through the content column's
     * live coordinates rather than a captured rect.
     */
    private fun toolboxCellAt(at: Offset): Pair<Int, Float>? {
        if (toolboxSearching) return null
        val viewport = toolboxViewport ?: return null
        if (!viewport.contains(at)) return null
        val coords = toolboxContentCoords?.takeIf { it.isAttached } ?: return null
        val cell = toolboxCellSize
        if (cell.width <= 0f || cell.height <= 0f) return null
        val origin = coords.positionInRoot()
        val columns = toolboxColumns.coerceAtLeast(1)
        val x = (at.x - origin.x) / cell.width
        val across = x.toInt().coerceIn(0, columns - 1)
        val within = (x - across).coerceIn(0f, 1f)
        // The grid fills from the right under RTL, so the leftmost cell of a
        // full row is its last column, not its first.
        val col = if (boxRtl) columns - 1 - across else across
        val row = ((at.y - origin.y) / cell.height).toInt().coerceAtLeast(0)
        return (row * columns + col) to (if (boxRtl) 1f - within else within)
    }

    /** Whether a tool held here can be filed with the cell under it (#709). */
    private fun mergesHere(): Boolean {
        val tool = dragging ?: return false
        return folderView == null && tool !in toolboxHidden
    }

    /**
     * The cell whose middle a dragged tool is held over (#709), or null. Only
     * the middle: the outer parts of a cell are still the slots either side of
     * it, so a reorder never needs to aim around anything.
     */
    private fun mergeAt(at: Offset): ToolboxCell? {
        if (!mergesHere()) return null
        val (local, within) = toolboxCellAt(at) ?: return null
        if (within !in ToolboxMergeZone || local >= toolboxPageLength) return null
        return cellsWithout().getOrNull(toolboxPageStart + local)
    }

    /**
     * Toolbox grid slot under [at], or null when off the visible panel. Where a
     * tool can be filed into a cell, the cell's start side is the slot before
     * it and its end side the slot after; the middle is [mergeAt]'s.
     */
    private fun toolboxSlotAt(at: Offset): Int? {
        val tool = dragging
        if (tool == null && draggingFolder == null) return null
        if (tool != null && tool in toolboxHidden) return null
        val (local, within) = toolboxCellAt(at) ?: return null
        val count = cellsWithout().size
        val after = if (mergesHere() && within > ToolboxMergeZone.endInclusive) 1 else 0
        // The cell is local to whatever registered the coords: the whole grid
        // when the toolbox scrolls, one page when it paginates.
        val slot = (local + after).coerceIn(0, toolboxPageLength)
        return (toolboxPageStart + slot).coerceIn(0, count)
    }

    /** The tool a cell stands at in the toolbox order: itself, or a folder's first. */
    private fun anchorOf(cell: ToolboxCell?): ToolbarTool? = when (cell) {
        null -> null
        is ToolboxCell.Tool -> cell.tool
        is ToolboxCell.Folder -> cell.folder.tools.minByOrNull { tool ->
            toolboxOrder.indexOf(tool).takeIf { it >= 0 } ?: Int.MAX_VALUE
        }
    }

    /** The full tool order with [tool] moved to display slot [slot] of the grid. */
    private fun orderWith(tool: ToolbarTool, slot: Int): List<ToolbarTool> {
        // The grid previews the drop with the dragged cell removed, so the
        // slot indexes that list; the displayed cell it lands in front of
        // anchors the position in the complete order.
        val displayed = cellsWithout()
        val successor = anchorOf(displayed.getOrNull(slot.coerceIn(0, displayed.size)))
        val order = toolboxOrder.toMutableList().apply { remove(tool) }
        val at = successor?.let { order.indexOf(it) }?.takeIf { it >= 0 } ?: order.size
        order.add(at, tool)
        return order
    }

    /**
     * The full tool order with every tool of [folder] moved, as one block in
     * the order they already had, to display slot [slot] of the grid (#709).
     */
    private fun folderOrderWith(folder: ToolboxFolder, slot: Int): List<ToolbarTool> {
        val members = folder.tools.toSet()
        val block = toolboxOrder.filter { it in members }
        val displayed = cellsWithout()
        val successor = anchorOf(displayed.getOrNull(slot.coerceIn(0, displayed.size)))
        val order = toolboxOrder.filterNot { it in members }.toMutableList()
        val at = successor?.let { order.indexOf(it) }?.takeIf { it >= 0 } ?: order.size
        order.addAll(at, block)
        return order
    }

    /** Over the open folder's header with a tool from inside it: the take-out drop (#709). */
    private fun folderExitAt(at: Offset): Boolean {
        val view = folderView ?: return false
        val tool = dragging ?: return false
        if (fromToolbar || tool !in view.tools) return false
        return folderExitBounds?.contains(at) == true
    }
}

/**
 * The part of a toolbox cell, across from the side the grid starts at, where a
 * dragged tool is filed with the cell rather than put beside it (#709). The
 * middle half or so: wide enough to aim at with a thumb, with a quarter either
 * side left for reordering.
 */
private val ToolboxMergeZone = 0.28f..0.72f

/**
 * Distance a held tool has to travel before the gesture counts as a move
 * rather than a stationary hold. Generous on purpose: a hold meant to open
 * the tool's settings drifts a few pixels under any real thumb, and landing
 * in "moved the tool" because of that is the more annoying misfire.
 */
private val ToolDragSlop = 24.dp

/**
 * How often a held toolbar tool repeats its move, or null for the tools (and
 * the settings) where holding means something else.
 *
 * The interval is the text-editing tool's repeat speed: the same key held down
 * at the same rate, whether the user reached it through the panel or pinned it
 * to the bar.
 */
private fun holdRepeatMs(tool: ToolbarTool, state: KeyboardUiState): Long? =
    if (tool in HoldRepeatCursorTools && state.settings.textEditing.cursorToolsRepeatOnHold) {
        state.settings.textEditing.repeatMs.toLong()
    } else {
        null
    }

/**
 * What a press and hold on [tool] does on the toolbar — the user's binding, else
 * HeliBoard's pairing (issue #639), else the settings page; see
 * [holdActionOf] — or null when the hold has another job here and the toolbar
 * opens the settings page as it always did.
 *
 * Toolbar only, and never for a tool whose hold already repeats — that hold is
 * spoken for, and the tools it covers are the caret moves, where a repeat is the
 * whole point. Reads through to a tool rather than a separate action vocabulary:
 * "holding this does what tapping that does" needs nothing new to be dispatched,
 * and every tool is already a target.
 */
private fun holdActionFor(
    tool: ToolbarTool,
    fromToolbar: Boolean,
    state: KeyboardUiState,
): ToolHoldAction? = if (
    !fromToolbar || holdRepeatMs(tool, state) != null ||
    holdArmsSelection(tool, fromToolbar, state) || holdOpensTrackpad(tool, fromToolbar, state) ||
    holdPicksVoiceMode(tool, fromToolbar, state)
) {
    null
} else {
    state.settings.toolbarBehavior.holdActionOf(tool)
}

/**
 * Whether a press and hold on [tool] opens the voice typing mode menu: the
 * Voice tool on the toolbar, unless the user has given that hold back (#173).
 * The fifth thing a stationary hold can be, exclusive with the other four the
 * way they are with each other, and toolbar only for the reason
 * [holdArmsSelection] is.
 */
private fun holdPicksVoiceMode(
    tool: ToolbarTool,
    fromToolbar: Boolean,
    state: KeyboardUiState,
): Boolean = fromToolbar &&
    tool == ToolbarTool.VOICE &&
    state.settings.voiceBar.holdPicksTypingMode &&
    // A menu of one is no choice: the hold goes back to the toolbar.
    state.supportedVoiceModes().size > 1

/**
 * Whether a press and hold on [tool] opens the trackpad panel for as long as the
 * finger stays down: the Trackpad tool on the toolbar, unless the user has
 * given that hold back (issue #39). The fourth thing a stationary hold can be,
 * exclusive with the other three the way they are with each other, and toolbar
 * only for the reason [holdArmsSelection] is.
 */
private fun holdOpensTrackpad(
    tool: ToolbarTool,
    fromToolbar: Boolean,
    state: KeyboardUiState,
): Boolean = fromToolbar &&
    tool == ToolbarTool.TRACKPAD &&
    state.settings.trackpad.holdToOpen

/**
 * Whether a press and hold on [tool] turns selection mode on for as long as the
 * finger stays down — true for the Selection mode tool on the toolbar, unless
 * the user has given that hold back.
 *
 * The third thing a stationary hold can be, beside repeating a caret move and
 * running a bound action, and it excludes the other two the same way they
 * exclude each other. Toolbar only: in the toolbox a hold reaches every tool's
 * settings page, and there is nothing to select behind an open panel anyway.
 */
/**
 * The wait before a hold on a tool counts: the toolbar's own setting when it
 * has one (#665), else the system's touch-and-hold delay.
 */
private fun toolHoldDelay(settingMs: Int, systemMs: Long): Long =
    if (settingMs > 0) settingMs.toLong() else systemMs

private fun holdArmsSelection(
    tool: ToolbarTool,
    fromToolbar: Boolean,
    state: KeyboardUiState,
): Boolean = fromToolbar &&
    tool == ToolbarTool.SELECT_MODE &&
    state.settings.textEditing.selectionModeHold

/**
 * Wires long-press-drag onto a tool. Three outcomes from one gesture: a tap
 * runs [onTap]; a hold that never travels past [ToolDragSlop] opens the
 * tool's settings page — or runs [holdAction] when the user has given that
 * tool one; a hold that does travel picks the tool up and drops it wherever it
 * lands (reorder, pin, or unpin).
 *
 * [holdRepeatMs] replaces the middle one for the caret tools (see
 * [HoldRepeatCursorTools]): a stationary hold runs [onTap] again every
 * [holdRepeatMs] instead, so the cursor keeps moving for as long as the finger
 * is down. Null everywhere else, and on those tools the settings page is a hold
 * away in the toolbox instead.
 *
 * [holdArms] replaces it in the same way for the Selection mode tool: the hold
 * turns selection mode on while the finger is down and the release turns it off
 * (see [holdArmsSelection]). The release reaches the service on the drag path
 * too, or the mode would be left on by a reorder.
 *
 * [holdPanel] is the same shape for the Trackpad tool: the hold opens the
 * trackpad panel and the release closes it (see [holdOpensTrackpad]).
 *
 * Whatever the hold means, the pick-up itself waits for the finger to travel
 * past the slop. Only then does the cell wash out and the scope pill appear:
 * a hold that stays put is one of the three outcomes above, not a reorder, and
 * must not look like one while it is being held.
 *
 * The tap is dispatched from here rather than from a `clickable` on the tool
 * itself: a `clickable` sits deeper in the modifier chain, so it saw the
 * release first and fired its own click on top of every hold.
 */
@Composable
private fun DraggableTool(
    tool: ToolbarTool,
    fromToolbar: Boolean,
    enabled: Boolean,
    drag: ToolDragController,
    onTap: () -> Unit,
    holdRepeatMs: Long? = null,
    /**
     * What a stationary hold does — another tool's tap, or nothing at all —
     * or null to open the tool's settings page.
     */
    holdAction: ToolHoldAction? = null,
    /**
     * Whether a hold that travels picks the tool up. Off (#136), travel is
     * ignored: the hold stays a hold and ends as whatever a stationary one
     * would have, so the bar is rearranged from the toolbox instead.
     */
    dragEnabled: Boolean = true,
    /** Whether a stationary hold arms selection mode for as long as it lasts. */
    holdArms: Boolean = false,
    /** Whether a stationary hold opens the trackpad panel for as long as it lasts. */
    holdPanel: Boolean = false,
    /**
     * Whether a stationary hold opens a menu on its release — the Voice tool's
     * typing modes (#173) — through [onHoldMenu]. Dispatched like the settings
     * page and a bound action, on the lift, not like [holdArms]: the menu is
     * what the hold was for, and it stands after the finger is gone.
     */
    holdMenu: Boolean = false,
    onHoldMenu: () -> Unit = {},
    /** How long the hold takes, in ms; 0 is the system's touch-and-hold delay (#665). */
    holdDelayMs: Int = 0,
    content: @Composable (Modifier) -> Unit,
) {
    var origin by remember { mutableStateOf(Offset.Zero) }
    val feedback = LocalKeyPressFeedback.current
    val scope = rememberCoroutineScope()
    // Read through a holder rather than keying pointerInput on the lambda:
    // a fresh lambda every recomposition would restart the handler, and the
    // drop preview recomposes this row on every frame of a drag.
    val tapAction by rememberUpdatedState(onTap)
    val menuAction by rememberUpdatedState(onHoldMenu)
    content(
        Modifier
            .onGloballyPositioned { origin = it.positionInRoot() }
            // Keyed on the interval too: it comes from a setting, so the handler
            // has to be rebuilt when it changes. A Long changes far more rarely
            // than the lambda above, which is why that one goes through a holder.
            .pointerInput(enabled, tool, holdRepeatMs, holdArms, holdPanel, holdMenu, dragEnabled, holdDelayMs) {
                if (!enabled) return@pointerInput
                // Raw press-and-hold, mirroring the key rows' handler, instead
                // of detectDragGesturesAfterLongPress: its long-press never
                // fired inside the IME window on device, so tools could not
                // be dragged at all. An external timer plus a plain event
                // loop is the pattern already proven by the repeat keys.
                val dragSlop = ToolDragSlop.toPx()
                awaitEachGesture {
                    val down = awaitFirstDown(requireUnconsumed = false)
                    // Travel is measured in root coordinates, not from raw
                    // node-relative deltas: the row reflows around the drop
                    // preview while the finger is down, and a node that moves
                    // under a still finger reports deltas of its own.
                    val downRoot = origin + down.position
                    var rootPos = downRoot
                    var longPressed = false
                    var dragged = false
                    var released = false
                    var scrolled = false
                    // Whether selection mode is on because of *this* hold, so
                    // the release turns off exactly what the press turned on.
                    var armed = false
                    // Same for the trackpad panel: open by this hold, closed by
                    // its release, and never by a release that did not open it.
                    var held = false
                    val timer = scope.launch {
                        delay(toolHoldDelay(holdDelayMs, viewConfiguration.longPressTimeoutMillis))
                        // The buzz tells the user the long-press registered.
                        // The pick-up itself waits for travel (see the drag
                        // slop below), for every kind of hold: starting it here
                        // parked a drag ghost and the scope pill under a finger
                        // that was only holding the button, so a hold that
                        // ended as a bound action or the settings page first
                        // washed its own cell out and flashed a "changing the
                        // tool order" notice for a reorder nobody made (#31).
                        feedback()
                        longPressed = true
                        if (holdArms) {
                            // Selection mode for as long as the finger stays
                            // down. The bar can still be rearranged from this
                            // button: travel picks it up like any other.
                            armed = true
                            drag.onSelectionHold(true)
                        } else if (holdPanel) {
                            // The trackpad for as long as the finger stays
                            // down; the other thumb does the dragging. The bar
                            // can still be rearranged from this button too.
                            held = true
                            drag.onTrackpadHold(true)
                        } else if (holdRepeatMs != null) {
                            // The first move lands with no delay of its own —
                            // the long-press timeout has already served as the
                            // repeat's start delay.
                            while (true) {
                                tapAction()
                                delay(holdRepeatMs)
                            }
                        }
                    }
                    try {
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            if (!change.pressed) {
                                released = true
                                // Swallow the release once the hold is ours so
                                // nothing downstream treats it as a tap too.
                                if (longPressed) change.consume()
                                break
                            }
                            rootPos = origin + change.position
                            val travel = (rootPos - downRoot).getDistance()
                            if (!longPressed) {
                                // Real drift before the hold registers is a
                                // scroll (toolbox grid) — hand the gesture back.
                                if (travel > viewConfiguration.touchSlop) {
                                    scrolled = true
                                    break
                                }
                            } else {
                                change.consume()
                                if (travel > dragSlop && !dragged && dragEnabled) {
                                    dragged = true
                                    // Travel means this was a reorder all along,
                                    // so the tool picks itself up from here. A
                                    // repeating tool stops repeating; the moves
                                    // it already made stand — they are caret
                                    // moves, undone by moving the caret back.
                                    timer.cancel()
                                    // The mode ends here rather than on the
                                    // drop: from this point the gesture is
                                    // about the toolbar, not the text.
                                    if (armed) {
                                        armed = false
                                        drag.onSelectionHold(false)
                                    }
                                    if (held) {
                                        held = false
                                        drag.onTrackpadHold(false)
                                    }
                                    drag.start(tool, fromToolbar, rootPos)
                                }
                                // Nothing to move until the finger has travelled:
                                // no drag has been started, and drag.move would
                                // tick the drop haptic anyway.
                                if (dragged) drag.move(rootPos)
                            }
                        }
                    } finally {
                        timer.cancel()
                        // Whatever ended the gesture — a release, a drop, the
                        // handler being torn down mid-hold — the mode this press
                        // armed ends with it. Nothing else here can be trusted
                        // to run: the branches below are exclusive.
                        if (armed) {
                            armed = false
                            drag.onSelectionHold(false)
                        }
                        if (held) {
                            held = false
                            drag.onTrackpadHold(false)
                        }
                        when {
                            !longPressed -> {
                                drag.cancel()
                                if (released && !scrolled) tapAction()
                            }
                            dragged -> drag.end()
                            // A hold that armed selection mode, or held the
                            // trackpad open, has already done its work, and
                            // there is nothing to drop. Its settings page is a
                            // hold away in the toolbox.
                            holdArms || holdPanel -> drag.cancel()
                            // Same for a repeating hold. Its settings page is a
                            // hold away in the toolbox, which never repeats.
                            holdRepeatMs != null -> drag.cancel()
                            // A hold that opens a menu opens it on the lift,
                            // like the settings page below: a menu under a
                            // finger that is still down would be dismissed by
                            // the release that was meant to read it.
                            holdMenu -> {
                                drag.cancel()
                                menuAction()
                            }
                            // A hold that never travelled past the slop is a
                            // distinct gesture: the action the user bound to it,
                            // nothing at all if that is what they bound (#136),
                            // or the tool's settings page when they bound none.
                            else -> {
                                drag.cancel()
                                when (val bound = holdAction) {
                                    null, ToolHoldAction.OpenSettings -> drag.onOpenSettings(tool)
                                    ToolHoldAction.None -> Unit
                                    is ToolHoldAction.Run -> drag.onHoldAction(bound.tool)
                                }
                            }
                        }
                    }
                }
            }
    )
}

/**
 * Slides this element to its new position when layout around it changes —
 * pinned tools shuffle smoothly instead of jumping when the toolbox chevron
 * shows up or a tool is (un)pinned. Fast, no-bounce spring: quick but not
 * sudden.
 *
 * The position is measured against [anchor] (the keyboard body) rather than
 * the immediate parent: the toolbar nests rows inside rows and its weighted
 * cells resize, so an icon's parent-relative position barely moves while
 * its on-screen position shifts a lot. Anchoring at the body captures the
 * whole motion in one spring, so nothing snaps at animation start. Falls
 * back to parent-relative when no anchor is available.
 *
 * [enabled] is the reduce-motion switch. It has to snap rather than skip the
 * modifier: opening a panel adds the back chevron, which shifts every pinned
 * icon, so a disabled slide still needs to track the new position or the
 * icons would sit at their old offsets.
 *
 * [inRow] marks a node that only ever slides along a single row — everything
 * on the toolbar. Those get the row rules [animateSharedPlacement] already
 * used for the emoji tool: a vertical move snaps (the row itself has moved,
 * see [ToolbarRowShiftPx]) and a horizontal one may travel as far as the bar
 * is wide (see [ToolbarSlideCapFraction]). The toolbox grid leaves it false —
 * its cells legitimately move between rows when the grid reflows — and brings
 * its own [cap] instead, because a grid cell is far bigger than the fixed one
 * (see [toolboxSlideCap]).
 *
 * [cap] is the furthest a move may be and still be slid rather than snapped,
 * given the anchor it was measured against. The default is the row/fixed rule
 * [placementCap]; a caller whose layout has a natural step of its own passes
 * that step instead.
 */
private fun Modifier.animatePlacement(
    enabled: Boolean = true,
    inRow: Boolean = false,
    cap: (LayoutCoordinates?) -> Float = { placementCap(inRow, it) },
    anchor: () -> LayoutCoordinates? = { null },
): Modifier =
    composed {
        val scope = rememberCoroutineScope()
        val animatable = remember { Animatable(IntOffset.Zero, IntOffset.VectorConverter) }
        // The displacement drawn right now, set synchronously from onPlaced.
        // Everything below hangs on this: onPlaced runs in the layout phase,
        // by which point a layout-phase offset for this frame has already
        // been decided, and the coroutine that starts the spring does not run
        // until the next one. So the icon was drawn once at its destination,
        // then jumped back to where it came from and slid in — a one-frame
        // flash on every icon, every time the bar changed. Draw runs after
        // layout in the same frame, so a draw-phase displacement written here
        // lands before the icon is ever painted undisplaced.
        var immediate by remember { mutableStateOf<IntOffset?>(null) }
        var lastTarget by remember { mutableStateOf<IntOffset?>(null) }
        // Whether [lastTarget] was measured against the anchor or against the
        // parent. The anchor is published from an onGloballyPositioned, which
        // runs AFTER this node's first placement, so the first target is always
        // parent-relative and every later one anchor-relative. Two different
        // spaces: subtracting one from the other invents a move nothing made.
        var lastAnchored by remember { mutableStateOf(false) }
        this
            .onPlaced { coords ->
                val anchorCoords = anchor()?.takeIf { it.isAttached }
                val target = (
                    anchorCoords?.localPositionOf(coords, Offset.Zero)
                        ?: coords.positionInParent()
                    ).round()
                val anchored = anchorCoords != null
                val previous = lastTarget.takeIf { lastAnchored == anchored }
                lastTarget = target
                lastAnchored = anchored
                // First placement settles in place: a fresh icon has nowhere to
                // have travelled from. So does the first one after the anchor
                // turned up, for the same reason — that target and the one
                // before it are in different spaces.
                //
                // This is what made a freshly opened toolbox slide its pills
                // around: parent-relative, every pill sits at ~(0,0) inside its
                // own cell, so the second pass handed each one a "move" equal to
                // its own slot in the grid. Column offsets and the lower rows
                // were past [PlacementSlideCap] and snapped, but the left column
                // of row 2 is exactly one pill-pitch down — inside the cap — so
                // that one pill, and only that one, slid in from the row above.
                if (previous == null || previous == target) return@onPlaced
                val delta = previous - target
                // A row-bound icon that moved vertically did not move: its row
                // did, and sliding after a row that has already arrived reads
                // as lag. Snap — and snap for every icon in the bar alike. This
                // was [animateSharedPlacement]'s rule alone, so opening the
                // emoji panel over an always-on emoji row (the row folds away,
                // the whole bar rises) left the emoji tool and the toolbox
                // standing still while the clipboard and settings icons drifted
                // in diagonally from where the old row had been.
                val rowShifted = inRow &&
                    (delta.x == 0 || kotlin.math.abs(delta.y) > ToolbarRowShiftPx)
                val jump = delta.toOffset().getDistance()
                // Deadband, and the big-jump escape. The toolbar's cells are
                // weighted, so their widths land on fractions that round
                // differently between passes; nothing travels a single pixel
                // on purpose here, so a move that small is rounding, not
                // motion. A move past the cap is a layout jump (a scroll, a
                // toolbox page flip) and animating it reads as lag.
                val capPx = cap(anchorCoords)
                if (!enabled || rowShifted || jump < 2f || jump > capPx) {
                    immediate = null
                    scope.launch { animatable.snapTo(IntOffset.Zero) }
                    return@onPlaced
                }
                // Carry any displacement still in flight, so a change that
                // lands mid-slide continues from where the icon actually is
                // rather than restarting from the new delta alone.
                val start = delta + (immediate ?: animatable.value)
                immediate = start
                scope.launch {
                    animatable.snapTo(start)
                    immediate = null
                    animatable.animateTo(IntOffset.Zero, ToolbarSlideSpring)
                }
            }
            .graphicsLayer {
                val shift = immediate ?: animatable.value
                translationX = shift.x.toFloat()
                translationY = shift.y.toFloat()
            }
    }

/**
 * The furthest a re-placed icon may have travelled and still be slid rather
 * than snapped.
 *
 * A toolbar icon is measured against the bar it sits in ([anchorCoords] is the
 * keyboard body, so its width is the bar's), because what the bar asks of its
 * icons scales with how wide it is; see [ToolbarSlideCapFraction]. Anything
 * else, and a bar with no anchor to measure, falls back to [PlacementSlideCap].
 */
private fun placementCap(inRow: Boolean, anchorCoords: LayoutCoordinates?): Float {
    if (!inRow) return PlacementSlideCap
    val width = anchorCoords?.size?.width?.toFloat() ?: return PlacementSlideCap
    return (width * ToolbarSlideCapFraction).coerceAtLeast(PlacementSlideCap)
}

/**
 * Headroom over one reorder step, before a toolbox move is taken for a layout
 * jump. A step is never *exactly* a step — a cell's own padding shifts by a
 * pixel or two between passes — so the cap has to clear it rather than sit on
 * it.
 */
private const val ToolboxSlideCapSlack = 1.15f

/**
 * The furthest a toolbox cell may travel and still slide, sized off the grid's
 * own step rather than the fixed [PlacementSlideCap].
 *
 * The fixed cap is a toolbar cap: 160 px is well under half an icon's slot on
 * the bar, but it is under *one cell* of the grid on every phone (four columns
 * of a 1080 px keyboard are 270 px each). So every reorder step the grid ever
 * made was read as a layout jump and snapped, and the tools popped from slot to
 * slot while the toolbar beside them slid — the whole of this bug.
 *
 * The real step is one slot, and the biggest one slot can be is a wrap: the
 * last cell of a row becoming the first of the next, which is [columns] - 1
 * cells across and one cell down. Anything past that is a reflow the grid did
 * not ask for — the column count changed, the panel resized — and snapping
 * those is what the cap is still for.
 */
private fun toolboxSlideCap(columns: Int, cell: Size): Float {
    if (cell.width <= 0f || cell.height <= 0f) return PlacementSlideCap
    val across = cell.width * (columns - 1).coerceAtLeast(1)
    val wrap = Offset(across, cell.height).getDistance()
    return (wrap * ToolboxSlideCapSlack).coerceAtLeast(PlacementSlideCap)
}

/**
 * Where an icon that lives in more than one branch of the tree last sat.
 *
 * [animatePlacement] can only animate a node that survives the layout
 * change, and the emoji icon does not: the strip draws its own copy and
 * the toolbar draws another as a pinned tool, so flipping between them
 * disposes one node and composes a different one. Parking the last
 * body-relative position outside both lets the arriving node start from
 * where the leaving one stood, which is the whole illusion.
 */
private class SharedPlacement {
    var last: IntOffset? = null

    /** Whether [last] was measured against the anchor or against a parent. */
    var lastAnchored: Boolean = false

    /**
     * When the node holding [last] was disposed, or 0 while one still holds it.
     *
     * This is what separates a handoff from a reappearance. A handoff is one
     * node being disposed and another composed inside a single frame, so the
     * arriving node finds a stamp a frame or two old. A reappearance — the
     * icon's whole host went away, because a full-bleed panel takes the top
     * bar with it, and came back seconds later — finds a stale one, and
     * sliding in from a position that old is a phantom: the icon flies in
     * from wherever it happened to sit before the panel opened.
     *
     * It has to be dispose time, not the time [last] was written. Writing it
     * on placement looks equivalent and is not: a node is only re-placed when
     * layout invalidates, so the strip's emoji icon stamps once when it
     * appears and then sits untouched for as long as the user types. Every
     * real handoff then read as ancient and refused to animate, which is
     * exactly the icon snapping into place instead of sliding.
     */
    var vacatedAtNanos: Long = 0L
}

/** Two frames at 60Hz, the window a real strip/toolbar handoff lands in. */
private const val SharedPlacementMaxAgeNanos = 33_000_000L

/**
 * Slides this element in from wherever [shared] was last seen, then keeps
 * [shared] pointing at its own position. The counterpart to
 * [animatePlacement] for an icon that changes parents rather than moving
 * within one.
 */
private fun Modifier.animateSharedPlacement(
    shared: SharedPlacement,
    enabled: Boolean = true,
    anchor: () -> LayoutCoordinates? = { null },
): Modifier =
    composed {
        val scope = rememberCoroutineScope()
        val offset = remember { Animatable(IntOffset.Zero, IntOffset.VectorConverter) }
        var immediate by remember { mutableStateOf<IntOffset?>(null) }
        // Stamp the moment this node leaves, so whichever node replaces it can
        // tell a handoff from a reappearance. onDispose runs while changes are
        // applied, ahead of the layout pass that places the arriving node, so
        // the stamp is always there in time.
        DisposableEffect(shared) {
            onDispose { shared.vacatedAtNanos = System.nanoTime() }
        }
        // This node's own last position, so a re-placement within one parent
        // (the bar reflowing under it) animates like [animatePlacement] does,
        // not just the cross-parent handoff. Without this the emoji snapped
        // whenever the toolbar reshuffled — every other icon slid but it.
        var lastTarget by remember { mutableStateOf<IntOffset?>(null) }
        // Anchor-relative or parent-relative, for this node and for the shared
        // stamp alike. The anchor arrives from an onGloballyPositioned a pass
        // late, so a first position is parent-relative and everything after it
        // is not; comparing across the two would invent a move. See the same
        // note in [animatePlacement].
        var lastAnchored by remember { mutableStateOf(false) }
        this
            .onPlaced { coords ->
                val anchorCoords = anchor()?.takeIf { it.isAttached }
                val position = (
                    anchorCoords?.localPositionOf(coords, Offset.Zero)
                        ?: coords.positionInParent()
                    ).round()
                val anchored = anchorCoords != null
                if (lastTarget == position && lastAnchored == anchored) return@onPlaced
                val ownPrevious = lastTarget.takeIf { lastAnchored == anchored }
                val sharedPrevious = shared.last?.takeIf { shared.lastAnchored == anchored }
                val vacatedAt = shared.vacatedAtNanos
                val first = ownPrevious == null
                lastTarget = position
                lastAnchored = anchored
                shared.last = position
                shared.lastAnchored = anchored
                // Claim the slot: while this node lives there is no vacancy.
                shared.vacatedAtNanos = 0L
                if (!enabled) return@onPlaced
                // A cross-parent handoff: this node just appeared and the
                // sibling it replaces vacated within the last frame or two
                // (see [SharedPlacement.vacatedAtNanos]). It slides in from
                // wherever that sibling stood, however far along the row.
                val handoff = first && sharedPrevious != null && vacatedAt != 0L &&
                    System.nanoTime() - vacatedAt <= SharedPlacementMaxAgeNanos
                // Where this placement travelled *from*: the vacated slot for a
                // handoff, else this node's own previous spot for an ordinary
                // reflow. A fresh node with neither has nowhere to come from.
                val previous = when {
                    handoff -> sharedPrevious
                    !first -> ownPrevious
                    else -> null
                } ?: return@onPlaced
                if (previous == position) return@onPlaced
                val raw = previous - position
                // A handoff travels along the bar and nowhere else, so only the
                // horizontal part of it is real. The two nodes are not the same
                // shape — the toolbar's pinned emoji is a 30dp circle with its
                // name under it, the strip's is a bare 38dp one — so their tops
                // sit a few pixels apart and the vertical rule below read that
                // as "the row moved" and snapped. Which is why the icon stopped
                // sliding across the moment toolbar labels were switched on.
                val delta = if (handoff) IntOffset(raw.x, 0) else raw
                // A slide along the bar never changes height; a vertical move
                // means the rows themselves shifted (a panel opened, the emoji
                // row appeared), which animating reads as lag — snap it.
                if (delta.x == 0 || kotlin.math.abs(delta.y) > ToolbarRowShiftPx) {
                    immediate = null
                    scope.launch { offset.snapTo(IntOffset.Zero) }
                    return@onPlaced
                }
                // A reflow nudge is small; a jump past the bar's own cap is a
                // layout change (a scroll, a resize), not motion. The handoff is
                // exempt — it is deliberately a long slide.
                val jump = delta.toOffset().getDistance()
                if (!handoff && (jump < 2f || jump > placementCap(true, anchorCoords))) {
                    immediate = null
                    scope.launch { offset.snapTo(IntOffset.Zero) }
                    return@onPlaced
                }
                // Carry any displacement still in flight so a change that lands
                // mid-slide continues from where the icon actually is. This is
                // what keeps the drawn position continuous when a handoff is
                // followed a frame later by the layout settling to its final
                // slot: the seed offset re-anchors to the new target instead of
                // snapping the icon out to the row's edge.
                val start = delta + (immediate ?: offset.value)
                // Drawn this frame, not next; see the note in animatePlacement.
                immediate = start
                scope.launch {
                    offset.snapTo(start)
                    immediate = null
                    offset.animateTo(IntOffset.Zero, ToolbarSlideSpring)
                }
            }
            .graphicsLayer {
                val shift = immediate ?: offset.value
                translationX = shift.x.toFloat()
                translationY = shift.y.toFloat()
            }
    }

/**
 * One round tool button; the circle radius comes from the theme (0 = bare
 * icon). With [longPressLabel] set, holding the button pops the tool's name
 * above it — the toolbar shows bare icons, so this is how a user finds out
 * what one does without tapping it.
 */
@Composable
internal fun ToolCircle(
    slot: String,
    description: String,
    active: Boolean,
    modifier: Modifier = Modifier,
    longPressLabel: String? = null,
    onLongPress: (() -> Unit)? = null,
    // False when an ancestor owns the whole gesture (see DraggableTool):
    // a clickable here would sit deeper in the chain and steal the release.
    interactive: Boolean = true,
    // Inactive-icon tint override (the tool's accent colour). Null keeps the
    // theme's toolbar-icon colour; the active state always wins over this.
    tint: Color? = null,
    // The gradient to paint the inactive icon with instead of [tint], when the
    // gradient tool colours are on. Same precedence: active still wins.
    tintBrush: Brush? = null,
    // When set, the tool's name is drawn under the icon (toolbar labels). The
    // long-press tooltip is then redundant and suppressed.
    label: String? = null,
    labelSizeSp: Int = 9,
    // Draws this button as a drop preview — washed out, outlined, "will go
    // here" — while keeping the footprint of the real thing. Same look as
    // [GhostToolCircle], but it follows the label setting, and a bare circle
    // standing in for a labelled button is a whole row's worth of height
    // missing from the preview.
    ghost: Boolean = false,
    // Bar buttons stretch to the theme's tool width (38 = today's circle);
    // panel headers and grids keep the fixed circle regardless of the setting.
    wide: Boolean = false,
    // The physical key that opens this tool, drawn as a badge over the bottom of
    // the button. An overlay, never an extra child: the badge appears the moment
    // the picker arms, and a button that grew a row then would shove the whole
    // keyboard down under the user's hands.
    hint: String? = null,
    // A smaller button for a switch that lives beside something else (the
    // suggestion strip) rather than on the toolbar. Bare-icon form only: a
    // labelled button already has its own, shorter box.
    compact: Boolean = false,
    // The button's width and glyph size in dp, over the theme's tool sizes:
    // the strip's buttons when they are sized apart from the toolbar's.
    // Bare-icon form only, and ignored when [compact].
    widthDp: Int? = null,
    iconSizeDp: Int? = null,
    // The labelled button's widest, in dp: a longer name is cut short rather
    // than widening the button (#970). Null lets the name set the width.
    labelMaxWidthDp: Int? = null,
    onClick: () -> Unit,
) {
    val kb = LocalKbTheme.current
    val shape = kb.toolShape()
    val background = when {
        ghost -> kb.toolCircleActive.copy(alpha = 0.22f)
        active -> kb.toolCircleActive
        kb.toolRadiusDp > 0 -> kb.toolCircle
        else -> Color.Transparent
    }
    val outline = when {
        // The ghost's own dashed-out look wins: it is saying "will go here",
        // not wearing the theme's outline.
        ghost -> Modifier.border(1.dp, kb.toolbarIcon.copy(alpha = 0.35f), shape)
        kb.toolBorder != null && kb.toolBorderWidthDp > 0f ->
            Modifier.border(kb.toolBorderWidthDp.dp, kb.toolBorder, shape)
        else -> Modifier
    }
    var showLabel by remember { mutableStateOf(false) }
    // A bare icon with no label of its own still names itself on a hold: the
    // panels' header buttons are ToolCircles too, and pass no label.
    val holdLabel = longPressLabel ?: description.takeIf { label == null && it.isNotBlank() }
    val feedback = LocalKeyPressFeedback.current
    // Every live button is a possible panel opener: the panel a tap opens
    // grows out of the button (see [PanelMotionSlot]). Not the inert ones — the
    // cell around those owns the press, and records itself with its name.
    val click = if (!interactive) {
        Modifier
    } else if (holdLabel == null && onLongPress == null) {
        Modifier.panelOrigin().clickable(onClick = onClick)
    } else {
        Modifier.panelOrigin().pointerInput(holdLabel, onLongPress != null) {
            detectTapGestures(
                onTap = { onClick() },
                onLongPress = {
                    feedback()
                    if (onLongPress != null) onLongPress() else showLabel = true
                },
            )
        }
    }
    val fullTint = if (active) kb.toolCircleActiveIcon else (tint ?: kb.toolbarIcon)
    val iconTint = if (ghost) fullTint.copy(alpha = 0.45f) else fullTint
    val iconBrush = if (active || ghost) null else tintBrush
    if (label != null) {
        // Labelled variant (toolbar labels): icon in its circle, name beneath.
        Column(
            modifier = modifier
                .then(if (labelMaxWidthDp != null) Modifier.widthIn(max = labelMaxWidthDp.dp) else Modifier)
                .then(click),
            horizontalAlignment = Alignment.CenterHorizontally,
            verticalArrangement = Arrangement.Center,
        ) {
            Box(
                modifier = Modifier
                    .size(
                        width = (if (wide) (kb.toolWidthDp - 8).coerceAtLeast(30) else 30).dp,
                        height = 30.dp,
                    )
                    .clip(shape)
                    .then(if (kb.toolRadiusDp > 0) Modifier.frostGlass(kb, shape, FrostSurface.TOOLS) else Modifier)
                    .background(background, shape)
                    .then(outline),
                contentAlignment = Alignment.Center,
            ) {
                SlotIcon(
                    slot,
                    contentDescription = description,
                    modifier = Modifier
                        // Two under the Tool icon size setting and capped at 26:
                        // this box is 30 dp, not 38, because the name underneath
                        // has to fit in the same toolbar height. A bigger glyph
                        // lifted clear of the hint badge would leave the box
                        // through the top. The name grew instead — which is
                        // what is read here anyway.
                        .size((kb.toolIconSizeDp - 2).coerceAtMost(26).dp)
                        // Lifted, not shrunk, so the badge below has room inside
                        // a box whose size must not change (see [HintBadge]).
                        .offset(y = if (hint != null) -(HintBadgeHeight / 2) else 0.dp),
                    tint = iconTint,
                    brush = iconBrush,
                )
                // Under the icon, over the name: the badge is temporary and the
                // name is what the labels setting was turned on for, so the
                // badge borrows the name's top edge rather than the icon's face.
                if (hint != null) {
                    HintBadge(hint, modifier = Modifier.align(Alignment.BottomCenter))
                }
            }
            Text(
                label,
                fontSize = labelSizeSp.sp,
                lineHeight = (labelSizeSp + 1).sp,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                color = if (ghost) fullTint.copy(alpha = 0.5f) else fullTint,
                modifier = Modifier.padding(top = 1.dp, start = 1.dp, end = 1.dp),
            )
        }
        return
    }
    val side = if (compact) CompactToolSide else 38
    Box(
        modifier = modifier
            .size(
                width = when {
                    compact -> side
                    widthDp != null -> widthDp
                    wide -> kb.toolWidthDp
                    else -> side
                }.dp,
                height = side.dp,
            )
            .clip(shape)
            // Glass under the tool's own fill; a bare-icon theme (radius 0)
            // has no background to be glass.
            .then(if (kb.toolRadiusDp > 0) Modifier.frostGlass(kb, shape, FrostSurface.TOOLS) else Modifier)
            .background(background, shape)
            .then(outline)
            .then(click),
        contentAlignment = Alignment.Center,
    ) {
        SlotIcon(
            slot,
            contentDescription = description,
            modifier = Modifier
                .size(
                    when {
                        compact -> CompactToolIconSize
                        iconSizeDp != null -> iconSizeDp.dp
                        else -> kb.toolIconSizeDp.dp
                    },
                )
                // The icon steps up by half the badge's height so the badge sits
                // under it rather than across it. The button's own 38 dp box is
                // untouched, so nothing on the bar moves.
                .offset(y = if (hint != null) -(HintBadgeHeight / 2) else 0.dp),
            tint = iconTint,
            brush = iconBrush,
        )
        if (hint != null) {
            HintBadge(hint, modifier = Modifier.align(Alignment.BottomCenter))
        }
        if (showLabel && holdLabel != null) {
            IconHintBubble(holdLabel) { showLabel = false }
        }
    }
}

/**
 * The finger steering the swipe-up popup of more words, and the popup's cells as
 * the finger sees them.
 *
 * The finger never leaves the strip's window: it went down on the strip, and the
 * keyboard window keeps every move of that pointer however far above itself it
 * travels. The popup is a window of its own over the app, so it cannot be hit
 * test against directly; both sides state their positions on screen instead, the
 * cells as they are placed and the strip as it is, and the strip's gesture asks
 * [track] which cell is under the finger.
 */
@Stable
internal class MoreSuggestionsHold {
    /** The cell under the finger, as an index into [words], or -1 for none. */
    val selected = mutableIntStateOf(-1)

    /** The words the popup is drawing, in cell order. */
    var words: List<String> = emptyList()

    /** The strip's top-left corner on screen, which the gesture's positions are relative to. */
    var origin: Offset = Offset.Zero

    /** The strip's width, which the popup takes. */
    var widthPx: Int = 0

    /** Each cell's bounds on screen, by index. */
    val cells = HashMap<Int, Rect>()

    fun reset() {
        selected.intValue = -1
        cells.clear()
    }

    /**
     * Lights the cell at [screen]: the one it is inside, else the nearest one
     * while the finger is still within half a cell of the popup's edge. Further
     * out than that (back down on the strip, say) nothing is lit, so lifting
     * there picks nothing.
     */
    fun track(screen: Offset) {
        selected.intValue = moreSuggestionAt(cells, screen)
    }

    /** The lit word, or null when none is. */
    fun selectedWord(): String? = words.getOrNull(selected.intValue)
}

/** See [MoreSuggestionsHold.track]. Pure, for the tests. */
internal fun moreSuggestionAt(cells: Map<Int, Rect>, screen: Offset): Int {
    if (cells.isEmpty()) return -1
    cells.entries.firstOrNull { it.value.contains(screen) }?.let { return it.key }
    val first = cells.values.first()
    var union = first
    for (cell in cells.values) {
        union = Rect(
            minOf(union.left, cell.left),
            minOf(union.top, cell.top),
            maxOf(union.right, cell.right),
            maxOf(union.bottom, cell.bottom),
        )
    }
    val slack = first.height / 2f
    if (!union.inflate(slack).contains(screen)) return -1
    return cells.minByOrNull { (_, cell) ->
        val dx = (screen.x - screen.x.coerceIn(cell.left, cell.right))
        val dy = (screen.y - screen.y.coerceIn(cell.top, cell.bottom))
        dx * dx + dy * dy
    }?.key ?: -1
}

/**
 * The word strip's vertical swipes, as one gesture: down hides the keyboard or
 * opens the pages of more words (#385), up opens the popup of more words over
 * the strip and keeps the finger to steer it.
 *
 * Its own detector rather than [detectVerticalDragGestures], because the popup
 * needs every move of the finger once it is open, sideways ones included, and
 * that detector reports only the vertical part of a vertical drag. Until the
 * finger has travelled past the touch slop nothing is consumed, so a tap still
 * reaches the word under it; travel that is more sideways than up or down is
 * handed back too, so a scrolling strip still scrolls.
 *
 * Each flag is read at the moment of the swipe through its [State], since
 * whether there are words to show changes with every keystroke.
 */
private fun Modifier.stripSwipes(
    pages: State<Boolean>,
    more: State<Boolean>,
    pagesOpen: State<Boolean>,
    hide: State<Boolean>,
    hold: MoreSuggestionsHold,
    suggestionHold: SuggestionHoldCallbacks,
    onSwipeDownHide: () -> Unit,
): Modifier = this
    .onGloballyPositioned {
        hold.origin = it.positionOnScreen()
        hold.widthPx = it.size.width
    }
    .pointerInput(onSwipeDownHide, suggestionHold, hold) {
        val threshold = ToolbarSwipeHideThreshold.toPx()
        awaitEachGesture {
            val down = awaitFirstDown(requireUnconsumed = false)
            var dragging = false
            var fired = false
            var opened = false
            try {
                while (true) {
                    val event = awaitPointerEvent()
                    val change = event.changes.firstOrNull { it.id == down.id } ?: break
                    if (!change.pressed) {
                        if (opened) {
                            // The lift is the pick: whatever is lit, or nothing.
                            change.consume()
                            val word = hold.selectedWord()
                            opened = false
                            suggestionHold.onMorePopup(false)
                            if (word != null) suggestionHold.onMorePick(word)
                        }
                        break
                    }
                    val total = change.position - down.position
                    if (!dragging) {
                        // Something under the finger took the gesture first (a
                        // tool picked up for a reorder): it is not a swipe.
                        if (change.isConsumed) break
                        val slop = viewConfiguration.touchSlop
                        val ay = kotlin.math.abs(total.y)
                        val ax = kotlin.math.abs(total.x)
                        when {
                            ay > slop && ay >= ax -> dragging = true
                            ax > slop -> break
                            else -> continue
                        }
                    }
                    change.consume()
                    if (opened) {
                        hold.track(hold.origin + change.position)
                        continue
                    }
                    if (fired) continue
                    when {
                        // Either way closes the open pages.
                        pagesOpen.value && kotlin.math.abs(total.y) > threshold -> {
                            fired = true
                            suggestionHold.onPagesToggle(false)
                        }
                        // Words to page through win the swipe; the keyboard
                        // hides from an idle strip.
                        total.y > threshold -> {
                            fired = true
                            if (pages.value) suggestionHold.onPagesToggle(true)
                            else if (hide.value) onSwipeDownHide()
                        }
                        total.y < -threshold && more.value -> {
                            fired = true
                            opened = true
                            hold.reset()
                            suggestionHold.onMorePopup(true)
                        }
                    }
                }
            } finally {
                // A gesture torn down mid-steer (the strip left the screen)
                // takes its popup with it.
                if (opened) suggestionHold.onMorePopup(false)
            }
        }
    }

/**
 * The swipe-up popup of more words: the engine's deeper list, over the app and
 * just above the strip, as wide as the strip. The finger that swiped up steers
 * it from the strip ([stripSwipes]); the popup itself takes no touches, so its
 * window is not touchable and nothing under it is blocked.
 *
 * In a grid of the strip's own columns when the expanded-grid setting is on,
 * filled from the row nearest the strip upward, so the best of the extra words
 * is the shortest reach from where the finger already is. Otherwise each row
 * wraps the words to their own widths, in the same bottom-up order.
 */
@Composable
private fun MoreSuggestionsPopup(state: KeyboardUiState, hold: MoreSuggestionsHold) {
    val kb = LocalKbTheme.current
    val words = state.moreSuggestions
    SideEffect { hold.words = words }
    val density = LocalDensity.current
    val width = with(density) { hold.widthPx.toDp() }
    val selected = hold.selected.intValue
    val columns = state.settings.suggestionStrip.slotCount.coerceAtLeast(1)
    val grid = state.settings.suggestionStrip.expandedGrid
    val textScale = state.settings.suggestionStrip.textScale
    val provider = remember {
        object : PopupPositionProvider {
            override fun calculatePosition(
                anchorBounds: IntRect,
                windowSize: IntSize,
                layoutDirection: LayoutDirection,
                popupContentSize: IntSize,
            ): IntOffset = IntOffset(anchorBounds.left, anchorBounds.top - popupContentSize.height)
        }
    }
    val cell: @Composable (Modifier, Int) -> Unit = { modifier, index ->
        val lit = index == selected
        Box(
            modifier = modifier
                .padding(2.dp)
                .height(MoreSuggestionRowHeight)
                .onGloballyPositioned { coords ->
                    val at = coords.positionOnScreen()
                    hold.cells[index] = Rect(at, coords.size.toSize())
                }
                .clip(kb.chipShape())
                .background(if (lit) kb.popupText.copy(alpha = 0.16f) else Color.Transparent),
            contentAlignment = Alignment.Center,
        ) {
            Text(
                text = words[index],
                modifier = Modifier.padding(horizontal = 10.dp),
                color = kb.popupText,
                fontSize = MoreSuggestionFontSize * textScale,
                fontWeight = if (lit) FontWeight.SemiBold else FontWeight.Normal,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
            )
        }
    }
    Popup(popupPositionProvider = provider, properties = MoreSuggestionsProperties) {
        Surface(
            modifier = Modifier.width(width),
            shape = kb.popupShape(),
            color = kb.popup,
            border = kb.popupSurfaceBorder(),
            shadowElevation = elevationFor(kb.popupShapeKind, 6.dp),
        ) {
            Column(modifier = Modifier.padding(4.dp)) {
                // Rows are built nearest-the-strip first, then laid out top
                // down, so the list reads upward from the strip.
                val rows = if (grid) {
                    words.indices.chunked(columns)
                } else {
                    words.indices.chunked(columns + 1)
                }
                for (row in rows.asReversed()) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = if (grid) Arrangement.Start else Arrangement.SpaceEvenly,
                    ) {
                        for (index in row) {
                            key(words[index]) {
                                cell(if (grid) Modifier.weight(1f) else Modifier.weight(1f, fill = false), index)
                            }
                        }
                        if (grid) repeat(columns - row.size) { Spacer(modifier = Modifier.weight(1f)) }
                    }
                }
            }
        }
    }
}

/** The popup's window: drawn only, never touched, so it blocks nothing beneath it. */
private val MoreSuggestionsProperties = PopupProperties(
    flags = WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE or
        WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE,
    inheritSecurePolicy = true,
    dismissOnBackPress = false,
    dismissOnClickOutside = false,
    excludeFromSystemGesture = true,
    usePlatformDefaultWidth = false,
)

private val MoreSuggestionRowHeight = 40.dp
private val MoreSuggestionFontSize = 15.sp

/**
 * The language whose phonetic layout is being typed on, when the English-words
 * switch can do something there: the switch is on for the strip, and English is
 * among that language's secondary suggestion languages, which is the gate the
 * toggle itself refuses outside of. Null otherwise.
 */
private fun phoneticEnglishLanguage(state: KeyboardUiState): String? =
    state.composer.phoneticLanguage?.takeIf {
        state.settings.suggestionStrip.phoneticEnglishSwitch &&
            "en" in state.settings.secondaryLanguages[it].orEmpty()
    }

/**
 * The tools the user keeps beside the suggestions (#462), in their order, less
 * any this build or these settings cannot run. Empty while the strip's buttons
 * are off ([KeyboardSettings.emojiToolbar]).
 */
private fun stripShortcutTools(state: KeyboardUiState): List<ToolbarTool> {
    if (!state.settings.emojiToolbar) return emptyList()
    return state.settings.toolbarBehavior.stripShortcuts.filter {
        it in state.settings.enabledTools && isSupportedTool(it) && isUsableTool(it, state.settings)
    }
}

/**
 * Every tool the strip draws a copy of: the user's list plus the English-words
 * switch while it is due. The toolbar's pinned copy of any of these hands its
 * position across the strip↔toolbar flip instead of fading (see [ToolbarRow]).
 */
private fun stripToolSet(state: KeyboardUiState): Set<ToolbarTool> {
    val tools = stripShortcutTools(state)
    return if (phoneticEnglishLanguage(state) != null) {
        tools.toSet() + ToolbarTool.PHONETIC_ENGLISH
    } else {
        tools.toSet()
    }
}

/**
 * The buttons kept beside the suggestions while the pinned tools are off the
 * row: the tools the user picked (#462), in their order, then the phonetic
 * layouts' English-words switch.
 *
 * Which tools those are is the user's to say: the clipboard or the microphone
 * for someone who never opens the emoji panel, or several at once. A tool that
 * is also pinned on the toolbar slides between its two spots on the flip
 * ([ToolDragController.placementOf]) rather than vanishing here and
 * reappearing there; the toolbar side of that is [ToolbarRow]'s `sharedTools`.
 *
 * With the tools on a row of their own and a tool on it, that one is already in
 * reach and a second copy beside the suggestions is just the same button twice,
 * so it is left out.
 *
 * The English-words switch is kept beside the words it decides. A phonetic
 * layout reading a Bangla word as English is only ever noticed while the word
 * is on the strip, and that is precisely when the toolbar the switch otherwise
 * lives on is off the row, so the one moment it is wanted is the one moment it
 * could not be reached. It stays for as long as it can do something (see
 * [phoneticEnglishLanguage]), a step down in size from the user's own buttons
 * unless those have a size of their own, and lit while the switch is on.
 *
 * Its own composable: the strip's lambda sits near ART's 10,000-instruction
 * compile ceiling, and this loop would push it over.
 */
@Composable
private fun StripTools(
    state: KeyboardUiState,
    toolsRowVisible: Boolean,
    drag: ToolDragController,
    onToolTap: (ToolbarTool) -> Unit,
    onToolbox: () -> Unit,
) {
    val onRow = if (toolsRowVisible) visibleToolbarTools(state) else emptyList()
    val tools = stripShortcutTools(state).filter { it !in onRow }
    val phonetic = ToolbarTool.PHONETIC_ENGLISH
    val autoPhonetic = phonetic !in tools && phonetic !in onRow && phoneticEnglishLanguage(state) != null
    // Null is the toolbox button. Drawn in the order they read left to right,
    // whichever way the strip runs, unless the toolbar mirrors for this script
    // too (see [stripToolsAtEnd]).
    val order = buildList {
        if (state.settings.emojiToolbar && state.settings.toolbarBehavior.stripToolbox) add(null)
        addAll(tools)
        if (autoPhonetic) add(phonetic)
    }
    for (tool in if (stripToolsHeldLtr(state)) order.asReversed() else order) {
        if (tool == null) {
            key("§toolbox") { StripToolboxButton(state, onToolbox) }
        } else {
            // Only the switch added by itself is a step down in size.
            val compact = autoPhonetic && tool == phonetic && !state.settings.toolbarBehavior.stripOwnSize
            key(tool) { StripToolButton(state, tool, drag, compact = compact, onToolTap) }
        }
    }
}

/**
 * Whether the strip runs right to left under its buttons while the toolbar
 * does not mirror: an RTL script with [ToolbarBehaviorSettings.reverseForRtl]
 * off. The buttons then keep the side and the order they have in every other
 * language (#970), the way the toolbar's own tools do, rather than following
 * the words to the other edge.
 */
private fun stripToolsHeldLtr(state: KeyboardUiState): Boolean =
    state.script.direction == TextDirection.RTL && !toolbarReadsRtl(state)

/**
 * Whether [StripTools] goes after the words in the strip's own direction. A
 * strip held LTR for its buttons ([stripToolsHeldLtr]) runs the other way, so
 * the start the user picked is that row's end.
 */
private fun stripToolsAtEnd(state: KeyboardUiState): Boolean =
    state.settings.toolbarBehavior.stripShortcutsAtEnd != stripToolsHeldLtr(state)

/** The toolbox launcher among the buttons beside the suggestions (#970). */
@Composable
private fun StripToolboxButton(state: KeyboardUiState, onToolbox: () -> Unit) {
    val behavior = state.settings.toolbarBehavior
    val label = stringResource(R.string.ime_toolbox_desc)
    ToolCircle(
        slot = IconSlots.CHROME_TOOLBOX,
        description = label,
        active = false,
        longPressLabel = label,
        wide = true,
        widthDp = behavior.stripToolWidthDp.takeIf { behavior.stripOwnSize },
        iconSizeDp = behavior.stripIconSizeDp.takeIf { behavior.stripOwnSize },
    ) { onToolbox() }
}

/** One of [StripTools]' buttons. */
@Composable
private fun StripToolButton(
    state: KeyboardUiState,
    tool: ToolbarTool,
    drag: ToolDragController,
    compact: Boolean,
    onToolTap: (ToolbarTool) -> Unit,
) {
    val behavior = state.settings.toolbarBehavior
    // The width the bar would give this icon, so the two copies of a tool are
    // the same shape. Nothing constrains it here, so at a tool width wider than
    // a toolbar cell the strip's copy came out at the full setting while the
    // pinned one was capped at its cell: the icon changed size mid-slide, and
    // since the slide tracks left edges its centre jumped by half the
    // difference first. See [ToolDragController.pinnedToolWidthPx]. Not when
    // the strip's buttons have a size of their own, which is then the point.
    val pinnedWidth = with(LocalDensity.current) {
        drag.pinnedToolWidthPx.takeIf { it > 0 && !behavior.stripOwnSize }?.toDp()
    }
    val label = stringResource(toolLabelRes(tool))
    // Coloured as the pinned copy is, so the slide between them lands on the same icon.
    val paint = if (behavior.pinnedToolColors) toolAccentPaint(tool, state.settings) else null
    ToolCircle(
        // The emoji keeps an icon-pack slot of its own here, the one this
        // button has always had.
        slot = if (tool == ToolbarTool.EMOJI) IconSlots.CHROME_EMOJI_SHORTCUT else IconSlots.forTool(tool),
        description = label,
        active = toolActive(tool, state),
        tint = paint?.color,
        tintBrush = paint?.brush,
        modifier = Modifier
            .then(if (pinnedWidth != null) Modifier.widthIn(max = pinnedWidth) else Modifier)
            .animateSharedPlacement(
                drag.placementOf(tool),
                enabled = !state.settings.reduceMotion,
            ) { drag.bodyCoords },
        longPressLabel = label,
        // Matches the toolbar's pinned footprint, so the shared-placement slide
        // lands on an identical shape.
        wide = true,
        compact = compact,
        widthDp = behavior.stripToolWidthDp.takeIf { behavior.stripOwnSize },
        iconSizeDp = behavior.stripIconSizeDp.takeIf { behavior.stripOwnSize },
    ) { onToolTap(tool) }
}

/**
 * The ANSI button on a Bengali layout's strip, and the Zawgyi one on a Burmese
 * layout's: the encoding's name on a pill the height of a compact
 * [ToolCircle], filled while the layouts write it. A word rather than an icon,
 * because ANSI and Zawgyi are what the fonts that want them are called and no
 * glyph says it better.
 */
@Composable
private fun EncodingToggle(active: Boolean, label: String, description: String, onClick: () -> Unit) {
    val kb = LocalKbTheme.current
    val shape = kb.toolShape()
    Box(
        modifier = Modifier
            .height(CompactToolSide.dp)
            .clip(shape)
            .background(
                when {
                    active -> kb.toolCircleActive
                    kb.toolRadiusDp > 0 -> kb.toolCircle
                    else -> Color.Transparent
                },
                shape,
            )
            .toggleable(value = active, role = Role.Switch, onValueChange = { onClick() })
            .semantics { contentDescription = description }
            .padding(horizontal = 7.dp),
        contentAlignment = Alignment.Center,
    ) {
        Text(
            label,
            color = if (active) kb.toolCircleActiveIcon else kb.toolbarIcon,
            fontSize = 11.sp,
            lineHeight = 12.sp,
            fontWeight = FontWeight.Bold,
            maxLines = 1,
        )
    }
}

/**
 * The drop-preview stand-in rendered at the slot a dragged tool would land
 * in: same footprint as [ToolCircle], drawn washed out so it reads as
 * "will go here" rather than "is here". Keyed placement animation makes it
 * slide from slot to slot as the finger moves.
 */
@Composable
private fun GhostToolCircle(
    tool: ToolbarTool,
    modifier: Modifier = Modifier,
    wide: Boolean = false,
) {
    val kb = LocalKbTheme.current
    val shape = kb.toolShape()
    Box(
        modifier = modifier
            .size(width = (if (wide) kb.toolWidthDp else 38).dp, height = 38.dp)
            .background(kb.toolCircleActive.copy(alpha = 0.22f), shape)
            .border(1.dp, kb.toolbarIcon.copy(alpha = 0.35f), shape),
        contentAlignment = Alignment.Center,
    ) {
        SlotIcon(
            IconSlots.forTool(tool),
            contentDescription = null,
            modifier = Modifier.size(kb.toolIconSizeDp.dp),
            tint = kb.toolbarIcon.copy(alpha = 0.45f),
        )
    }
}

/**
 * The glyph inside a toolbox pill, and the default of the Tool icon size
 * setting ([KbTheme.toolIconSizeDp]) that sizes it inside a tool button.
 *
 * It was 20 dp in a 38 dp button, which left the icon floating in a lot of
 * empty circle: at a glance a toolbox page read as a field of identical
 * bubbles, and picking one out meant looking at each in turn rather than
 * seeing the shape. 22 dp still clears the button's edge — and the hint badge
 * that overlays its bottom — while giving the glyph enough of the circle to
 * be recognised on the way past.
 */
private val ToolIconSize = 22.dp

/** A [ToolCircle] drawn `compact`: the box's side in dp, and the glyph in it. */
private const val CompactToolSide = 30
private val CompactToolIconSize = 18.dp

/**
 * The tools on a row of their own, above the suggestion strip — the row
 * [ToolbarPlacement.ON_DEMAND_ROW] and [ToolbarPlacement.ALWAYS_ROW] add.
 *
 * A plain [Row] of the same height as the strip wrapping the same [ToolbarRow]
 * the strip hosts in the shared arrangement, so the two placements draw the same
 * tools, the same widths, and the same drag behaviour. No fade: nothing is being
 * exchanged here — the row is either there or it is not, and its own appearance
 * is the animation.
 *
 * The row mirrors for RTL scripts only when the user asked it to
 * ([toolbarReadsRtl]) — the row holds nothing but buttons, so there is no
 * reading order for the script to dictate, and with the setting off it stays
 * exactly where it was in the last language. The drag hit-testing follows the
 * same answer (see [ToolbarRow]).
 */
@Composable
private fun ToolsRow(
    state: KeyboardUiState,
    onPanelChange: (PanelMode) -> Unit,
    onToolTap: (ToolbarTool) -> Unit,
    drag: ToolDragController,
) {
    val direction = if (toolbarReadsRtl(state)) LayoutDirection.Rtl else LayoutDirection.Ltr
    CompositionLocalProvider(LocalLayoutDirection provides direction) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .height(topBarHeight(state.settings))
                .toolbarPadding(state.settings),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            ToolbarRow(state, onPanelChange, onToolTap, drag)
        }
    }
}

/**
 * The pinned tools in a column down one side of the keys, for a phone on its
 * side ([ToolbarBehavior.landscapeColumn], #970): the bar's buttons in the
 * bar's order, top to bottom. The way back out of an open panel, the toolbox
 * launcher, the pinned tools and folders, the toolbox's search while it is
 * open, the show-keys button and the incognito and power-saving badges, each
 * where [ToolbarRow] has it along the row.
 *
 * The tools are [PinnedToolCell]s, so they hold, drag and wear their colours
 * exactly as on the bar. They fit the column the way Tool layout fits the
 * bar: spread over its height, packed at its top, or scrolling, the
 * first two shrinking together once there are more than the height holds
 * ([fitToolsColumn]).
 *
 * Never mirrored: a column has no reading order, and its side is the screen's.
 */
@Composable
private fun ToolsColumn(
    state: KeyboardUiState,
    onPanelChange: (PanelMode) -> Unit,
    onToolTap: (ToolbarTool) -> Unit,
    drag: ToolDragController,
    modifier: Modifier = Modifier,
) {
    val customizing = state.panel == PanelMode.TOOLBOX
    val scrollable = state.settings.toolbarBehavior.scrollable
    val spread = state.settings.toolbarBehavior.greedy && !scrollable
    val labels = state.settings.toolbarLabels
    val labelSize = state.settings.toolbarLabelSize
    // A name is cut to the column rather than widening it.
    val labelMaxWidth = toolsColumnWidthDp(state) - 2 * ToolsColumnGutterDp
    val motion = !state.settings.reduceMotion
    val dpadRing = LocalDpadRing.current
    val tools = visibleToolbarTools(state)
    val pinnedFolders = state.settings.toolbox.folders.filter { it.pinned }
    drag.visibleTools = tools
    drag.barRtl = false
    drag.barVertical = true
    // The drop preview moves the dragged tool's own cell to the slot under
    // the finger, as on the bar (see [ToolbarRow]).
    val dragTool = drag.dragging
    val ghostSlot = drag.barSlot
    val displayTools: List<ToolbarTool> = if (dragTool != null && ghostSlot != null) {
        (tools - dragTool).toMutableList().apply {
            add(ghostSlot.coerceIn(0, size), dragTool)
        }
    } else {
        tools
    }
    val hints = if (dragTool == null) armedHintPlan(state) else null
    val toolboxSearchShown = customizing && state.settings.toolbox.searchButton &&
        !state.toolboxView.searchActive
    val searchAtEnd = state.settings.toolbox.searchAtEnd
    val cell = Modifier.padding(vertical = 3.dp)
    val toolboxSearch: @Composable () -> Unit = {
        ToolCircle(
            slot = IconSlots.CHROME_TOOLBOX_SEARCH,
            description = stringResource(R.string.ime_toolbox_search_desc),
            active = false,
            modifier = cell,
            longPressLabel = stringResource(R.string.ime_toolbox_search_desc),
            wide = true,
        ) { drag.toolbox.onSearchToggle() }
    }
    Column(
        modifier = modifier
            // The whole column is where a drop lands; the cells' centres say
            // in front of which tool.
            .onGloballyPositioned { drag.toolbarBounds = it.boundsInRoot() }
            .then(
                if (scrollable) Modifier.verticalScroll(rememberScrollState()) else Modifier.fitToolsColumn(spread),
            ),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = if (spread) Arrangement.SpaceEvenly else Arrangement.Top,
    ) {
        // With any tool panel open, the top of the column is the way back to
        // the keys. Out at once, for the bar's reason: a fading exit holds
        // the slot, and the tools under it move twice.
        AnimatedVisibility(
            visible = state.panel != PanelMode.NONE,
            enter = fadeIn(tween(if (motion) ToolbarMotionMs else 0)),
            exit = ExitTransition.None,
        ) {
            ToolCircle(
                slot = IconSlots.CHROME_PANEL_BACK,
                description = stringResource(R.string.ime_panel_back_desc),
                active = false,
                longPressLabel = stringResource(R.string.ime_panel_back_desc),
                modifier = cell.then(
                    if (dpadRing) {
                        Modifier.dpadTarget(BarBackRingId) { onPanelChange(state.panel) }
                    } else {
                        Modifier
                    },
                ),
                wide = true,
            ) { onPanelChange(state.panel) }
        }
        if (toolboxSearchShown && !searchAtEnd) toolboxSearch()
        ToolCircle(
            slot = IconSlots.CHROME_TOOLBOX,
            description = stringResource(R.string.ime_toolbox_desc),
            active = customizing,
            label = stringResource(R.string.ime_toolbox_desc).takeIf { labels },
            labelSizeSp = labelSize,
            labelMaxWidthDp = labelMaxWidth,
            modifier = cell
                .then(
                    if (dpadRing) {
                        Modifier.dpadTarget(BarToolboxRingId) { onPanelChange(PanelMode.TOOLBOX) }
                    } else {
                        Modifier
                    },
                )
                .animatePlacement(enabled = motion) { drag.bodyCoords },
            longPressLabel = stringResource(R.string.ime_toolbox_desc).takeUnless { labels },
            wide = true,
            hint = hints?.label(HintSurface.TOOLBAR, 0),
        ) { onPanelChange(PanelMode.TOOLBOX) }
        for (tool in displayTools) {
            key(tool) {
                PinnedToolCell(
                    tool, state, drag, onToolTap,
                    cell = cell.onGloballyPositioned { drag.columnCentres[tool] = it.boundsInRoot().center.y },
                    hint = hints?.label(HintSurface.TOOLBAR, tools.indexOf(tool) + 1),
                    labelMaxWidthDp = labelMaxWidth,
                    inRow = false,
                )
            }
        }
        // Folders after the tools, as on the bar (#709).
        for (folder in pinnedFolders) {
            key("folder:${folder.id}") {
                PinnedFolderButton(
                    folder = folder,
                    state = state,
                    open = customizing && state.toolboxView.folderOpen == folder.id,
                    onOpen = { drag.toolbox.onFolderOpen(folder.id) },
                    modifier = cell.animatePlacement(enabled = motion) { drag.bodyCoords },
                )
            }
        }
        if (toolboxSearchShown && searchAtEnd) toolboxSearch()
        // The keys called up over the toolbar-only view go away from here too (#642).
        if (hardwareKeysToggleable(state)) {
            val shown = state.settings.toolbarBehavior.hardwareKeysShown
            val desc = stringResource(
                if (shown) R.string.ime_hardware_keys_hide_desc else R.string.ime_hardware_keys_show_desc,
            )
            ToolCircle(
                slot = if (shown) IconSlots.CHROME_HIDE_KEYS else IconSlots.CHROME_SHOW_KEYS,
                description = desc,
                active = shown,
                label = desc.takeIf { labels },
                labelSizeSp = labelSize,
                labelMaxWidthDp = labelMaxWidth,
                modifier = cell,
                longPressLabel = desc.takeUnless { labels },
                wide = true,
            ) { drag.onHardwareKeysToggle() }
        }
        if (state.incognitoOn) {
            SlotIcon(
                IconSlots.CHROME_INCOGNITO,
                contentDescription = stringResource(R.string.ime_incognito_on_desc),
                modifier = Modifier
                    .clickable { drag.onIncognitoBadge() }
                    .padding(4.dp)
                    .size(16.dp),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
        if (state.powerSavingOn) {
            SlotIcon(
                IconSlots.CHROME_POWER_SAVING,
                contentDescription = stringResource(R.string.ime_power_saving_on_desc),
                modifier = Modifier
                    .padding(4.dp)
                    .size(16.dp),
                tint = MaterialTheme.colorScheme.onSurfaceVariant,
            )
        }
    }
}

/**
 * [ToolsColumn]'s fit, as [shrinkToFit] is the packed bar's: the buttons at
 * their own size while they fit, spread over the column's height or packed at
 * its top, and scaled down together from the top once they don't, so every
 * tool stays on screen and a tap still lands on the icon under the finger.
 */
private fun Modifier.fitToolsColumn(spread: Boolean): Modifier = layout { measurable, constraints ->
    val bounded = constraints.hasBoundedHeight
    val height = constraints.maxHeight
    // Spread, the buttons are given at least the column's height to spread
    // over; packed, they take what they take.
    val placeable = measurable.measure(
        constraints.copy(
            minHeight = if (spread && bounded) height else 0,
            maxHeight = Constraints.Infinity,
        ),
    )
    if (!bounded || placeable.height <= height) {
        layout(placeable.width, if (bounded) height else placeable.height) { placeable.place(0, 0) }
    } else {
        val scale = height / placeable.height.toFloat()
        layout(placeable.width, height) {
            placeable.placeWithLayer(0, 0) {
                scaleX = scale
                scaleY = scale
                transformOrigin = TransformOrigin(0.5f, 0f)
            }
        }
    }
}

/**
 * The side the pinned tools stand on in a column beside the keys (#970), or
 * null while they are along the top where [ToolbarBehavior.placement] puts
 * them. Landscape only, and only with keys to stand beside: the toolbar-only
 * view for a physical keyboard, and the strip up only for its candidates,
 * keep the one row they have.
 *
 * What the strip asks to know whether the tools are on screen beside it;
 * [toolsColumnShown] is whether the column is drawn right now.
 */
@Composable
private fun toolsColumnSide(state: KeyboardUiState): ToolbarColumn? {
    val behavior = state.settings.toolbarBehavior
    val side = behavior.landscapeColumn
    if (side == ToolbarColumn.OFF || !behavior.enabled) return null
    if (hardwareKeysStepAside(state) || state.hardwareCandidateWindow) return null
    val landscape = LocalConfiguration.current.orientation == Configuration.ORIENTATION_LANDSCAPE
    return side.takeIf { landscape }
}

/**
 * [toolsColumnSide], less the moments the column steps out with the rest of
 * the bar: a full-bleed panel takes the whole keyboard, its width included,
 * and brings its own way back; lock-screen privacy hides every pinned tool.
 */
@Composable
private fun toolsColumnShown(state: KeyboardUiState): ToolbarColumn? =
    toolsColumnSide(state)?.takeUnless { barFullBleed(state) || barLockHidden(state) }

/**
 * The column's width in dp: a tool's width with a gutter either side, and
 * room for a short name once the tools wear labels.
 */
@Composable
private fun toolsColumnWidthDp(state: KeyboardUiState): Int {
    val tool = LocalKbTheme.current.toolWidthDp
    val content = if (state.settings.toolbarLabels) tool.coerceAtLeast(ToolsColumnLabelWidthDp) else tool
    return content + 2 * ToolsColumnGutterDp
}

/** Space between [ToolsColumn]'s buttons and its edges, in dp. */
private const val ToolsColumnGutterDp = 4

/** The narrowest [ToolsColumn]'s buttons get with labels on, in dp: room for "Undo" or "Paste" at the default size. */
private const val ToolsColumnLabelWidthDp = 48

/**
 * The toolbar itself: fixed toolbox launcher, then the user's tools —
 * spread across the free space when the greedy setting is on, packed to
 * the left otherwise.
 */
@Composable
private fun RowScope.ToolbarRow(
    state: KeyboardUiState,
    onPanelChange: (PanelMode) -> Unit,
    onToolTap: (ToolbarTool) -> Unit,
    drag: ToolDragController,
    // Opacity for the tools while the toolbar fades in. On an in-place
    // strip→toolbar flip the tools in [sharedTools] are exempt — they hand
    // their position across and slide instead of fading — so this rides the
    // toolbox launcher and the other pinned tools only. On a fresh mount
    // nothing slides, so [fadeShared] folds them into the same fade and the
    // whole bar comes up together.
    contentAlpha: () -> Float = { 1f },
    // The tools the suggestion strip also draws a copy of (see [stripToolSet]).
    sharedTools: Set<ToolbarTool> = emptySet(),
    fadeShared: Boolean = false,
) {
    val customizing = state.panel == PanelMode.TOOLBOX
    // Scrolling wants the tools at their natural width, so it overrides the
    // greedy even-spread (which would keep them all on screen and shrinking).
    val scrollable = state.settings.toolbarBehavior.scrollable
    val greedy = state.settings.toolbarBehavior.greedy && !scrollable
    val labels = state.settings.toolbarLabels
    val labelSize = state.settings.toolbarLabelSize
    // A name cut to the tool width, when asked for (#970); null lets it set the width.
    val labelMaxWidth = LocalKbTheme.current.toolWidthDp.takeIf { state.settings.toolbarBehavior.labelsFixedWidth }
    val motion = !state.settings.reduceMotion
    // Enter and exit share one duration so the back chevron takes the same
    // time to leave as it took to arrive; a shorter exit made closing a panel
    // finish ahead of the icons still sliding back into the freed slot.
    val enterMs = if (motion) ToolbarMotionMs else 0
    // The tools are always held in storage order; whether they READ
    // right-to-left is a layout direction on the sub-row that draws them
    // ([toolsDirection] below). Keeping the two apart is what fixes the RTL
    // reorder: the enclosing bar is already flipped for the suggestion strip's
    // sake, so a mirrored list flipped it a second time and every drag landed
    // on the slot opposite the finger (issue #79).
    val tools = visibleToolbarTools(state)
    val pinnedFolders = state.settings.toolbox.folders.filter { it.pinned }
    // The D-pad ring reaches the bar as well as the keys: without it a remote
    // could type but never open a tool, change a setting or start voice input.
    // Each button registers where it is while it is drawn (see [dpadTarget]).
    val dpadRing = LocalDpadRing.current
    drag.visibleTools = tools
    val toolsRtl = toolbarReadsRtl(state)
    val toolsDirection = if (toolsRtl) LayoutDirection.Rtl else LayoutDirection.Ltr
    drag.barRtl = toolsRtl
    drag.barVertical = false
    // The tools hug the toolbox launcher, which sits at the enclosing bar's
    // start. When the sub-row runs the other way that end is its own end, so
    // the packing spacer has to lead instead of trail.
    val toolsPackAtEnd = toolsDirection != LocalLayoutDirection.current
    // While a drag is live the bar previews the drop by MOVING the dragged
    // tool's own cell to the slot under the finger and drawing it as a ghost
    // there. Not by inserting a separate ghost entry: the dragged cell has to
    // stay composed (it hosts the pointer handler driving the drag — dropping
    // it disposed that handler the instant the hold registered, which sent
    // every long-press down the "open settings" path instead), so an inserted
    // ghost made the row one cell longer than the row the drop commits to.
    // Every icon between the tool's old slot and the new one then previewed a
    // slot to the side of where it actually ended up.
    //
    // A keyed move is enough here. Row re-measures and re-places its children
    // on a pure reorder — unlike FlowRow, which is why the toolbox grid has to
    // re-key its ghost per slot instead (see [ToolboxGrid]).
    val dragTool = drag.dragging
    val ghostSlot = drag.barSlot
    val displayTools: List<ToolbarTool> = if (dragTool != null && ghostSlot != null) {
        (tools - dragTool).toMutableList().apply {
            add(ghostSlot.coerceIn(0, size), dragTool)
        }
    } else {
        tools
    }
    // Slot 0 is the toolbox launcher, so a tool's badge is its place in `tools`
    // plus one. Dropped entirely during a drag: the dragged cell may have come
    // from the toolbox and not be in `tools` at all, and a badge indexed off the
    // preview order would label cells with their neighbours' keys.
    val hints = if (dragTool == null) armedHintPlan(state) else null
    val panelOpen = state.panel != PanelMode.NONE
    // The toolbox's search button, shown while the toolbox is open (#687) and
    // opening over the whole keyboard (see [barFullBleed]). It sits at the far
    // end of the bar by default, out of reach of a tap meant for back, or
    // beside the back button when the user puts it there.
    val toolboxSearchShown = customizing && state.settings.toolbox.searchButton &&
        !state.toolboxView.searchActive
    val searchAtEnd = state.settings.toolbox.searchAtEnd
    val toolboxSearchCell: @Composable (Modifier) -> Unit = { cell ->
        Box(cell, contentAlignment = Alignment.Center) {
            ToolCircle(
                slot = IconSlots.CHROME_TOOLBOX_SEARCH,
                description = stringResource(R.string.ime_toolbox_search_desc),
                active = false,
                longPressLabel = stringResource(R.string.ime_toolbox_search_desc),
                wide = true,
            ) { drag.toolbox.onSearchToggle() }
        }
    }

    // In greedy mode every button — chevron, toolbox and tools alike — is an
    // equal-weight cell, so the whole bar is one evenly spaced grid instead
    // of fixed buttons on the left with the tools spread over the leftover.
    val leading: @Composable (Modifier) -> Unit = { cell ->
        // With any tool panel open, one tap on the chevron returns to the keys.
        // The transition state keeps the cell composed until the exit
        // animation finishes, then drops it entirely so a weighted cell
        // doesn't linger as an invisible gap.
        val chevronVisible = remember { MutableTransitionState(false) }
        chevronVisible.targetState = panelOpen
        if (chevronVisible.currentState || chevronVisible.targetState) {
            AnimatedVisibility(
                visibleState = chevronVisible,
                modifier = if (greedy) cell else Modifier,
                // Reduce motion collapses the durations to zero rather than
                // dropping AnimatedVisibility: the transition state still has
                // to run its lifecycle or the weighted cell never releases.
                // Both branches animate paint only, never measured size. The
                // greedy one already did (its slot is weighted, so the chevron
                // scales inside a cell that appears at full width); the other
                // used to expand/shrink its width, which re-measured the row
                // on every frame and made the pinned icons chase a target that
                // moved under them for the whole transition. See the matching
                // note on the suggestions chevron in TopBar.
                enter = if (greedy) {
                    // The weighted slot can't grow, so the chevron itself
                    // scales and fades into it.
                    scaleIn(tween(enterMs)) + fadeIn(tween(enterMs))
                } else {
                    fadeIn(tween(enterMs))
                },
                // Instant, for the same reason as the suggestions chevron: an
                // exit transition holds this cell's width (its whole weighted
                // slot, in greedy mode) until it finishes, so closing a tool
                // played the chevron out, paused, and only then let the icons
                // move — which is why closing felt broken while opening, where
                // the slot is claimed on the first frame, felt fine. Dropping
                // it at once makes the icons' spring the closing animation.
                exit = ExitTransition.None,
            ) {
                Box(
                    if (greedy) Modifier.fillMaxSize() else cell,
                    contentAlignment = Alignment.Center,
                ) {
                    ToolCircle(
                        slot = IconSlots.CHROME_PANEL_BACK,
                        description = stringResource(R.string.ime_panel_back_desc),
                        active = false,
                        longPressLabel = stringResource(R.string.ime_panel_back_desc),
                        modifier = if (dpadRing) {
                            Modifier.dpadTarget(BarBackRingId) { onPanelChange(state.panel) }
                        } else {
                            Modifier
                        },
                        wide = true,
                    ) { onPanelChange(state.panel) }
                }
            }
        }
        // The toolbox's search, when it sits beside the way back rather than
        // at the far end (see [toolboxSearchCell]).
        if (toolboxSearchShown && !searchAtEnd) toolboxSearchCell(cell)
        Box(cell, contentAlignment = Alignment.Center) {
            ToolCircle(
                slot = IconSlots.CHROME_TOOLBOX,
                description = stringResource(R.string.ime_toolbox_desc),
                active = customizing,
                // The launcher wears its name alongside the tools it sits with:
                // with labels on, one bare icon at the head of a row of named
                // buttons reads as a button that forgot its own label, and it
                // sits a few pixels off the others' baseline as well.
                label = stringResource(R.string.ime_toolbox_desc).takeIf { labels },
                labelSizeSp = labelSize,
                labelMaxWidthDp = labelMaxWidth,
                modifier = Modifier
                    .then(
                        if (dpadRing) {
                            Modifier.dpadTarget(BarToolboxRingId) {
                                onPanelChange(PanelMode.TOOLBOX)
                            }
                        } else {
                            Modifier
                        },
                    )
                    // The width a pinned button actually gets, published for the
                    // strip's emoji shortcut to match (see [pinnedToolWidthPx]).
                    .onSizeChanged { drag.pinnedToolWidthPx = it.width }
                    .animatePlacement(enabled = motion, inRow = true) { drag.bodyCoords }
                    // Under the slide, never over it: a fade renders offscreen
                    // and clips to its own node, so a stationary fade around a
                    // displaced icon cuts a slice off it. See the tool cells.
                    .graphicsLayer { alpha = contentAlpha() },
                // The tooltip is what the labels setting replaces; the labelled
                // variant never draws it anyway.
                longPressLabel = stringResource(R.string.ime_toolbox_desc).takeUnless { labels },
                wide = true,
                hint = hints?.label(HintSurface.TOOLBAR, 0),
            ) { onPanelChange(PanelMode.TOOLBOX) }
        }
    }
    val toolCells: @Composable RowScope.() -> Unit = {
        for (tool in displayTools) {
            key(tool) {
                val cell = if (greedy) {
                    Modifier
                        .weight(1f)
                        .fillMaxHeight()
                } else {
                    Modifier.padding(horizontal = 3.dp)
                }
                // On an in-place flip a shared tool slides and stays opaque
                // while the rest fade (see [contentAlpha]); on a fresh mount
                // ([fadeShared]) nothing slides, so it fades in with them.
                //
                // The alpha rides the *icon*, not the cell around it. A
                // graphicsLayer below full opacity renders to an offscreen
                // buffer the size of its node, and that buffer clips — so with
                // the fade on the cell, an icon that [animatePlacement] had
                // displaced out of its cell (which happens whenever the bar
                // reflows mid-fade: a chevron claiming or releasing its slot)
                // was drawn with a slice missing and a hard vertical edge where
                // the cell ended. On the icon's own node the buffer travels
                // with it and there is nothing to clip.
                val shared = tool in sharedTools
                val fadeThis = !shared || fadeShared
                PinnedToolCell(
                    tool, state, drag, onToolTap, cell,
                    hint = hints?.label(HintSurface.TOOLBAR, tools.indexOf(tool) + 1),
                    labelMaxWidthDp = labelMaxWidth,
                    inRow = true,
                    shared = shared,
                    fadeThis = fadeThis,
                    contentAlpha = contentAlpha,
                )
            }
        }
        // Folders the user pinned (#709), after the tools: a folder has no
        // place in the bar's own stored list, so it cannot sit between them.
        for (folder in pinnedFolders) {
            key("folder:${folder.id}") {
                Box(
                    if (greedy) Modifier.weight(1f).fillMaxHeight() else Modifier.padding(horizontal = 3.dp),
                    contentAlignment = Alignment.Center,
                ) {
                    PinnedFolderButton(
                        folder = folder,
                        state = state,
                        open = customizing && state.toolboxView.folderOpen == folder.id,
                        onOpen = { drag.toolbox.onFolderOpen(folder.id) },
                        // Slides when the tools before it move, and fades with the
                        // rest of the bar, like a pinned tool.
                        modifier = Modifier
                            .animatePlacement(enabled = motion, inRow = true) { drag.bodyCoords }
                            .graphicsLayer { alpha = contentAlpha() },
                    )
                }
            }
        }
    }
    if (greedy) {
        Row(
            modifier = Modifier
                .weight(1f)
                .fillMaxHeight(),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            leading(
                Modifier
                    .weight(1f)
                    .fillMaxHeight()
            )
            // The tools sub-row carries a weight equal to its cell count, so
            // its cells end up exactly as wide as the leading buttons' cells.
            // It still exists (zero tools aside) as the drag-drop target.
            //
            // The direction is provided around the row rather than on it: the
            // node takes its own layout direction from the composition local,
            // while where the row sits inside the bar still follows the bar.
            CompositionLocalProvider(LocalLayoutDirection provides toolsDirection) {
                Row(
                    modifier = Modifier
                        .weight((displayTools.size + pinnedFolders.size).coerceAtLeast(1).toFloat())
                        .fillMaxHeight()
                        .onGloballyPositioned { drag.toolbarBounds = it.boundsInRoot() },
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    toolCells()
                }
            }
            // Inside the grid, as one more equal cell. Out in the bar beside
            // this weighted row it would split the width with the whole grid
            // and take half the bar.
            if (toolboxSearchShown && searchAtEnd) {
                toolboxSearchCell(
                    Modifier
                        .weight(1f)
                        .fillMaxHeight(),
                )
            }
        }
    } else {
        leading(Modifier.padding(horizontal = 3.dp))
        CompositionLocalProvider(LocalLayoutDirection provides toolsDirection) {
            Row(
                modifier = Modifier
                    .weight(1f)
                    .fillMaxHeight()
                    // Weighted so it claims exactly the free width; the scroll
                    // then lets the pinned tools overflow that width instead of
                    // packing to fit. Reordering by drag still works — the
                    // toolbox is the simpler place to rearrange a long,
                    // scrolling bar.
                    .then(
                        if (scrollable) {
                            Modifier.horizontalScroll(rememberScrollState())
                        } else {
                            Modifier.shrinkToFit(
                                anchorRight = toolsPackAtEnd != (toolsDirection == LayoutDirection.Rtl),
                            )
                        },
                    )
                    .onGloballyPositioned { drag.toolbarBounds = it.boundsInRoot() },
                verticalAlignment = Alignment.CenterVertically,
            ) {
                toolCells()
            }
        }
    }
    // The toolbox search at the far end, after the tools. Unweighted here:
    // the greedy bar draws its own inside its grid, above.
    if (toolboxSearchShown && searchAtEnd && !greedy) {
        toolboxSearchCell(Modifier.padding(horizontal = 3.dp))
    }
    // Typing on a physical keyboard with only the toolbar showing: the keys
    // are one tap away (#642). At the far end and never weighted, so it
    // stays put whatever the tools do, and a greedy bar does not hand it half
    // the width.
    if (hardwareKeysToggleable(state)) {
        val shown = state.settings.toolbarBehavior.hardwareKeysShown
        val desc = stringResource(
            if (shown) R.string.ime_hardware_keys_hide_desc else R.string.ime_hardware_keys_show_desc,
        )
        Box(Modifier.padding(horizontal = 3.dp), contentAlignment = Alignment.Center) {
            ToolCircle(
                slot = if (shown) IconSlots.CHROME_HIDE_KEYS else IconSlots.CHROME_SHOW_KEYS,
                description = desc,
                active = shown,
                label = desc.takeIf { labels },
                labelSizeSp = labelSize,
                modifier = Modifier.graphicsLayer { alpha = contentAlpha() },
                longPressLabel = desc.takeUnless { labels },
                wide = true,
            ) { drag.onHardwareKeysToggle() }
        }
    }
    if (state.incognitoOn) {
        // Tappable: a field can switch incognito on by itself, and a badge
        // that shows up with no reason given reads as a bug (#665).
        SlotIcon(
            IconSlots.CHROME_INCOGNITO,
            contentDescription = stringResource(R.string.ime_incognito_on_desc),
            modifier = Modifier
                .clickable { drag.onIncognitoBadge() }
                .padding(start = 4.dp, top = 4.dp, end = 6.dp, bottom = 4.dp)
                .size(16.dp),
            tint = MaterialTheme.colorScheme.onSurfaceVariant,
        )
    }
    // Same badge for power saving, whichever source switched it on: the
    // dropped animations, haptics and sounds otherwise read as the keyboard
    // being broken, since the trigger (the system's battery saver, a low
    // battery) is nowhere near the keyboard.
    if (state.powerSavingOn) {
        SlotIcon(
            IconSlots.CHROME_POWER_SAVING,
            contentDescription = stringResource(R.string.ime_power_saving_on_desc),
            modifier = Modifier
                .padding(end = 6.dp)
                .size(16.dp),
            tint = MaterialTheme.colorScheme.onSurfaceVariant,
        )
    }
}

/**
 * One pinned tool, on the bar ([ToolbarRow]) or in the column beside the keys
 * ([ToolsColumn]): the hold and drag handling, the button in the tool's own
 * colours when the bar wears them, and the Voice tool's hold menu. One cell
 * for both, so a tool behaves the same wherever it is pinned.
 *
 * [inRow] is how the icon slides when the tools around it move: along a row,
 * where a vertical move is the row itself moving and snaps, or down a column,
 * where it is the tool's own. [shared], [fadeThis] and [contentAlpha] are the
 * bar's strip-to-toolbar dissolve; see [ToolbarRow].
 */
@Composable
private fun PinnedToolCell(
    tool: ToolbarTool,
    state: KeyboardUiState,
    drag: ToolDragController,
    onToolTap: (ToolbarTool) -> Unit,
    cell: Modifier,
    hint: String?,
    labelMaxWidthDp: Int?,
    inRow: Boolean,
    shared: Boolean = false,
    fadeThis: Boolean = true,
    contentAlpha: () -> Float = { 1f },
) {
    val customizing = state.panel == PanelMode.TOOLBOX
    val labels = state.settings.toolbarLabels
    val labelSize = state.settings.toolbarLabelSize
    val pinnedColors = state.settings.toolbarBehavior.pinnedToolColors
    val motion = !state.settings.reduceMotion
    val dpadRing = LocalDpadRing.current
    // The Voice tool's hold menu (#173). Cell-local: it is about
    // this one cell, opens on the hold's lift and closes on a
    // pick or a tap outside, and nothing else needs to know.
    var voiceMenuOpen by remember { mutableStateOf(false) }
    Box(cell, contentAlignment = Alignment.Center) {
        // Drag is always live: hold-and-drag reorders the bar
        // (or unpins into an open toolbox); a hold that never
        // moves opens the tool's settings page instead — or,
        // on the caret tools, repeats the move for as long as
        // the finger is down. Only here: the toolbox keeps the
        // hold-for-settings gesture for every tool, which is
        // what makes those pages still reachable.
        DraggableTool(
            tool,
            fromToolbar = true,
            enabled = true,
            drag = drag,
            onTap = { onToolTap(tool) },
            holdRepeatMs = holdRepeatMs(tool, state),
            holdAction = holdActionFor(tool, fromToolbar = true, state = state),
            dragEnabled = state.settings.toolbarBehavior.dragToRearrange,
            holdArms = holdArmsSelection(tool, fromToolbar = true, state = state),
            // Not while the toolbox is open (#320): the trackpad
            // took the toolbox's place under the held finger, so a
            // drag back to the grid found no grid to land on and
            // the tool could never leave the bar. Customizing, a
            // hold is for arranging, the way it is in the grid.
            holdPanel = !customizing &&
                holdOpensTrackpad(tool, fromToolbar = true, state = state),
            holdMenu = holdPicksVoiceMode(tool, fromToolbar = true, state = state),
            onHoldMenu = { voiceMenuOpen = true },
            holdDelayMs = state.settings.toolbarBehavior.holdDelayMs,
        ) { dragModifier ->
            val paint = if (pinnedColors) toolAccentPaint(tool, state.settings) else null
            ToolCircle(
                slot = IconSlots.forTool(tool),
                description = toolLabel(tool),
                active = toolActive(tool, state),
                tint = paint?.color,
                tintBrush = paint?.brush,
                label = if (labels) toolLabel(tool) else null,
                labelSizeSp = labelSize,
                labelMaxWidthDp = labelMaxWidthDp,
                // This cell IS the drop preview while it is the one
                // being dragged: it has moved to the slot under the
                // finger and draws washed out there, so the row on
                // screen is exactly the row the drop commits. The
                // solid icon to look at is the floating one under
                // the finger.
                ghost = tool == drag.dragging,
                wide = true,
                hint = hint,
                // The icon itself animates, anchored at the
                // keyboard body: cells are weighted so their
                // widths snap, and only body-relative tracking
                // sees the true on-screen motion.
                // A tool the suggestion strip also keeps
                // hands its position across that swap
                // instead of tracking only its own node.
                modifier = dragModifier
                    // The cell owns the press (interactive = false
                    // below), so it is the cell that marks itself
                    // as the opener a panel grows out of.
                    .panelOrigin()
                    .then(
                        if (dpadRing) {
                            Modifier.dpadTarget(tool) { onToolTap(tool) }
                        } else {
                            Modifier
                        },
                    )
                    .then(
                        if (shared) {
                            Modifier.animateSharedPlacement(
                                drag.placementOf(tool),
                                enabled = motion,
                            ) { drag.bodyCoords }
                        } else {
                            Modifier.animatePlacement(
                                enabled = motion,
                                inRow = inRow,
                            ) { drag.bodyCoords }
                        },
                    )
                    // Inside the slide, so the fade's buffer travels
                    // with the icon rather than clipping it.
                    .then(
                        if (fadeThis) {
                            Modifier.graphicsLayer { alpha = contentAlpha() }
                        } else {
                            Modifier
                        },
                    ),
                interactive = false,
            ) {}
        }
        if (voiceMenuOpen) {
            StripMenuScrim(onDismiss = { voiceMenuOpen = false })
            VoiceModeMenu(
                current = state.settings.voiceBar.typingMode,
                modes = state.supportedVoiceModes(),
                onDismiss = { voiceMenuOpen = false },
                onPick = { mode ->
                    voiceMenuOpen = false
                    drag.onVoiceModePick(mode)
                },
            )
        }
    }
}

/**
 * The packed toolbar's tools at their own width while they fit, and scaled
 * down together, icons and labels alike, when they don't.
 *
 * Packed cells have fixed widths, so a bar with as many tools as fit lost its
 * last one off the end the moment anything else claimed a few dp of the bar:
 * the incognito or power-saving badge, the hardware-keys button (#970). Scaling
 * the group keeps every tool on screen and in proportion, and a layer's scale
 * carries through to hit testing, so a tap and a drag still land on the icon
 * drawn under the finger.
 *
 * [anchorRight] is which screen edge the tools hug, the toolbox launcher's: it
 * is where the free space ends while they fit, and the fixed point of the
 * scale when they don't.
 */
private fun Modifier.shrinkToFit(anchorRight: Boolean): Modifier = layout { measurable, constraints ->
    val placeable = measurable.measure(constraints.copy(minWidth = 0, maxWidth = Constraints.Infinity))
    val width = constraints.maxWidth
    val scale = if (placeable.width > width) width / placeable.width.toFloat() else 1f
    layout(width, placeable.height) {
        val x = if (anchorRight) width - placeable.width else 0
        if (scale == 1f) {
            placeable.place(x, 0)
        } else {
            placeable.placeWithLayer(x, 0) {
                scaleX = scale
                scaleY = scale
                transformOrigin = TransformOrigin(if (anchorRight) 1f else 0f, 0.5f)
            }
        }
    }
}

/**
 * A committed toolbox order the grid draws before storage has echoed it back.
 *
 * [before] is the visible list as it stood when the drop happened: the preview
 * is dropped the moment that list changes, which is the settings arriving —
 * with this order, or with another one that has better claim to the screen.
 */
private data class ToolboxOrderPreview(
    val order: List<ToolbarTool>,
    val before: List<ToolbarTool>,
) {
    /** Where [tool] sits in the committed order; unranked tools keep the tail. */
    fun rank(tool: ToolbarTool): Int =
        order.indexOf(tool).takeIf { it >= 0 } ?: Int.MAX_VALUE
}

/**
 * Gboard-style toolbox: every tool that is not on the toolbar, shown in a
 * labeled grid ordered by [KeyboardSettings.toolboxOrder] (most-used-first
 * until the user rearranges it), or by use when [ToolboxSettings.sort] says
 * so. Tap to use a tool in place; hold and drag
 * it up onto the toolbar to pin it, or around the grid to reorder. Toolbar
 * tools drag down here to unpin — at the spot they're dropped.
 *
 * Two shapes, chosen by [ToolboxSettings.layout]: round icons with a caption,
 * or [ToolPill] rows. Either can scroll as one long grid or break into swiped
 * pages; that is [ToolboxSettings.paginate], and the cells are the same
 * [ToolboxGrid] either way.
 *
 * A tool held over the middle of another and let go there makes a folder of
 * the two (#709), which takes one cell and opens in place onto its own grid.
 * The search (#687), opened from the toolbar beside the back button, takes the
 * whole keyboard and lists the tools whose names match what the keys type,
 * folders or not, with the keys under a shorter panel.
 */
@Composable
private fun ToolboxPanel(
    state: KeyboardUiState,
    onToolTap: (ToolbarTool) -> Unit,
    onHintDismiss: () -> Unit,
    drag: ToolDragController,
) {
    val view = state.toolboxView
    val callbacks = drag.toolbox
    val openFolder = state.settings.toolbox.folders.folderById(view.folderOpen)
    val searching = view.searchActive
    val motionOn = LocalKbTheme.current.motion.any
    // Which level of the toolbox is showing. Moving between them is one
    // transition (#709, #687): into a folder its grid grows out of the cell
    // that was tapped, back out it settles down into that same spot, and the
    // search grows from the corner its button sat over. The header crossfades
    // with it, on the same clock.
    val level = when {
        searching -> "search"
        openFolder != null -> "folder:${openFolder.id}"
        else -> "top"
    }
    val levelIn = remember { Animatable(1f) }
    var shownLevel by remember { mutableStateOf(level) }
    var levelGrows by remember { mutableStateOf(true) }
    var levelPivot by remember { mutableStateOf(TransformOrigin.Center) }
    LaunchedEffect(level) {
        if (level == shownLevel) return@LaunchedEffect
        val leaving = shownLevel
        shownLevel = level
        // Deeper grows from small; back up a level settles from slightly large.
        levelGrows = level != "top"
        val box = drag.toolboxViewport
        val from = drag.folderOrigin
        levelPivot = when {
            level == "search" || leaving == "search" ->
                TransformOrigin(if (state.settings.toolbox.searchAtEnd) 1f else 0f, 0f)
            box != null && from != null && box.width > 0f && box.height > 0f -> TransformOrigin(
                ((from.x - box.left) / box.width).coerceIn(0f, 1f),
                ((from.y - box.top) / box.height).coerceIn(0f, 1f),
            )
            else -> TransformOrigin(0.5f, 0f)
        }
        if (!motionOn) return@LaunchedEffect
        levelIn.snapTo(0f)
        levelIn.animateTo(1f, spring(dampingRatio = 0.8f, stiffness = Spring.StiffnessMediumLow))
    }
    // Folders already drawn, with how many tools each held: one that is new
    // since then pops into its cell, one that gained a tool gives a little
    // bounce, so a drop visibly lands (#709). Seeded with what is there when
    // the panel opens, so opening it animates nothing.
    val seenFolders = remember {
        state.settings.toolbox.folders.associateTo(HashMap()) { it.id to it.tools.size }
    }
    SideEffect {
        for (folder in state.settings.toolbox.folders) seenFolders[folder.id] = folder.tools.size
    }
    val folderPop: (ToolboxCell.Folder) -> Float? = { cell ->
        val before = seenFolders[cell.folder.id]
        when {
            !motionOn -> null
            before == null -> 0.4f
            cell.folder.tools.size > before -> 1.18f
            else -> null
        }
    }
    // While the search or a folder's name has the keys, the panel gives up
    // its height so they fit under it: to the clipboard search's height, as
    // the snippets' search does, since the matches are the point of it.
    val typing = state.captureTarget().let {
        it == CaptureTarget.TOOLBOX_SEARCH || it == CaptureTarget.TOOLBOX_FOLDER_NAME
    }
    // The search is full-bleed: the toolbar and the rows with it hide, and
    // the panel takes their height so the window keeps its size.
    val bled = if (searching) fullBleedHiddenRows(state, macroRowAtPanelOpen(state)) else 0.dp
    val height = if (typing) {
        toolPanelHeight(
            state,
            wanted = ClipboardSearchHeight - captureStripHeight(state) + bled,
            floor = ToolboxHeaderHeight,
        )
    } else {
        keyRowsHeight(state) + bled
    }
    // First open: always show the drag hint. After it was dismissed once,
    // resurface it only rarely as a reminder. Rolled once per panel open.
    val rareReminder = remember { Random.nextFloat() < 0.03f }
    var hintVisible by remember(state.settings.toolboxHintDismissed) {
        mutableStateOf(!state.settings.toolboxHintDismissed || rareReminder)
    }
    // The registered geometry outlives the panel unless cleared, and a
    // stale viewport would let a later drag "drop on the toolbox" with the
    // panel long gone.
    DisposableEffect(drag) {
        onDispose {
            drag.toolboxViewport = null
            drag.toolboxContentCoords = null
            drag.toolboxPageStart = 0
            drag.toolboxPageLength = Int.MAX_VALUE
            drag.folderView = null
            drag.folderExitBounds = null
            drag.toolboxSearching = false
        }
    }
    Column(
        modifier = Modifier
            .fillMaxWidth()
            .height(height)
            .onGloballyPositioned { drag.toolboxViewport = it.boundsInRoot() },
    ) {
        // A slim header carrying the drag hint until it's dismissed. Resetting
        // the pinned tools now lives in Settings → Appearance ("Reset pinned
        // tools"), so the toolbox no longer shows its own reset control.
        Box(
            Modifier
                .fillMaxWidth()
                .graphicsLayer {
                    val p = levelIn.value.coerceIn(0f, 1f)
                    alpha = p
                    translationY = (1f - p) * -6.dp.toPx()
                },
        ) {
            when {
                searching -> ToolboxHeaderRow(Modifier.height(FullBleedHeaderHeight)) {
                    ToolCircle(
                        slot = IconSlots.CHROME_PANEL_BACK,
                        description = stringResource(R.string.ime_panel_back_desc),
                        active = false,
                        onClick = callbacks.onSearchToggle,
                    )
                    HeaderSearchPill(
                        query = view.query,
                        placeholder = stringResource(R.string.ime_toolbox_search_hint),
                        clearDescription = stringResource(R.string.ime_toolbox_search_clear_desc),
                        onClose = callbacks.onSearchToggle,
                    )
                }
                openFolder != null -> ToolboxFolderHeader(state, openFolder, drag)
                hintVisible -> ToolboxTopHeader(
                    state = state,
                    onHintDismiss = {
                        hintVisible = false
                        onHintDismiss()
                    },
                )
            }
        }
        // Everything under the header rides the level transition above.
        Column(
            Modifier
                .weight(1f)
                .fillMaxWidth()
                .graphicsLayer {
                    val p = levelIn.value
                    alpha = p.coerceIn(0f, 1f)
                    val start = if (levelGrows) 0.82f else 1.1f
                    val scale = start + (1f - start) * p
                    scaleX = scale
                    scaleY = scale
                    transformOrigin = levelPivot
                },
        ) {
            // Toolbox order is a complete ranking over every tool; the grid
            // shows the available subset in that order.
            val context = LocalContext.current
            val settledTools = when {
                // A search lists tools from every folder, so it draws no folders.
                searching -> toolboxSearchMatches(state) { context.getString(toolLabelRes(it)) }
                openFolder != null -> visibleToolboxTools(state).toSet().let { shown ->
                    openFolder.tools.filter { it in shown }
                }
                else -> toolboxGridTools(state)
            }
            // Ranked by use, the grid does not follow the order a drop commits:
            // it lands in the arrangement "Your order" brings back, and a
            // preview of it would hold the grid in that order with nothing to
            // let it go, since the list it was taken from never changes.
            val rankedByUse = !searching && openFolder == null &&
                state.settings.toolbox.sort != ToolboxSort.CUSTOM
            // The order the last drop committed, drawn until the settings flow
            // comes back with it.
            //
            // The commit is a suspend hop through DataStore, so for a frame or two
            // after the finger lifts the only order this composable can see is the
            // PRE-drag one: the tool snapped back to where it started, and then the
            // arriving settings moved it again. Two moves for one drop, the first
            // of them backwards, and the second landing as a rebuild of every cell
            // (see [ToolboxGrid]'s keys) — which is the jerk at the end of a drag.
            // Drawing the committed order at once makes the drop the only move.
            var preview by remember { mutableStateOf<ToolboxOrderPreview?>(null) }
            drag.onOrderPreview = { order ->
                if (!rankedByUse) preview = ToolboxOrderPreview(order, settledTools)
            }
            val available = preview
                ?.let { held -> settledTools.sortedBy { tool -> held.rank(tool) } }
                ?: settledTools
            // Let go of it the moment the settings say anything new, whether that
            // is this drop arriving or something else entirely (a mode switch, a
            // reset from the settings app) — the preview must never outlive the
            // list it was an early look at.
            LaunchedEffect(settledTools) {
                if (preview?.before != settledTools) preview = null
            }
            val toolbox = state.settings.toolbox
            val pills = toolbox.layout == ToolboxLayout.PILLS
            // The two layouts count their columns separately: a pill needs room for
            // a name, so its comfortable width is nothing like an icon's.
            val columns = if (pills) {
                toolbox.pillColumns.coerceAtLeast(1)
            } else {
                state.settings.toolboxColumns.coerceAtLeast(1)
            }
            // Folders gather at the top level only; inside one, and in a search,
            // every cell is a tool.
            val cells = if (openFolder == null && !searching) {
                toolboxCells(available, toolbox.folders)
            } else {
                available.map { ToolboxCell.Tool(it) }
            }
            drag.toolboxCells = cells
            drag.toolboxOrder = openFolder?.tools ?: state.settings.toolboxOrder
            drag.folderView = openFolder
            drag.toolboxSearching = searching
            drag.toolboxHidden = toolbox.hiddenTools
            drag.toolboxColumns = columns
            // The grid takes the ambient direction (it has no script of its own to
            // follow). The service pins the board to LTR (#336), but whatever the
            // ambient is, the cell maths has to mirror with it — the grid half of
            // issue #79.
            drag.boxRtl = LocalLayoutDirection.current == LayoutDirection.Rtl
            // Drop preview: the dragged tool LEAVES the list and a ghost marks the
            // slot it would land in. That is one hole, not two, and — the reason
            // it has to be done this way — it is a removal plus an insertion.
            //
            // A permutation does not work here. Keeping the tool in the list and
            // moving it to the target slot reads identically in the composition,
            // but Compose moves the composition groups without re-placing the
            // laid-out children, so the grid never reflowed: verified on device,
            // where a whole drag produced exactly one layout pass and every cell
            // kept its original x. The old code only appeared to shuffle because
            // inserting a ghost was a structural change.
            //
            // Removing the tool means its cell is disposed mid-gesture, which is
            // why the drag is no longer hosted there — see the pointerInput on the
            // grid below. The cells are pure visuals now.
            val boxSlot = drag.boxSlot
            // What the ghost draws as: the tool in flight, or the folder.
            val dragCell: ToolboxCell? = drag.dragging?.let { ToolboxCell.Tool(it) }
                ?: drag.draggingFolder?.let { folder ->
                    cells.firstOrNull { it.key == "folder:${folder.id}" } ?: ToolboxCell.Folder(folder, folder.tools)
                }
            // Identifies the settled order, and changes only when it does — never
            // during a drag, where the settings are untouched and `cells` is the
            // same list frame after frame. See [ToolboxGrid]'s cell keys for what
            // it is for. The folders ride in it too: a merge settles as a new cell.
            //
        // Not while searching (#687): there every keystroke is a different
        // list, and a re-keyed grid rebuilds every cell, so nothing could
        // slide. Typing more only removes results and deleting only adds them
        // back, both structural, so plain keys reflow there on their own.
        val orderKey = if (searching) 0 else cells.hashCode()
            // Removing a cell that is not there is a no-op when the drag came from
            // the toolbar, so both origins land on one ghost and one hole. Held over
            // the middle of a cell (#709) there is a hole and no ghost: the cell it
            // is held over stays exactly where the finger found it.
            val without = if (dragCell != null) cells.filterNot { it.key == dragCell.key } else cells
            val display: List<ToolboxCell?> = when {
                drag.active && boxSlot != null -> ArrayList<ToolboxCell?>(without).apply {
                    add(boxSlot.coerceIn(0, without.size), null)
                }
                drag.active && drag.boxMerge != null -> without
                else -> cells
            }
            if (display.isEmpty()) {
                Box(modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.Center) {
                    Text(
                        when {
                            searching -> stringResource(R.string.ime_toolbox_search_no_match, view.query.trim())
                            openFolder != null -> stringResource(R.string.ime_toolbox_folder_empty)
                            else -> stringResource(R.string.ime_toolbox_empty)
                        },
                        color = MaterialTheme.colorScheme.onSurfaceVariant,
                        textAlign = TextAlign.Center,
                        modifier = Modifier.padding(horizontal = 16.dp),
                    )
                }
                return@Column
            }
            // Indexed against `cells`, never `display`: the drop preview inserts
            // a null ghost slot into `display`, which would shift every index past it
            // and open the wrong tool. The ring is hidden mid-drag anyway (below),
            // but the count published here must match what Enter will resolve.
            PanelFocusTarget(
                panel = PanelMode.TOOLBOX,
                count = cells.size,
                columns = columns,
                onActivate = { index ->
                    when (val cell = cells.getOrNull(index)) {
                        is ToolboxCell.Tool -> onToolTap(cell.tool)
                        is ToolboxCell.Folder -> callbacks.onFolderOpen(cell.folder.id)
                        null -> Unit
                    }
                },
            )
            val focusedTool = state.focusedIndex().takeIf { !drag.active }
            if (!toolbox.paginate) {
                // One long grid the user scrolls: every cell is at its absolute
                // slot, so the drop math needs no page offset.
                drag.toolboxPageStart = 0
                drag.toolboxPageLength = Int.MAX_VALUE
                ToolboxGrid(
                    state = state,
                    drag = drag,
                    display = display,
                    pageStart = 0,
                    columns = columns,
                    pills = pills,
                    dragCell = dragCell,
                    dragEnabled = !searching,
                appear = searching && motionOn,
                folderPop = folderPop,
                    mergeKey = drag.boxMerge?.key,
                    orderKey = orderKey,
                    focusedSlot = focusedTool,
                    registerGeometry = true,
                    onToolTap = onToolTap,
                )
                return@Column
            }
            // Paginated: fixed pages to swipe through instead of a scroll. The
            // ghost takes a slot like anything else, so a drop preview near a page
            // boundary pushes the last tool onto the next page — which is what the
            // drop itself would do, so the preview stays honest.
            val pageSize = toolbox.pageSize.coerceIn(ToolboxPageSizeRange)
            val pageCount = toolboxPageCount(display.size, pageSize)
            val pager = rememberPagerState(pageCount = { pageCount })
            // A tool held against either side edge turns the page that way, so a
            // drag can carry it to another page (issue #536). Without this the drop
            // only ever measured against the page in front, and the grid's own
            // handler swallows the swipe a turn would otherwise take.
            val edgePx = with(LocalDensity.current) { ToolboxPageTurnEdge.toPx() }
            LaunchedEffect(drag.active) {
                if (!drag.active) return@LaunchedEffect
                var heldDir = 0
                var heldSince = 0L
                while (true) {
                    val now = withFrameMillis { it }
                    val box = drag.toolboxViewport
                    val at = drag.position
                    val side = when {
                        box == null || at.y !in box.top..box.bottom -> 0
                        at.x < box.left + edgePx -> -1
                        at.x > box.right - edgePx -> 1
                        else -> 0
                    }
                    // The pager runs its pages right to left under RTL, so the left
                    // edge is the way to the next page there.
                    val dir = if (drag.boxRtl) -side else side
                    if (dir != heldDir) {
                        heldDir = dir
                        heldSince = now
                        continue
                    }
                    val target = pager.currentPage + dir
                    if (dir == 0 || now - heldSince < ToolboxPageTurnDwellMs ||
                        target !in 0 until pager.pageCount
                    ) {
                        continue
                    }
                    pager.animateScrollToPage(target)
                    // The finger has not moved, but the page under it has: measure
                    // the drop again against the page now in front, once it has
                    // been laid out and registered its coordinates.
                    withFrameMillis { }
                    if (drag.dragging != null) drag.move(drag.position)
                    // Still on the edge, the next page is another full dwell away.
                    heldSince = withFrameMillis { it }
                }
            }
            HorizontalPager(
                state = pager,
                modifier = Modifier.weight(1f),
                // A page is cheap to build, but building the ones nobody has
                // swiped towards is still work the first frame doesn't need.
                // Except mid-drag: the gesture lives in the pointerInput of the page
                // the tool was picked up from, and turning away from that page would
                // dispose it and drop the tool wherever the finger happened to be.
                beyondViewportPageCount = if (drag.active) pageCount else 0,
            ) { page ->
                // Only the page in front publishes to the drag controller: its
                // neighbours stay composed through a swipe, and two pages claiming
                // the drop geometry would race over one set of coordinates.
                val current = page == pager.currentPage
                if (current) {
                    drag.toolboxPageStart = page * pageSize
                    drag.toolboxPageLength = pageSize
                }
                ToolboxGrid(
                    state = state,
                    drag = drag,
                    display = toolboxPage(display, page, pageSize),
                    pageStart = page * pageSize,
                    columns = columns,
                    pills = pills,
                    dragCell = dragCell,
                    dragEnabled = !searching,
                appear = searching && motionOn,
                folderPop = folderPop,
                    mergeKey = drag.boxMerge?.key,
                    orderKey = orderKey,
                    focusedSlot = focusedTool.takeIf { current },
                    registerGeometry = current,
                    onToolTap = onToolTap,
                )
            }
            PageDots(count = pageCount, current = pager.currentPage)
            // The hardware focus ring walks the whole toolbox, so following it here
            // means turning to the page it walked onto.
            LaunchedEffect(focusedTool, pageSize, pageCount) {
                val index = focusedTool ?: return@LaunchedEffect
                val target = (index / pageSize).coerceIn(0, pageCount - 1)
                if (target != pager.currentPage) pager.animateScrollToPage(target)
            }
        }
    }
}

/**
 * One screenful of toolbox cells — the whole grid when the toolbox scrolls,
 * a single page when it paginates — plus the one gesture handler that owns
 * every cell in it.
 *
 * The handler is hoisted above the cells rather than sitting on each one, and
 * that is what lets a cell be disposed mid-drag: the handler outlives any cell,
 * so the dragged tool can leave the list and the rest can close up behind it.
 * One FlowRow, so a part-full last line still lines up with the ones above it.
 */
@OptIn(ExperimentalLayoutApi::class)
@Composable
private fun ToolboxGrid(
    state: KeyboardUiState,
    drag: ToolDragController,
    /** This page's cells: tools and folders, with a null where the drop ghost goes. */
    display: List<ToolboxCell?>,
    /** Absolute slot of this page's first cell; 0 for the scrolling toolbox. */
    pageStart: Int,
    columns: Int,
    pills: Boolean,
    /** What the ghost draws as, while something is in flight. */
    dragCell: ToolboxCell?,
    /** False while the grid lists search results (#687): a hold opens a tool's settings, nothing moves. */
    dragEnabled: Boolean,
    /** The cell a dragged tool is held over the middle of (#709), drawn lit. */
    mergeKey: String?,
    /** Cells fade and grow in as they first appear, a little after one another (#687's results). */
    appear: Boolean,
    /** The scale a folder cell springs in from, when it is new or just grew (#709). */
    folderPop: (ToolboxCell.Folder) -> Float?,
    /** Identifies the settled toolbox order; see the cell keys below. */
    orderKey: Int,
    /** Absolute slot the hardware focus ring is on, or null. */
    focusedSlot: Int?,
    /** Whether this grid is the one a drop should be measured against. */
    registerGeometry: Boolean,
    onToolTap: (ToolbarTool) -> Unit,
) {
    // The placement anchor is this scrolling content column, NOT the keyboard
    // body: relative to the body every icon "moves" on every scroll frame,
    // which made each one restart its placement spring per frame (a
    // coroutine-and-relayout storm that tanked scroll fps). Relative to the
    // content, scrolling is a no-op for the animation.
    var gridCoords by remember { mutableStateOf<LayoutCoordinates?>(null) }
    var gridOrigin by remember { mutableStateOf(Offset.Zero) }
    val feedback = LocalKeyPressFeedback.current
    // Once for the grid, not once per cell: this walks the tool lists and
    // builds two maps, and a forty-cell toolbox would have done it forty times
    // for one answer. Null with no picker armed, and during a drag — a drag
    // inserts a ghost into `display`, and every slot past it would then be
    // labelled with its neighbour's key.
    val hints = if (dragCell == null && state.toolPicker != null) armedHintPlan(withLiveTyping(state)) else null
    // The plan numbers the toolbox's tools in grid order, folders or not,
    // so a cell's badge is found by its tool rather than by where it sits.
    val hintSlots = hints?.let { toolboxGridTools(state).withIndex().associate { (i, tool) -> tool to i } }
    val dragEnabledNow by rememberUpdatedState(dragEnabled)
    val openFolder by rememberUpdatedState(drag.toolbox.onFolderOpen)
    val scope = rememberCoroutineScope()
    val tapTool by rememberUpdatedState(onToolTap)
    // Read through holders, and key the handler on nothing. `display` is a
    // fresh list on every recomposition and the drop preview recomposes this
    // panel on every frame of a drag, so keying pointerInput on it would tear
    // down and restart the very gesture it is running — the same trap the
    // per-cell handler documented.
    val cellsNow by rememberUpdatedState(display)
    val columnsNow by rememberUpdatedState(columns)
    val registerNow by rememberUpdatedState(registerGeometry)
    // Through a holder for the same reason, rather than as a pointerInput key:
    // the grid's handler is keyed on nothing at all, and a settings change is
    // not a reason to be the one thing that restarts it mid-gesture.
    val toolboxRepeatNow by rememberUpdatedState(state.settings.textEditing.toolboxRepeatTools)
    val repeatMsNow by rememberUpdatedState(state.settings.textEditing.repeatMs.toLong())
    // The bar's hold delay holds in the grid too: one wait for every hold on a tool.
    val holdDelayNow by rememberUpdatedState(state.settings.toolbarBehavior.holdDelayMs)
    val gridScroll = rememberScrollState()
    // No lazy state to scroll by index, so scroll by row: every cell reports
    // the same size, and the drag controller already collects it.
    ScrollFocusIntoView(focusedSlot) { index ->
        val rowHeight = drag.toolboxCellSize.height
        if (rowHeight > 0f) {
            val target = (((index - pageStart) / columns) * rowHeight).coerceAtLeast(0f)
            gridScroll.animateScrollTo(target.toInt().coerceIn(0, gridScroll.maxValue))
        }
    }
    FlowRow(
        modifier = Modifier
            .verticalScroll(gridScroll)
            .onGloballyPositioned {
                gridCoords = it
                gridOrigin = it.positionInRoot()
                if (registerNow) drag.toolboxContentCoords = it
            }
            .pointerInput(Unit) {
                val dragSlop = ToolDragSlop.toPx()
                awaitEachGesture {
                    val down = awaitFirstDown(requireUnconsumed = false)
                    // Which tool was grabbed is resolved once, from where the
                    // finger landed. The grid is uniform, so this is the same
                    // arithmetic the drop target uses. Nothing has moved yet at
                    // this point: a drag is not live, so the list on screen is
                    // still the plain one, ghost-free.
                    val cell = drag.toolboxCellSize
                    if (cell.width <= 0f || cell.height <= 0f) return@awaitEachGesture
                    val cols = columnsNow
                    val across = (down.position.x / cell.width).toInt()
                    if (down.position.x < 0f || across !in 0 until cols) {
                        return@awaitEachGesture
                    }
                    // Same mirror the drop target applies: cell 0 of an RTL
                    // grid is the rightmost one.
                    val col = if (drag.boxRtl) cols - 1 - across else across
                    val row = (down.position.y / cell.height).toInt()
                    val hit = cellsNow.getOrNull(row * cols + col)
                        ?: return@awaitEachGesture
                    val tool = (hit as? ToolboxCell.Tool)?.tool
                    val folder = (hit as? ToolboxCell.Folder)?.folder
                    // Where a folder opened from here grows out of.
                    val cellCenter = gridOrigin + Offset((across + 0.5f) * cell.width, (row + 0.5f) * cell.height)
                    // Root coordinates throughout: the grid reflows around the
                    // drop preview while the finger is down, and a node that
                    // moves under a still finger reports deltas of its own.
                    val downRoot = gridOrigin + down.position
                    var rootPos = downRoot
                    var longPressed = false
                    var dragged = false
                    var released = false
                    var scrolled = false
                    // A hold that travels where nothing can move (a search).
                    var wandered = false
                    // Resolved with the tool, from the set as it stands now. A
                    // tool the user opted in repeats here exactly as it does on
                    // the toolbar, and gives up this grid's hold-for-settings
                    // to do it; every other tool keeps it.
                    val repeatTool = tool?.takeIf { it in toolboxRepeatNow && it in HoldRepeatCursorTools }
                    val holdRepeatMs = repeatMsNow.takeIf { repeatTool != null }
                    val timer = scope.launch {
                        delay(toolHoldDelay(holdDelayNow, viewConfiguration.longPressTimeoutMillis))
                        feedback()
                        longPressed = true
                        // Pick-up held back until the finger travels, as on the
                        // toolbar: starting it here parked a drag ghost and the
                        // scope pill under a finger that was only holding a
                        // cell down — for its settings page, or for a repeat.
                        if (holdRepeatMs != null && repeatTool != null) {
                            while (true) {
                                tapTool(repeatTool)
                                delay(holdRepeatMs)
                            }
                        }
                    }
                    try {
                        while (true) {
                            val event = awaitPointerEvent()
                            val change = event.changes.firstOrNull { it.id == down.id } ?: break
                            if (!change.pressed) {
                                released = true
                                if (longPressed) change.consume()
                                break
                            }
                            rootPos = gridOrigin + change.position
                            val travel = (rootPos - downRoot).getDistance()
                            if (!longPressed) {
                                // Drift before the hold registers is a scroll,
                                // or a page swipe — hand the gesture back.
                                if (travel > viewConfiguration.touchSlop) {
                                    scrolled = true
                                    break
                                }
                            } else {
                                change.consume()
                                if (travel > dragSlop && !dragged && !wandered) {
                                    // Travel means a reorder after all, so the
                                    // tool picks itself up from here (and a
                                    // repeating one stops repeating).
                                    timer.cancel()
                                    if (!dragEnabledNow) {
                                        wandered = true
                                    } else {
                                        dragged = true
                                        if (folder != null) drag.startFolder(folder, rootPos)
                                        else if (tool != null) drag.start(tool, false, rootPos)
                                    }
                                }
                                // Nothing to move until the finger has travelled:
                                // no drag has been started, and drag.move would
                                // tick the drop haptic anyway.
                                if (dragged) drag.move(rootPos)
                            }
                        }
                    } finally {
                        timer.cancel()
                        when {
                            !longPressed -> {
                                drag.cancel()
                                if (released && !scrolled) {
                                    if (folder != null) {
                                    drag.folderOrigin = cellCenter
                                    openFolder(folder.id)
                                } else if (tool != null) tapTool(tool)
                                }
                            }
                            dragged -> drag.end()
                            // A repeating hold has already done its work, and
                            // there is nothing to drop.
                            holdRepeatMs != null || wandered -> drag.cancel()
                            // A hold that never travelled past the slop is a
                            // distinct gesture: open the tool's settings. A
                            // folder has none, so the hold opens the folder.
                            else -> {
                                drag.cancel()
                                if (folder != null) {
                                    drag.folderOrigin = cellCenter
                                    openFolder(folder.id)
                                } else if (tool != null) drag.onOpenSettings(tool)
                            }
                        }
                    }
                }
            },
        maxItemsInEachRow = columns,
    ) {
        display.forEachIndexed { slot, cell ->
            // The ghost's key encodes its slot so a move is a structural
            // remove+add, not a same-key reorder. FlowRow re-measures and
            // re-places its children on a structural change, but on a pure
            // reorder it moves the composition groups while leaving every
            // laid-out child at its old position — verified on device, where
            // the grid reflowed once (the dragged tool leaving) and then
            // froze for the rest of the drag: the ghost never moved and the
            // icons never made room. Re-keying per slot forces the reflow on
            // every step. (The toolbar is a Row, which re-places on reorder,
            // so its ghost keeps one stable key.)
            // The saved order rides in the key ([orderKey]) for the same reason
            // the ghost's slot does: FlowRow re-measures and re-places on a
            // structural change and does neither on a pure keyed reorder, and
            // the order arrives from settings a frame or two AFTER the drop —
            // by which time the ghost is gone and the list is nothing but a
            // reorder. So the drop saved, and the grid went on drawing the old
            // arrangement until the panel was closed and opened again. Re-keying
            // makes that arrival structural. Stable through the drag itself
            // (settings do not change mid-gesture), so the cells still slide
            // around the ghost; a settled reorder costs one rebuild of a cell
            // each, and lands with no animation, which is right — the drag has
            // already shown the move.
            key(cell?.let { "${it.key}@$orderKey" } ?: "box-ghost-${pageStart + slot}") {
                // Where this cell's tool name is drawn: a panel opened from
                // the cell grows out of it and lifts that name into its header.
                val nameAnchor = remember { PanelLabelAnchor() }
                Box(
                    modifier = Modifier
                        .toolboxCellWidth(columns)
                        // Every cell is the same size, so whichever reported
                        // last feeds the slot math. That is an invariant the
                        // tap and drop maths depend on, not an observation:
                        // width is fixed by toolboxCellWidth and height by the
                        // label's fixed line count. Anything put in a cell that
                        // can change its height breaks hit testing for every
                        // row below it.
                        .onGloballyPositioned { drag.toolboxCellSize = it.size.toSize() }
                        // Watches the press only; the grid's loop still owns it.
                        .panelOrigin(nameAnchor),
                    contentAlignment = Alignment.Center,
                ) {
                    // Pure visuals — the grid's own pointerInput owns the
                    // gesture, so nothing here has to survive the dragged
                    // tool leaving the list.
                    val ghost = cell == null
                    // dragCell is never null when a ghost entry exists.
                    val shownCell = cell ?: dragCell ?: return@Box
                    // `slot` indexes this page, which holds the plain tools
                    // whenever the ring is drawn at all — focusedSlot is null
                    // for the whole of a drag, and only a drag inserts a ghost.
                    // A cell a tool is held over the middle of wears the same
                    // ring: it is the one the drop will go into (#709).
                    val merging = !ghost && shownCell.key == mergeKey
                    val focused = focusedSlot == pageStart + slot || merging
                    // Anchored at the scrolling content (see gridCoords), NOT
                    // the keyboard body: body-relative, every scroll frame
                    // moved every icon and restarted its spring — a per-frame
                    // coroutine storm that tanked scroll fps. Content-relative,
                    // scrolling is a no-op; reorders still slide.
                    //
                    // The cap is the grid's own step, not the toolbar's fixed
                    // one — see [toolboxSlideCap] for why the fixed one snapped
                    // every reorder the grid ever made. Read from the live cell
                    // size inside the placement pass, so it is the size the row
                    // actually got rather than one guessed from the settings.
                    // A cell a tool is held over swells to meet it, with a bounce,
                    // and settles back when the tool moves on.
                    val mergeScale by animateFloatAsState(
                        if (merging) ToolboxMergeScale else 1f,
                        animationSpec = if (state.settings.reduceMotion) {
                            snap()
                        } else {
                            spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessMedium)
                        },
                        label = "mergeScale",
                    )
                    // Search results fade and grow in, one a beat after the
                    // other, rather than all landing on one frame.
                    val appearIn = remember { Animatable(if (appear) 0f else 1f) }
                    if (appear) {
                        LaunchedEffect(Unit) {
                            delay((slot * ToolboxAppearStaggerMs).coerceAtMost(ToolboxAppearMaxDelayMs))
                            appearIn.animateTo(1f, spring(dampingRatio = 0.75f, stiffness = Spring.StiffnessMediumLow))
                        }
                    }
                    val placement = Modifier
                        .animatePlacement(
                            enabled = !state.settings.reduceMotion,
                            cap = { toolboxSlideCap(columns, drag.toolboxCellSize) },
                        ) { gridCoords }
                        .graphicsLayer {
                            val shownIn = appearIn.value
                            val scale = mergeScale * (0.85f + 0.15f * shownIn)
                            scaleX = scale
                            scaleY = scale
                            alpha = shownIn.coerceIn(0f, 1f)
                        }
                    if (shownCell is ToolboxCell.Folder) {
                        ToolboxFolderCell(
                            state = state,
                            cell = shownCell,
                            pills = pills,
                            ghost = ghost,
                            focused = focused,
                            nameAnchor = nameAnchor,
                            modifier = placement,
                            popFrom = if (ghost) null else folderPop(shownCell),
                        )
                        return@Box
                    }
                    val shown = (shownCell as ToolboxCell.Tool).tool
                    val paint = toolAccentPaint(shown, state.settings)
                    val hint = hints?.let { plan -> hintSlots?.get(shown)?.let { plan.label(HintSurface.TOOLBOX, it) } }
                    if (pills) {
                        ToolPill(
                            tool = shown,
                            active = toolActive(shown, state),
                            labelSize = toolboxLabelSize(state),
                            paint = paint,
                            filled = state.settings.toolbox.pillFilled,
                            ghost = ghost,
                            hint = hint,
                            modifier = placement
                                .padding(horizontal = 3.dp, vertical = 3.dp)
                                .focusRing(focused, RoundedCornerShape(pillRadius())),
                            labelAnchor = nameAnchor,
                        )
                        return@Box
                    }
                    Column(
                        modifier = placement
                            .focusRing(focused, RoundedCornerShape(12.dp))
                            // The same for a folder's cell, so the grid stays uniform.
                            .padding(vertical = state.settings.toolbox.cellSpacingDp.dp),
                        horizontalAlignment = Alignment.CenterHorizontally,
                    ) {
                        if (ghost) {
                            GhostToolCircle(shown)
                        } else {
                            ToolCircle(
                                slot = IconSlots.forTool(shown),
                                description = toolLabel(shown),
                                active = toolActive(shown, state),
                                interactive = false,
                                tint = paint?.color,
                                tintBrush = paint?.brush,
                                hint = hint,
                            ) {}
                        }
                        Text(
                            toolLabel(shown),
                            // The name is what the grid is actually read by —
                            // the icons are close cousins of one another and
                            // the words are not — so it carries the same
                            // weight as a suggestion chip rather than the
                            // caption size it used to have.
                            fontSize = toolboxLabelSize(state),
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                                .copy(alpha = if (ghost) 0.5f else 1f),
                            textAlign = TextAlign.Center,
                            // Always two lines, never one and never three, so
                            // every cell is the same height. The grid's tap and
                            // drop maths divide a touch by one cell size to get
                            // a slot, which is only true of a uniform grid: when
                            // a long name wrapped and a short one did not, rows
                            // differed in height, the error accumulated downwards
                            // and a tap landed on the tool below — further out
                            // the further down you were, until the index ran off
                            // the end and the last tools stopped opening at all.
                            minLines = 2,
                            maxLines = 2,
                            overflow = TextOverflow.Ellipsis,
                            onTextLayout = nameAnchor::onTextLayout,
                            modifier = Modifier
                                .padding(top = 4.dp, start = 2.dp, end = 2.dp)
                                .fillMaxWidth()
                                .panelOriginLabel(nameAnchor),
                        )
                    }
                }
            }
        }
    }
}

/** The toolbox header's floor: one row of its small buttons with room around them. */
private val ToolboxHeaderHeight = 40.dp

/** How much a toolbox cell grows while a dragged tool is held over its middle (#709). */
private const val ToolboxMergeScale = 1.12f

/** The beat between one search result appearing and the next (#687). */
private const val ToolboxAppearStaggerMs = 18L

/** The last search result is never more than this late. */
private const val ToolboxAppearMaxDelayMs = 180L

/**
 * The tool under the finger shrinks a little while it is held over a cell it
 * would be filed into (#709), so it reads as about to drop in rather than to
 * sit beside it. A modifier of its own so the ghost's caller, which sits at
 * the JVM's method-size ceiling, pays for one call.
 */
@Composable
private fun Modifier.ghostMergeShrink(drag: ToolDragController): Modifier {
    val motion = LocalKbTheme.current.motion.any
    val scale by animateFloatAsState(
        if (drag.boxMerge != null) 0.78f else 1f,
        animationSpec = if (motion) {
            spring(dampingRatio = Spring.DampingRatioMediumBouncy, stiffness = Spring.StiffnessMedium)
        } else {
            snap()
        },
        label = "ghostMerge",
    )
    return graphicsLayer {
        scaleX = scale
        scaleY = scale
    }
}

/** The toolbox's slim header row; what it carries depends on what the panel is showing. */
@Composable
private fun ToolboxHeaderRow(modifier: Modifier = Modifier, content: @Composable RowScope.() -> Unit) {
    Row(
        modifier = modifier
            .fillMaxWidth()
            .heightIn(min = ToolboxHeaderHeight)
            .padding(horizontal = 8.dp, vertical = 2.dp),
        verticalAlignment = Alignment.CenterVertically,
        content = content,
    )
}

/** A small round button in the toolbox header, with its name as the hold tooltip. */
@Composable
private fun ToolboxHeaderButton(description: String, onClick: () -> Unit, icon: @Composable () -> Unit) {
    IconHint(description) {
        IconButton(onClick = onClick, modifier = Modifier.size(32.dp)) { icon() }
    }
}

/**
 * The toolbox header at its top level: the drag hint, until it is dismissed.
 * The search (#687) is on the toolbar, beside the back button.
 */
@Composable
private fun ToolboxTopHeader(
    state: KeyboardUiState,
    onHintDismiss: () -> Unit,
) {
    val tint = MaterialTheme.colorScheme.onSurfaceVariant
    ToolboxHeaderRow {
        val activeMode = state.settings.keyboardModes
            .firstOrNull { it.id == state.activeModeId }
            ?.takeIf { state.settings.modeToolOrderEdits && it.ownsToolOrder }
        // With a mode on, the arrangement being edited is that mode's
        // own — say so, or the same keyboard looking different in the
        // next app reads as the drag being lost.
        val dragHint = stringResource(R.string.ime_toolbox_hint_drag)
        Text(
            if (activeMode != null) {
                stringResource(R.string.ime_toolbox_hint_mode, activeMode.name) + " " + dragHint
            } else {
                dragHint
            },
            fontSize = 12.sp,
            color = tint,
            textAlign = TextAlign.Center,
            modifier = Modifier
                .weight(1f)
                .padding(start = 16.dp, top = 2.dp, bottom = 2.dp),
        )
        ToolboxHeaderButton(stringResource(R.string.ime_toolbox_hint_dismiss_desc), onHintDismiss) {
            Icon(
                Icons.Outlined.Close,
                contentDescription = stringResource(R.string.ime_toolbox_hint_dismiss_desc),
                modifier = Modifier.size(16.dp),
                tint = tint,
            )
        }
    }
}

/**
 * The header of an open toolbox folder (#709): back up a level, the name (a
 * tap types a new one), pin to the toolbar, ungroup. While one of the folder's
 * tools is being dragged it is the drop that takes the tool out instead.
 */
@Composable
private fun ToolboxFolderHeader(state: KeyboardUiState, folder: ToolboxFolder, drag: ToolDragController) {
    val kb = LocalKbTheme.current
    val callbacks = drag.toolbox
    val tint = MaterialTheme.colorScheme.onSurfaceVariant
    val draft = state.toolboxView.nameDraft
    val dragged = drag.dragging
    ToolboxHeaderRow(Modifier.onGloballyPositioned { drag.folderExitBounds = it.boundsInRoot() }) {
        if (dragged != null && dragged in folder.tools) {
            val armed = drag.overFolderExit
            val shape = RoundedCornerShape(18.dp)
            val motion = kb.motion.any
            // The drop target fills in and swells as the tool reaches it.
            val fill by animateColorAsState(
                if (armed) kb.toolCircleActive else kb.chip,
                animationSpec = if (motion) tween(160) else snap(),
                label = "takeOutFill",
            )
            val swell by animateFloatAsState(
                if (armed) 1.04f else 1f,
                animationSpec = if (motion) spring(dampingRatio = Spring.DampingRatioMediumBouncy) else snap(),
                label = "takeOutSwell",
            )
            // And arrives with a short rise, since it takes the header's place
            // the moment the pick-up happens.
            val arrive = remember { Animatable(if (motion) 0f else 1f) }
            LaunchedEffect(Unit) { arrive.animateTo(1f, tween(180, easing = LinearOutSlowInEasing)) }
            Box(
                modifier = Modifier
                    .weight(1f)
                    .height(32.dp)
                    .graphicsLayer {
                        scaleX = swell
                        scaleY = swell
                        alpha = arrive.value
                        translationY = (1f - arrive.value) * 6.dp.toPx()
                    }
                    .clip(shape)
                    .background(fill, shape)
                    .border(1.dp, kb.toolbarIcon.copy(alpha = 0.35f), shape)
                    .padding(horizontal = 12.dp),
                contentAlignment = Alignment.Center,
            ) {
                Text(
                    stringResource(R.string.ime_toolbox_folder_take_out),
                    fontSize = 12.sp,
                    color = if (armed) kb.toolCircleActiveIcon else kb.modifierKeyText,
                    maxLines = 1,
                    overflow = TextOverflow.Ellipsis,
                )
            }
            return@ToolboxHeaderRow
        }
        ToolboxHeaderButton(stringResource(R.string.ime_panel_back_desc), { callbacks.onFolderOpen(null) }) {
            SlotIcon(
                IconSlots.CHROME_PANEL_BACK,
                contentDescription = stringResource(R.string.ime_panel_back_desc),
                modifier = Modifier.size(18.dp),
                tint = tint,
            )
        }
        if (draft != null) {
            HeaderSearchPill(
                query = draft,
                placeholder = stringResource(R.string.ime_toolbox_folder_name_hint),
                clearDescription = stringResource(R.string.ime_toolbox_folder_rename_done_desc),
                onClose = callbacks.onRenameDone,
                leadingIcon = Icons.Outlined.Edit,
                closeIcon = Icons.Outlined.Check,
            )
            return@ToolboxHeaderRow
        }
        val renameDesc = stringResource(R.string.ime_toolbox_folder_rename_desc)
        Row(
            modifier = Modifier
                .weight(1f)
                .clip(RoundedCornerShape(8.dp))
                .clickable(onClickLabel = renameDesc, onClick = callbacks.onRename)
                .padding(horizontal = 8.dp, vertical = 6.dp),
            verticalAlignment = Alignment.CenterVertically,
        ) {
            Text(
                folder.name,
                color = kb.secondaryText,
                fontSize = 13.sp,
                fontWeight = FontWeight.Medium,
                maxLines = 1,
                overflow = TextOverflow.Ellipsis,
                modifier = Modifier.weight(1f, fill = false),
            )
            Spacer(Modifier.width(6.dp))
            Icon(Icons.Outlined.Edit, contentDescription = renameDesc, modifier = Modifier.size(14.dp), tint = tint)
        }
        val pinDesc = stringResource(
            if (folder.pinned) R.string.ime_toolbox_folder_unpin_desc else R.string.ime_toolbox_folder_pin_desc,
        )
        ToolboxHeaderButton(pinDesc, { callbacks.onPinToggle(folder.id) }) {
            Icon(
                if (folder.pinned) Icons.Filled.PushPin else Icons.Outlined.PushPin,
                contentDescription = pinDesc,
                modifier = Modifier.size(18.dp),
                tint = if (folder.pinned) kb.toolCircleActiveIcon else tint,
            )
        }
        val ungroupDesc = stringResource(R.string.ime_toolbox_folder_ungroup_desc)
        ToolboxHeaderButton(ungroupDesc, { callbacks.onUngroup(folder.id) }) {
            Icon(Icons.Outlined.FolderOpen, contentDescription = ungroupDesc, modifier = Modifier.size(18.dp), tint = tint)
        }
    }
}

/**
 * A header-row text field typed through the keyboard's own keys: the snippets
 * search (#471), the toolbox search (#687), a toolbox folder's name (#709).
 * Takes the row's free width; [onClose] is its end button.
 */
@Composable
private fun RowScope.HeaderSearchPill(
    query: String,
    placeholder: String,
    clearDescription: String,
    onClose: () -> Unit,
    leadingIcon: ImageVector = Icons.Outlined.Search,
    closeIcon: ImageVector = Icons.Outlined.Close,
) {
    val kb = LocalKbTheme.current
    Row(
        modifier = Modifier
            .weight(1f)
            .padding(start = 6.dp, end = 4.dp)
            .clip(RoundedCornerShape(18.dp))
            .frostGlass(kb, RoundedCornerShape(18.dp), FrostSurface.CHIPS)
            .background(kb.chip)
            .padding(start = 12.dp, end = 4.dp, top = 2.dp, bottom = 2.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
        Icon(
            leadingIcon,
            contentDescription = null,
            modifier = Modifier.size(16.dp),
            tint = kb.toolbarIcon,
        )
        Spacer(Modifier.width(8.dp))
        SearchQueryText(
            query = query,
            placeholder = placeholder,
            active = true,
            textColor = kb.modifierKeyText,
            placeholderColor = kb.toolbarIcon,
            fontSize = 13.sp,
            modifier = Modifier.weight(1f),
        )
