            IconButton(onClick = onClose, modifier = Modifier.size(30.dp)) {
                Icon(
                    closeIcon,
                    contentDescription = clearDescription,
                    modifier = Modifier.size(16.dp),
                    tint = kb.toolbarIcon,
                )
            }
        }
