                            // key, and never out of the key's open popup.
                            val starts = if (slideSource) {
                                !alternatesGate.open &&
                                    liveRects.value.keyAt(change.position + boxOrigin)
                                        .let { it != null && it !== source }
                            } else {
                                (change.position - down.position).getDistance() > slop
                            }
