                        // still unconsumed, and it latches exactly as it always has.
                        // A shift held past the long press with nothing typed
                        // under it is a long press, and locks the capitals the
                        // way it does on most keyboards (#679). Not a shift
                        // press: that one recases the word at the caret when
                        // the setting is on, which left no way to lock caps
                        // with the caret on a word.
                        if (!dragging) {
                            // A slide that never left its key is the key's own
                            // tap, and the held shift's deferred press is not
                            // this finger's to fire.
                            if (!slideSource && !shiftHold.typed) {
                                shiftHold.deferred?.let { stampedOnKey(it.copy(action = KeyAction.CapsLock)) }
                            }
                            return@awaitEachGesture
                        }
                        if (!slideSource) trail.release()
                        val target = over
                        when {
                            // Lifted off the grid: the slide-away cancel every other
                            // key already has, and nothing fires.
                            target == null -> Unit
                            // A slide types the key it lifts on as a tap would,
                            // through the same route, so a held shift still
                            // capitalises it (#367).
                            slideSource -> if (fires(target)) keyTapOnKey(target)
                            // Wandered off and came back. The press was cancelled on
                            // the way out, so the tap it would have been is fired
                            // here rather than swallowed.
                            target === source -> stampedOnKey(target)
                            // Onto a key with no shortcut: nothing, like a chord
                            // onto a key no hardware keyboard could send.
                            globe -> globeDragAction(target, letterActionsLive.value)?.let(onGlobeShortcut)
                            else -> {
                                val fired =
                                    if (mod != null) chordKey(target, mod) else shiftChordKey(target)
                                fired?.let(stampedOnKey)
                            }
                        }
                    } finally {
                        chordDrag.active = false
                        chordDrag.shifted = false
                        chordDrag.pressRect.value = null
                        // Released, not cancelled: the bubble gets the same short
                        // minimum a tapped key's does, so the capital typed is
                        // readable for a beat after the lift.
                        keyPreview.release(ChordPreviewToken)
                        if (holdsShift) shiftHold.end()
                    }
                }
            }
